def test_a_player_who_dms_max_is_pointed_at_the_public_channels():
    """One sentence from the harness, and nothing else exists: no conversation, no model.

    A DM used to be dropped in the listener, which is the right policy said in the one way a
    person cannot tell from an outage. The policy has not moved — a DM has no moderator, no
    other players to correct a wrong answer and no record the next person to ask can find — but
    saying so costs one queued post, and saying it is what makes it a policy rather than a
    silence.
    """
    print("a player's DM")
    fixture = base_fixture()
    fixture["channel_objects"] = {DM_CHANNEL: {"id": DM_CHANNEL, "type": 1,
                                               "recipients": [{"id": PLAYER}]}}
    fixture["messages"][DM_CHANNEL] = [
        message(5201, "how do I unlock the mass driver?", channel=DM_CHANNEL)]
    case = Case("dm-player", fixture)
    case.cfg["operators"] = {"lothsahn": {"discord": LOTHSAHN, "model": SUITE_CLAUDE_NAME}}
    case.events({"ts": "2026-08-21T00:00:00Z", "kind": "player_dm", "channel": None,
                 "channel_id": DM_CHANNEL, "id": "5201", "author_id": PLAYER})
    case.watcher.drain_events()

    check("a player's DM opens no conversation", case.rows("SELECT * FROM conversation") == [],
          case.rows("SELECT * FROM conversation"))
    check("and no message, turn or run is recorded for it",
          not case.rows("SELECT * FROM message") and not case.rows("SELECT * FROM turn")
          and not case.rows("SELECT * FROM run"), case.rows("SELECT * FROM message"))
    # THE TEXT IS NEVER FETCHED. The reply does not depend on what was said, so nothing reads
    # it: the only call is the one that establishes this is a one-to-one DM and not a room.
    kinds = [c[0] for c in case.calls() if c and "--help" not in c]
    check("the harness never even reads what they wrote", kinds == ["channel"], case.calls())

    queued = case.rows("SELECT * FROM outbound")
    check("exactly one post is queued, with no conversation behind it",
          len(queued) == 1 and queued[0]["action"] == "post"
          and queued[0]["conversation_id"] is None and queued[0]["run_id"] is None, queued)
    check("and it is the standing note, verbatim",
          json.loads(queued[0]["payload_json"])["text"] == ffwatch.DM_AUTOREPLY_TEXT,
          queued[0]["payload_json"])

    case.watcher.send_pending()
    posts = sent_calls(case)
    check("which goes out to the DM channel it came from",
          len(posts) == 1 and posts[0][1] == DM_CHANNEL, posts)
    check("silently, because nothing here is worth a ping", "--silent" in posts[0], posts)

    # THE DOORBELL ARRIVES TWICE. drain_events re-reads from the last cursor after a crash and
    # the Gateway replays dispatches across a resume; with no conversation row to collide on,
    # the outbound local_id is the only thing standing between a player and two identical
    # messages.
    case.events({"ts": "2026-08-21T00:00:01Z", "kind": "player_dm", "channel": None,
                 "channel_id": DM_CHANNEL, "id": "5201", "author_id": PLAYER})
    case.watcher.drain_events()
    case.watcher.send_pending()
    check("a replayed doorbell for the same message says nothing twice",
          len(case.rows("SELECT * FROM outbound")) == 1, case.rows("SELECT * FROM outbound"))

    # A SECOND MESSAGE, which is a person typing again rather than a doorbell repeating. They
    # get told once; the same sentence three times reads as a broken bot, not as a policy.
    fixture["messages"][DM_CHANNEL].append(
        message(5202, "hello?", channel=DM_CHANNEL))
    case.write_fixture(fixture)
    case.events({"ts": "2026-08-21T00:00:02Z", "kind": "player_dm", "channel": None,
                 "channel_id": DM_CHANNEL, "id": "5202", "author_id": PLAYER})
    case.watcher.drain_events()
    case.watcher.send_pending()
    check("and a follow-up inside the cooldown is left alone",
          len(sent_calls(case)) == 1, sent_calls(case))


def test_a_dm_doorbell_never_grants_the_trust_it_claims():
    """ffwatch re-decides who wrote it, whichever kind the listener rang.

    Both directions, because the doorbell is a file on disk that anything on this box could
    append to, and the whole trust story rests on the author id being Discord's rather than the
    listener's opinion of it.
    """
    print("a DM doorbell is a hint, not a grant")
    fixture = base_fixture()
    fixture["channel_objects"] = {DM_CHANNEL: {"id": DM_CHANNEL, "type": 1,
                                               "recipients": [{"id": PLAYER}]}}
    fixture["messages"][DM_CHANNEL] = [message(5301, "let me in", channel=DM_CHANNEL)]
    case = Case("dm-forged", fixture)
    case.cfg["operators"] = {"lothsahn": {"discord": LOTHSAHN, "model": SUITE_CLAUDE_NAME}}
    # A forged doorbell: the listener would never emit this for a player's id.
    case.events({"ts": "2026-08-21T00:00:00Z", "kind": "operator_dm", "channel": None,
                 "channel_id": DM_CHANNEL, "id": "5301", "author_id": PLAYER})
    case.watcher.drain_events()
    check("a DM doorbell naming a non-operator opens no conversation, whatever kind it claims",
          case.rows("SELECT * FROM conversation") == [],
          case.rows("SELECT * FROM conversation"))
    check("it is answered with the standing note instead",
          len(case.rows("SELECT * FROM outbound")) == 1, case.rows("SELECT * FROM outbound"))

    # And the other way: a `player_dm` from an operator is still an operator's conversation.
    op = base_fixture()
    op["channel_objects"] = {DM_CHANNEL: {"id": DM_CHANNEL, "type": 1,
                                          "recipients": [{"id": LOTHSAHN}]}}
    op["messages"][DM_CHANNEL] = [message(5302, "what broke the belt merger?", channel=DM_CHANNEL,
                                          author=LOTHSAHN, name="lothsahn")]
    case2 = Case("dm-underclaimed", op)
    case2.cfg["operators"] = {"lothsahn": {"discord": LOTHSAHN, "model": SUITE_CLAUDE_NAME}}
    case2.events({"ts": "2026-08-21T00:00:00Z", "kind": "player_dm", "channel": None,
                  "channel_id": DM_CHANNEL, "id": "5302", "author_id": LOTHSAHN})
    case2.watcher.drain_events()
    convs = case2.rows("SELECT * FROM conversation")
    check("and an operator under-claimed by the doorbell still gets a conversation",
          len(convs) == 1 and convs[0]["kind"] == "operator_dm", convs)
    check("with nothing queued at them", not case2.rows("SELECT * FROM outbound"),
          case2.rows("SELECT * FROM outbound"))


def test_tier_and_venue_reach_the_container():
    print("trust and venue on the job")
    fixture = base_fixture()
    fixture["messages"][ASK_CHANNEL] = [
        message(4501, "what file defines the belt merger?", author=LOTHSAHN, name="lothsahn")]
    case = Case("tier-public", fixture)
    case.cfg["operators"] = {"lothsahn": {"discord": LOTHSAHN, "model": SUITE_CLAUDE_NAME}}
    case.events(ask_event(4501))
    case.watcher.drain_events()
    case.watcher.claim_turns()
    turn = case.rows("SELECT * FROM turn")[0]
    check("an authenticated operator id makes an operator turn",
          turn["trust_tier"] == "operator", turn)
    check("and the reason names the config key it came from",
          "trust.operators.lothsahn" in (turn["trust_reason"] or ""), turn["trust_reason"])
    check("a public channel is a public venue however trusted the asker",
          turn["venue"] == "public", turn)

    case.watcher.launch(turn["id"])
    run = case.watcher.db.one("SELECT * FROM run WHERE turn_id=?", (turn["id"],))
    job = json.load(open(os.path.join(os.path.dirname(run["stream_path"]), "job.json"),
                         encoding="utf-8"))
    check("the job carries the tier as a fact", job["trust"]["tier"] == "operator", job["trust"])
    prompt = job["prompt"]
    check("the prompt states it as a HARNESS FACT rather than leaving it to be inferred",
          "HARNESS FACT" in prompt and "OPERATOR" in prompt, prompt[:400])
    check("and tells it to write a public half that stands alone",
          "STANDS ALONE" in prompt and "private half" in prompt, prompt[:800])
    # AND WHERE THE PLUGINS ARE. This branch tells the agent to follow a role it must open BY
    # PATH, and cwd is the workspace -- so a directory the prompt does not name is one the agent
    # has no reason to look in, whatever --add-dir granted. Every mounted plugin is named, not
    # just the one carrying the role.
    check("and names every plugin directory it was given, so their files can be opened",
          job["plugin_dirs"] and all(d in prompt for d in job["plugin_dirs"]),
          (job.get("plugin_dirs"), prompt[:400]))
    # VOICE IS THE VENUE'S DECISION, not the asker's. This is an OPERATOR asking, and the answer
    # still goes out as Max, because a player scrolling the channel finds it either way.
    check("a public venue takes the ff-discord voice however trusted the asker",
          "role and the ff-discord skills for policy and voice" in prompt, prompt[:600])

    # The same person, in a channel declared private. No split, everything in place.
    priv = base_fixture()
    priv["channels"]["dev_chat"] = DEVCHAT
    priv["messages"][DEVCHAT] = [
        message(4601, "which file defines the belt merger?", channel=DEVCHAT,
                author=LOTHSAHN, name="lothsahn")]
    priv["messages"][DEVCHAT][0]["mentions"] = [{"id": BOT}]
    case2 = Case("tier-private", priv)
    case2.cfg["operators"] = {"lothsahn": {"discord": LOTHSAHN, "model": SUITE_CLAUDE_NAME}}
    case2.cfg["watch"]["dev_chat"] = {"kind": "ask", "forum": False,
                                      "venue": "private", "engage": "mention"}
    case2.events(ask_event(4601, channel="dev_chat", channel_id=DEVCHAT))
    case2.watcher.drain_events()
    case2.watcher.claim_turns()
    turn2 = case2.rows("SELECT * FROM turn")[0]
    check("a declared private channel is a private venue", turn2["venue"] == "private", turn2)
    case2.watcher.launch(turn2["id"])
    run2 = case2.watcher.db.one("SELECT * FROM run WHERE turn_id=?", (turn2["id"],))
    job2 = json.load(open(os.path.join(os.path.dirname(run2["stream_path"]), "job.json"),
                          encoding="utf-8"))
    check("the private prompt says answer fully",
          "PRIVATE channel" in job2["prompt"] and "Answer fully" in job2["prompt"],
          job2["prompt"][:600])
    check("and does not ask for a split", "STANDS ALONE" not in job2["prompt"])
    # THE OTHER THING THE VENUE DECIDES. Nobody but the people who run the box reads this, so
    # there is no audience for a persona -- and the exception has to be stated rather than
    # merely omitted, because the role file and the max-voice skill both say the voice binds
    # every surface that posts as Max.
    check("a private venue still names the role, for policy and process",
          "role for policy and process" in job2["prompt"], job2["prompt"][:600])
    check("but excepts the voice loudly enough to beat the role text it overrides",
          "VOICE does not apply" in job2["prompt"]
          and "`max-voice` skill" in job2["prompt"], job2["prompt"][:600])
    check("and never asks for the voice a public turn gets",
          "policy and voice" not in job2["prompt"], job2["prompt"][:600])


def test_a_player_never_inherits_an_operators_clearance():
    print("tier is a property of the turn")
    fixture = base_fixture()
    root = message(4701, "here is how it works", author=LOTHSAHN, name="lothsahn")
    # A REPLY, so both land in one conversation and one turn batches them. The reply is a
    # player's, and the turn answers both, so the whole turn is a player's.
    fixture["messages"][ASK_CHANNEL] = [
        root, message(4702, "wait, which file is that in?", ref=root)]
    case = Case("tier-mixed", fixture)
    case.cfg["operators"] = {"lothsahn": {"discord": LOTHSAHN, "model": SUITE_CLAUDE_NAME}}
    case.events(ask_event(4701), ask_event(4702))
    case.watcher.drain_events()
    case.watcher.claim_turns()
    tiers = {t["trust_tier"] for t in case.rows("SELECT * FROM turn")}
    check("a batch that contains a player's message is a player's turn",
          tiers == {"player"}, case.rows("SELECT trust_tier, trust_actor FROM turn"))


def test_operator_table_holds_ids_only():
    print("operators")
    cfg = {"_discord": {"trust": {"operators": {
        "ben": "226422780445458432", "lothsahn": "193210319093497857",
        "impostor": ".slims"}}}}
    ops = ffwatch.operators(cfg)
    check("a username entry is dropped rather than kept", "impostor" not in ops, ops)
    check("the two real ids survive",
          set(ops.values()) == {"226422780445458432", "193210319093497857"}, ops)
    check("an authenticated author id matches",
          ffwatch.is_operator(cfg, "193210319093497857"))
    check("an author id that is merely SIMILAR does not",
          not ffwatch.is_operator(cfg, "19321031909349785"))
    check("a name is never a trust key", not ffwatch.is_operator(cfg, "lothsahn"))
    check("no table means nobody is an operator",
          ffwatch.operators({}) == {} and not ffwatch.is_operator({}, "193210319093497857"))
    check("a table of usernames also means nobody",
          not ffwatch.is_operator({"_discord": {"trust": {"operators": {"ben": "slims"}}}},
                                  "slims"))


def test_which_pool_a_discord_author_gets_is_read_from_the_trust_table():
    """user_pool for a stranger, operator_pool for an account in trust.operators.

    A configuration reader and nothing else: the same is_operator() the trust tier uses, an
    authenticated snowflake, no message text anywhere near it.
    """
    print("discord pools")
    cfg = {"_discord": {"trust": {"operators": {"lothsahn": LOTHSAHN}}}}
    check("a stranger opens in the fenced class",
          ffwatch.discord_agent_class(cfg, PLAYER) == "ffagent", None)
    check("an operator opens in the unfenced one",
          ffwatch.discord_agent_class(cfg, LOTHSAHN) == "ffdev", None)
    check("no author at all is a stranger", ffwatch.discord_agent_class(cfg, "") == "ffagent")
    check("and a box with no operators has only strangers",
          ffwatch.discord_agent_class({}, LOTHSAHN) == "ffagent", None)

    # Both keys are configurable, so a box that does not want the split can point them at one
    # class -- which is also how you put operator traffic back behind the fence.
    same = {"_discord": {"trust": {"operators": {"lothsahn": LOTHSAHN}},
                         "user_pool": "ffagent", "operator_pool": "ffagent"}}
    check("operator_pool can be pointed back at the fenced class",
          ffwatch.discord_agent_class(same, LOTHSAHN) == "ffagent", None)

    # A NAME THAT IS NOT A CLASS falls back rather than propagating. Writing 'ffdevv' on a
    # conversation would match no pool on any later turn of it, so the run would never find a
    # container -- a typo must cost a log line, not a lane.
    typo = {"_discord": {"trust": {"operators": {"lothsahn": LOTHSAHN}},
                         "user_pool": "ffdevv", "operator_pool": "ffagentt"}}
    check("a typo in user_pool falls back to ffagent",
          ffwatch.discord_agent_class(typo, PLAYER) == "ffagent", None)
    check("a typo in operator_pool falls back to ffdev",
          ffwatch.discord_agent_class(typo, LOTHSAHN) == "ffdev", None)


def test_where_a_conversation_goes_when_a_stranger_speaks_in_it():
    """The policy half of the demotion, keyed on the network rather than on a class name.

    A configuration reader like discord_agent_class() above: it answers WHERE, and
    demote_for_stranger() decides WHETHER anyone should be moved there.
    """
    print("stranger demotion: the policy")
    cfg = ffwatch.load_config()
    check("an unfenced conversation falls back to the fenced class",
          ffwatch.stranger_downgrade_class(cfg, "ffdev") == "ffagent", None)
    check("and one already behind the fence has nothing left to lose",
          ffwatch.stranger_downgrade_class(cfg, "ffagent") is None, None)

    # NOT BY NAME. A box that puts ffdev back behind the fence has two fenced classes and
    # nothing to demote, whatever the class is called.
    fenced = copy.deepcopy(cfg)
    fenced["agent_classes"]["ffdev"]["network"] = "limited"
    check("a class that is not unfenced is not demoted",
          ffwatch.stranger_downgrade_class(fenced, "ffdev") is None, None)

    # AND IT REFUSES TO MOVE ONE UNFENCED CLASS ONTO ANOTHER. A box whose user_pool is itself
    # "full" has opted out of the split; moving the conversation sideways would read as a
    # demotion while changing nothing about what the container can reach.
    opted_out = copy.deepcopy(cfg)
    opted_out["_discord"] = {"user_pool": "ffdev", "operator_pool": "ffdev"}
    check("a box with no fenced pool to fall back to moves nothing",
          ffwatch.stranger_downgrade_class(opted_out, "ffdev") is None, None)

    both = copy.deepcopy(cfg)
    both["_discord"] = {"user_pool": "ffagent", "operator_pool": "ffagent"}
    check("and user_pool is where it goes, read from the config",
          ffwatch.stranger_downgrade_class(both, "ffdev") == "ffagent", None)


def test_a_discord_conversation_opens_in_the_pool_its_opener_earns():
    """The ingress end of the same rule, and the "whoever opened it decides" half of it.

    Two cases rather than one because two messages in one channel would cluster into a single
    conversation, which is a different test.
    """
    print("discord pools: at the ingress")
    ops = {"operators": {"lothsahn": LOTHSAHN}}

    # A PLAYER OPENS ONE. Fenced, and an operator answering in it does not promote it: the
    # thread still carries a stranger's text, and moving the class under a live conversation
    # would move the clocks its session is running under besides.
    fixture = base_fixture()
    root = message(4801, "how do belts work?")
    fixture["messages"][ASK_CHANNEL] = [
        root, message(4802, "the splitter page covers it", author=LOTHSAHN, name="lothsahn",
                      ref=root)]
    case = Case("pool-player", fixture)
    case.cfg["_discord"]["trust"] = ops
    case.events(ask_event(4801), ask_event(4802))
    case.watcher.drain_events()
    convs = case.rows("SELECT * FROM conversation")
    check("a player's message opens one conversation", len(convs) == 1, convs)
    check("in the fenced class", convs[0]["agent_class"] == "ffagent", convs)
    check("and an operator answering in it does not promote it",
          case.rows("SELECT COUNT(*) c FROM message")[0]["c"] == 2
          and convs[0]["agent_class"] == "ffagent", convs)

    # AN OPERATOR OPENS ONE. Unfenced -- until a player joins in, which is the case worth
    # knowing about, and which now takes the class back rather than carrying the player's text
    # into a container with the whole internet in it.
    fixture2 = base_fixture()
    root2 = message(4811, "look at the belt throughput regression", author=LOTHSAHN,
                    name="lothsahn")
    case2 = Case("pool-operator", fixture2)
    case2.cfg["_discord"]["trust"] = ops
    ev = ask_event(4811)
    ev["author_id"] = LOTHSAHN
    fixture2["messages"][ASK_CHANNEL] = [root2]
    case2.write_fixture(fixture2)
    case2.events(ev)
    case2.watcher.drain_events()
    convs2 = case2.rows("SELECT * FROM conversation")
    check("an operator's message opens one conversation", len(convs2) == 1, convs2)
    check("in the unfenced class", convs2[0]["agent_class"] == "ffdev", convs2)

    # AND THE BOT'S OWN REPLY DOES NOT DEMOTE IT. Max's answers come back through the sweep
    # like every other message in the thread; if they counted, every unfenced conversation
    # would fence itself on its own first answer.
    fixture2["messages"][ASK_CHANNEL] = [
        root2, message(4812, "on it", author=BOT, name="max", bot=True, ref=root2)]
    case2.write_fixture(fixture2)
    case2.events(ask_event(4812))
    case2.watcher.drain_events()
    convs2 = case2.rows("SELECT * FROM conversation")
    check("our own bot answering in it does not demote it",
          convs2[0]["agent_class"] == "ffdev", convs2)

    # A PLAYER DOES. One message from anybody not in trust.operators, and the rest of the
    # conversation runs behind the fence.
    fixture2["messages"][ASK_CHANNEL].append(message(4813, "seeing it too", ref=root2))
    case2.write_fixture(fixture2)
    case2.events(ask_event(4813))
    case2.watcher.drain_events()
    convs2 = case2.rows("SELECT * FROM conversation")
    check("a player joining demotes it to the fenced class",
          case2.rows("SELECT COUNT(*) c FROM message")[0]["c"] == 3
          and convs2[0]["agent_class"] == "ffagent", convs2)

    # ONE-WAY. The operator speaking again does not buy the network back -- the player's text
    # is in the chain and in the session transcript this conversation resumes.
    fixture2["messages"][ASK_CHANNEL].append(
        message(4814, "fixed on my branch", author=LOTHSAHN, name="lothsahn", ref=root2))
    case2.write_fixture(fixture2)
    case2.events(ask_event(4814))
    case2.watcher.drain_events()
    convs2 = case2.rows("SELECT * FROM conversation")
    check("and the operator answering again does not promote it back",
          convs2[0]["agent_class"] == "ffagent", convs2)

    # AND THE TURN'S TIER IS STILL THE TURN'S. The class says which container; trust_tier says
    # what that container may say and do. A player in the batch makes the turn a player's
    # however unfenced the box it runs in.
    case2.watcher.claim_turns()
    tiers = {t["trust_tier"] for t in case2.rows("SELECT * FROM turn")}
    check("a player in an operator's conversation still makes a player's turn",
          tiers == {"player"}, case2.rows("SELECT trust_tier, trust_actor FROM turn"))


def test_no_channel_is_watched_unless_the_config_says_so():
    """The regression this whole file exists to pin: a config naming ONE channel used to get
    four more added to it, because _deep_merge recurses and DEFAULTS shipped a populated watch
    table. The box then swept #dev-chat every catchup_secs and nobody could say "not that one",
    because the table could only be added to."""
    print("watch is config-only")
    check("nothing ships a channel", ffwatch.DEFAULTS["watch"] == {},
          ffwatch.DEFAULTS["watch"])
    only_one = ffwatch._deep_merge(ffwatch.DEFAULTS, {"watch": {
        "agent_testing": {"kind": "ask", "forum": False,
                          "venue": "private", "engage": "mention"},
    }})
    check("a config naming one channel watches exactly that one",
          list(only_one["watch"]) == ["agent_testing"], list(only_one["watch"]))
    for gone in ("ask_claude", "bug_reports", "suggestions", "dev_chat"):
        check(f"{gone} is not inherited from anywhere", gone not in only_one["watch"])
    check("and a config with no watch block at all watches nothing",
          ffwatch._deep_merge(ffwatch.DEFAULTS, {})["watch"] == {})
    # The other half of the same rule: the source files must not name a channel either, or the
    # default creeps back in as a fallback somewhere.
    for name in ("ffwatch.py", "06-services.sh"):
        body = open(os.path.join(HERE, name), encoding="utf-8").read()
        for token in ('"ask_claude"', '"bug_reports"', '"suggestions"', '"dev_chat"',
                      "ask_claude,bug_reports"):
            check(f"{name} does not hard-code {token}", token not in body)


def test_sweep_uses_the_id_once_the_config_has_one():
    """sweep_target re-reads the discord.channels table from DISK every call, because
    `ffdiscord read <alias>` writes a resolved id back into it. That is what makes the name lookup happen once
    instead of on every sweep forever."""
    print("sweep targets")
    case = Case("sweep-targets")

    def channels_on_disk(table):
        with open(ffwatch.FFBOX_CONFIG, "w", encoding="utf-8") as fh:
            json.dump({"discord": {"channels": table}}, fh)

    try:
        channels_on_disk({})
        check("an alias with no id is passed by name, which is what lets it resolve once",
              case.watcher.sweep_target("agent_testing") == "agent_testing")
        channels_on_disk({"agent_testing": ASK_CHANNEL})
        check("and the snowflake is used the moment the file has it",
              case.watcher.sweep_target("agent_testing") == ASK_CHANNEL)
        channels_on_disk({"agent_testing": "   "})
        check("a blank id is not an id",
              case.watcher.sweep_target("agent_testing") == "agent_testing")
    finally:
        if os.path.exists(ffwatch.FFBOX_CONFIG):
            os.remove(ffwatch.FFBOX_CONFIG)

    # An id written back at RUNTIME must be visible to everything that maps an id to an alias,
    # not just to the sweep. cfg["_discord"] is a start-up snapshot and ffwatch never reloads
    # it, so a config-only lookup would call the channel unknown and fall closed: no ping, and
    # a private channel silently treated as public.
    case.cfg["_discord"] = {"channels": {}}
    case.cfg["watch"]["escalation"] = {"kind": "ask", "forum": False,
                                       "venue": "private", "engage": "mention", "ping": True}
    check("before the id exists, an unknown channel falls closed",
          not case.watcher.ping_allowed({"ping": True}, DEVCHAT)
          and ffwatch.venue_for(case.cfg, ffwatch.alias_for_channel(case.cfg, DEVCHAT))
          == "public")
    try:
        with open(ffwatch.FFBOX_CONFIG, "w", encoding="utf-8") as fh:
            json.dump({"discord": {"channels": {"escalation": DEVCHAT}}}, fh)
        check("an id resolved after start-up is seen without restarting ffwatch",
              ffwatch.alias_for_channel(case.cfg, DEVCHAT) == "escalation")
        check("so the escalation may ping",
              case.watcher.ping_allowed({"ping": True}, DEVCHAT))
        check("and the channel is private, as declared",
              ffwatch.venue_for(case.cfg, ffwatch.alias_for_channel(case.cfg, DEVCHAT))
              == "private")
    finally:
        if os.path.exists(ffwatch.FFBOX_CONFIG):
            os.remove(ffwatch.FFBOX_CONFIG)
    del case.cfg["watch"]["escalation"]

    # Repeated failures are one line, not four an hour: the sweep runs every catchup_secs.
    case.cfg["watch"] = {"nowhere": {"kind": "ask", "forum": False}}
    logged = []
    real_log, real_ffd = ffwatch.log, ffwatch.ffd_json
    ffwatch.log = lambda m: logged.append(m)
    ffwatch.ffd_json = lambda *a, **k: (_ for _ in ()).throw(
        ffwatch.FFDiscordError("could not resolve channel 'nowhere'"))
    try:
        case.watcher.sweep()
        case.watcher.sweep()
        case.watcher.sweep()
    finally:
        ffwatch.log, ffwatch.ffd_json = real_log, real_ffd
    check("an unresolvable alias is reported once per process, not once per sweep",
          len(logged) == 1, logged)
    check("and the line says how to fix it",
          "channels.nowhere" in logged[0] and "watch block" in logged[0], logged)


def test_venue_and_engage_come_from_the_watch_entry():
    print("venue and engage")
    cfg = ffwatch._deep_merge(ffwatch.DEFAULTS, {"watch": {
        "dev_chat": {"kind": "ask", "forum": False, "venue": "private", "engage": "mention"},
        "half_done": {"kind": "ask", "forum": False},
        "nonsense": {"kind": "ask", "venue": "secret", "engage": "sometimes"},
    }})
    check("a declared private channel reads back private",
          ffwatch.venue_for(cfg, "dev_chat") == "private")
    check("and mention-only reads back mention",
          ffwatch.engage_for(cfg, "dev_chat") == "mention")
    check("an entry with no venue or engage falls closed to public and mention",
          (ffwatch.venue_for(cfg, "half_done"), ffwatch.engage_for(cfg, "half_done"))
          == ("public", "mention"))
    check("an entry with junk values falls closed the same way",
          (ffwatch.venue_for(cfg, "nonsense"), ffwatch.engage_for(cfg, "nonsense"))
          == ("public", "mention"))
    check("a channel with no entry at all is public and mention-only",
          (ffwatch.venue_for(cfg, "never_heard_of_it"),
           ffwatch.engage_for(cfg, "never_heard_of_it")) == ("public", "mention"))


def test_config_warnings_name_every_silent_default():
    print("config warnings")
    quiet = ffwatch._deep_merge(ffwatch.DEFAULTS, {"watch": {
        "agent_testing": {"kind": "ask", "forum": False,
                          "venue": "private", "engage": "mention"}}})
    quiet["_discord"] = {"trust": {"operators": {"ben": "226422780445458432"}}}
    check("a fully declared config warns about nothing",
          ffwatch.config_warnings(quiet) == [], ffwatch.config_warnings(quiet))
    # The shipped state is now "watches nothing", which is safe but is NOT what most people
    # think they installed. It looks identical in the journal to a working box otherwise.
    empty = ffwatch._deep_merge(ffwatch.DEFAULTS, {})
    empty["_discord"] = {"trust": {"operators": {"ben": "226422780445458432"}}}
    check("an empty watch block says so, rather than looking like a working box",
          any("watch block is empty" in w for w in ffwatch.config_warnings(empty)),
          ffwatch.config_warnings(empty))
    bare = ffwatch._deep_merge(ffwatch.DEFAULTS, {"watch": {"mystery": {"kind": "ask"}}})
    bare["_discord"] = {}
    warnings = " | ".join(ffwatch.config_warnings(bare))
    check("a missing operator table is called out by name",
          "trust.operators" in warnings and "NOBODY" in warnings, warnings)
    check("an undeclared venue says which channel and which way it fell",
          "watch.mystery" in warnings and "PUBLIC" in warnings, warnings)
    check("an undeclared engage does too",
          "MENTION" in warnings, warnings)
    usernames = ffwatch._deep_merge(ffwatch.DEFAULTS, {})
    usernames["_discord"] = {"trust": {"operators": {"ben": ".slims"}}}
    check("a table of usernames warns that it holds no ids",
          "no numeric discord ids" in " ".join(ffwatch.config_warnings(usernames)),
          ffwatch.config_warnings(usernames))
    # AND IT NAMES WHICHEVER LOCATION THIS BOX ACTUALLY USES. Telling somebody whose operators
    # are all in the old place to go and look at an empty new one is worse than saying nothing.
    check("a box that predates the move is pointed at the old location",
          "discord.trust.operators" in " ".join(ffwatch.config_warnings(usernames)),
          ffwatch.config_warnings(usernames))
    moved = ffwatch._deep_merge(ffwatch.DEFAULTS, {})
    moved["operators"] = {"ben": {"discord": ".slims"}}
    warned = " ".join(ffwatch.config_warnings(moved))
    check("and a box that has moved is pointed at the new one",
          "operators in the config" in warned and "discord.trust" not in warned, warned)


BOT = "999000999"


def test_a_mention_only_channel_stays_quiet():
    """An unaddressed message never STARTS anything. What changed is that it is no longer lost.

    Before clustering each of these was its own conversation, so the mention arrived with no
    antecedent for whatever it was following on from. They are now one conversation, and the
    two orderings differ in a way worth pinning separately: a message already declined by the
    gate is excluded from the next turn's `messages` (create_turn filters on gate IS NULL) but
    still reaches the prompt as `history`, which is exactly where an unasked-for aside belongs.
    """
    print("engage: mention")
    quiet_id, mention_id = sflake(0, 1), sflake(90, 2)
    fixture = base_fixture()
    fixture["messages"][ASK_CHANNEL] = [
        message(quiet_id, "anyone else seeing this on develop?"),
        message(mention_id, "hey @max what does the splitter do?", attachments=None),
    ]
    fixture["messages"][ASK_CHANNEL][1]["mentions"] = [{"id": BOT}]
    case = Case("engage-mention", fixture)
    case.cfg["watch"]["ask_claude"]["engage"] = "mention"
    case.events(ask_event(quiet_id), ask_event(mention_id))
    case.watcher.drain_events()
    check("both messages land in ONE conversation",
          len(case.rows("SELECT * FROM conversation")) == 1,
          case.rows("SELECT id, thread_id FROM conversation"))
    case.watcher.claim_turns()
    turns = case.rows("SELECT * FROM turn")
    check("the mention makes exactly one turn", len(turns) == 1, turns)
    claimed = {m["discord_id"] for m in
               case.rows("SELECT * FROM message WHERE turn_id IS NOT NULL")}
    check("and the message it was following on from comes with it, rather than being lost",
          claimed == {quiet_id, mention_id}, claimed)

    # The other ordering: the aside is seen, and declined, before the mention arrives.
    case2 = Case("engage-mention-2", fixture)
    case2.cfg["watch"]["ask_claude"]["engage"] = "mention"
    case2.events(ask_event(quiet_id))
    case2.watcher.drain_events()
    case2.watcher.claim_turns()
    check("an unaddressed message on its own makes no turn",
          case2.rows("SELECT * FROM turn") == [], case2.rows("SELECT * FROM turn"))
    quiet = case2.rows("SELECT * FROM message WHERE discord_id=?", (quiet_id,))[0]
    check("the ordinary message is recorded, not dropped", quiet["content"], quiet["content"])
    check("and marked so the scheduler stops reconsidering it", quiet["gate"] == "none", quiet)
    check("with a reason a human can read", "mention-only" in (quiet["gate_reason"] or ""),
          quiet["gate_reason"])
    case2.events(ask_event(mention_id))
    case2.watcher.drain_events()
    case2.watcher.claim_turns()
    check("the later mention makes a turn", len(case2.rows("SELECT * FROM turn")) == 1)
    turn = case2.rows("SELECT * FROM turn")[0]
    job = case2.watcher.build_job(
        turn, case2.rows("SELECT * FROM conversation")[0], "r1",
        os.path.join(case2.root, "att"))
    check("the declined message is not in the turn's messages",
          [m["discord_id"] for m in job["messages"]] == [mention_id], job["messages"])
    check("but it IS in the history the agent is given, which is where an aside belongs",
          quiet_id in [m["discord_id"] for m in job["history"]], job["history"])
    case2.watcher.claim_turns()
    check("a second pass does not resurrect it",
          len(case2.rows("SELECT * FROM turn")) == 1)


def test_a_thread_creation_notice_is_not_somebody_talking():
    """Discord's own events arrive as messages, and one of them impersonates a question well.

    THREAD_CREATED (type 18) lands in the PARENT channel carrying the thread's NAME as its
    content, the author of whoever opened it, and THE THREAD'S OWN ID as its message id. Seen
    on the build server 2026-09-06, the day agent_testing moved to `engage: all`: the title
    "Counting Lines of Code 4" was ingested as a message, engaged on its own, and ran a full
    container turn that Discord then refused every word of — that id is not a message inside
    the thread, so the ack came back 404 and the reply 400. The run was invisible end to end
    while holding the conversation busy, and the real follow-up typed meanwhile waited on it.

    The case runs on the suite's default watch block, which is `engage: all` with a classifier
    that fails open — the exact conditions that let the title through.
    """
    print("system messages: a thread notice is not a question")
    title_id, real_id = sflake(0, 1), sflake(60, 2)
    fixture = base_fixture()
    fixture["messages"][ASK_CHANNEL] = [
        message(title_id, "Counting Lines of Code 4", mtype=18),
        message(real_id, "how many lines does that branch add?"),
    ]
    case = Case("system-thread-notice", fixture)
    case.watcher.sweep()
    case.watcher.claim_turns()
    turns = case.rows("SELECT * FROM turn")
    check("the thread notice does not make a turn of its own", len(turns) == 1, turns)
    claimed = [m["discord_id"] for m in
               case.rows("SELECT * FROM message WHERE turn_id IS NOT NULL")]
    check("and the one turn there is belongs to what the person actually typed",
          claimed == [real_id], claimed)
    check("the notice is never stored, so it opens no conversation of its own",
          case.rows("SELECT * FROM message WHERE discord_id=?", (title_id,)) == [],
          case.rows("SELECT * FROM message"))
    check("one conversation, not two", len(case.rows("SELECT * FROM conversation")) == 1,
          case.rows("SELECT id, title FROM conversation"))

    # THE DOORBELL SAYS IT TOO. The sweep is what fired in production, but this path is the one
    # that opens conversations, and the notice's id IS the thread's — so an unfiltered doorbell
    # would file the title into the thread's own conversation as though somebody had typed it.
    case.events(ask_event(title_id))
    case.watcher.drain_events()
    case.watcher.claim_turns()
    check("a doorbell carrying the same notice is refused as well",
          case.rows("SELECT * FROM message WHERE discord_id=?", (title_id,)) == [])
    check("and still no second conversation",
          len(case.rows("SELECT * FROM conversation")) == 1)

    # THE DIRECTION THIS MUST FAIL IN. A payload with no `type` at all is a person's. Discord
    # has always sent the field; silencing real messages over a shape nobody imagined is the
    # one outcome worse than answering a title.
    typeless_id = sflake(120, 3)
    fixture = case.read_fixture()
    typeless = message(typeless_id, "and does that include the tests?")
    typeless.pop("type")
    fixture["messages"][ASK_CHANNEL].append(typeless)
    case.write_fixture(fixture)
    case.watcher.sweep()
    stored = case.rows("SELECT * FROM message WHERE discord_id=?", (typeless_id,))
    check("a message with no type at all is read as a person's, not as Discord's",
          stored and stored[0]["gate"] is None, stored)


def test_a_system_event_inside_a_thread_is_history_and_nothing_else():
    """The other way in. A thread bundle carries whatever Discord filed inside the thread
    alongside the real posts, and those reach insert_message rather than the sweep's filter —
    so they come in GATED instead of dropped, exactly as a pre-attach message does. The row is
    what advances in_watermark_id past them, and the report itself still opens its turn."""
    print("system messages: inside a thread")
    post_id, pinned_id = sflake(0, 1), sflake(60, 2)
    fixture = base_fixture()
    bug_thread(fixture, "31000", "belt merger drops items", [
        message(post_id, "it drops one item in eight", channel="31000"),
        message(pinned_id, "", channel="31000", mtype=6),      # CHANNEL_PINNED_MESSAGE
    ])
    fixture["thread_lists"][BUG_FORUM] = [{"id": "31000", "name": "belt merger drops items"}]
    case = Case("system-in-thread", fixture)
    case.watcher.sweep()
    case.watcher.claim_turns()
    stored = {m["discord_id"]: m for m in case.rows("SELECT * FROM message")}
    check("the system event is kept as history", pinned_id in stored, sorted(stored))
    check("but marked so no scheduler pass reconsiders it",
          stored.get(pinned_id, {}).get("gate") == "none", stored.get(pinned_id))
    check("with a reason naming Discord rather than the engagement gate",
          "system message" in (stored.get(pinned_id, {}).get("gate_reason") or ""),
          stored.get(pinned_id, {}).get("gate_reason"))
    turns = case.rows("SELECT * FROM turn")
    check("the report still opens its turn", len(turns) == 1, turns)
    claimed = [m["discord_id"] for m in
               case.rows("SELECT * FROM message WHERE turn_id IS NOT NULL")]
    check("and that turn claims the post alone", claimed == [post_id], claimed)


