PLAYTEST_EDITOR_STUB = r"""#!/bin/sh
# Stub unity-editor for ffplaytest: a WRAPPER, like the real one (which execs xvfb-run), so the
# test can prove the whole process group dies rather than just the wrapper.
#
# It asserts the config is there, emits the phase lines the real bootstrap logs, and writes a
# label-scoped journal where the real session writes one.
PROJ=""
while [ $# -gt 0 ]; do
  case "$1" in -projectPath) PROJ=$2; shift 2 ;; *) shift ;; esac
done
CFG="$PROJ/.ff-local-automation.json"
[ -f "$CFG" ] || { echo "STUB: launched with no automation config"; exit 9; }
cp "$CFG" "$STUB_CONFIG_COPY"
LABEL=$(python3 -c "import json,sys;print(json.load(open(sys.argv[1]))['Label'])" "$CFG")
echo "[LocalMultiplayerAutomation] status host-listening: port=7777"
echo "[LocalMultiplayerAutomation] status pre-connect-command-start: chain"
D="$FFPLAYTEST_PDP/PlaytestSessions/$LABEL"
mkdir -p "$D"
printf '%s\n%s\n' \
  '{"seq":1,"event":"commandIssued","cmd":"ffauto:blueprint.place"}' \
  '{"seq":2,"event":"commandResult","ok":true}' > "$D/journal.jsonl"
printf '{"label":"%s"}\n' "$LABEL" > "$D/session.json"
# A grandchild that outlives a naive kill of this wrapper, recorded so the test can check it.
sh -c 'sleep 120' &
echo "$!" >> "$STUB_PIDS"
echo "$$" >> "$STUB_PIDS"
echo "[LocalMultiplayerAutomation] status pre-connect-command-complete: chain"
wait
"""


FFMCP_EDITOR_STUB = """#!/bin/sh
# Stub unity-editor for ffmcp, in the shape the REAL one has -- measured in a container on
# 2026-09-11 and not what the first version of this stub assumed:
#
#     wrapper (bash /usr/bin/unity-editor)   pgid = ours
#       xvfb-run                             pgid = ours
#         Xvfb                               pgid = ours
#         /opt/unity/Editor/Unity            pgid = ITS OWN      <- escapes
#           AssetImportWorkerN               pgid = ITS OWN      <- and its workers
#
# So the editor is NOT in the process group ffmcp created, and a group kill never signals it. The
# `setsid` below reproduces exactly that, which is what makes this test worth having: without the
# descendant walk in ffmcp, the escaped child survives `ffmcp stop` and holds the licence seat.
# It carries -projectPath because that is what proves the process is ours to kill.
setsid python3 -c "
import socket, time
s = socket.socket(); s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
s.bind(('127.0.0.1', PORT_PLACEHOLDER)); s.listen(5)
print('MCP-FOR-UNITY: StdioBridgeHost started on port PORT_PLACEHOLDER. (OS=LinuxEditor)', flush=True)
time.sleep(300)
" -projectPath "$FFMCP_PROJECT" &
echo "$!" >> "$STUB_PIDS"
echo "$$" >> "$STUB_PIDS"
wait
"""


def test_the_live_editor_is_off_until_a_class_asks_for_it():
    """The MCP bridge is a per-class switch, and OFF is the shape that must not drift.

    A class that has not asked for a live editor must see NOTHING of it. A class that HAS asked must
    get the tools in BOTH lists -- the Workflow lesson, measured on 2026-09-06: running a tool
    raises a permission request, and a `-p` run has nobody to answer it, so a tool named in --tools
    alone buys a turn that dies at its first call.
    """
    print("the live editor: off by default, both lists when on")
    for name, blk in ffwatch.DEFAULTS["agent_classes"].items():
        mcp = blk.get("unity_mcp") or {}
        check(f"{name} carries unity_mcp, off, with a readiness ceiling",
              mcp.get("enabled") is False and int(mcp.get("ready_timeout_secs")) == 600, mcp)

    off = ffwatch.capabilities_for("dev", {"unity_mcp": {"enabled": False}})
    check("off: the tool list is exactly what it was",
          off["tools"] == ffwatch.CAPABILITY_TOOLS, off["tools"])
    check("off: nothing mcp-shaped on the allow list",
          not any(a.startswith("mcp__") for a in off["allowed"]), off["allowed"])

    on = ffwatch.capabilities_for("dev", {"unity_mcp": {"enabled": True}})
    names = ffwatch.mcp_tool_names()
    tools = on["tools"].split(",")
    check("on: every curated tool is offered", all(n in tools for n in names),
          [n for n in names if n not in tools])
    check("on: and every one is ALLOWED too, or a -p run dies at its first call",
          all(n in on["allowed"] for n in names),
          [n for n in names if n not in on["allowed"]])
    check("on: the base tools are still there", "Bash" in tools and "Edit" in tools, tools[:8])
    check("the server is named UnityMCP, matching the mcp__UnityMCP__* the roles already use",
          all(n.startswith("mcp__UnityMCP__") for n in names), names[:3])

    # The curation is the point: a turn does NOT get all 46 tools the server offers.
    check("the script-mutation tools are absent -- Edit/Write are the channel a reviewer reads",
          not any(n.endswith(("__create_script", "__delete_script", "__script_apply_edits",
                              "__apply_text_edits", "__validate_script")) for n in names), names)
    check("and so are the generation/import tools, which would reach outside the fence",
          not any("generate_" in n or "import_model" in n for n in names), names)

    # THE SWITCH HAS TO BE REACHABLE FROM THE FILE, and for a while it was not: the DEFAULTS dict
    # is called `agent_classes` but the CONFIG FILE's per-class section is `pools`, and
    # _class_blocks rebuilds every class from _pool_section AFTER the deep merge -- so an
    # `agent_classes` block in config.json is read by nothing at all. Phase F found that by being
    # unable to turn the feature on; this is the check that keeps it found.
    def to_int(value, fallback):
        try:
            return int(value)
        except (TypeError, ValueError):
            return fallback

    blocks = ffwatch._class_blocks(
        {"pools": {"ffdev": {"unity_mcp": {"enabled": True, "ready_timeout_secs": 900}}}},
        6, to_int)
    check("a pools.<class>.unity_mcp block in the FILE reaches the class config",
          blocks["ffdev"]["unity_mcp"] == {"enabled": True, "ready_timeout_secs": 900},
          blocks["ffdev"]["unity_mcp"])
    check("and one class asking for it does not turn it on for the other",
          blocks["ffagent"]["unity_mcp"]["enabled"] is False, blocks["ffagent"]["unity_mcp"])

    # FILLED IN, NOT COPIED, like pool/github/warm_branches: an operator writes {"enabled": true}
    # and every reader must still find a numeric timeout; a bool where a mapping belongs must not
    # reach a reader either.
    partial = ffwatch._class_blocks({"pools": {"ffdev": {"unity_mcp": {"enabled": True}}}},
                                    6, to_int)["ffdev"]["unity_mcp"]
    check("a partial unity_mcp still comes back with a numeric ready_timeout_secs",
          partial["enabled"] is True and isinstance(partial["ready_timeout_secs"], int)
          and partial["ready_timeout_secs"] == 600, partial)
    garbage = ffwatch._class_blocks({"pools": {"ffdev": {"unity_mcp": True}}},
                                    6, to_int)["ffdev"]["unity_mcp"]
    check("and a non-mapping unity_mcp falls back to this class's default rather than crashing",
          garbage == {"enabled": False, "ready_timeout_secs": 600}, garbage)
    bad_secs = ffwatch._class_blocks(
        {"pools": {"ffdev": {"unity_mcp": {"enabled": True, "ready_timeout_secs": "soon"}}}},
        6, to_int)["ffdev"]["unity_mcp"]
    check("a non-numeric readiness ceiling falls back instead of taking the daemon down",
          bad_secs == {"enabled": True, "ready_timeout_secs": 600}, bad_secs)

    # The review lane's extra tool and the editor's must coexist rather than replace each other.
    both = ffwatch.capabilities_for(ffwatch.GITHUB_KIND, {"unity_mcp": {"enabled": True}})
    check("a review lane with a live editor keeps Workflow AND gains the editor",
          ffwatch.REVIEW_TOOL in both["tools"] and names[0] in both["tools"],
          both["tools"][-120:])


def test_ffmcp_owns_the_editor_it_starts():
    """ffmcp against a stub editor: every property here is one a caller gets wrong.

    Readiness is the LOG LINE, not the port registry file -- PortManager writes that file only when
    it has to move off the default port, so the first probe of this feature waited five minutes for
    a file a healthy bridge never writes. The editor dies as a GROUP, because `unity-editor` is an
    xvfb-run wrapper whose children survive a pid-targeted signal and go on holding the licence
    seat. And a run whose class never asked for a bridge cannot start one.
    """
    print("ffmcp: readiness, the process group, and the gates")
    root = os.path.join(TMPROOT, "ffmcp")
    proj = os.path.join(root, "project")
    state = os.path.join(root, "state")
    bindir = os.path.join(root, "bin")
    for d in (os.path.join(proj, "Assets"), state, bindir):
        os.makedirs(d, exist_ok=True)
    script = os.path.join(HERE, "ffmcp.sh")
    pids_file = os.path.join(root, "stub-pids")
    port = 6473
    write_stub(os.path.join(bindir, "unity-editor"),
               FFMCP_EDITOR_STUB.replace("PORT_PLACEHOLDER", str(port)))
    open(pids_file, "w").close()

    def run(*args, enabled=True):
        # THE WAITS ARE TURNED DOWN, not removed: every path this test walks is still walked,
        # it just does not spend the production grace period doing it. The stub editor dies on
        # the first TERM, so a 3-second ceiling proves as much as a 20-second one -- and the
        # refusal path spends none of it at all now that stop skips the wait for a process it
        # deliberately did not signal.
        env = dict(os.environ, FFMCP_PROJECT=proj, FFMCP_STATE=state,
                   FFMCP_UNITY=os.path.join(bindir, "unity-editor"),
                   FFMCP_READY_TIMEOUT="60", FFMCP_STOP_GRACE="3", FFMCP_POLL_SECS="1",
                   STUB_PIDS=pids_file)
        if enabled:
            env["FFBOX_UNITY_MCP"] = "1"
        else:
            env.pop("FFBOX_UNITY_MCP", None)
        return subprocess.run(["bash", script, *args], capture_output=True, text=True,
                              env=env, timeout=180)

    off = run("start", enabled=False)
    check("a run whose class did not ask for a bridge cannot start one", off.returncode == 3,
          (off.returncode, off.stderr[-200:]))

    nopkg = run("start")
    check("a workspace with no MCP package degrades instead of booting an editor",
          nopkg.returncode == 3, (nopkg.returncode, nopkg.stderr[-200:]))
    check("and it names the package that is missing",
          "com.coplaydev.unity-mcp" in nopkg.stderr, nopkg.stderr[-200:])

    # The real repo resolves the package as a GIT dependency into Library/PackageCache with a hash
    # suffix -- Packages/com.coplaydev.unity-mcp does not exist there -- so the glob is the case
    # that matters, not the embedded copy the feasibility probe used.
    pkg = os.path.join(proj, "Library", "PackageCache", "com.coplaydev.unity-mcp@7b7db7b31f4e")
    os.makedirs(pkg, exist_ok=True)
    with open(os.path.join(pkg, "package.json"), "w", encoding="utf-8") as fh:
        fh.write('{"name":"com.coplaydev.unity-mcp","version":"10.0.0"}')

    started = run("start")
    check("start reports the port off the editor's own log line",
          started.returncode == 0 and str(port) in started.stdout,
          (started.returncode, started.stdout[-200:], started.stderr[-200:]))

    st = json.load(open(os.path.join(state, "state.json"), encoding="utf-8"))
    check("the state file records the bridge, the pid and the package version it found",
          st["phase"] == "up" and st["port"] == port and st["pid"] > 0
          and st["editor_package_version"] == "10.0.0", st)

    check("status agrees while it is up", run("status").returncode == 0, None)
    check("port prints just the port", run("port").stdout.strip() == str(port), None)
    again = run("start")
    check("a second start is idempotent rather than a second editor",
          again.returncode == 0 and "already up" in again.stdout, again.stdout[-160:])

    # THE GUARD THE OTHER TWO WRAPPERS CARRY: one project cannot hold two editors.
    guard_bin = os.path.join(root, "guardbin")
    os.makedirs(guard_bin, exist_ok=True)
    write_stub(os.path.join(guard_bin, "ffmcp"), "#!/bin/sh\nexit 0\n")
    for name, extra in (("ffverify.sh", []), ("ffplaytest.sh", ["--chain", "ffauto:wait|1"])):
        res = subprocess.run(["bash", os.path.join(HERE, name), "--project", proj,
                              "--out", os.path.join(root, "out"), *extra],
                             capture_output=True, text=True, timeout=120,
                             env=dict(os.environ,
                                      PATH=guard_bin + os.pathsep + os.environ["PATH"]))
        check(f"{name} refuses while a live bridge holds the project", res.returncode == 2,
              (res.returncode, res.stderr[-200:]))
        check(f"{name} names the fix rather than leaving Unity to explain it",
              "ffmcp stop" in res.stderr and "run_tests" in res.stderr, res.stderr[-200:])

    # A pid that is NOT our editor is never signalled, however the state file got that way: the
    # file lives on a mount the agent can write.
    forged = dict(st)
    forged["pid"] = os.getpid()
    forged["pgid"] = os.getpid()
    with open(os.path.join(state, "state.json"), "w", encoding="utf-8") as fh:
        json.dump(forged, fh)
    refused = run("stop")
    check("stop refuses a pid that is not an editor on this project rather than signalling it",
          "refusing to signal" in refused.stderr, refused.stderr[-200:])
    check("and this test process is still alive to say so", _pid_alive(os.getpid()), None)

    # Put the real pid back and stop for real.
    with open(os.path.join(state, "state.json"), "w", encoding="utf-8") as fh:
        json.dump(st, fh)
    stopped = run("stop")
    check("stop reports what it stopped", stopped.returncode == 0, stopped.stdout[-160:])
    alive = [int(x) for x in open(pids_file, encoding="utf-8").read().split()
             if _pid_alive(int(x))]
    for pid in alive:
        try:
            os.kill(pid, signal.SIGKILL)
        except OSError:
            pass
    check("the ESCAPED editor is gone too -- the real one is not in the group ffmcp made",
          not alive, alive)
    check("and status now says down", run("status").returncode == 1, None)


def test_the_harness_stops_the_bridge_before_it_reads_the_tree():
    """Source-level, because ORDER is the property and only production has the real order.

    Opening a Unity project RESERIALIZES ASSETS, and the commit after the agent exits is
    `git add -A` under the run's identity -- d133t5 is the worked example, a turn that edited
    nothing gaining a commit that changed a material. An editor open for the whole turn is that
    hazard with a much longer exposure, so it must be stopped before anything reads the tree, not
    merely before the harness's own ffverify.
    """
    print("the bridge is stopped before anything reads the tree")
    body = io.open(os.path.join(HERE, "discord-task.sh"), encoding="utf-8").read()

    boot = body.find("ffmcp start")
    argv_build = body.find('if ! python3 - "$JOB_FILE" "$FFBOX_OUT/argv"')
    agent = body.find(': > "$FFBOX_OUT/.agent-started"')
    check("the boot happens before the argv is built, which is what decides the tool list",
          0 < boot < argv_build, (boot, argv_build))
    check("and before .agent-started, so it is warm-up and not the model's clock",
          0 < boot < agent, (boot, agent))

    # CODE ONLY. Both of these strings appear in the prose that explains them as well, and a
    # naive find lands in a comment -- which is how the first version of this test failed while
    # the ordering it was checking was correct.
    def code_offset(needle, after=0):
        pos = after
        while True:
            pos = body.find(needle, pos)
            if pos < 0:
                return -1
            line_start = body.rfind("\n", 0, pos) + 1
            if not body[line_start:pos].lstrip().startswith("#"):
                return pos
            pos += len(needle)

    wait_line = body.find('wait "$FFBOX_AGENT_PID"')
    stop = code_offset("ffmcp stop", wait_line)
    # The real spelling, not the one the comments use: `git -C "$WORKSPACE" add -A -- .` with the
    # .github exclusion.
    staged = code_offset('add -A -- .', wait_line)
    verify = code_offset('ffverify --out "$FFBOX_OUT/verification"')
    check("the editor is stopped as soon as the agent is gone",
          0 < wait_line < stop, (wait_line, stop))
    check("BEFORE the tree is staged, or its reserialized assets become the agent's commit",
          stop < staged, (stop, staged))
    check("which is necessarily before the harness's own verification too", stop < verify,
          (stop, verify))

    # The exit trap covers the run that never reaches the line above at all, and it must go before
    # the harvest, which is the other thing that commits the tree.
    trap = body[body.find("_ffbox_finish() {"):body.find("trap _ffbox_finish")]
    trap_stop = trap.find("ffmcp stop")
    trap_harvest = trap.find("/ffbox/harvest-workspace.sh")
    check("a killed run stops the editor in the exit trap",
          trap_stop > 0, trap[:200])
    check("and does it before the harvest commits whatever the editor reserialized",
          0 < trap_stop < trap_harvest, (trap_stop, trap_harvest))

    check("a degraded turn drops the mcp tools from its own argv",
          "if not MCP_PORT:" in body and 'startswith("mcp__")' in body, None)
    check("and the prompt says the bridge is absent rather than leaving it to be inferred",
          "PREAMBLE_MCP_DEGRADED" in body, None)
    check("--strict-mcp-config is passed, so only the server this run wrote can load",
          "--strict-mcp-config" in body, None)


def test_ffplaytest_never_leaves_a_config_or_an_editor_behind():
    """The three things a play-mode run can do to the NEXT run, checked against the real script.

    A leftover `.ff-local-automation.json` auto-starts play mode on the next editor boot, and the
    next boot in a container is the harness's own ffverify — the run that decides whether a pull
    request opens. A leaked editor holds the Unity licence seat. A shared session label makes two
    runs read each other's journal. So: the config goes on every exit path, the editor dies as a
    GROUP (the real `unity-editor` is an xvfb-run wrapper whose children otherwise survive), and
    the journal is label-scoped.

    Also the base-ref gate: the automation harness is on develop, not on master, and a master-based
    workspace must be told that instead of paying minutes for an editor that ignores its config.
    """
    print("ffplaytest: cleanup, the process group, and the base-ref gate")
    root = os.path.join(TMPROOT, "ffplaytest")
    proj = os.path.join(root, "project")
    out = os.path.join(root, "out")
    bindir = os.path.join(root, "bin")
    pdp = os.path.join(root, "pdp")
    for d in (os.path.join(proj, "Assets"), out, bindir, pdp):
        os.makedirs(d, exist_ok=True)
    script = os.path.join(HERE, "ffplaytest.sh")
    config = os.path.join(proj, ".ff-local-automation.json")
    pids_file = os.path.join(root, "stub-pids")
    config_copy = os.path.join(root, "config-as-launched.json")
    stub = write_stub(os.path.join(bindir, "unity-editor"), PLAYTEST_EDITOR_STUB)

    def run(*extra, **kw):
        env = dict(os.environ, FFPLAYTEST_UNITY=stub, FFPLAYTEST_PDP=pdp,
                   FFPLAYTEST_SETTLE="1", FFPLAYTEST_POLL="1", STUB_PIDS=pids_file,
                   STUB_CONFIG_COPY=config_copy)
        env.update(kw.pop("env", {}))
        return subprocess.run(["bash", script, "--project", proj, "--out", out, *extra],
                              capture_output=True, text=True, env=env, timeout=180, **kw)

    # A master-shaped workspace: Assets, but no automation bootstrap anywhere in it.
    gate = run("--chain", "ffauto:wait|1", "--tag", "gate")
    check("a workspace with no automation harness is refused, not launched",
          gate.returncode == 3, (gate.returncode, gate.stderr[-300:]))
    check("and the refusal names develop, so the reader knows what to do",
          "develop" in gate.stderr and "master" in gate.stderr, gate.stderr[-300:])
    check("nothing was written into the project to clean up later",
          not os.path.exists(config), None)

    # Now a develop-shaped one.
    bootstrap = os.path.join(proj, "Assets", "Scripts", "Behaviours", "Multiplayer",
                             "LocalMultiplayerAutomationBootstrap.cs")
    os.makedirs(os.path.dirname(bootstrap), exist_ok=True)
    with open(bootstrap, "w", encoding="utf-8") as fh:
        fh.write("// the harness the config needs\n")

    ok = run("--chain", "ffauto:blueprint.place|BP|0|0", "--tag", "ok")
    check("a session whose chain completes exits 0", ok.returncode == 0,
          (ok.returncode, ok.stdout[-400:], ok.stderr[-400:]))
    check("THE CONFIG IS GONE afterwards — the next editor boot must not auto-play",
          not os.path.exists(config), None)
    report = json.load(open(os.path.join(out, "playtest-ok.json"), encoding="utf-8"))
    check("the report says the chain completed and the session entered play",
          report["chain_complete"] and report["entered_play"], report)
    check("the journal came back with it", report["events"] == 2, report)
    check("and it is label-scoped, so two runs cannot read each other's",
          report["label"] == "ffplaytest-ok"
          and os.path.isdir(os.path.join(pdp, "PlaytestSessions", "ffplaytest-ok")), report)
    check("the report refuses to be read as a timing measurement",
          report["timing_valid"] is False and "no GPU" in report["timing_note"], report)
    launched = json.load(open(config_copy, encoding="utf-8"))
    check("the chain is handed over as PreConnectCommand — a solo host never reaches post-join",
          launched["PreConnectCommand"] == "ffauto:blueprint.place|BP|0|0"
          and not launched.get("PostReadyCommand"), launched)
    check("the session quits itself rather than holding the editor open",
          launched["AutoQuit"] and launched["ExitPlayModeOnComplete"], launched)
    check("no determinism report is asked for, which would need a peer and a policy",
          launched["EnableDeterminismAudit"] is False and launched["WriteReport"] is False,
          launched)
    stub_pids = [int(x) for x in open(pids_file, encoding="utf-8").read().split()]
    alive = [pid for pid in stub_pids if _pid_alive(pid)]
    for pid in alive:                      # never leave the suite's own mess behind
        try:
            os.kill(pid, signal.SIGKILL)
        except OSError:
            pass
    check("the whole editor process group is dead, grandchildren included",
          not alive, alive)

    # An existing config is somebody else's session or the wreckage of one: refuse it.
    with open(config, "w", encoding="utf-8") as fh:
        fh.write('{"Label":"somebody-elses"}\n')
    clash = run("--chain", "ffauto:wait|1", "--tag", "clash")
    check("an existing config is refused rather than overwritten", clash.returncode == 2,
          (clash.returncode, clash.stderr[-200:]))
    check("and it is left exactly as it was",
          json.load(open(config, encoding="utf-8"))["Label"] == "somebody-elses", None)
    os.unlink(config)

    # A chain is the point of the run.
    empty = run("--tag", "nochain")
    check("a session with no chain is refused — it would prove nothing",
          empty.returncode == 2, (empty.returncode, empty.stderr[-200:]))


def _pid_alive(pid):
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    return True


def test_shell_is_an_ingress_not_a_second_pipeline():
    """`ffbox "prompt"` produces the SAME rows a Discord message does.

    It used to clone a workspace and run a container on its own, touching none of the database —
    which is why a shell run was invisible on the web page. The point of routing it here is that
    there is one path by which Claude is invoked; the front door only decides what goes in.
    """
    print("shell: one pipeline, several front doors")
    case = Case("shellingress")
    turn_id = case.watcher.submit("what does the merger do when both inputs saturate?")
    turn = case.watcher.db.one("SELECT * FROM turn WHERE id=?", (turn_id,))
    conv = case.watcher.db.one("SELECT * FROM conversation WHERE id=?",
                               (turn["conversation_id"],))
    check("a shell prompt becomes a conversation, a message and a queued turn",
          conv["kind"] == "shell" and turn["status"] == "queued" and turn["lane"] == "dev",
          (conv["kind"], turn["status"], turn["lane"]))
    check("it is not classified — the person typing already has a login here",
          json.loads(turn["classification_json"])["source"] == "shell",
          turn["classification_json"])
    check("the submission carries no unity switch to survive",
          "unity" not in json.loads(turn["options_json"]), turn["options_json"])

    case.watcher.once()
    turn = case.watcher.db.one("SELECT * FROM turn WHERE id=?", (turn_id,))
    run = case.watcher.db.one("SELECT * FROM run WHERE turn_id=?", (turn_id,))
    check("the ordinary scheduler runs it", turn["status"] == "done", turn["status"])
    check("and it lands in the run table like any other run",
          run is not None and run["terminal_state"] == "done", run)
    check("with an editor, because every run gets one", run["unity"] == 1, run["unity"])

    job = json.load(open(os.path.join(os.path.dirname(run["stream_path"]), "job.json"),
                         encoding="utf-8"))
    check("the dev lane gets Bash outright, not a list of program prefixes",
          "Bash" in job["capabilities"]["allowed"], job["capabilities"]["allowed"])
    # The merged lane runs under a schema like every other lane. What keeps the terminal
    # readable is result_text unwrapping `summary`, not the absence of a schema — checked
    # below, because it is the half of the merge that could regress silently.
    check("it runs under the one verdict schema, like every other turn",
          job["verdict_schema"] == "turn", job["verdict_schema"])
    check("and the container is told there is no thread on the other end of it",
          job["local"] is True, job["local"])
    check("what the person at the terminal reads is the summary, not the raw verdict",
          case.watcher.result_text(turn_id) ==
          "Checked the belt merger path; this is expected behaviour.",
          case.watcher.result_text(turn_id))
    # A local turn is a dev turn with nobody to post to, so it is verified and published like
    # one. The fifteen-minute EditMode suite a typed question must not pay for is skipped by the
    # CONTAINER, on the fact that the run changed no files, rather than by excluding the lane.
    check("harness verification is scheduled for a local turn like any other dev turn",
          job["verify"]["enabled"] is True, job["verify"])
    # ASKED FOR ON THE COMMAND LINE, not read back off the run row. run.branch is what the run
    # PUBLISHED, and since v12 a run that published nothing carries NULL there rather than the
    # name it was launched with — this stub changes no files, so the column is empty and the
    # question "was a branch asked for" has to be put to ffbox's argv, which is where the ask
    # actually lives.
    argv = json.load(open(os.path.join(os.path.dirname(run["stream_path"]),
                                       "ffbox-argv.json"), encoding="utf-8"))
    check("and a branch is asked for, so the work can leave the clone",
          "--branch" in argv and argv[argv.index("--branch") + 1]
          == f"ffbox/{run['ffbox_run_id']}", argv)
    # Measured, not assumed: with the Discord framing in place, a shell prompt asking which file
    # defines something came back as a POLICY REFUSAL addressed to a player, because the
    # answerer role forbids naming repo internals to Discord users.
    check("the prompt carries no Discord framing and no answerer role",
          "<discord>" not in job["prompt"] and "ff-discord" not in (job["prompt"] or ""),
          job["prompt"][:200])
    # The plugin IS mounted, and the policy is carried by the declared venue instead. A local
    # run gets max-voice and the rest of the ff-discord skills; what it does not get is a
    # Discord fence or a player-facing disclosure rule.
    check("the ff-discord plugin is mounted, so its skills are available",
          any(d.endswith("ff-discord") for d in job["plugin_dirs"]), job["plugin_dirs"])
    check("the shell ingress is an operator at a private venue",
          (job["trust"]["tier"], job["venue"]["kind"]) == ("operator", "private"), job["trust"])
    check("nothing is queued for Discord, because there is no thread to answer",
          not case.rows("SELECT * FROM outbound"), case.rows("SELECT * FROM outbound"))


def build_container_argv(job, tmpname):
    """Run discord-task.sh's OWN argv builder over a job.json and hand back the argv.

    The preamble a lane gets is decided inside that heredoc, not on the host, so asserting on
    the host's job dict would prove nothing about what `claude` is actually told. The block is
    lifted out and executed here instead: same code, real job files, no container.
    """
    text = io.open(os.path.join(HERE, "discord-task.sh"), encoding="utf-8").read()
    start = text.index("<<'ARGVEOF'\n") + len("<<'ARGVEOF'\n")
    block = text[start:text.index("\nARGVEOF", start)]
    job_path = os.path.join(TMPROOT, tmpname + ".job.json")
    argv_path = os.path.join(TMPROOT, tmpname + ".argv")
    with io.open(job_path, "w", encoding="utf-8") as fh:
        json.dump(job, fh)
    saved = sys.argv
    sys.argv = ["builder", job_path, argv_path]
    try:
        exec(compile(block, "discord-task.sh:ARGVEOF", "exec"), {"__name__": "__main__"})
    finally:
        sys.argv = saved
    with io.open(argv_path, "rb") as fh:
        return [a.decode("utf-8") for a in fh.read().split(b"\0")]


# The smallest job the argv builder will accept, for checks that are about the PREAMBLE rather
# than about a particular run. Anything a test cares about it overrides.
JOB_SKELETON = {
    "prompt": "make the belt merger respect item priority",
    "lane": "dev",
    "local": False,
    "verdict_schema": "change",
    "session": {"id": "b0a1c2d3-0000-4000-8000-000000000000", "resume": False},
    "capabilities": {"tools": "Read,Grep,Glob,Edit,Write,Bash",
                     "permission_mode": "acceptEdits", "allowed": ["Bash"], "disallowed": []},
    "model": {},
    "trust": {"tier": "operator", "actor": "", "why": ""},
    "venue": {"kind": "private"},
}


def preamble_for(job, tmpname):
    """What --append-system-prompt actually carries for this job."""
    argv = build_container_argv(job, tmpname)
    return argv[argv.index("--append-system-prompt") + 1]


def test_the_shell_lane_was_merged_into_dev():
    """There is no `shell` lane any more, and nothing lost a capability in the merge.

    The two entries differed in exactly two fields — bare Bash, and no verdict schema — and
    neither difference survived the question "who is this lane for". Both routes into dev are a
    person this box already trusts: an operator with a Discord-authenticated author id, or
    somebody with a login here. So both get bare Bash, and both run under the schema the
    harness reads.

    What is still different about a locally typed prompt is decided by is_local_conversation,
    never by the lane, because the real question was always whether there is a thread on the
    other end. That is the half worth pinning down here: the same lane, told two different
    things, because it is answering into two different places.
    """
    print("lanes: there is one capability set")
    check("there is no lane table left to select from",
          not hasattr(ffwatch, "LANE_CAPABILITIES") and not hasattr(ffwatch, "LANE_BY_KIND"))
    check("every run gets the same tools",
          ffwatch.CAPABILITIES["tools"] == "Read,Grep,Glob,Edit,Write,Bash",
          ffwatch.CAPABILITIES["tools"])
    check("and bare Bash",
          ffwatch.CAPABILITIES["allowed"] == ["Bash"], ffwatch.CAPABILITIES["allowed"])
    check("the local kinds still bypass the gate, along with the addressed Discord kinds",
          set(ffwatch.GATE_BYPASS_KINDS)
          # github_pr is here because its prompt is built by the harness out of the pull
          # request: there is no text for a classifier to read and nothing for it to decide.
          == {"shell", "web", "operator_dm", "directive", "mention", "github_pr"},
          ffwatch.GATE_BYPASS_KINDS)

    # -- the rate limit -------------------------------------------------------------------
    # Asserted against DEFAULTS, not against the loaded config: a box whose
    # ~/.config/ffbox/config.json still pins the old dev cap keeps it, because _deep_merge
    # merges the dict rather than replacing it. That is the correct behaviour for an operator
    # override and the reason this check cannot read case.cfg — it would pass or fail on the
    # machine running the suite rather than on the code.
    limits = ffwatch.DEFAULTS["rate_limits"]
    check("an operator carries no daily cap by default", not limits.get("operator"), limits)
    check("and a player does — one budget across every kind of turn they can cause",
          limits["player"] == 5, limits)
    case = Case("devunlimited")
    case.cfg["rate_limits"] = dict(limits)
    case.watcher.db.execute(
        "INSERT INTO conversation(id, thread_id, kind, state) VALUES(9001,'t-9001','shell','idle')")
    for seq in range(1, 60):
        case.watcher.db.execute(
            "INSERT INTO turn(conversation_id, seq, lane, status, started_at)"
            " VALUES(9001,?,'dev','done',?)", (seq, ffwatch.now_iso()))
    check("fifty-nine dev turns in a day do not close the lane",
          case.watcher.rate_limited("dev") is False)

    # -- the same lane, told two different things -------------------------------------------
    local = Case("mergelocal")
    local_turn = local.watcher.submit("what does the merger do when both inputs saturate?")
    local.watcher.once()
    local_run = local.watcher.db.one("SELECT * FROM run WHERE turn_id=?", (local_turn,))
    local_job = json.load(open(os.path.join(os.path.dirname(local_run["stream_path"]),
                                            "job.json"), encoding="utf-8"))

    fixture = base_fixture()
    fixture["messages"][ASK_CHANNEL] = [message(15001, "ship the merger fix", author=LOTHSAHN)]
    remote = Case("mergeremote", fixture,
                  verdict={"engage": True, "reason": "asks for a fix"})
    remote.cfg["operators"] = {"lothsahn": {"discord": LOTHSAHN, "model": SUITE_CLAUDE_NAME}}
    remote.events({"ts": "2026-08-21T00:00:00Z", "kind": "operator_directive",
                   "channel": "ask_claude", "channel_id": ASK_CHANNEL, "id": "15001",
                   "author_id": LOTHSAHN})
    remote.watcher.once()
    remote_run = remote.rows("SELECT * FROM run")[0]
    remote_job = json.load(open(os.path.join(remote.watcher.conv_dir(1), "runs",
                                             remote_run["ffbox_run_id"], "job.json"),
                                encoding="utf-8"))

    check("both turns take the dev lane",
          (local_job["lane"], remote_job["lane"]) == ("dev", "dev"),
          (local_job["lane"], remote_job["lane"]))
    check("with identical capabilities, Bash included",
          local_job["capabilities"] == remote_job["capabilities"],
          (local_job["capabilities"], remote_job["capabilities"]))
    check("and identical verdict schemas",
          local_job["verdict_schema"] == remote_job["verdict_schema"] == "turn",
          (local_job["verdict_schema"], remote_job["verdict_schema"]))
    check("locality is what separates them, and the host decides it",
          (local_job["local"], remote_job["local"]) == (True, False),
          (local_job["local"], remote_job["local"]))
    check("both are verified by the harness",
          (local_job["verify"]["enabled"], remote_job["verify"]["enabled"]) == (True, True),
          (local_job["verify"], remote_job["verify"]))
    # From the argv for the same reason as above: neither stub run changes a file, so neither
    # PUBLISHES a branch, and run.branch is NULL on both. What this check is about is that the
    # host asked ffbox for one in both cases — locality does not decide whether work can leave
    # the clone.
    local_argv_launch = json.load(open(os.path.join(
        os.path.dirname(local_run["stream_path"]), "ffbox-argv.json"), encoding="utf-8"))
    remote_argv_launch = json.load(open(os.path.join(
        os.path.dirname(remote_run["stream_path"]), "ffbox-argv.json"), encoding="utf-8"))
    check("and both get a branch to publish, because both can change code",
          "--branch" in local_argv_launch and "--branch" in remote_argv_launch,
          (local_argv_launch, remote_argv_launch))
    check("only the Discord turn is fenced as untrusted input",
          "<discord>" not in local_job["prompt"] and "<discord>" in remote_job["prompt"],
          local_job["prompt"][:120])

    # -- what the container is actually told -------------------------------------------------
    local_argv = build_container_argv(local_job, "mergelocal")
    remote_argv = build_container_argv(remote_job, "mergeremote")
    check("both invocations impose the verdict schema",
          "--json-schema" in local_argv and "--json-schema" in remote_argv, local_argv)
    local_pre = local_argv[local_argv.index("--append-system-prompt") + 1]
    remote_pre = remote_argv[remote_argv.index("--append-system-prompt") + 1]
    check("the local preamble says nothing is posted anywhere",
          "no Discord thread on the other end" in local_pre, local_pre[:160])
    check("and tells it summary IS the answer, at whatever length the question deserves",
          "printed verbatim" in local_pre and "no length rule applies" in local_pre,
          local_pre)
    # The difference between the two is the destination of the ANSWER, and nothing else. Both
    # are told to make a branch, both are told the harness pushes it, and both are told a run
    # that ends on develop is thrown away — which is what stops a locally typed fix from
    # quietly being the one kind of run whose work dies with its clone.
    for name, pre in (("local", local_pre), ("Discord", remote_pre)):
        check(f"the {name} preamble tells the agent to make its own branch first",
              "MAKE A BRANCH BEFORE YOU CHANGE ANYTHING" in pre, pre[:200])
        check(f"and the {name} one says what happens if it works on develop instead",
              "ends on develop, master or main is refused" in pre, pre[:200])
        check(f"the {name} one still forbids what the container cannot do anyway",
              "Do NOT push" in pre and "do NOT open a pull request" in pre, pre[:200])
    # Discord hard-limits a message to 2000 characters. compose_head fits the post to that and
    # attaches whatever will not go, but a post that stops mid-sentence next to an unopened file
    # is a worse answer than a shorter one, so the lane writing it is told the budget.
    check("the Discord preamble states the 2000-character limit and a budget under it",
          "2000 characters" in remote_pre and "1500" in remote_pre, remote_pre[-320:])
    check("which the local one does not carry",
          "2000 characters" not in local_pre, local_pre[-160:])
    check("and the budget it is given leaves the composer room it will not have to take back",
          ffwatch.HEAD_CAP == 1500 < ffwatch.DISCORD_LIMIT, ffwatch.HEAD_CAP)

    # -- the migration -------------------------------------------------------------------------
    old = os.path.join(case.root, "pre-v8.db")
    conn = sqlite3.connect(old)
    with conn:
        conn.executescript(io.open(os.path.join(HERE, "ffwatch_schema.sql"),
                                   encoding="utf-8").read())
        conn.execute("INSERT INTO conversation(id, thread_id, kind, lane)"
                     " VALUES(1,'t-1','shell','shell')")
        conn.execute("INSERT INTO conversation(id, thread_id, kind, lane)"
                     " VALUES(2,'imported-x','shell',NULL)")
        conn.execute("INSERT INTO turn(conversation_id, seq, lane, status)"
                     " VALUES(1,1,'shell','done')")
        conn.execute("INSERT INTO turn(conversation_id, seq, lane, status)"
                     " VALUES(2,1,'shell','done')")
    conn.close()
    ffwatch.Db(old).init_schema()
    ro = sqlite3.connect(old)
    lanes = [r[0] for r in ro.execute("SELECT lane FROM conversation ORDER BY id")]
    tlanes = [r[0] for r in ro.execute("SELECT lane FROM turn ORDER BY id")]
    ro.close()
    check("an existing database stops naming a lane that cannot be produced any more",
          tlanes == ["dev", "dev"], tlanes)
    check("and an imported run, whose conversation never got a lane, is filled in from its turn",
          lanes == ["dev", "dev"], lanes)


def test_web_is_the_same_ingress_wearing_a_different_label():
    """`--source web` changes the RECORD and nothing else.

    The page needed to be distinguishable from a terminal on the conversation list — a question
    people ask of the record, which it could not answer while both said "shell". So the kind is
    new and everything the kind decides is deliberately not: same lane, same capabilities, same
    private venue, same nothing-queued-for-Discord. A second ingress that behaved differently
    would be a second pipeline, which is the thing this design keeps refusing to grow.
    """
    print("web: a front door, not a second pipeline")
    case = Case("webingress")
    turn_id = case.watcher.submit("what does the merger do when both inputs saturate?",
                                  kind="web")
    turn = case.watcher.db.one("SELECT * FROM turn WHERE id=?", (turn_id,))
    conv = case.watcher.db.one("SELECT * FROM conversation WHERE id=?",
                               (turn["conversation_id"],))
    check("the conversation records the front door it came through",
          conv["kind"] == "web", conv["kind"])
    check("but it takes the dev lane, the same one a terminal prompt and a directive take",
          turn["lane"] == "dev", turn["lane"])
    check("the trigger says which door too",
          turn["trigger"] == "web_prompt", turn["trigger"])
    check("it is not classified either — the person typing signed in here",
          json.loads(turn["classification_json"])["source"] == "web",
          turn["classification_json"])

    case.watcher.once()
    turn = case.watcher.db.one("SELECT * FROM turn WHERE id=?", (turn_id,))
    run = case.watcher.db.one("SELECT * FROM run WHERE turn_id=?", (turn_id,))
    check("the ordinary scheduler runs it", turn["status"] == "done", turn["status"])
    job = json.load(open(os.path.join(os.path.dirname(run["stream_path"]), "job.json"),
                         encoding="utf-8"))
    check("with the same operator tier and private venue a shell prompt gets",
          (job["trust"]["tier"], job["venue"]["kind"]) == ("operator", "private"), job["trust"])
    check("and is local too, so it is framed for a reader rather than for a thread",
          job["local"] is True, job["local"])
    check("and the same Bash-outright capability set",
          "Bash" in job["capabilities"]["allowed"], job["capabilities"]["allowed"])
    check("no Discord framing, because there is still no Discord in this",
          "<discord>" not in job["prompt"], job["prompt"][:200])
    check("nothing is queued for Discord: a web conversation is local, like a shell one",
          not case.rows("SELECT * FROM outbound"), case.rows("SELECT * FROM outbound"))

    # The guard is a list, not a habit: an unknown source is refused rather than recorded.
    try:
        case.watcher.submit("who goes there?", kind="carrier_pigeon")
        check("an unknown ingress is refused", False, "it was accepted")
    except ValueError as exc:
        check("an unknown ingress is refused", "not a local ingress" in str(exc), str(exc))


def test_a_local_conversation_can_be_continued():
    """A follow-up is turn 2 of the SAME conversation, which is what makes it worth having.

    The page grew a box that says something else to the conversation being read, and the whole
    value of it is downstream: the turn carries that conversation's session id, so the run
    resumes its own transcript instead of meeting the follow-up cold. Asking again in a new
    conversation is how a person ends up re-explaining a bug to something that just spent four
    minutes reading the code for it.
    """
    print("local conversations: continuing one")
    case = Case("continue")
    first = case.watcher.submit("what does the merger do when both inputs saturate?",
                                kind="web")
    case.watcher.once()
    conv_id = case.watcher.db.one("SELECT conversation_id FROM turn WHERE id=?",
                                  (first,))["conversation_id"]

    _msg, second = case.watcher.follow_up(conv_id, "and when only one of them is?")
    turns = case.rows("SELECT * FROM turn ORDER BY seq")
    check("the follow-up is a second turn on the same conversation",
          len(turns) == 2 and turns[1]["id"] == second
          and turns[1]["conversation_id"] == conv_id, turns)
    check("not a second conversation",
          len(case.rows("SELECT * FROM conversation")) == 1,
          case.rows("SELECT id, kind, title FROM conversation"))
    check("it takes the same lane, unclassified like the prompt that opened it",
          turns[1]["lane"] == "dev"
          and json.loads(turns[1]["classification_json"])["source"] == "web",
          (turns[1]["lane"], turns[1]["classification_json"]))
    check("and the same operator tier at the same private venue",
          (turns[1]["trust_tier"], turns[1]["venue"]) == ("operator", "private"),
          (turns[1]["trust_tier"], turns[1]["venue"]))

    case.watcher.once()
    runs = case.rows("SELECT * FROM run ORDER BY id")
    check("the ordinary scheduler runs it, like any other turn",
          len(runs) == 2 and runs[1]["terminal_state"] == "done", runs)
    check("turn 1 opened the session and turn 2 RESUMES it",
          runs[0]["resumed"] == 0 and runs[1]["resumed"] == 1
          and runs[0]["session_id"] == runs[1]["session_id"], runs)
    job = json.load(open(os.path.join(os.path.dirname(runs[1]["stream_path"]), "job.json"),
                         encoding="utf-8"))
    check("the run is handed the follow-up, and nothing but the follow-up",
          job["prompt"].strip() == "and when only one of them is?", job["prompt"][:200])
    check("still no Discord framing on a local conversation",
          "<discord>" not in job["prompt"], job["prompt"][:200])
    check("and still nothing queued for Discord",
          not case.rows("SELECT * FROM outbound"), case.rows("SELECT * FROM outbound"))


def test_two_local_messages_in_one_millisecond_are_still_two_messages():
    """The key `ffwatch submit` and `ffwatch continue` mint has to be unique, not just sorted.

    Milliseconds plus the pid sort correctly and collide: two follow-ups typed back to back --
    a script, the web page, or simply a fast caller -- land on the same value inside one
    millisecond, INSERT OR IGNORE drops the second, and follow_up raises at somebody who typed
    a perfectly good second line. This suite hit it as an intermittent failure of the test
    below, roughly one run in three.
    """
    print("local conversations: two keys minted in the same instant")
    minted = [ffwatch.local_message_key() for _ in range(500)]
    check("no two are the same", len(set(minted)) == 500, len(set(minted)))
    check("and they still sort as increasing integers, which the ordering casts to",
          [int(k) for k in minted] == sorted(int(k) for k in minted), minted[:4])
    check("keeping the millisecond+pid width, so a local id still compares with a snowflake",
          all(len(k) == len(minted[0]) for k in minted), minted[:4])


def test_a_follow_up_typed_mid_run_waits_and_batches():
    """Two follow-ups typed while the container works become ONE turn, after it exits.

    Not a nicety: create_turn sets the conversation back to 'queued', which is the one state
    the scheduler reads as free, so a turn created while a run is in flight would launch
    alongside it — and two runs resuming one session id fork the transcript irrecoverably. So
    the message is recorded and left unclaimed, exactly as a burst of Discord follow-ups is,
    and claim_turns picks the batch up on the pass after the run ends.
    """
    print("local conversations: a follow-up typed mid-run")
    case = Case("continuemidrun")
    first = case.watcher.submit("start something long", kind="web")
    case.watcher.once()
    conv_id = case.watcher.db.one("SELECT conversation_id FROM turn WHERE id=?",
                                  (first,))["conversation_id"]

    # The state the scheduler leaves a conversation in for the life of the container.
    case.watcher.db.execute("UPDATE conversation SET state='running' WHERE id=?", (conv_id,))
    m1, t1 = case.watcher.follow_up(conv_id, "actually also this")
    m2, t2 = case.watcher.follow_up(conv_id, "and this")
    check("neither follow-up queues a turn against the run in flight",
          t1 is None and t2 is None, (t1, t2))
    check("but both messages are recorded, so nothing is lost",
          [r["content"] for r in case.rows(
              "SELECT content FROM message WHERE turn_id IS NULL ORDER BY id")]
          == ["actually also this", "and this"],
          case.rows("SELECT content, turn_id FROM message ORDER BY id"))
    check("and the sweep will not claim them while the run is still in flight",
          case.watcher.claim_turns() == []
          and len(case.rows("SELECT * FROM turn")) == 1,
          case.rows("SELECT id, seq, status FROM turn"))

    case.watcher.db.execute("UPDATE conversation SET state='idle' WHERE id=?", (conv_id,))
    created = case.watcher.claim_turns()
    turns = case.rows("SELECT * FROM turn ORDER BY seq")
    check("when it ends the pair becomes ONE turn, not two",
          len(created) == 1 and len(turns) == 2, (created, turns))
    check("with both messages on it",
          [r["turn_id"] for r in case.rows(
              "SELECT turn_id FROM message WHERE id IN (?, ?)", (m1, m2))]
          == [turns[1]["id"], turns[1]["id"]],
          case.rows("SELECT id, turn_id, content FROM message ORDER BY id"))

    case.watcher.once()
    runs = case.rows("SELECT * FROM run ORDER BY id")
    job = json.load(open(os.path.join(os.path.dirname(runs[1]["stream_path"]), "job.json"),
                         encoding="utf-8"))
    # The shell lane used to hand the model job["messages"][-1] and only that, so a person who
    # followed a question with a correction had the question silently dropped.
    check("and the run is handed BOTH of them, not just the last one typed",
          "actually also this" in job["prompt"] and "and this" in job["prompt"],
          job["prompt"][:300])


def test_only_a_local_conversation_can_be_continued_from_this_side():
    """A Discord thread is answered in Discord. This refuses rather than adapts.

    A message inserted here carries this box's unix user as its author, which is not a Discord
    identity the trust rules can read, and the turn it produced would queue a reply into a
    public thread on the strength of it. Whether the person at the keyboard may speak in that
    thread is Discord's question, and a login on this box does not answer it.
    """
    print("local conversations: a Discord thread is not one")
    fixture = bug_thread(base_fixture(), 17400, "merger drops items",
                         [message(17401, "first report", channel="17400")])
    case = Case("continueforeign", fixture)
    case.events(thread_event(17400, kind="thread"))
    case.watcher.once()
    conv = case.watcher.db.one("SELECT * FROM conversation WHERE thread_id='17400'")
    try:
        case.watcher.follow_up(conv["id"], "any progress?")
        check("a Discord conversation is refused", False, "it was accepted")
    except ValueError as exc:
        check("a Discord conversation is refused", "answered in Discord" in str(exc), str(exc))
    check("and nothing was written for it",
          not case.rows("SELECT * FROM message WHERE content='any progress?'"))

    try:
        case.watcher.follow_up(9999, "hello?")
        check("so is a conversation that does not exist", False, "it was accepted")
    except ValueError as exc:
        check("so is a conversation that does not exist", "no conversation" in str(exc),
              str(exc))


def test_the_cli_can_continue_a_conversation():
    """`ffwatch submit --conversation N` is the argv ffweb's reply box actually sends."""
    print("local conversations: the CLI verb")
    args = ffwatch.build_parser().parse_args(
        ["submit", "--conversation", "11", "--", "and when only one is saturated?"])
    check("the flag parses as the conversation to continue",
          args.cmd == "submit" and args.conversation == 11
          and args.prompt == ["and when only one is saturated?"], args)
    check("and a plain submission still has none",
          ffwatch.build_parser().parse_args(["submit", "hello"]).conversation is None)


def test_drain_pauses_launches_without_holding_replies():
    """A drain is a pause, not a stop: nothing new launches, everything else keeps working.

    The distinction is the whole reason it is not the kill switch. `discord.disabled` also
    holds every outbound row, which would strand the replies of the very runs the updater is
    waiting on.
    """
    print("drain: launches pause, replies do not")
    fixture = base_fixture()
    fixture["messages"][ASK_CHANNEL] = [message(9300, "does the merger round-robin?"),
                                        message(9301, "and what about the splitter?")]
    case = Case("drainpause", fixture)

    # A run that finished before the drain leaves an outbound row waiting to be sent.
    case.events(ask_event(9300))
    case.watcher.once()
    check("a normal turn runs and sends its reply",
          [(r["action"], r["status"])
           for r in case.rows("SELECT action, status FROM outbound")]
          # The acknowledgement is dropped rather than sent: one pass claimed, ran and answered
          # this turn, so the 👀 would have gone out after the answer it promised.
          == [("react", "rejected"), ("post", "sent")],
          case.rows("SELECT action, status FROM outbound"))

    left = case.watcher.drain()
    check("drain writes the flag", os.path.exists(case.watcher.cfg["drain_switch"]))
    check("and reports nothing in flight on a quiet machine", left == 0, left)

    case.events(ask_event(9301))
    case.watcher.once()
    check("the second turn is still claimed and queued",
          [t["status"] for t in case.rows("SELECT status FROM turn ORDER BY id")]
          == ["done", "queued"], case.rows("SELECT id, status FROM turn"))
    check("but nothing launched for it",
          len(case.rows("SELECT * FROM run")) == 1, case.rows("SELECT ffbox_run_id FROM run"))
    check("the drain switch is not the kill switch: sending still works",
          not case.rows("SELECT * FROM outbound WHERE status IN ('pending','approved')"),
          case.rows("SELECT action, status FROM outbound"))

    check("resume lifts it", case.watcher.resume() is True)
    check("and is idempotent", case.watcher.resume() is False)
    case.watcher.once()
    check("the queued turn then runs, with nothing lost",
          [t["status"] for t in case.rows("SELECT status FROM turn ORDER BY id")]
          == ["done", "done"], case.rows("SELECT id, status FROM turn"))


def test_drain_never_blocks_on_a_dead_daemon():
    """`drain --wait` returns at once when no daemon holds the lock.

    This is the case the updater exists for. A hard-killed ffwatch leaves run rows with
    terminal_state NULL that nothing will ever settle; waiting the full ceiling for containers
    that died hours ago would stall the update meant to repair the machine. Nobody is
    launching, so there is nothing to wait for.
    """
    print("drain: a dead daemon is not something to wait for")
    case = Case("draindead")
    conv_id = case.watcher.upsert_conversation("7100", kind="ask", channel_id=ASK_CHANNEL,
                                               title="a run that never finished")
    cur = case.watcher.db.execute(
        "INSERT INTO turn(conversation_id, seq, trigger, lane, status, queued_at)"
        " VALUES(?,1,'message','answer','running',?)", (conv_id, ffwatch.now_iso()))
    case.watcher.db.execute(
        "INSERT INTO run(turn_id, ffbox_run_id, container_name) VALUES(?,'ghost','ffbox-ghost')",
        (cur.lastrowid,))
    check("the ghost run looks exactly like work in flight",
          case.watcher.running_counts() == 1, case.watcher.running_counts())

    started = time.monotonic()
    left = case.watcher.drain(wait=True, timeout=30)
    elapsed = time.monotonic() - started
    check("drain --wait returns immediately rather than waiting out the ceiling",
          left == 0 and elapsed < 5, (left, round(elapsed, 1)))
    check("and the flag is still down, so the update stops a machine that launches nothing",
          os.path.exists(case.watcher.cfg["drain_switch"]))
    case.watcher.resume()


def test_config_failsafe_stops_every_launch():
    """A config file that does not parse launches nothing, and says so on disk.

    THE FAILURE THIS PREVENTS. Every reader of ~/.config/ffbox/config.json answers {} for a file
    it cannot parse -- this file's loader included -- so a stray comma does not stop anything: it
    silently swaps a built-in default in for every clock, ceiling, network mode and pool size on
    the box, and the turns keep coming out of containers configured by nobody. The failsafe is
    that they stop instead.

    A PAUSE, NOT A FAILURE, exactly like the drain above it: the turn stays queued, the ingest
    keeps working, and the queue moves the moment the file parses.
    """
    print("config failsafe: a file that does not parse launches nothing")
    fixture = base_fixture()
    fixture["messages"][ASK_CHANNEL] = [message(9600, "what does a splitter do?")]
    case = Case("configfailsafe", fixture)
    case.events(ask_event(9600))
    flag = ffwatch.FFBOX_CONFIG_FAILSAFE
    try:
        with open(ffwatch.FFBOX_CONFIG, "w", encoding="utf-8") as fh:
            # The trailing comma, which is what this actually happens as.
            fh.write('{"max_concurrent_runs": 6,}\n')
        case.watcher.once()
        check("nothing is launched while the config does not parse",
              len(case.rows("SELECT * FROM run")) == 0, case.rows("SELECT * FROM run"))
        turn = case.rows("SELECT * FROM turn")[0]
        check("the turn stays queued rather than failing", turn["status"] == "queued", turn)
        check("the pool keeper stages nothing either", case.watcher.keep_pool() == [])
        # THE FLAG IS THE ONLY WAY ffstatus.sh CAN SEE THE LATCH BELOW, so it is written for
        # every failsafe rather than only for that one -- one flag, one meaning.
        reason = ""
        if os.path.exists(flag):
            with open(flag, encoding="utf-8") as fh:
                reason = fh.read()
        check("and the failsafe is announced on disk, where a status command can read it",
              reason.startswith("reason=") and "is not valid JSON" in reason, reason)
        # The parse error is re-read from disk every pass, so this needs no restart.
        with open(ffwatch.FFBOX_CONFIG, "w", encoding="utf-8") as fh:
            fh.write('{"max_concurrent_runs": 6}\n')
        case.watcher.once()
        check("repairing the file lifts it, with the queued turn intact",
              len(case.rows("SELECT * FROM run")) == 1, case.rows("SELECT * FROM run"))
        check("and the flag is cleared", not os.path.exists(flag))
    finally:
        for path in (ffwatch.FFBOX_CONFIG, flag):
            if os.path.exists(path):
                os.remove(path)


def test_config_failsafe_latches_after_a_broken_startup():
    """A daemon that CAME UP on a broken file stays down until it is restarted.

    ffwatch reads the config once, in main(), and loops for weeks off that dict -- so a process
    that started while the file was broken is running on built-in defaults, and repairing the
    file does nothing for it. Resuming there would be the failure this whole thing exists to
    prevent, one step later: launching turns out of a config nobody chose, on a box whose
    operator has just watched the fault clear.

    Nothing has to be done by hand. config.json is one of the files update_ffbox.sh watches, so
    the repair earns a restart within a poll or two, and the restart is what lifts this.
    """
    print("config failsafe: a broken startup latches until a restart")
    fixture = base_fixture()
    fixture["messages"][ASK_CHANNEL] = [message(9700, "and what about the merger?")]
    flag = ffwatch.FFBOX_CONFIG_FAILSAFE
    try:
        with open(ffwatch.FFBOX_CONFIG, "w", encoding="utf-8") as fh:
            fh.write("{ this is not json\n")
        # Case() builds its watcher out of load_config(), which is the startup this is about.
        case = Case("configlatch", fixture)
        check("load_config records WHY the file said nothing",
              "is not valid JSON" in (case.cfg.get("_config_error") or ""),
              case.cfg.get("_config_error"))
        check("and the warning that goes to the journal leads with it",
              "BUILT-IN DEFAULTS" in (ffwatch.config_warnings(case.cfg) or [""])[0],
              ffwatch.config_warnings(case.cfg)[:1])
        # The operator fixes the file. Every OTHER reader on the box is well again; this process
        # is not, because it is still holding the defaults it came up on.
        with open(ffwatch.FFBOX_CONFIG, "w", encoding="utf-8") as fh:
            fh.write('{"max_concurrent_runs": 6}\n')
        case.events(ask_event(9700))
        case.watcher.once()
        check("a repaired file does not resume a process running on defaults",
              len(case.rows("SELECT * FROM run")) == 0, case.rows("SELECT * FROM run"))
        check("and the reason says what does",
              "restarted" in (case.watcher.config_failsafe() or ""),
              case.watcher.config_failsafe())
    finally:
        for path in (ffwatch.FFBOX_CONFIG, flag):
            if os.path.exists(path):
                os.remove(path)


def test_a_local_conversation_never_reaches_discord():
    """A shell conversation cannot be swept into a turn, and cannot queue an outbound row.

    Both halves are guards against the same real incident (2026-08-22): five imported shell
    runs were sitting in the database with their prompt recorded as an unclaimed message. The
    sweep read them as players waiting for an answer, classified them, burned five containers
    re-answering questions that already had answers, and queued ten replies addressed to a
    channel id of `imported-20260820-025120-418020`. Nothing was sent, and only because the
    machine had no bot token.
    """
    print("shell: a local conversation has no Discord side")
    fixture = base_fixture()
    fixture["messages"][ASK_CHANNEL] = [message(9100, "does the merger round-robin?")]
    case = Case("localnodiscord", fixture)

    # Exactly the row the incident turned on: a message that never got linked to its turn,
    # which is what a crash between insert_message and the turn INSERT leaves behind.
    conv_id = case.watcher.upsert_conversation(
        "imported-20260820-025120-418020", kind="shell", channel_id=None,
        title="Reply with exactly: hello world", root_message_id="imported-1",
        opener="tester", is_thread=False)
    case.watcher.insert_message(conv_id, {
        "id": "imported-1", "content": "Reply with exactly: hello world",
        "timestamp": "2026-08-20T06:51:28Z",
        "author": {"id": "1000", "username": "tester", "bot": False},
    })
    check("the unclaimed message is really there to be found",
          case.rows("SELECT * FROM message WHERE turn_id IS NULL AND conversation_id=?",
                    (conv_id,)))
    check("but the sweep does not claim it", case.watcher.claim_turns() == [],
          case.rows("SELECT * FROM turn WHERE conversation_id=?", (conv_id,)))
    case.watcher.once()
    check("so no turn, no container and no run come of it",
          not case.rows("SELECT * FROM run"), case.rows("SELECT * FROM run"))

    # The second guard, at the single point where anything enters the queue. A caller that
    # asks for it anyway is refused rather than obeyed.
    nonce = case.watcher.record_outbound(None, conv_id, "post", {"channel": "x", "text": "hi"})
    check("record_outbound refuses a conversation with nowhere to post", nonce is None, nonce)
    check("and nothing lands in the queue", not case.rows("SELECT * FROM outbound"),
          case.rows("SELECT * FROM outbound"))

    # The guard must not over-reach: a real thread still gets its reply.
    case.events(ask_event(9100))
    case.watcher.drain_events()
    case.watcher.once()
    check("a Discord conversation is still claimed, acknowledged, run and answered",
          [r["action"] for r in case.rows("SELECT action FROM outbound ORDER BY id")]
          == ["react", "post"], case.rows("SELECT * FROM outbound"))

    # WHERE THE LINE IS, now that follow_up() leaves a message for the sweep on purpose. The
    # sweep admits a local conversation that already HAS a turn, which a crashed submit cannot
    # have; give this one a turn and the same unclaimed message is claimed on the next pass.
    case.watcher.db.execute(
        "INSERT INTO turn(conversation_id, seq, trigger, lane, status, queued_at)"
        " VALUES(?,1,'shell_prompt','dev','done',?)", (conv_id, ffwatch.now_iso()))
    check("a conversation that already answered one turn is swept for the next",
          len(case.watcher.claim_turns()) == 1,
          case.rows("SELECT id, seq, status FROM turn WHERE conversation_id=?", (conv_id,)))


def test_past_standalone_runs_import():
    """The runs from before the shell was an ingress are folded in, once, idempotently."""
    print("shell: importing older standalone runs")
    case = Case("shellimport")
    root = os.path.join(TMPROOT, "oldruns", "20260820-035053-432324")
    os.makedirs(root, exist_ok=True)
    with open(os.path.join(root, "prompt.txt"), "w", encoding="utf-8") as fh:
        fh.write("Reply with exactly: hello world")
    with open(os.path.join(root, "claude.log"), "w", encoding="utf-8") as fh:
        fh.write("hello world")

    turn_id = case.watcher.import_run_dir(root)
    check("the run becomes a conversation with a completed turn", turn_id is not None)
    run = case.watcher.db.one("SELECT * FROM run WHERE turn_id=?", (turn_id,))
    events = case.rows("SELECT * FROM transcript_event WHERE run_id=? ORDER BY seq",
                       (run["id"],))
    check("the prompt and the answer become transcript rows the page already knows how to draw",
          [e["type"] for e in events] == ["user", "assistant"], [e["type"] for e in events])
    check("the answer is the one the run actually produced",
          events[1]["text"] == "hello world", events[1]["text"])
    check("re-importing the same directory does nothing",
          case.watcher.import_run_dir(root) is None)
    check("a directory with no prompt is skipped rather than half-imported",
          case.watcher.import_run_dir(os.path.join(TMPROOT, "oldruns")) is None)


def test_config_lives_under_ffbox():
    """ONE FILE holds every setting this box has, and the Discord keys are a section of it.

    ffwatch's and ffweb's settings once sat in a block inside a Discord config of their own,
    which meant a ROOT-run installer had to read a user's Discord directory to learn where the
    WEB PAGE should listen — and that is exactly how the sudo/$HOME bug shipped. Everything is
    one document now, which also keeps the `channels` alias table beside the `watch` block that
    gives those aliases their meaning: two files that had to be edited together could disagree.

    ~/.config/ffbox/discord is STATE and only state — cursors, the doorbell, the listener lock
    — and holds no configuration at all.
    """
    print("config: one file under ~/.config/ffbox")
    root = os.path.join(TMPROOT, "confmove")
    shutil.rmtree(root, ignore_errors=True)
    ffbox_dir = os.path.join(root, ".config", "ffbox")
    os.makedirs(ffbox_dir)

    saved = dict(os.environ)
    try:
        os.environ.pop("FFDISCORD_HOME", None)
        os.environ["HOME"] = root
        os.environ["FFBOX_CONFIG_DIR"] = ffbox_dir

        with open(os.path.join(ffbox_dir, "config.json"), "w", encoding="utf-8") as fh:
            json.dump({"web_host": "192.168.1.5", "catchup_secs": 4242,
                       "discord": {"app_token": "t", "server_id": "9",
                                   "channels": {"agent_testing": "111"},
                                   "trust": {"operators": {"loth": "600"}}}}, fh)
        importlib.reload(ffwatch)
        cfg = ffwatch.load_config()
        check("the settings are read from the ffbox file", cfg["web_host"] == "192.168.1.5"
              and cfg["catchup_secs"] == 4242, (cfg["web_host"], cfg["catchup_secs"]))
        check("the Discord section is read as read-only context, not merged into the settings",
              cfg["_discord"]["server_id"] == "9" and "app_token" not in cfg, sorted(cfg)[:5])
        check("the alias table comes from that section",
              ffwatch.discord_channels(cfg) == {"agent_testing": "111"},
              ffwatch.discord_channels(cfg))
        check("and so does the operator table the listener shares",
              ffwatch.operators(cfg) == {"loth": "600"}, ffwatch.operators(cfg))

        # A section that is missing, null or the wrong shape must not take the daemon down:
        # ffwatch runs unattended, and a hand-edited config is exactly where this happens.
        with open(os.path.join(ffbox_dir, "config.json"), "w", encoding="utf-8") as fh:
            json.dump({"web_host": "192.168.1.5", "discord": None}, fh)
        importlib.reload(ffwatch)
        cfg = ffwatch.load_config()
        check("a null discord section is read as absent rather than raising",
              ffwatch.discord_channels(cfg) == {} and ffwatch.operators(cfg) == {})

        # THE STATE HOME IS DERIVED, not configured: it hangs off ~/.config/ffbox whether or
        # not it exists yet, so the listener and ffwatch agree on where the doorbell is before
        # anything has created it.
        check("the state home sits under the ffbox directory",
              ffwatch.FFDISCORD_HOME == os.path.join(ffbox_dir, "discord"),
              ffwatch.FFDISCORD_HOME)
        check("and it is not where any configuration is read from",
              ffwatch.FFBOX_CONFIG == os.path.join(ffbox_dir, "config.json"),
              ffwatch.FFBOX_CONFIG)
    finally:
        os.environ.clear(); os.environ.update(saved)
        importlib.reload(ffwatch)

    services = open(os.path.join(HERE, "06-services.sh"), encoding="utf-8").read()
    check("the listener unit is told its home explicitly, since the launcher may be older",
          "@FFDHOME@" in services and "@FFDHOME@" in open(
              os.path.join(HERE, "systemd", "ffdiscord-listener.service"),
              encoding="utf-8").read(), )


def test_systemd_units_hang_off_one_target():
    """One handle: `systemctl enable --now ffbox.target` runs the whole pipeline, and stopping
    the target stops all of it.

    Three mistakes are cheap to make here and silent when made, so they are pinned:
      * a service that the target does not Want never starts with it;
      * a service without PartOf=ffbox.target is not stopped when the target stops;
      * StartLimit* under [Service] is IGNORED by systemd with only a log line — the same as
        having no restart ceiling at all, which is how a revoked token turns into a crash loop
        against Discord's gateway.
    """
    print("systemd: one target, three services")
    unit_dir = os.path.join(HERE, "systemd")
    services = ["ffdiscord-listener.service", "ffwatch.service", "ffweb.service"]
    target = open(os.path.join(unit_dir, "ffbox.target"), encoding="utf-8").read()

    for name in services:
        check(f"{name} is Wanted by the target, so it starts with it", name in target, target)
    check("the target installs into multi-user.target, so it survives a reboot with nobody "
          "logged in", "WantedBy=multi-user.target" in target, target)

    for name in services:
        body = open(os.path.join(unit_dir, name), encoding="utf-8").read()
        # Split on the SECTION HEADER, not the first occurrence of the string: these units
        # discuss "[Service]" in their own comments, and splitting on that lands mid-comment.
        unit_section = re.split(r"^\[Service\]$", body, flags=re.M)[0]
        check(f"{name} is PartOf the target, so a stop propagates to it",
              "PartOf=ffbox.target" in unit_section, unit_section)
        check(f"{name} installs under the target, not default.target",
              "WantedBy=ffbox.target" in body and "WantedBy=default.target" not in body, body)
        check(f"{name} runs as a named user rather than root",
              "User=@USER@" in body and "Group=@GROUP@" in body, body)
        check(f"{name} has no %h, which does NOT mean the user's home in a system unit",
              "%h" not in body, body)
        for key in ("StartLimitIntervalSec", "StartLimitBurst"):
            check(f"{name} keeps {key} in [Unit], where systemd actually reads it",
                  key in unit_section, unit_section)
        check(f"{name} restarts on its own", "Restart=always" in body, body)

    # The web UI is not optional any more (2026-08-22): the outbound queue, the run transcripts
    # and the verification rows are only legible through it.
    check("ffweb is part of the pipeline rather than an extra someone remembers to enable",
          "ffweb.service" in target)
    setup = open(os.path.join(HERE, "06-services.sh"), encoding="utf-8").read()
    # DERIVED FROM THE TEMPLATES, not a list kept by hand beside them. The hand-written list
    # said @CHANNELS_ARG@ long enough for the placeholder to be deleted from every template and
    # from the script, and the check still passed — it was asserting that the SCRIPT mentioned a
    # token nothing used. Reading the placeholders out of the units answers the question that
    # actually matters: is there one this script will leave in a live unit file.
    placeholders = set()
    for name in sorted(os.listdir(os.path.join(HERE, "systemd"))):
        body = open(os.path.join(HERE, "systemd", name), encoding="utf-8").read()
        placeholders |= set(re.findall(r"@[A-Z0-9_]+@", body))
    check("the templates carry placeholders at all", placeholders, placeholders)
    for token in sorted(placeholders):
        check(f"setup substitutes {token}", f"s|{token}|" in setup, )

    # THE UPDATER HOLDS NO ROOT. It fetches code off the internet every five minutes and then
    # executes it, so it runs as the checkout's owner and reaches for sudo exactly once, for the
    # systemctl verbs 02-zfsSetup grants it by name.
    upd_unit = open(os.path.join(HERE, "systemd", "ffbox-update.service"),
                    encoding="utf-8").read()
    check("the updater unit runs as the owner, not root",
          "User=@USER@" in upd_unit and "Group=@GROUP@" in upd_unit, upd_unit)
    upd = open(os.path.join(HERE, "update_ffbox.sh"), encoding="utf-8").read()
    check("and it never calls bare systemctl for a state change",
          "\nsystemctl stop" not in upd and "\nsystemctl start" not in upd, )
    check("it elevates only through the -n helper, which cannot hang on a prompt",
          "sudo -n systemctl" in upd, )
    zfs = open(os.path.join(HERE, "02-zfsSetup.sh"), encoding="utf-8").read()
    # The GRANT ITSELF, not the prose around it: pull the Cmnd_Alias body out and read it.
    alias_body = zfs.split("Cmnd_Alias FFBOX_UNITS =")[1].split("\n${OWNER}")[0]
    granted = [c.strip() for c in alias_body.replace("\\\\", "").split(",") if c.strip()]
    check("the updater is granted exactly two commands",
          granted == ["${SYSTEMCTL_BIN} stop ffbox.target",
                      "${SYSTEMCTL_BIN} start ffbox.target"], granted)
    check("with no wildcard, so no other unit can be named",
          "*" not in alias_body, alias_body)
    check("and nothing that writes a unit file, which would be root by another name",
          not any(w in alias_body for w in ("install", "cp ", "tee", "systemd/system")),
          alias_body)
    # ffbox-egress is the one ffbox unit with no User=, so it runs as root off a script in the
    # checkout. It must never become startable by the account that can edit that script.
    check("and never ffbox-egress, the one unit that runs as root",
          "egress" not in alias_body, alias_body)

    # THE ZFS GRANT IS REGEXES, NOT WILDCARDS, and the difference is the whole point. sudo
    # matches command arguments as one concatenated string in which '*' spans spaces and
    # slashes, so the `clone -o *` this rule carried until 2026-08-25 permitted
    # `-o mountpoint=/etc`: a dataset of the owner's own files mounted over /etc, no password.
    zfs_body = zfs.split("Cmnd_Alias FFBOX_ZFS =")[1].split("\n\n")[0]
    zfs_rules = [c.strip() for c in zfs_body.replace("\\\\", "").split(",") if c.strip()]
    check("the zfs grant spells out four commands", len(zfs_rules) == 4, zfs_rules)
    check("none of them uses a wildcard, which would swallow the rest of the command line",
          "*" not in zfs_body, zfs_body)
    check("every one is a regex anchored at both ends",
          all(r.split(" ", 1)[1].startswith("^") and r.endswith("\\$") for r in zfs_rules),
          zfs_rules)
    check("the clone rule pins the mountpoint under the runs directory",
          any("mountpoint=${RUNS_MNT}/run-" in r for r in zfs_rules), zfs_rules)
    check("and the free part of every rule is a run id, not an open pattern",
          all("${RUNID_RE}" in r for r in zfs_rules), zfs_rules)

    # The id class has to be the SAME one ffbox enforces on --run-id. Widening either alone
    # breaks runs or reopens the hole, and nothing at runtime notices.
    ffbox_src = open(os.path.join(HERE, "ffbox"), encoding="utf-8").read()
    check("the sudoers id class is the one ffbox validates --run-id against",
          "RUNID_RE='[A-Za-z0-9._-]+'" in zfs and "*[!A-Za-z0-9._-]*" in ffbox_src, )
    check("and it admits no slash, so a mountpoint cannot climb out of the runs directory",
          "/" not in "[A-Za-z0-9._-]", )

    # Now the rule as sudo will actually read it, against the invocation ffbox makes and the
    # ones it must refuse. This is the assertion that would have failed before the fix.
    clone_re = [r for r in zfs_rules if "^clone" in r][0].split(" ", 1)[1]
    for token, value in (("${RUNS_MNT}", "/opt/ffruns"), ("${GOLDEN_DS}", "rpool/ff/golden"),
                         ("${FF_DS}", "rpool/ff"), ("${RUNID_RE}", "[A-Za-z0-9._-]+")):
        clone_re = clone_re.replace(token, value)
    clone_re = clone_re.replace("\\$", "$")
    real = ("clone -o mountpoint=/opt/ffruns/run-d7t2-1a2b "
            "rpool/ff/golden@ffbox-d7t2-1a2b rpool/ff/run-d7t2-1a2b")
    check("the rule matches the clone ffbox actually runs", re.match(clone_re, real), clone_re)
    for hostile, why in (
            ("clone -o mountpoint=/etc rpool/ff/golden@ffbox-x rpool/ff/run-x",
             "a mountpoint outside the runs directory"),
            ("clone -o mountpoint=/opt/ffruns/run-x/../../../etc "
             "rpool/ff/golden@ffbox-x rpool/ff/run-x",
             "a mountpoint that climbs out with .."),
            ("clone -o mountpoint=/opt/ffruns/run-x -o setuid=on "
             "rpool/ff/golden@ffbox-x rpool/ff/run-x",
             "a second property riding along"),
            ("clone -o mountpoint=/opt/ffruns/run-x rpool/ff/golden@ffbox-x "
             "rpool/ROOT/ubuntu_g210oe",
             "a clone landing outside the ff dataset")):
        check(f"and refuses {why}", not re.match(clone_re, hostile), hostile)

    # Regexes need sudo 1.9.10. On an older one these rules match nothing and every run fails,
    # so the script says so before writing rather than leaving it to be discovered.
    check("the script refuses to write these rules on a sudo too old to read them",
          "sudo_regex_ok" in zfs and "sudo_regex_ok || die" in zfs, )

    # ---- ROOTLESS DOCKER -------------------------------------------------------------------
    # ffbox talks to a rootless daemon owned by the run user. The account is not in the docker
    # group, because membership there is root-equivalent. Everything below is a way that fact
    # can be quietly undone. See design/rootless_docker_design.txt.
    ffwatch_unit = open(os.path.join(unit_dir, "ffwatch.service"), encoding="utf-8").read()
    # Directives only: the unit explains in a COMMENT why the line is gone, and a naive
    # substring search would trip on the explanation.
    ffwatch_directives = "\n".join(l for l in ffwatch_unit.splitlines()
                                   if not l.lstrip().startswith("#"))
    check("ffwatch does not name the docker group, which a unit gets whether or not the "
          "account is still a member", "SupplementaryGroups" not in ffwatch_directives,
          ffwatch_directives)
    for name in ("ffwatch.service", "ffbox-update.service", "ffbox-egress.service",
                 "ffbox-docker.service"):
        body = open(os.path.join(unit_dir, name), encoding="utf-8").read()
        check(f"{name} exists and runs as the owner, not root",
              "User=@USER@" in body, body)
    for name in ("ffwatch.service", "ffbox-update.service", "ffbox-egress.service"):
        body = open(os.path.join(unit_dir, name), encoding="utf-8").read()
        check(f"{name} names the rootless socket, so docker cannot find the root daemon",
              "Environment=DOCKER_HOST=unix://@DOCKERSOCK@" in body, body)

    gate = open(os.path.join(unit_dir, "ffbox-docker.service"), encoding="utf-8").read()
    check("the gate is a oneshot that stays satisfied, so the wait is paid once per boot",
          "Type=oneshot" in gate and "RemainAfterExit=yes" in gate, gate)
    check("and it waits on the daemon rather than on the socket file, which appears first",
          "@WAITDOCKER@" in gate, gate)
    waiter = open(os.path.join(HERE, "wait-for-docker.sh"), encoding="utf-8").read()
    check("the waiter asks the daemon a question", "docker version" in waiter, )
    check("and fails rather than waiting forever", "exit 1" in waiter, )
    for name in ("ffwatch.service", "ffbox-egress.service"):
        body = open(os.path.join(unit_dir, name), encoding="utf-8").read()
        check(f"{name} orders after the gate, which system units cannot do against a user unit",
              "After=" in body and "ffbox-docker.service" in body, body)

    svc = open(os.path.join(HERE, "06-services.sh"), encoding="utf-8").read()
    check("06-services installs the gate along with the rest",
          "DOCKER_UNITS=" in svc and "$DOCKER_UNITS $UNIT_NAMES" in svc, )
    # Every placeholder any template uses, not a list somebody remembers to extend. An
    # unsubstituted @TOKEN@ reaches systemd as a literal and the unit fails at start.
    used = set()
    for fname in os.listdir(unit_dir):
        used |= set(re.findall(r"@[A-Z_]+@",
                               open(os.path.join(unit_dir, fname), encoding="utf-8").read()))
    missing = sorted(t for t in used if f"s|{t}|" not in svc)
    check("every placeholder in every template has a substitution", not missing, missing)
    check("and renders the socket from the OWNER's uid, not from whoever ran sudo",
          'id -u "$RUN_USER"' in svc, )

    # INSTALLING FROM THE WRONG CLONE. The units carry absolute paths rendered from $HERE, so
    # --install from a scratch checkout silently repoints ffwatch, ffweb, the fence and the
    # updater at it — and --check then agrees with whichever clone you ask, because it compares
    # against the caller. A box with four clones ran from the wrong one for an afternoon on
    # 2026-08-25 for exactly this reason.
    check("--install checks the recorded checkout before doing anything",
          "recorded_checkout" in svc and "REFUSING" in svc, )
    check("and the check comes before the root check, so the sudo round trip is not wasted",
          svc.index("REFUSING") < svc.index("--install writes to $UNIT_DIR"), )
    check("--force is the deliberate way past it", "--force)      FORCE=1" in svc, )
    check("which warns that the recorded path now needs updating too",
          "WARNING: --force" in svc and "registerAgents.sh" in svc, )
    check("a machine with nothing recorded is not blocked",
          "nothing recorded at" in svc, )
    check("--check says when its answer is about a clone the machine does not run from",
          "is not the recorded one" in svc, )
    check("and --force is documented in --help, whose sed range covers it",
          "--install --force" in svc and "sed -n '2,14p'" in svc, )

    # The egress fence lost its root. Nothing in the script may reach for privilege again, and
    # the `sudo docker` fallback in particular would have addressed the WRONG daemon.
    egress = open(os.path.join(HERE, "egress", "ffbox-egress.sh"), encoding="utf-8").read()
    egress_code = "\n".join(l for l in egress.splitlines() if not l.lstrip().startswith("#"))
    for banned in ("sudo ", "iptables", "as_root", "require_root"):
        check(f"the egress script no longer calls {banned.strip()}",
              banned not in egress_code, egress_code)
    egress_unit = open(os.path.join(unit_dir, "ffbox-egress.service"), encoding="utf-8").read()
    check("and its unit is no longer the one exception that runs as root",
          "User=@USER@" in egress_unit, egress_unit)

    # Nothing may put the group back. 01-dockerSetup added it until 2026-08-25, and setup.sh is
    # re-run unattended by the updater, so a usermod left in place would reopen the hole on a
    # schedule.
    for fname in ("01-dockerSetup.sh", "02-zfsSetup.sh", "06-services.sh", "setup.sh",
                  "update_ffbox.sh", "ffbox", "egress/ffbox-egress.sh"):
        body = open(os.path.join(HERE, fname), encoding="utf-8").read()
        code = "\n".join(l for l in body.splitlines() if not l.lstrip().startswith("#"))
        check(f"{fname} never adds anyone to the docker group",
              "usermod -aG docker" not in code and "gpasswd -a" not in code, fname)
        check(f"{fname} never shells out to `sudo docker`", "sudo docker" not in code, fname)

    # The updater re-runs setup rather than keeping a second model of what a diff "means".
    check("the updater re-runs setup.sh rather than reimplementing it",
          "ffbox/setup.sh" in upd and "--non-interactive" in upd, )
    st = open(os.path.join(HERE, "setup.sh"), encoding="utf-8").read()
    check("setup takes --non-interactive", "--non-interactive) NONINTERACTIVE=1" in st, )
    check("and skips the root stages rather than prompting for them",
          "needs_root()" in st and "SKIPPED" in st, )
    check("setup registers the agent plugins, which is how a skill bump reaches a box",
          "registerAgents.sh" in st, )
    check("no channel-name trigger list survives in the updater",
          "changed_match" not in upd, )
    # The page's bind address is config, not a constant in the unit — but it must DEFAULT to
    # loopback in every path, because the page has no authentication and shows raw model
    # thinking. A default that leaked would leak silently.
    check("ffwatch's config defaults the page to loopback",
          ffwatch.DEFAULTS["web_host"] == "127.0.0.1", ffwatch.DEFAULTS.get("web_host"))
    ffweb_src = open(os.path.join(HERE, "ffweb.py"), encoding="utf-8").read()
    check("and ffweb falls back to loopback when there is no config to read",
          'or "127.0.0.1"' in ffweb_src, )
    check("the unit carries no hard-coded address any more",
          "--host @WEBHOST@" in open(os.path.join(unit_dir, "ffweb.service"),
                                     encoding="utf-8").read(), )
    # git is the only source. A rendered copy kept beside the config was the previous design and
    # it meant two files on disk that could disagree — with systemd reading the stale one.
    check("there is an --install mode that installs straight from the checkout",
          "--install" in setup and 'install -m 0644 "$TMP/$u"' in setup, )
    # Installing a unit and leaving it stopped is a half-finished job — the setup path enables
    # and starts the target itself, and --no-enable is the opt-out.
    check("installing also enables and starts the target",
          "systemctl enable --now ffbox.target" in setup and "--no-enable" in setup, )
    # `enable --now` starts what is STOPPED and leaves what is running alone, so a re-install
    # without this leaves the old process serving the old command line while systemd cheerfully
    # reports "active". ffweb stayed bound to 127.0.0.1 through two correct installs that way.
    check("and restarts the units whose file it just changed",
          "WAS_ACTIVE" in setup and "systemctl restart \"$u\"" in setup, )
    check("the report also catches a process older than its unit file",
          "ActiveEnterTimestamp" in setup and "running with an OLDER unit" in setup, )
    check("nothing rendered is kept outside a temp dir — one source, no copy to go stale",
          'STAGE=$FFBOX_CONFIG' not in setup and 'render_units "$TMP"' in setup, )
    check("the install mode recovers the real user from SUDO_USER, since $HOME is root's "
          "under sudo", "SUDO_USER" in setup and "getent passwd" in setup, )
    # The two stages are split so neither can do the other's damage: 06-services.sh needs root
    # and touches only /etc, 05-discord-setup.sh touches only $HOME and refuses to run as root
    # (a root-owned state directory is one the service user cannot write).
    discord = open(os.path.join(HERE, "05-discord-setup.sh"), encoding="utf-8").read()
    check("the Discord stage owns no units at all",
          "systemctl" not in discord and "UNIT_DIR" not in discord, )
    check("and refuses to run under sudo, which would root-own the state directory",
          "run this WITHOUT sudo" in discord, )
    # setup.sh is the one command a new machine runs; a stage that is not wired in is a stage
    # somebody has to remember.
    top = open(os.path.join(HERE, "setup.sh"), encoding="utf-8").read()
    for script in ("01-dockerSetup.sh", "02-zfsSetup.sh", "03-build.sh",
                   "05-discord-setup.sh", "06-services.sh"):
        check(f"setup.sh runs {script}", f'"$ROOT/{script}"' in top, )


def test_allow_list_is_scope_not_a_boundary():
    """The enumerated allow list is gone. This records why it was never containment.

    Measured against the real CLI, not assumed: a command whose PREFIX matches no entry was
    refused (`sh -c 'git push origin main'` was denied and recorded), but a trailing `*` matched
    the whole command string including separators, so `git status --short && touch marker` was
    PERMITTED under `Bash(git status*)`. The pattern does not decompose a chain.

    That measurement is the reason removing the list cost nothing: it reduced scope and caught
    accidents, and a determined agent walked through it. What this pins now is that the reasoning
    survived the removal, and that the deny list — which never was a boundary either — is still
    carrying the four commands the harvest's identity check depends on.
    """
    print("allow list: scope, not a boundary, and now gone")
    src = open(os.path.join(HERE, "ffwatch.py"), encoding="utf-8").read()
    check("the measurement that justified removing it is still written down",
          "was PERMITTED under `Bash(git status*)`" in src
          and "matches the WHOLE command string" in src)
    check("and the real containment is named in its place",
          "no git or GitHub credential in the" in src
          and "the host owns the refspec and holds the only token" in src
          and "there is no merge method" in src, "see the CAPABILITY_TOOLS comment")

    check("bare Bash is granted, and it is required rather than decorative",
          ffwatch.CAPABILITIES["allowed"] == ["Bash"], ffwatch.CAPABILITIES["allowed"])
    check("because acceptEdits approves edits and not Bash, which is said where it is granted",
          "auto-approves EDITS and not Bash" in src)

    # The deny list is a tripwire and never was more. Four of its entries are load-bearing for a
    # different reason: they import commits somebody else authored, which is what the harvest's
    # identity check has no answer for.
    check("the tripwire still names every way to reach a remote",
          all(p in ffwatch.TRIPWIRE for p in
              ["Bash(git push*)", "Bash(gh *)", "Bash(git remote*)", "Bash(git fetch*)"]),
          ffwatch.TRIPWIRE)
    check("and the four that would import somebody else's commits",
          all(p in ffwatch.TRIPWIRE for p in
              ["Bash(git merge*)", "Bash(git rebase*)", "Bash(git cherry-pick*)",
               "Bash(git am*)"]), ffwatch.TRIPWIRE)
    check("nothing in the capability set can publish on its own",
          not [p for p in ffwatch.CAPABILITIES["allowed"]
               if "push" in p or "gh " in p or "remote" in p], ffwatch.CAPABILITIES)


def run_harvest(repo, out, *, branch, prefix="", run_id="d1t1-test", base_refs="",
                base_sha="", protected=None, range_from_start=False):
    """Run the REAL harvest-workspace.sh over a real repo. Returns (published_ok, branch, error).

    It used to lift a block of shell out of `ffbox` and exec it, on the reasoning that a
    re-implementation tests the test. That reasoning was right and the mechanism was not: the
    harvest moved into the container when the workspace became a tmpfs, the marker comment the
    block was cut at went with it, and the test raised IndexError from then on while the
    behaviour it covers went on working. Running the shipped script needs no marker to stay put
    and no fragment to stay self-contained — and it is the thing that actually runs.

    Everything it needs is a git repo and an output directory. No docker, no tmpfs, no network.
    """
    os.makedirs(out, exist_ok=True)
    env = {**os.environ,
           "FFBOX_WORKSPACE": repo,
           "FFBOX_OUT": out,
           "FFBOX_BRANCH": branch,
           "FFBOX_BRANCH_PREFIX": prefix,
           "FFBOX_BASE_REFS": base_refs,
           "FFBOX_RUN_ID": run_id,
           "FFBOX_GIT_NAME": "ffbox",
           "FFBOX_GIT_EMAIL": "ffbox@final-factory.invalid",
           "FFBOX_PROTECTED_BRANCHES": protected or "develop master main",
           "FFBOX_RANGE_FROM_START": "1" if range_from_start else "0"}
    if base_sha:
        env["FFBOX_BASE_SHA"] = base_sha
    done = subprocess.run(["bash", os.path.join(HERE, "harvest-workspace.sh")],
                          capture_output=True, text=True, env=env)
    if done.returncode != 0:
        raise AssertionError(f"harvest-workspace.sh aborted: {done.stderr[-400:]}")
    read = lambda n: (open(os.path.join(out, n), encoding="utf-8").read().strip()
                      if os.path.exists(os.path.join(out, n)) else "")
    error = read("harvest_error.txt")
    return (not error), read("branch.txt"), error


def seed_agent_repo(root, *, host_branch, ending):
    """A repo that looks like a workspace an agent has just finished in.

    `ending` is what the agent left HEAD on: a branch name, or None for a detached HEAD.
    """
    repo = os.path.join(root, "repo")
    shutil.rmtree(root, ignore_errors=True)
    os.makedirs(repo)

    def g(*args):
        return subprocess.run(["git", "-C", repo, *args], capture_output=True, text=True)

    subprocess.run(["git", "init", "-q", "-b", "master", repo], check=True)
    g("config", "user.email", "ffbox@final-factory.invalid"); g("config", "user.name", "ffbox")
    with io.open(os.path.join(repo, "Belt.cs"), "w", encoding="utf-8") as fh:
        fh.write("code\n")
    g("add", "-A"); g("commit", "-qm", "base")
    base = g("rev-parse", "HEAD").stdout.strip()
    g("checkout", "-q", "-B", host_branch)
    if ending is None:
        g("checkout", "-q", "--detach")
    elif ending != host_branch:
        g("checkout", "-q", "-B", ending)
    with io.open(os.path.join(repo, "Belt.cs"), "a", encoding="utf-8") as fh:
        fh.write("the agent's work\n")
    g("add", "-A"); g("commit", "-qm", "agent work")
    return repo, base


def run_branch_derivation(root, *, host_branch, prefix, run_id, ending, protected=None):
    """What name this run's work publishes under, from the real harvest. (ok, branch, out, repo)."""
    repo, base = seed_agent_repo(root, host_branch=host_branch, ending=ending)
    out = os.path.join(root, "out")
    ok, published, _ = run_harvest(repo, out, branch=host_branch, prefix=prefix, run_id=run_id,
                                   base_sha=base, protected=protected)
    return ok, published, out, repo


def seed_somebody_elses_branch(root, *, forged_run_commit=False):
    """A workspace on a branch a PERSON pushed, with this run's commit on top of theirs.

    Returns (repo, base_sha) where base_sha is where the run started — the tip of their work,
    which is what restore-workspace.sh records when the clone lands on their branch.
    """
    repo = os.path.join(root, "repo")
    shutil.rmtree(root, ignore_errors=True)
    os.makedirs(repo)

    def g(*args):
        return subprocess.run(["git", "-C", repo, *args], capture_output=True, text=True)

    subprocess.run(["git", "init", "-q", "-b", "master", repo], check=True)
    g("config", "user.email", "ffbox@final-factory.invalid"); g("config", "user.name", "ffbox")
    with io.open(os.path.join(repo, "Belt.cs"), "w", encoding="utf-8") as fh:
        fh.write("code\n")
    g("add", "-A"); g("commit", "-qm", "base")
    g("checkout", "-q", "-B", "loth/save-fix")
    with io.open(os.path.join(repo, "Save.cs"), "w", encoding="utf-8") as fh:
        fh.write("their work\n")
    g("add", "-A")
    g("-c", "user.name=Loth", "-c", "user.email=loth@example.invalid",
      "commit", "-qm", "save fix, by hand")
    start = g("rev-parse", "HEAD").stdout.strip()
    with io.open(os.path.join(repo, "Belt.cs"), "a", encoding="utf-8") as fh:
        fh.write("the agent's work\n")
    g("add", "-A")
    if forged_run_commit:
        g("-c", "user.name=Loth", "-c", "user.email=loth@example.invalid",
          "commit", "-qm", "agent work wearing a person's name")
    else:
        g("commit", "-qm", "agent work")
    return repo, start


def test_a_run_on_somebody_elses_branch_publishes_only_its_own_commits():
    """--range-from-start, and why a run on an adopted branch cannot publish without it.

    The identity check is what an agent-authored range is held to: every commit between the base
    and the tip must carry ffbox's own email, because a commit wearing a person's name on a
    branch a reviewer reads by author is how agent work would pass as human work. The base comes
    from the --base-refs scan, so on a branch somebody else pushed the range holds THEIR commits
    and the check refuses the whole publication -- correctly about the range, and about the
    wrong question. What it is meant to bound is what THIS RUN did.

    The flag moves the bottom of the range to where the run started and leaves the base NAME
    alone, so the pull request still targets master.
    """
    print("harvest: a run continuing somebody else's branch")
    # BOTH ENV PATHS, because a cold run gets its variables as -e on `docker create` and a
    # pooled one reads them out of a file pool-task.sh exports. A flag on one path only is a
    # flag that works until the box has a warm container.
    ffbox_src = open(os.path.join(HERE, "ffbox"), encoding="utf-8").read()
    check("the flag reaches a cold container and a dispatched one alike",
          ffbox_src.count("FFBOX_RANGE_FROM_START") == 2
          and '-e "FFBOX_RANGE_FROM_START=$RANGE_FROM_START"' in ffbox_src
          and "printf 'FFBOX_RANGE_FROM_START=%s\\n' \"$RANGE_FROM_START\"" in ffbox_src,
          ffbox_src.count("FFBOX_RANGE_FROM_START"))

    root = os.path.join(TMPROOT, "adoptrange")
    repo, start = seed_somebody_elses_branch(root)
    out = os.path.join(root, "out")

    ok, published, error = run_harvest(repo, out, branch="loth/save-fix", base_refs="master",
                                       base_sha=start)
    check("without the flag the range reaches back over their commits and is refused",
          not ok and "identity this run does not own" in error, error)

    shutil.rmtree(out, ignore_errors=True)
    ok, published, error = run_harvest(repo, out, branch="loth/save-fix", base_refs="master",
                                       base_sha=start, range_from_start=True)
    check("with it the run publishes", ok and published == "loth/save-fix", (published, error))
    read = lambda n: open(os.path.join(out, n), encoding="utf-8").read().strip()
    check("the range starts at the commit the run began on", read("publish_base_sha.txt")
          == start, (read("publish_base_sha.txt"), start))
    check("only this run's own file is in the range",
          read("changed_files.txt").split() == ["Belt.cs"], read("changed_files.txt"))
    check("and the base NAME is still master, so the pull request is aimed the same way",
          read("publish_base.txt") == "master", read("publish_base.txt"))

    # THE FENCE IS NOT WEAKENED: it still covers every commit the run itself made.
    shutil.rmtree(out, ignore_errors=True)
    repo, start = seed_somebody_elses_branch(os.path.join(TMPROOT, "adoptforge"),
                                             forged_run_commit=True)
    out = os.path.join(TMPROOT, "adoptforge", "out")
    ok, published, error = run_harvest(repo, out, branch="loth/save-fix", base_refs="master",
                                       base_sha=start, range_from_start=True)
    check("a commit THIS RUN made wearing a person's name is still refused",
          not ok and "identity this run does not own" in error, error)

    # No start commit, or one the work does not descend from, is refused HERE rather than
    # bundled from the base ref -- which is what produces the identity refusal three steps later
    # with a message about the wrong thing.
    repo, start = seed_somebody_elses_branch(os.path.join(TMPROOT, "adoptnostart"))
    out = os.path.join(TMPROOT, "adoptnostart", "out")
    ok, published, error = run_harvest(repo, out, branch="loth/save-fix", base_refs="master",
                                       base_sha="", range_from_start=True)
    check("the flag with no start commit refuses and says so",
          not ok and "no start commit was recorded" in error, error)
    shutil.rmtree(out, ignore_errors=True)
    stranger = subprocess.run(["git", "-C", repo, "rev-parse", "master"],
                              capture_output=True, text=True).stdout.strip()
    subprocess.run(["git", "-C", repo, "checkout", "-q", "-B", "loth/save-fix", "master"],
                   check=True)
    ok, published, error = run_harvest(repo, out, branch="loth/save-fix", base_refs="master",
                                       base_sha=start, range_from_start=True)
    check("and a start commit the work does not descend from refuses too",
          not ok and "does not descend from the commit this run started at" in error, error)
    del stranger


def test_the_agent_names_the_branch_it_publishes():
    """The branch the agent made is the branch a reviewer reads, and develop is refused.

    The host still creates ffbox/<run id> and starts the run on it, so nothing is lost by an
    agent that never branches. What the rule buys is the name: `ffbox/belt-merger-priority-<id>`
    says what the change is where a run id says only which run made it. The run id is on the end
    of every one of them because two runs at the same bug pick the same obvious name, and a name
    that already exists on origin is a push rejected at the end of an hour's work.
    """
    print("harvest: the agent names its own branch")
    root = os.path.join(TMPROOT, "branchname")
    run_id = "d7t2-1a2b3c4d"

    ok, published, out, _ = run_branch_derivation(
        root, host_branch=f"ffbox/{run_id}", prefix="ffbox/", run_id=run_id,
        ending="belt-merger-priority")
    check("a branch the agent made publishes under its own name",
          (ok, published) == (True, f"ffbox/belt-merger-priority-{run_id}"), (ok, published))
    check("and nothing was refused", not os.path.exists(os.path.join(out, "harvest_error.txt")))

    ok, published, _, _ = run_branch_derivation(
        root, host_branch=f"ffbox/{run_id}", prefix="ffbox/", run_id=run_id,
        ending="ffbox/already-prefixed")
    check("a name that already carries the prefix is not prefixed twice",
          published == f"ffbox/already-prefixed-{run_id}", published)

    # git itself refuses a space, a tilde or a colon in a branch name, so this is what an agent
    # CAN hand over: legal to git, unwanted in a refspec the host pushes.
    ok, published, _, _ = run_branch_derivation(
        root, host_branch=f"ffbox/{run_id}", prefix="ffbox/", run_id=run_id,
        ending="fix&the;merger")
    check("a name legal to git but unwanted in a refspec is sanitised, not passed through",
          (ok, published) == (True, f"ffbox/fix-the-merger-{run_id}"), (ok, published))

    ok, published, _, _ = run_branch_derivation(
        root, host_branch=f"ffbox/{run_id}", prefix="ffbox/", run_id=run_id, ending=None)
    check("a detached HEAD publishes under the host's own name, so the work is not lost",
          (ok, published) == (True, f"ffbox/{run_id}"), (ok, published))

    ok, published, _, _ = run_branch_derivation(
        root, host_branch=f"ffbox/{run_id}", prefix="ffbox/", run_id=run_id,
        ending=f"ffbox/{run_id}")
    check("an agent that never branched keeps the host's name, with no second run id on it",
          (ok, published) == (True, f"ffbox/{run_id}"), (ok, published))

    for shared in ("develop", "master"):
        ok, published, out, repo = run_branch_derivation(
            root, host_branch=f"ffbox/{run_id}", prefix="ffbox/", run_id=run_id, ending=shared)
        reason = io.open(os.path.join(out, "harvest_error.txt"), encoding="utf-8").read()
        check(f"a run that ends on {shared} is refused", not ok, (ok, published))
        check("with a reason that says which branch it was, for the reply",
              shared in reason and "branch of its own" in reason, reason)
        check("and no branch file for the host to publish from",
              not os.path.exists(os.path.join(out, "branch.txt")))

    # `ffbox --branch wip "..."` at a terminal: somebody asked for a name and got it.
    ok, published, _, _ = run_branch_derivation(
        root, host_branch="wip", prefix="", run_id=run_id, ending="explored")
    check("without a prefix the harness's own name still publishes",
          (ok, published) == (True, "wip"), (ok, published))


def test_a_local_run_publishes_like_a_dev_dm():
    """A shell or web prompt is a dev turn with nobody to post to — and nothing else.

    It used to be much more than that: no verification, no branch, no push, no pull request, on
    the reasoning that the person who typed it was standing at the terminal. What that produced
    was a patch file in a run directory, because the ZFS clone the work lived in is destroyed
    when the run ends. So the flow is the operator DM's now, and locality decides the reply.
    """
    print("publication: a local prompt takes the same flow as a dev DM")
    case = Case("localpublish")
    origin, host = git_origin(case)
    os.environ["FFBOX_STUB_CHANGED"] = json.dumps(["Assets/Belt.cs"])
    os.environ["FFBOX_STUB_VERIFY"] = json.dumps(PASSING_VERIFY)
    os.environ["FFBOX_STUB_VERDICT"] = json.dumps(CONFIDENT_VERDICT)
    os.environ["FFBOX_STUB_AGENT_BRANCH"] = "belt-merger-priority"
    try:
        turn_id = case.watcher.submit("make the belt merger respect item priority")
        case.watcher.once()
    finally:
        for key in ("FFBOX_STUB_CHANGED", "FFBOX_STUB_VERIFY", "FFBOX_STUB_VERDICT",
                    "FFBOX_STUB_AGENT_BRANCH"):
            os.environ.pop(key, None)

    run = case.rows("SELECT * FROM run WHERE turn_id=?", (turn_id,))[0]
    expected = f"ffbox/belt-merger-priority-{run['ffbox_run_id']}"
    check("the agent's name for the work is what the host published",
          run["branch"] == expected, run["branch"])
    check("and it really was pushed", run["pushed"] == 1, run)
    check("the branch exists on the remote",
          expected in git_run("-C", host, "ls-remote", "--heads", "origin").stdout)
    check("and is checkoutable in the host checkout, tracking origin",
          git_run("-C", host, "config",
                  f"branch.{expected}.merge").stdout.strip() == f"refs/heads/{expected}",
          git_run("-C", host, "branch", "--list").stdout)

    pull = GH_STATE["pulls"][-1]
    check("a pull request opened, against develop like any other",
          (pull["_head"], pull["base"]) == (expected, "develop"), pull)
    check("whose body says where the prompt came from, and does not invent a Discord thread",
          "on the build server" in (pull["body"] or "")
          and "from Discord" not in (pull["body"] or ""), (pull["body"] or "")[:400])
    # A LOOPBACK PAGE IS NOT A LINK. This case's config never widened web_host, and 127.0.0.1 in
    # a pull request points at the reader's own laptop; the bottom block still names the
    # conversation, which is all that was ever true.
    conv = case.rows("SELECT * FROM conversation")[0]
    check("and offers no link to a page only this machine can reach",
          "https://127.0.0.1" not in (pull["body"] or "")
          and not (pull["body"] or "").startswith("From ["), (pull["body"] or "")[:200])
    case.watcher.cfg["web_host"] = "192.168.51.10"
    body = case.watcher.pr_body(run["id"], conv, {"run_id": run["ffbox_run_id"]},
                                CONFIDENT_VERDICT)
    expect = (f"From [ffbox conversation {conv['id']}]"
              f"(https://192.168.51.10:8787/conversation/{conv['id']}).")
    check("once the page is reachable, the same first line points at the ffbox conversation",
          body.startswith(expect), body[:200])

    check("nothing was queued for Discord, because there is no thread to answer",
          not case.rows("SELECT * FROM outbound"), case.rows("SELECT * FROM outbound"))
    line = case.watcher.publish_line(turn_id)
    check("and the person who typed the prompt is told where the work went",
          expected in line and str(pull["number"]) in line, line)

    # `ffbox --branch wip "..."` names the work; it does not claim the top level of the
    # repository's branch namespace, and it is still only the name the run STARTS on.
    os.environ["FFBOX_STUB_CHANGED"] = json.dumps(["Assets/Belt.cs"])
    os.environ["FFBOX_STUB_VERIFY"] = json.dumps(PASSING_VERIFY)
    os.environ["FFBOX_STUB_VERDICT"] = json.dumps(dict(CONFIDENT_VERDICT, confident=False,
                                                       confidence_reason="wanted a look first"))
    try:
        second = case.watcher.submit("try the other approach", branch="wip")
        case.watcher.once()
    finally:
        for key in ("FFBOX_STUB_CHANGED", "FFBOX_STUB_VERIFY", "FFBOX_STUB_VERDICT"):
            os.environ.pop(key, None)
    run2 = case.rows("SELECT * FROM run WHERE turn_id=?", (second,))[0]
    check("a hand-chosen name is published under the same prefix as everything else",
          run2["branch"] == "ffbox/wip" and run2["pushed"] == 1,
          (run2["branch"], run2["pushed"]))
    check("and it reached the remote under exactly that name",
          "refs/heads/ffbox/wip" in git_run("-C", host, "ls-remote", "--heads",
                                            "origin").stdout)
    check("but no pull request, because the agent was not confident",
          run2["pr_number"] is None and "wanted a look first" in (run2["no_pr_reason"] or ""),
          (run2["pr_number"], run2["no_pr_reason"]))


def test_a_run_that_changed_nothing_is_not_verified():
    """The suite costs fifteen minutes and the machine's one Unity slot, so it is skipped.

    This is what let verification be turned on for locally typed prompts without making
    `ffbox "which file defines the belt merger?"` a quarter of an hour. The decision is the
    CONTAINER's, taken after the agent process is gone and measured against a HEAD read before
    it started, because everything under /ffbox/out is writable by the agent.
    """
    print("verification: nothing changed, nothing to test")
    task = io.open(os.path.join(HERE, "discord-task.sh"), encoding="utf-8").read()
    check("the pre-agent HEAD is read before the agent is launched",
          task.index("PRE_AGENT_HEAD=") < task.index('"${ARGV[@]}"'))
    check("and it is what the skip is measured against, not anything under /ffbox/out",
          "PRE_AGENT_HEAD=$(git" in task
          and 'diff --quiet "$PRE_AGENT_HEAD" HEAD' in task)

    fn = "run_changed_anything() {" + \
        task.split("run_changed_anything() {")[1].split("\n}\n")[0] + "\n}\n"
    root = os.path.join(TMPROOT, "nothing")
    repo = os.path.join(root, "repo")
    shutil.rmtree(root, ignore_errors=True)
    os.makedirs(repo)

    def g(*args):
        return subprocess.run(["git", "-C", repo, *args], capture_output=True, text=True)

    subprocess.run(["git", "init", "-q", repo], check=True)
    g("config", "user.email", "t@t"); g("config", "user.name", "t")
    with io.open(os.path.join(repo, "Belt.cs"), "w", encoding="utf-8") as fh:
        fh.write("code\n")
    g("add", "-A"); g("commit", "-qm", "base")
    base = g("rev-parse", "HEAD").stdout.strip()

    def changed():
        script = "\n".join(["set -euo pipefail", 'WORKSPACE="$1"', 'PRE_AGENT_HEAD="$2"', fn,
                             'if run_changed_anything; then echo CHANGED; else echo NOTHING; fi'])
        done = subprocess.run(["bash", "-c", script, "task", repo, base],
                              capture_output=True, text=True)
        if done.returncode != 0:
            raise AssertionError(done.stderr[-300:])
        return done.stdout.strip()

    check("a run that touched nothing has nothing to verify", changed() == "NOTHING", changed())
    with io.open(os.path.join(repo, "Belt.cs"), "a", encoding="utf-8") as fh:
        fh.write("edited but not committed\n")
    check("an uncommitted edit is a change", changed() == "CHANGED", changed())
    g("add", "-A"); g("commit", "-qm", "the agent's own commit")
    check("and so is one the agent committed", changed() == "CHANGED", changed())
    reverted = g("revert", "--no-edit", "HEAD")
    check("the revert itself worked, or the check below proves nothing",
          reverted.returncode == 0, reverted.stderr[-200:])
    check("a change the agent committed and then undid is not",
          changed() == "NOTHING", changed())

    # The host's half: a skipped suite is a third state, and it must not read as a failed one.
    case = bug_case("skipped", venue="private")
    git_origin(case)
    escalate(case, changed=[], verify={"ran": False, "skipped": True, "compiled": None,
                                       "evidence": "the run changed no files, so the harness "
                                                   "ran no tests"},
             verdict=dict(CONFIDENT_VERDICT, changed_anything=False,
                          summary="Already fixed on develop."))
    run = case.rows("SELECT r.* FROM run r JOIN turn t ON t.id=r.turn_id"
                    " ORDER BY r.id DESC")[0]
    ver = case.rows("SELECT * FROM verification WHERE run_id=?", (run["id"],))[0]
    check("the row records that it was skipped, not that it failed",
          (ver["ran"], ver["skipped"]) == (0, 1), dict(ver))
    text = json.loads(case.rows("SELECT * FROM outbound WHERE run_id=? AND action='post'",
                                (run["id"],))[0]["payload_json"])["text"]
    check("and the reply is the answer alone, with no NOT VERIFIED and no bookkeeping",
          text == "Already fixed on develop.", text[:400])
    check("nothing tells the reader that a run which changed nothing ran no tests",
          "no tests" not in text and "NOT VERIFIED" not in text, text[:400])
    check("nor that it published no branch, which nobody asked it to",
          "no branch" not in text and "bundled" not in text, text[:400])


def test_an_unverified_branch_is_what_the_next_turn_tests():
    """The skip asks what the RUN changed; the branch is what has to be verified.

    Conversation 133, exactly. Turn 3 pushed four files and never got a verdict -- it was
    killed on the agent clock with the suite still to run. Turn 4 resumed onto the branch, ran
    the tests by hand, reported them green and edited nothing, so the container skipped the
    suite over a tree carrying real work. Nothing downstream could rescue that: the gate wants
    a row for the run in front of it, and reconcile_publication re-ran the same gate against
    the same unverified run every sweep. The fix is one flag the HOST decides and the container
    obeys -- the agent's word for the test results is worth nothing here and is never asked for.
    """
    print("verification: a branch nothing has passed is tested by the turn that changes nothing")
    case = bug_case("stranded", venue="private")
    origin, host = git_origin(case)

    # Turn one: files change, no verification report comes back at all.
    escalate(case, changed=["Assets/Belt.cs"], verify=None)
    first = case.rows("SELECT r.* FROM run r JOIN turn t ON t.id=r.turn_id"
                      " ORDER BY r.id DESC")[0]
    check("the work reaches origin", first["pushed"] == 1 and first["branch"],
          (first["pushed"], first["branch"]))
    check("but nothing verified it, so no pull request opens",
          first["pr_number"] is None and "could not verify" in (first["no_pr_reason"] or ""),
          (first["pr_number"], first["no_pr_reason"]))
    first_job = json.load(io.open(os.path.join(case.watcher.conv_dir(1), "runs",
                                               first["ffbox_run_id"], "job.json"),
                                  encoding="utf-8"))
    check("that turn asked for no special treatment: there was no branch yet when it launched",
          first_job["verify"]["even_if_unchanged"] is False, first_job["verify"])

    # Turn two: the agent reads the branch, re-runs the tests itself, and edits nothing.
    escalate(case, changed=[], verify=PASSING_VERIFY,
             verdict=dict(CONFIDENT_VERDICT, summary="Tests pass on the branch."))
    second = case.rows("SELECT r.* FROM run r JOIN turn t ON t.id=r.turn_id"
                       " ORDER BY r.id DESC")[0]
    second_dir = os.path.join(case.watcher.conv_dir(1), "runs", second["ffbox_run_id"])
    second_job = json.load(io.open(os.path.join(second_dir, "job.json"), encoding="utf-8"))
    check("this one is told to run the suite even though the run changed nothing",
          second_job["verify"]["even_if_unchanged"] is True, second_job["verify"])
    check("the branch is still harvested, because the commits are on it either way",
          second["branch"] == first["branch"] and second["changed_files"] == 1,
          (second["branch"], second["changed_files"]))
    ver = case.rows("SELECT * FROM verification WHERE run_id=?", (second["id"],))[0]
    check("and the suite is what answered, not the agent's summary",
          (ver["ran"], ver["skipped"], ver["tests_passed"]) == (1, 0, 214), dict(ver))
    check("so the work the earlier turn stranded gets its pull request",
          second["pr_number"] is not None, (second["pr_number"], second["no_pr_reason"]))
    conv = case.rows("SELECT * FROM conversation")[0]
    check("and the conversation records it", bool(conv["github_pr"]), conv["github_pr"])

    # Turn three: there is a pull request now, so the expensive answer stops being given.
    escalate(case, changed=[], verify=PASSING_VERIFY,
             verdict=dict(CONFIDENT_VERDICT, summary="Nothing further."))
    third = case.rows("SELECT r.* FROM run r JOIN turn t ON t.id=r.turn_id"
                      " ORDER BY r.id DESC")[0]
    third_job = json.load(io.open(os.path.join(case.watcher.conv_dir(1), "runs",
                                               third["ffbox_run_id"], "job.json"),
                                  encoding="utf-8"))
    check("once the branch is under review the flag goes back off",
          third_job["verify"]["even_if_unchanged"] is False, third_job["verify"])


def test_the_container_obeys_the_host_about_an_untouched_tree():
    """The other half of the flag, read out of the script that acts on it.

    The skip and the override are shell, not Python, so the only honest test of them is the
    shell: the flag is read from job.json -- not from anything the agent can reach -- and it is
    what decides whether an untouched tree writes a `skipped` report or goes to the editor.
    """
    print("verification: the container's half of the override")
    task = io.open(os.path.join(HERE, "discord-task.sh"), encoding="utf-8").read()
    check("the flag comes out of job.json, like every other capability",
          "v.get('even_if_unchanged')" in task and 'VERIFY_UNCHANGED=$(python3' in task)
    read_it = task.split("VERIFY_UNCHANGED=$(python3")[1].split("\n\n")[0]
    check("and it is read from $JOB_FILE, not from anything under /ffbox/out",
          '"$JOB_FILE"' in read_it and "FFBOX_OUT" not in read_it, read_it)

    block = task.split("CHANGED_START=$(date +%s)")[1].split("\nlog ")[0]
    check("an untouched tree only writes the skipped report when the host did not override it",
          'if [ "$VERIFY_UNCHANGED" = 1 ]; then' in block
          and block.index('if [ "$VERIFY_UNCHANGED" = 1 ]; then')
              < block.index("verification skipped: this run changed no files"), block)
    check("and the override leaves VERIFY_ENABLED alone, so the suite actually runs",
          block.count("VERIFY_ENABLED=0") == 1
          and block.index('if [ "$VERIFY_UNCHANGED" = 1 ]; then')
              < block.index("VERIFY_ENABLED=0"), block)


def test_the_agents_work_is_committed_before_verification_opens_the_project():
    """discord-task.sh's half: commit what the agent left, then name the commit that was.

    Read out of the shipped script and run over a real repo, because the order IS the behaviour:
    after the agent is gone, or it races the agent; before ffverify, or it commits whatever the
    editor reserializes along with the agent's work. d133t5's branch gained exactly that commit.
    """
    print("verification: the agent's work is committed before the editor opens the project")
    task = io.open(os.path.join(HERE, "discord-task.sh"), encoding="utf-8").read()
    opener = 'if [ -n "$PRE_AGENT_HEAD" ]; then\n    rm -f "$FFBOX_OUT/.agent-work-committed"'
    at = task.index(opener)
    check("it runs after the agent is gone", task.index("\nlift_result\n") < at)
    check("and before the harness's own verification", at < task.index("ffverify --out"))
    block = task[at:task.index("\nfi\n", at) + 4]
    harvest = io.open(os.path.join(HERE, "harvest-workspace.sh"), encoding="utf-8").read()
    check("the harvest reads the same marker, and believes it only for the commit it names",
          ".agent-work-committed" in harvest
          and '"$AGENT_COMMITTED" = "$(g rev-parse HEAD' in harvest)

    root = os.path.join(TMPROOT, "commit-before-verify")
    repo, out = os.path.join(root, "repo"), os.path.join(root, "out")
    shutil.rmtree(root, ignore_errors=True)
    os.makedirs(repo)
    os.makedirs(out)
    git_run("init", "-q", repo)
    git_run("-C", repo, "config", "user.email", "t@t.invalid")
    git_run("-C", repo, "config", "user.name", "t")
    with io.open(os.path.join(repo, "Belt.cs"), "w", encoding="utf-8") as fh:
        fh.write("base\n")
    git_run("-C", repo, "add", "-A")
    git_run("-C", repo, "commit", "-qm", "base")
    pre = git_run("-C", repo, "rev-parse", "HEAD").stdout.strip()

    def run_block():
        script = "\n".join(['log() { printf "%s\\n" "$*"; }', 'WORKSPACE="$1"',
                            'PRE_AGENT_HEAD="$2"', 'FFBOX_OUT="$3"', "FFBOX_RUN_ID=d1t1-test",
                            "FFBOX_GIT_NAME=ffbox", "FFBOX_GIT_EMAIL=ffbox@final-factory.invalid",
                            block])
        done = subprocess.run(["bash", "-c", script, "task", repo, pre, out],
                              capture_output=True, text=True)
        if done.returncode != 0:
            raise AssertionError(done.stderr[-300:])
        return done.stdout

    def marker():
        return io.open(os.path.join(out, ".agent-work-committed"), encoding="utf-8").read().strip()

    with io.open(os.path.join(repo, "Belt.cs"), "a", encoding="utf-8") as fh:
        fh.write("the agent's edit, never committed\n")
    os.makedirs(os.path.join(repo, ".github"))
    with io.open(os.path.join(repo, ".github", "ci.yml"), "w", encoding="utf-8") as fh:
        fh.write("on: push\n")
    said = run_block()
    head = git_run("-C", repo, "rev-parse", "HEAD").stdout.strip()
    shown = git_run("-C", repo, "show", "--name-only", "--format=%s%n%ae", head).stdout
    check("the agent's edit is committed", head != pre and "Belt.cs" in shown, shown)
    check("under the harvest's own message for a run that made no commits of its own",
          shown.splitlines()[0] == "ffbox d1t1-test: agent work", shown)
    check("and as the run's identity, which the harvest's identity check holds it to",
          "ffbox@final-factory.invalid" in shown.splitlines()[1], shown)
    check("the marker names that commit", marker() == head, (marker(), head))
    check(".github stays out of it, as it does in the harvest",
          ".github/ci.yml" in git_run("-C", repo, "ls-files", "-o").stdout)
    check("and the log says it happened",
          "committed the agent's uncommitted work before verification" in said, said)

    run_block()
    check("a second pass over a clean tree commits nothing",
          git_run("-C", repo, "rev-parse", "HEAD").stdout.strip() == head)
    check("and still vouches for the commit HEAD is on", marker() == head, marker())


def test_the_harvest_leaves_out_what_verification_changed():
    """The agent's work is in the range; what the editor changed afterwards is not.

    d133t5's harvest swept the tree after the harness's own Unity run had been in it, and the
    branch gained a commit the agent never made: DysonPlatformPowerBeam.mat, render queue 3000
    to 2000, plus a report a test run wrote. With the marker naming HEAD, the harvest commits
    nothing on the agent's behalf. A marker naming any other commit is not believed, which is
    what keeps a run killed before verification harvested exactly as it always was.
    """
    print("harvest: what verification changed is not the run's work")

    def workspace(root):
        origin, repo, seed = (os.path.join(root, n) for n in ("origin.git", "repo", "seed"))
        shutil.rmtree(root, ignore_errors=True)
        os.makedirs(root)
        git_run("init", "-q", "--bare", "-b", "master", origin)
        git_run("clone", "-q", origin, seed)
        git_run("-C", seed, "config", "user.email", "t@t.invalid")
        git_run("-C", seed, "config", "user.name", "test")
        with io.open(os.path.join(seed, "Beam.mat"), "w", encoding="utf-8") as fh:
            fh.write("m_CustomRenderQueue: 3000\n")
        git_run("-C", seed, "add", "-A")
        git_run("-C", seed, "commit", "-qm", "released")
        git_run("-C", seed, "push", "-q", "origin", "HEAD:refs/heads/master")
        git_run("-C", seed, "push", "-q", "origin", "HEAD:refs/heads/develop")
        git_run("clone", "-q", origin, repo)
        git_run("-C", repo, "config", "user.email", "ffbox@final-factory.invalid")
        git_run("-C", repo, "config", "user.name", "ffbox")
        git_run("-C", repo, "checkout", "-q", "-b", "the-agents-branch", "origin/develop")
        start = git_run("-C", repo, "rev-parse", "HEAD").stdout.strip()
        with io.open(os.path.join(repo, "Belt.cs"), "w", encoding="utf-8") as fh:
            fh.write("the agent's fix\n")
        git_run("-C", repo, "add", "-A")
        git_run("-C", repo, "commit", "-qm", "the agent's fix")
        out = os.path.join(root, "out")
        os.makedirs(out)
        return repo, out, start

    def verification_was_here(repo):
        with io.open(os.path.join(repo, "Beam.mat"), "w", encoding="utf-8") as fh:
            fh.write("m_CustomRenderQueue: 2000\n")
        os.makedirs(os.path.join(repo, "reports"), exist_ok=True)
        with io.open(os.path.join(repo, "reports", "t004-proxy.json"), "w", encoding="utf-8") as fh:
            fh.write("{}\n")

    def changed(out):
        path = os.path.join(out, "changed_files.txt")
        return (io.open(path, encoding="utf-8").read().split()
                if os.path.exists(path) else [])

    repo, out, start = workspace(os.path.join(TMPROOT, "harvest-marker"))
    head = git_run("-C", repo, "rev-parse", "HEAD").stdout.strip()
    with io.open(os.path.join(out, ".agent-work-committed"), "w", encoding="utf-8") as fh:
        fh.write(head + "\n")
    verification_was_here(repo)
    ok, branch, error = run_harvest(repo, out, branch="ffbox/marker-test",
                                    base_refs="master develop", base_sha=start)
    check("the run still publishes", ok and branch == "ffbox/marker-test", (ok, branch, error))
    check("with the agent's file in it", "Belt.cs" in changed(out), changed(out))
    check("and neither the asset the editor reserialized nor the report a test wrote",
          "Beam.mat" not in changed(out) and "reports/t004-proxy.json" not in changed(out),
          changed(out))
    check("no commit was made on the agent's behalf",
          git_run("-C", repo, "rev-parse", "ffbox/marker-test").stdout.strip() == head)

    repo2, out2, start2 = workspace(os.path.join(TMPROOT, "harvest-stale-marker"))
    with io.open(os.path.join(out2, ".agent-work-committed"), "w", encoding="utf-8") as fh:
        fh.write(start2 + "\n")
    verification_was_here(repo2)
    ok2, _, error2 = run_harvest(repo2, out2, branch="ffbox/marker-test",
                                 base_refs="master develop", base_sha=start2)
    check("a marker naming some other commit is ignored, and the tree is swept as before",
          ok2 and "Beam.mat" in changed(out2) and "reports/t004-proxy.json" in changed(out2),
          (ok2, changed(out2), error2))


def test_a_base_the_container_could_not_name_is_found_on_the_host():
    """A shallow workspace names no base; the host has the history to find the right one.

    CI's cache entries are depth-limited clones, `git merge-base` finds no fork point inside one,
    and the harvest then writes no publish_base.txt. pr_base used to try the default and nothing
    else, so conversation 133's fifth turn -- develop-based, suite green -- was refused master and
    never offered develop. Every allowed base is tried now, in publish_bases order, under the same
    check that refuses a base which does not carry the work's fork points.
    """
    print("publication: a base the container could not name is found on the host")

    def published(name, base):
        case = bug_case(name)
        git_origin(case)
        os.environ["FFBOX_STUB_BASE"] = base
        try:
            escalate(case, changed=["Assets/Belt.cs"], verify=PASSING_VERIFY)
        finally:
            os.environ.pop("FFBOX_STUB_BASE", None)
        run = case.rows("SELECT r.* FROM run r JOIN turn t ON t.id=r.turn_id"
                        " ORDER BY r.id DESC")[0]
        run_dir = os.path.dirname(run["stream_path"])
        os.remove(os.path.join(run_dir, "publish_base.txt"))
        return case, run, run_dir

    case, run, run_dir = published("prbaseshallow", "develop")
    # The build server's shape: master is both the default and the first key.
    case.watcher.cfg["github"]["base"] = "master"
    base, reason = case.watcher.pr_base(run["id"], run_dir, run["branch"])
    check("develop-based work that names no base is proposed into develop, not refused",
          base == "develop", (base, reason))
    with io.open(os.path.join(run_dir, "publish_base.txt"), "w", encoding="utf-8") as fh:
        fh.write("refs/heads/../../evil\n")
    base, reason = case.watcher.pr_base(run["id"], run_dir, run["branch"])
    check("and so is the same work naming a base outside the configured set",
          base == "develop", (base, reason))
    base, reason = case.watcher.pr_base(run["id"], run_dir, run["branch"], required="master")
    check("an operator's base is still the only candidate",
          base is None and "asked to be based on `master`" in (reason or ""), (base, reason))

    case2, run2, run_dir2 = published("prbaseshallowmaster", "master")
    check("the test box's default is develop, which master-based work also passes the check for",
          case2.watcher.cfg["github"]["base"] == "develop", case2.watcher.cfg["github"])
    base, reason = case2.watcher.pr_base(run2["id"], run_dir2, run2["branch"])
    check("so master-based work that names no base still goes to master, in publish_bases order",
          base == "master", (base, reason))


def run_base_resolution(root, *, base_refs, ending):
    """Which branch the work is for, from the real harvest, over a repo with a real
    origin/master and origin/develop.

    Returns "<name> <sha>", or "" when the work descends from no known base. `ending` says what
    the work was branched from: "develop", "master", or "below" for an agent that reset
    underneath both.
    """
    origin = os.path.join(root, "origin.git")
    repo = os.path.join(root, "clone")
    shutil.rmtree(root, ignore_errors=True)
    os.makedirs(root)
    git_run("init", "-q", "--bare", "-b", "master", origin)
    seed = os.path.join(root, "seed")
    git_run("clone", "-q", origin, seed)
    git_run("-C", seed, "config", "user.email", "t@t.invalid")
    git_run("-C", seed, "config", "user.name", "test")

    def commit(text, message):
        with io.open(os.path.join(seed, "Belt.cs"), "a", encoding="utf-8") as fh:
            fh.write(text + "\n")
        git_run("-C", seed, "add", "-A")
        git_run("-C", seed, "commit", "-qm", message)

    # Two commits on the release line, so "below every base" is a commit that exists. A root
    # commit cannot be reset past, and an ending nobody can build proves nothing.
    commit("shipped a while ago", "an older release")
    commit("released", "the released build")
    git_run("-C", seed, "push", "-q", "origin", "HEAD:refs/heads/master")
    commit("next version", "develop is ahead of the release")
    git_run("-C", seed, "push", "-q", "origin", "HEAD:refs/heads/develop")
    if ending == "same":
        # A release merge just landed: the two branches are the same commit.
        git_run("-C", seed, "push", "-q", "-f", "origin", "HEAD:refs/heads/master")

    git_run("clone", "-q", origin, repo)
    git_run("-C", repo, "config", "user.email", "ffbox@final-factory.invalid")
    git_run("-C", repo, "config", "user.name", "ffbox")
    start = {"master": "origin/master", "below": "origin/master~1"}.get(ending, "origin/develop")
    if ending == "orphan":
        # NO SHARED HISTORY AT ALL, which is the only thing "descends from no known base" can
        # still mean now that a base which has merely moved on resolves by its fork point.
        made = git_run("-C", repo, "checkout", "-q", "--orphan", "the-agents-branch")
    else:
        made = git_run("-C", repo, "checkout", "-q", "-b", "the-agents-branch", start)
    if made.returncode != 0:
        raise AssertionError(f"could not branch from {start}: {made.stderr.strip()}")
    with io.open(os.path.join(repo, "Belt.cs"), "a", encoding="utf-8") as fh:
        fh.write("the agent's work\n")
    git_run("-C", repo, "add", "-A")
    git_run("-C", repo, "commit", "-qm", "agent work")

    # THE REAL HARVEST, not a resolver lifted out of it. The base decision moved into the
    # container with everything else, and the function this used to extract does not exist any
    # more — so the test raised rather than failed, which is the worst way for coverage of a
    # rule like this to go: a pull request into the wrong branch is a proposal to ship
    # unreleased work to players.
    out = os.path.join(root, "out")
    ok, _, _ = run_harvest(repo, out, branch="ffbox/base-test", base_refs=base_refs)
    read = lambda n: (io.open(os.path.join(out, n), encoding="utf-8").read().strip()
                      if os.path.exists(os.path.join(out, n)) else "")
    name, sha = read("publish_base.txt"), read("publish_base_sha.txt")
    return f"{name} {sha}".strip() if name else ""


def test_the_agent_picks_the_branch_its_work_is_for():
    """A fix for the released build is based on master; everything else on develop.

    The agent decides by deciding what it branches from, and the harness reads that back out of
    the commit graph rather than out of anything it said. The rule is "the base whose fork point
    with the work is the most specific": a branch off develop leaves develop at a develop-only
    commit and leaves master further back, so develop is the descendant of the two and wins. A
    branch off master leaves BOTH at master's head — develop carries it as well — and that tie
    goes to the base that has run on the least since, which is master.

    Fork points and not head-ancestry, since 2026-09-08. Asking whether `origin/<name>` is an
    ancestor of the work asks where that head is NOW, so a base that gained a commit while the
    run was going resolved to nothing at all and the host fell back to its configured default.
    """
    print("harvest: which branch the work is for")
    root = os.path.join(TMPROOT, "publishbase")

    resolved = run_base_resolution(root, base_refs="develop master", ending="develop")
    check("work branched off develop is for develop", resolved.split()[0] == "develop", resolved)

    resolved = run_base_resolution(root, base_refs="develop master", ending="master")
    check("work branched off master is for master — the released build",
          resolved.split()[0] == "master", resolved)

    resolved = run_base_resolution(root, base_refs="develop master", ending="same")
    check("with the two at the same commit, the first-listed wins",
          resolved.split()[0] == "develop", resolved)

    # THE BASE MOVED ON AFTER THE BRANCH STARTED. This is what every continuation looks like
    # once the box has merged anything: the branch left master a commit or two back, so master
    # is no longer an ancestor of it. It is still master's work and it still gets master's name.
    # It used to resolve to NOTHING — the scan asked whether `origin/master` was an ancestor of
    # HEAD, which is a question about where master's head is now — and the host was then left
    # with nothing but its configured default to go on.
    resolved = run_base_resolution(root, base_refs="develop master", ending="below")
    check("work off a base that has since moved on is still that base's work",
          resolved.split()[0] == "master", resolved)

    resolved = run_base_resolution(root, base_refs="develop master", ending="orphan")
    check("work sharing no history with any base resolves to nothing, and is refused",
          resolved == "", resolved)

    resolved = run_base_resolution(root, base_refs="", ending="develop")
    check("and with no candidates there is nothing to resolve",
          resolved == "", resolved)

    harvest = io.open(os.path.join(HERE, "harvest-workspace.sh"), encoding="utf-8").read()
    check("the resolved base is what gets bundled, not the commit the run was checked out at",
          'bundle create "$OUT/work.bundle" "${PUBLISH_BASE_SHA}..${BRANCH}"' in harvest)
    check("and the commit the run started at is the fallback when no branch claims the work",
          'PUBLISH_BASE_SHA=$BASE_SHA' in harvest)
    check("the base is found by where the work LEFT it, not by where its head is now",
          '_fork=$(g merge-base "$_sha" HEAD' in harvest
          and 'g merge-base --is-ancestor "$_sha" HEAD' not in harvest, harvest[:0])
    check("the name reaches the host in publish_base.txt",
          '"$OUT/publish_base.txt"' in harvest)


def test_the_pull_request_targets_the_branch_the_work_is_based_on():
    """master for a fix to the released build, develop for everything else.

    The host does not re-derive the choice — ffbox already made it — but it does not take the
    name on trust either: run_dir is bind-mounted into the container, so the file is checked
    against the configured set AND against the pushed commits before a pull request is aimed
    anywhere. A pull request into the wrong branch is a proposal to ship unreleased work to
    players, which is not a mistake worth being relaxed about.
    """
    print("publication: the PR targets the branch the work is based on")
    case = bug_case("prbase", venue="private")
    origin, host = git_origin(case)
    os.environ["FFBOX_STUB_BASE"] = "master"
    try:
        escalate(case, changed=["Assets/Belt.cs"], verify=PASSING_VERIFY)
    finally:
        os.environ.pop("FFBOX_STUB_BASE", None)

    run = case.rows("SELECT r.* FROM run r JOIN turn t ON t.id=r.turn_id"
                    " ORDER BY r.id DESC")[0]
    pull = GH_STATE["pulls"][-1]
    check("the run records which branch its work is for", run["pr_base"] == "master", run)
    check("and the pull request targets it, not the default",
          pull["base"] == "master", pull)
    check("the PR body says so too", "based on `master`" in (pull["body"] or ""),
          (pull["body"] or "")[-300:])
    text = json.loads(case.rows("SELECT * FROM outbound WHERE run_id=? AND action='post'",
                                (run["id"],))[0]["payload_json"])["text"]
    check("but the reply does not repeat it: the PR page it links to states its own base",
          "→" not in text and "master" not in text.split(CONFIDENT_VERDICT["summary"])[-1],
          text[:400])

    # A name the container could have written itself. Neither half is trusted: it is not in the
    # configured set, so it never reaches the API, and the default is used only because the work
    # really does descend from it.
    case2 = bug_case("prbaseforged")
    git_origin(case2)
    os.environ["FFBOX_STUB_BASE"] = "develop"
    try:
        escalate(case2, changed=["Assets/Belt.cs"], verify=PASSING_VERIFY)
        run2 = case2.rows("SELECT r.* FROM run r JOIN turn t ON t.id=r.turn_id"
                          " ORDER BY r.id DESC")[0]
        run_dir = os.path.dirname(run2["stream_path"])
        with io.open(os.path.join(run_dir, "publish_base.txt"), "w", encoding="utf-8") as fh:
            fh.write("refs/heads/../../evil\n")
        base, reason = case2.watcher.pr_base(run2["id"], run_dir, run2["branch"])
        check("a base outside the configured set is ignored", base == "develop", (base, reason))
    finally:
        os.environ.pop("FFBOX_STUB_BASE", None)

    # THE BASE MOVED WHILE THE RUN WAS GOING. This box merges its own pull requests, so this is
    # the ordinary case: master gains a commit between the container starting and the harvest
    # publishing, and the fast-forward test that used to decide this then said the work "does
    # not descend from master" and proposed nothing. Conversation 109 was refused by a merge two
    # and a half minutes ahead of it; eight runs had been refused that way when it was found.
    git_run("-C", host, "checkout", "-q", "--detach", "origin/master")
    with open(os.path.join(host, "Assets", "Other.cs"), "w", encoding="utf-8") as fh:
        fh.write("// somebody else's pull request, merged mid-run\n")
    git_run("-C", host, "add", "-A")
    git_run("-C", host, "commit", "-qm", "another PR lands on master")
    git_run("-C", host, "push", "-q", "origin", "HEAD:refs/heads/master")
    git_run("-C", host, "fetch", "-q", "origin")
    moved, reason = case.watcher.pr_base(run["id"], os.path.dirname(run["stream_path"]),
                                         run["branch"])
    check("a base that moved after the run started still gets the pull request",
          moved == "master", (moved, reason))

    # AND THE REFUSAL THAT MATTERS SURVIVES IT. The work really is on develop and the run
    # directory — which the container can write — claims master. Answering master would carry
    # every develop-only commit into a pull request against the released build.
    case3 = bug_case("prbasesmuggled")
    git_origin(case3)
    os.environ["FFBOX_STUB_BASE"] = "develop"
    try:
        escalate(case3, changed=["Assets/Belt.cs"], verify=PASSING_VERIFY)
        run3 = case3.rows("SELECT r.* FROM run r JOIN turn t ON t.id=r.turn_id"
                          " ORDER BY r.id DESC")[0]
        dir3 = os.path.dirname(run3["stream_path"])
        with io.open(os.path.join(dir3, "publish_base.txt"), "w", encoding="utf-8") as fh:
            fh.write("master\n")
        base3, _ = case3.watcher.pr_base(run3["id"], dir3, run3["branch"])
        check("develop-based work claiming master is still refused master",
              base3 == "develop", base3)
    finally:
        os.environ.pop("FFBOX_STUB_BASE", None)

    check("and the allow list is the config's, not a literal in the code",
          sorted(ffwatch.DEFAULTS["publish_bases"]) == ["develop", "master"],
          sorted(ffwatch.DEFAULTS["publish_bases"]))
    check("every base a run may choose is described, because the container renders those",
          all(v.strip() for v in ffwatch.DEFAULTS["publish_bases"].values()),
          ffwatch.DEFAULTS["publish_bases"])

    # What the container is actually told about the choice.
    job = dict(JOB_SKELETON, bases={"checked_out": "develop",
                                    "choices": ffwatch.DEFAULTS["publish_bases"]})
    pre = preamble_for(job, "basespre")
    check("the preamble names both branches and what each is for",
          "origin/develop" in pre and "origin/master" in pre
          and "released build" in pre, pre[-600:])
    check("and says the pull request follows what it branched from",
          "opens the pull request against that branch" in pre, pre[-600:])
    check("a lane with no bases to choose between is told nothing about them",
          "CHOOSE WHAT YOU BRANCH FROM" not in preamble_for(dict(JOB_SKELETON), "nobases"))



def test_the_admission_lock_does_not_ride_into_the_run():
    """The lock covers admission. It must not be held for the length of the container.

    OBSERVED ON THE BUILD SERVER, 2026-09-02, as "Max is not responding to Discord". The chain
    is four links and only the first is a bug:

      * fd 9 IS the admission lock -- `exec 9>>` in ffbox's own shell -- and a background
        command inherits every open descriptor. The cold run's `docker run ... &` stays up for
        the whole turn, so `exec 9>&-` closed only ffbox's copy: flock holds until the LAST
        descriptor on that open file description goes.
      * `ffbox --stage-pool` takes the same lock with a bare `flock 9`, which waits forever.
      * ffwatch kills it at its 180-second ceiling, and keep_pool() runs on the DAEMON'S OWN
        LOOP -- so every pass with a run in flight froze for three minutes, draining no events
        and sending nothing that was already composed and queued.
      * `slot.sh` takes the same lock while holding the CI pool lock, so all six runner slots
        sat on "another slot is still minting" for the same reason.

    The bash rule is demonstrated rather than described, because the reason for `9>&-` is not
    visible at the place it is written. Then the two fixes: a bounded wait for the speculative
    caller, and the shape itself in ffbox, which is what a later edit could quietly undo.
    """
    print("admission lock: it covers admission and not the run")
    lock = os.path.join(TMPROOT, "admission.lock")
    lib = os.path.join(HERE, "lib-workloads.sh")

    def still_held(child):
        """Is the lock still held after the holder releases, with the child still running?"""
        script = (f'. "{lib}"\n'
                  'ffbox_workload_lock_acquire\n'
                  f'{child}\n'
                  '_c=$!\n'
                  'ffbox_workload_lock_release\n'
                  f'if flock -w 0.2 "$FFBOX_WL_LOCK" -c true; then echo FREE; else echo HELD; fi\n'
                  'kill "$_c" 2>/dev/null || :\n')
        done = subprocess.run(["bash", "-c", script], capture_output=True, text=True,
                              env={**os.environ, "FFBOX_WL_LOCK": lock}, timeout=60)
        return (done.stdout or "").strip().splitlines()[-1:] == ["HELD"]

    check("a background child inherits fd 9 and holds the lock after the release",
          still_held("sleep 30 &"), None)
    check("and closing it in the child is what gives the lock back",
          not still_held("sleep 30 9>&- &"), None)

    # THE BOUNDED WAIT, for the caller that is only speculating. Held by somebody else, the
    # staging path must come back and say so rather than sit there: it is called from ffwatch's
    # loop, so a wait here is a wait on every reply the daemon has already queued.
    holder = subprocess.Popen(["flock", lock, "-c", "sleep 30"])
    try:
        started = time.monotonic()
        waited = subprocess.run(
            ["bash", "-c", f'. "{lib}"; ffbox_workload_lock_acquire 1'],
            capture_output=True, text=True, env={**os.environ, "FFBOX_WL_LOCK": lock},
            timeout=60)
        took = time.monotonic() - started
        check("a bounded acquire gives up instead of waiting on a lock somebody else holds",
              waited.returncode != 0 and took < 10, (waited.returncode, took))
        # And the unbounded one still waits, because a cold run has somebody waiting on it and
        # "the box is busy" is not a reason to fail their turn.
        blocked = subprocess.Popen(["bash", "-c", f'. "{lib}"; ffbox_workload_lock_acquire'],
                                   env={**os.environ, "FFBOX_WL_LOCK": lock})
        time.sleep(0.5)
        check("an unbounded acquire is still waiting, which is what a run wants",
              blocked.poll() is None, blocked.poll())
        blocked.kill()
        blocked.wait(timeout=10)
    finally:
        holder.kill()
        holder.wait(timeout=10)

    # THE SHAPE IN ffbox ITSELF. Every `docker run` that is created under the lock has to close
    # it, and the one that matters is the cold run, because that is the one that outlives the
    # release. A later edit that drops the redirection is the outage coming back.
    with open(os.path.join(HERE, "ffbox"), encoding="utf-8") as fh:
        src = fh.read()
    check("the cold run's supervised docker run closes the lock in the child",
          '"${COLD_RUN_ARGS[@]}" 9>&- &' in src, None)
    check("and so does its detached form",
          '"${COLD_RUN_ARGS[@]}" 9>&-)' in src, None)
    check("and so does the staged one", '"$IMAGE" 9>&-)' in src, None)
    # BY THE STARTS THEMSELVES rather than by counting a literal, so a fourth `docker run` cannot
    # be added without this failing. The two cold forms carry the redirection on their own line;
    # the staged one spells its arguments out, so its close sits on the last line of the list.
    starts = [ln.strip() for ln in src.splitlines()
              if "docker run" in ln and not ln.strip().startswith("#")]
    check("nothing creates a container under the lock without closing it",
          len(starts) == 3
          and sum("9>&-" in ln for ln in starts) == 2
          and src.count('"$IMAGE" 9>&-)') == 1
          and '"$IMAGE" &' not in src, starts)
    check("and staging asks for the lock with a bound on the wait",
          'ffbox_workload_lock_acquire "${FFBOX_STAGE_LOCK_WAIT:-30}"' in src, None)


def test_the_keeper_backs_off_a_class_whose_staging_failed():
    """One staging that cannot succeed must not become a daemon that does nothing else.

    pool_stage() blocks the daemon's own loop for as long as ffbox takes, and the loop is where
    events are drained, replies are sent and turns are started. Retried every poll_secs, a
    staging that hangs until its ceiling is not a wasted call -- it is the whole daemon, spending
    180 of every 185 seconds inside the one thing that was never going to work.

    Nothing is lost by waiting: the pool is an optimisation and a turn that finds none runs cold.
    """
    print("pool: a failed staging is not retried every pass")
    case = Case("poolbackoff", base_fixture())
    w = case.watcher
    w.cfg["agent_classes"]["ffagent"].update({"idle_agents": 1, "agent_pool_max": 4})
    w.cfg["agent_classes"]["ffdev"].update({"idle_agents": 1, "agent_pool_max": 4})
    w.cfg["max_concurrent_runs"] = 4
    # THE HELD TIER ONLY. keep_pool also keeps a second, evictable tier on recently-used branches
    # (design/ffbox_warm_branches_design.txt), and this test asserts the exact list of what was
    # staged -- so the other tier is switched off rather than left to make the assertions
    # depend on what happens to be in the fixture's conversation table.
    for _cls in ffwatch.AGENT_CLASSES:
        w.cfg["agent_classes"][_cls]["warm_branches"]["count"] = 0
    w.pool_has_room = lambda for_containers=1: True
    w.pool_reap = lambda: 0
    w.pool_containers = lambda: []

    tried = []
    w.pool_stage = lambda cls=None, **kw: (tried.append(cls) or None)
    check("the first pass tries both classes", w.keep_pool() == [] and tried == ["ffagent",
                                                                                 "ffdev"], tried)
    tried.clear()
    check("and the next one leaves them alone", w.keep_pool() == [] and tried == [], tried)

    # PER CLASS, PER BRANCH AND PER CREDENTIAL, and only for as long as configured: a box whose
    # staging failed because CI was briefly full has to come back to it by itself. The branch
    # half of the key is what keeps a failed warm-branch guess from also stopping that class's
    # held pool; the credential half is what keeps one operator's failing staging from stopping
    # another operator's spare.
    w._pool_stage_after[("ffdev", w.pool_branch("ffdev"), w.pool_stage_key("ffdev"))] = 0.0
    w.pool_stage = lambda cls=None, **kw: (tried.append(cls) or f"p{len(tried)}")
    check("the class whose backoff expired is tried again, and the other is not",
          w.keep_pool() == ["p1"] and tried == ["ffdev"], tried)


def test_the_keeper_writes_down_why_a_pool_is_short():
    """Every reason the keeper declines to stage is recorded where a reader outside this process
    can find it, and the reasons it no longer has are dropped.

    THE JOURNAL WAS NOT ENOUGH, and that is the whole point of this file. The box page renders
    `below target` off `docker ps` -- it can see that a pool is short and has no way to see why,
    because the why is a decision this daemon makes in memory. On 2026-09-10 an ffagent pool sat
    empty for days behind a missing ANTHROPIC_API_KEY, and answering "why" meant an ssh session
    and `journalctl`. It is one file, rewritten in place, and nothing schedules off it.

    THE KEY DATES THE HOLD AND THE MESSAGE DOES NOT. Reasons carry counts that move between
    passes, so latching `since` on the message would make a condition that has held for hours
    read as new every few seconds -- which is exactly the number an operator uses to decide
    whether this is the thing that broke.
    """
    print("pool: why it is short")
    case = Case("poolwhy", base_fixture())
    w = case.watcher
    for cls in ffwatch.AGENT_CLASSES:
        w.cfg["agent_classes"][cls].update({"idle_agents": 1, "agent_pool_max": 4})
        # The held tier only; the evictable one stages on its own rules and would put a second
        # set of decisions through this same pass.
        w.cfg["agent_classes"][cls]["warm_branches"]["count"] = 0
    w.cfg["max_concurrent_runs"] = 4
    w.pool_has_room = lambda for_containers=1: True
    w.pool_reap = lambda: 0
    w.pool_containers = lambda: []
    w.pool_stage_key = lambda cls=None: "CLAUDE_CODE_OAUTH_TOKEN1"

    def held():
        """What the file says right now — read back off disk, not out of the daemon."""
        with open(w.pool_hold_path(), encoding="utf-8") as fh:
            return json.load(fh)

    # --- a staging that failed ---------------------------------------------------------
    w.pool_stage = lambda cls=None, **kw: None
    w._pool_stage_error["ffagent"] = "ffbox exited 78: no such credential"
    w.keep_pool()
    doc = held()
    check("the file names each class that is short",
          sorted(doc["pools"]) == ["ffagent", "ffdev"], doc)
    check("and says why, in the words of the thing that failed",
          "exited 78" in doc["pools"]["ffagent"]["reason"], doc["pools"]["ffagent"])
    check("a class whose failure said nothing still gets a sentence",
          "journalctl" in doc["pools"]["ffdev"]["reason"], doc["pools"]["ffdev"])
    check("the file dates itself, so a reader can tell a standing reason from a dead daemon",
          abs(doc["checked_at"] - int(time.time())) < 5, doc.get("checked_at"))
    check("and dates the hold, which is a different clock and the one that says how long",
          abs(doc["pools"]["ffagent"]["since"] - int(time.time())) < 5, doc["pools"]["ffagent"])

    # THE COOLDOWN IS NOT THE REASON. A second pass finds the class inside its backoff and must
    # still say what the failure was, because "waiting to try again" answers nothing.
    #
    # AGED BY HAND FIRST, because every pass in this test happens inside one second and `since`
    # is an epoch: without this, "the clock was not restarted" would pass on a clock that WAS
    # restarted, to the same value.
    w._pool_hold["ffagent"]["since"] -= 600
    w.pool_hold_flush()
    since = held()["pools"]["ffagent"]["since"]
    w.keep_pool()
    doc = held()
    check("the next pass is inside the backoff and still carries the failure",
          "exited 78" in doc["pools"]["ffagent"]["reason"], doc["pools"]["ffagent"])
    check("and says how often it will try again, as a rate rather than a countdown that would "
          "rewrite the file every pass",
          "retries every" in doc["pools"]["ffagent"]["reason"], doc["pools"]["ffagent"])
    check("without restarting the clock, because a failure and its cooldown are one condition",
          doc["pools"]["ffagent"]["since"] == since, (since, doc["pools"]["ffagent"]))

    # --- nothing to bill ---------------------------------------------------------------
    w._pool_stage_after.clear()
    w.pool_stage_key = lambda cls=None: None
    w.keep_pool()
    doc = held()
    check("a class nothing can pay for says so, and says which file to look in",
          doc["pools"]["ffagent"]["key"] == "keyless"
          and "secrets.env" in doc["pools"]["ffagent"]["reason"], doc["pools"]["ffagent"])
    check("and a different condition restarts the clock the old one was carrying",
          doc["pools"]["ffagent"]["since"] >= since + 500, (since, doc["pools"]["ffagent"]))

    # --- the ceilings and the squeeze ---------------------------------------------------
    w.pool_stage_key = lambda cls=None: "CLAUDE_CODE_OAUTH_TOKEN1"
    w.workload_room = lambda: 0
    w.keep_pool()
    doc = held()
    check("a box at its container ceiling says which ceiling, and what the number is",
          doc["pools"]["ffagent"]["key"] == "ceiling"
          and "4" in doc["pools"]["ffagent"]["reason"], doc["pools"]["ffagent"])

    w.workload_room = lambda: 4
    w.agent_room = lambda cls=None: 0
    w.keep_pool()
    check("and a class at its own ceiling says that instead",
          "its own ceiling" in held()["pools"]["ffagent"]["reason"], held()["pools"]["ffagent"])

    w.agent_room = lambda cls=None: 4
    w.pool_has_room = lambda for_containers=1: False
    w.keep_pool()
    check("a memory squeeze is named as one",
          held()["pools"]["ffagent"]["key"] == "squeeze", held()["pools"]["ffagent"])

    # --- a box-wide hold ----------------------------------------------------------------
    w.pool_has_room = lambda for_containers=1: True
    open(case.drain_switch, "w").close()
    try:
        w.keep_pool()
        doc = held()
        check("a drain is recorded against both pools, since it holds both",
              all(doc["pools"][c]["key"] == "draining" for c in ffwatch.AGENT_CLASSES), doc)
        check("and it names the flag, which is the thing to remove",
              case.drain_switch in doc["pools"]["ffagent"]["reason"], doc["pools"]["ffagent"])
    finally:
        os.unlink(case.drain_switch)

    # --- and the reasons it no longer has -----------------------------------------------
    staged = []
    w.pool_stage = lambda cls=None, **kw: (staged.append(cls) or f"p{len(staged)}")
    w._pool_stage_after.clear()
    w.keep_pool()
    check("a pass that staged one clears that class's reason", held()["pools"] == {}, held())

    w.pool_containers = lambda: [
        {"name": "c1", "id": "a1", "branch": "master", "class": c, "tier": "held"}
        for c in ffwatch.AGENT_CLASSES]
    w.keep_pool()
    check("and a pool holding what it was asked to has nothing to explain",
          held()["pools"] == {}, held())
    check("while the file keeps saying when it last looked",
          abs(held()["checked_at"] - int(time.time())) < 5, held())


def test_the_box_page_reads_the_keepers_reasons_off_the_same_path():
    """ffwatch writes the file and ffstatus.sh reads it — in two languages, with two copies of
    the path, and nothing but this to keep them pointing at the same place.

    THE PATH IS THE INTERFACE and it is spelled twice: `os.path.join(state_dir, POOL_HOLD_FILE)`
    here, and `$(dirname "$POOL_DIR")/pool-hold.json` there. Neither can import the other -- one
    is bash -- so what is checked is the only thing that matters to an operator: a reason this
    daemon wrote reaches the document the web page renders, at the paths both would use on a real
    box.
    """
    print("pool: the reason reaches the page")
    case = Case("poolwhyread", base_fixture())
    w = case.watcher
    w.pool_hold_note("ffagent", "keyless", "no credential can pay for a turn it would serve")

    # A docker that answers nothing: every container table comes back empty, which is what makes
    # this runnable off the box. The pools table is read from the config file and the hold file,
    # and neither needs a daemon.
    docker = write_stub(os.path.join(case.root, "docker_empty.sh"), "#!/bin/sh\nexit 0\n")
    config = os.path.join(case.root, "ffstatus-config.json")
    with open(config, "w", encoding="utf-8") as fh:
        json.dump({"max_concurrent_runs": 4,
                   "pools": {"ffagent": {"pool": {"idle": 1, "max": 4}}}}, fh)
    env = dict(os.environ, FFBOX_DOCKER=docker, FFBOX_CONFIG_JSON=config,
               # THE DEFAULT PATH, DELIBERATELY NOT OVERRIDDEN. ffstatus derives the hold file
               # from the pool directory, so pointing that at this case's state dir is what
               # proves the two spellings land on one file.
               FFBOX_POOL_DIR=os.path.join(case.state_dir, "pool"))
    env.pop("FFBOX_POOL_HOLD", None)
    proc = subprocess.run(["bash", os.path.join(HERE, "ffstatus.sh"), "--json"],
                          capture_output=True, text=True, env=env, timeout=60)
    check("ffstatus answers", proc.returncode == 0, proc.stderr[-400:])
    doc = json.loads(proc.stdout)
    row = next(p for p in doc["pools"] if p["class"] == "ffagent")
    check("the pool it reports is the one that is short", row["waiting"] < row["idle"], row)
    check("and it carries the reason ffwatch wrote, at the path ffwatch wrote it to",
          (row.get("hold") or {}).get("reason", "").startswith("no credential"), row)
    check("with the key and both clocks, which is what the page renders",
          (row["hold"]["key"] == "keyless" and isinstance(row["hold"]["since"], int)
           and isinstance(row["hold"]["checked_at"], int)), row["hold"])
    check("a pool with nothing recorded carries no hold at all",
          next(p for p in doc["pools"] if p["class"] == "ffdev")["hold"] is None, doc["pools"])


def test_the_finish_handler_reaches_the_agent_and_its_work():
    """The three things a run's ending has to do, and the bash rule that decides whether any of
    them happen.

    `docker stop` sends SIGTERM to PID 1 and to nothing else, and bash does not run a trap while
    it is waiting on a FOREGROUND child — it waits for the child, then runs the handler. So an
    agent invoked in the foreground is not stopped by its own ceiling, and nothing after it runs
    either: docker's SIGKILL arrives 120 seconds later and no trap survives that.

    Both halves are asserted here. The bash semantics are demonstrated rather than described,
    because the reason the code is shaped this way is not visible in the code; and the shape
    itself is checked in discord-task.sh, because that is the thing a later edit could quietly
    undo.
    """
    print("finish handler")
    script = os.path.join(TMPROOT, "trapshape.sh")

    def handler_delay(launch):
        """Seconds between the TERM and the handler running, for one launch shape."""
        with open(script, "w", encoding="utf-8") as fh:
            fh.write("#!/usr/bin/env bash\n"
                     "trap 'echo TRAP >> \"$1\"; exit 9' EXIT INT TERM\n"
                     + launch + "\n")
        marker = os.path.join(TMPROOT, "trapshape.out")
        if os.path.exists(marker):
            os.remove(marker)
        proc = subprocess.Popen(["bash", script, marker])
        time.sleep(0.3)
        started = time.monotonic()
        proc.terminate()
        proc.wait(timeout=30)
        return time.monotonic() - started

    # TWO SECONDS, NOT SIX: the property is which side of the child's lifetime the handler runs
    # on, and that is the same shape at any length. The margins below are what the numbers have to
    # clear, and 0.3s in / 2s child leaves both of them wide.
    foreground = handler_delay("sleep 2")
    backgrounded = handler_delay('sleep 2 & _p=$!; wait "$_p"')
    check("a foreground child defers the handler until it finishes",
          foreground > 1, foreground)
    check("a backgrounded child lets it run at once", backgrounded < 0.5, backgrounded)

    # What the harvest itself does, and the trap ordering around it, is
    # test_every_task_script_harvests_its_own_workspace's job. This is only about whether that
    # trap can RUN on the path that matters most: an agent stopped at its ceiling.
    for name in ("discord-task.sh", "run-as-user.sh"):
        task = open(os.path.join(HERE, name), encoding="utf-8").read()
        check(f"{name} backgrounds the agent so the handler can reach it",
              "FFBOX_AGENT_PID=$!" in task, None)
        check(f"{name} waits on that pid, not on a bare wait that another child would hold",
              'wait "$FFBOX_AGENT_PID"' in task, None)
    task = open(os.path.join(HERE, "discord-task.sh"), encoding="utf-8").read()
    handler = task.split("_ffbox_finish() {", 1)[1].split("\n}", 1)[0]
    check("and the handler kills it before the tree is bundled",
          handler.index("_ffbox_stop_agent") < handler.index("harvest-workspace.sh"), handler)
    check("and leaves a result for the caller, which a killed agent never writes",
          "lift_result" in handler, handler)


def test_a_run_that_ran_out_of_time_still_says_so():
    """Every front door gets an answer, and none of them is told that something broke.

    result.json is written when the agent returns, so a killed agent leaves none. The container
    writes a stub from its finish handler now; this covers the host side, which has to hold up
    for a run killed before it could write even that.
    """
    print("timeout replies")
    job = {"run_id": "d1t1-slow", "session": {"id": "S"}, "classification": {}, "messages": [],
           "limits": {"agent_secs": 1800, "warmup_secs": 3600}}

    public = {"venue": "public", "failed_closed": 0, "failed_closed_reason": None}
    text = ffwatch.compose_head(None, public, "timed_out", {}, {}, "agent", job)
    check("a public thread is told it ran out of time, not that something broke",
          text == ffwatch.PUBLIC_TIMED_OUT, text)
    check("and is not invited to ask the identical question again",
          "again" not in ffwatch.PUBLIC_TIMED_OUT.lower(), ffwatch.PUBLIC_TIMED_OUT)

    private = {"venue": "private", "failed_closed": 0, "failed_closed_reason": None}
    text = ffwatch.compose_head(None, private, "timed_out", {}, {}, "agent", job)
    check("a private venue is told which clock", "agent clock" in text, text)
    check("and what the ceiling was, so the number to change is in the reply",
          "30 minutes" in text, text)

    # The ceiling comes out of the run's own job.json, not the live config, so a config edited
    # since the run started cannot rewrite what that run was actually given.
    text = ffwatch.compose_head(None, private, "timed_out", {}, {}, "agent",
                                dict(job, limits={"agent_secs": 900}))
    check("out of the job the run was launched with", "15 minutes" in text, text)


def test_a_verification_that_never_ran_does_not_read_as_one_that_failed():
    """⚠️ NOT VERIFIED on a timed-out run used to say "the container produced no verification
    report", which reads as a suite that ran and went wrong. Nothing ran: the finish handler
    harvests and returns the licence, and does not verify a tree the agent was killed inside."""
    print("verification evidence")
    case = Case("verifevidence", base_fixture())
    conv_id = case.watcher.upsert_conversation("77001", kind="ask", channel_id=ASK_CHANNEL)
    cur = case.watcher.db.execute(
        "INSERT INTO turn(conversation_id, seq, lane, status, queued_at, venue)"
        " VALUES(?,1,'fix','timed_out',?,'private')", (conv_id, ffwatch.now_iso()))
    turn = case.watcher.db.one("SELECT * FROM turn WHERE id=?", (cur.lastrowid,))
    run_dir = os.path.join(case.watcher.conv_dir(conv_id), "runs", "r1")
    os.makedirs(run_dir, exist_ok=True)
    # A run that changed files and produced no report: the case that gets a synthesised row.
    with open(os.path.join(run_dir, "changed_files.txt"), "w", encoding="utf-8") as fh:
        fh.write("Assets/Belt.cs\n")
    cur = case.watcher.db.execute(
        "INSERT INTO run(turn_id, ffbox_run_id, container_name) VALUES(?,?,?)",
        (turn["id"], "r1", "ffbox-r1"))
    run_row = cur.lastrowid

    case.watcher.record_verification(run_row, turn, run_dir, "agent")
    row = case.watcher.db.one("SELECT * FROM verification WHERE run_id=?", (run_row,))
    check("the row says the run was stopped before anything could be verified",
          "stopped on the agent clock" in (row["evidence"] or ""), dict(row))
    check("and does not claim a report went missing",
          "produced no verification report" not in (row["evidence"] or ""), dict(row))



def test_the_transcript_is_shared_before_the_host_first_looks():
    """The writer opens the transcript's mode, and it has to do it fast.

    Claude Code creates the session JSONL 0600 as the container's own mapped subuid, so the host
    cannot read it until the container chmods it. share_transcript_loop does that -- but it
    starts one line before the agent is exec'd, when there is no transcript yet, so its first
    pass finds nothing. At a flat five-second cadence the file then existed unreadable for the
    rest of that sleep, and ffwatch polls every two seconds.

    The tell was in the record: EXACTLY TWO "could not index the live transcript" warnings on
    every pooled run (31, 32, 33, 37, 39, 41, 42, 43, 45, 46) -- the shape of a fixed window,
    two polls inside one sleep, not of a failure. Nothing was lost; the live view was blind for
    five seconds and the journal took two lines per run.

    So the loop polls fast until the first transcript appears and settles afterwards. Asserted on
    the source: this is shell, and the behaviour is a cadence rather than a value anything
    returns.
    """
    print("task: the transcript is shared promptly")
    task = io.open(os.path.join(HERE, "discord-task.sh"), encoding="utf-8").read()
    code = "\n".join(ln for ln in task.splitlines() if not ln.strip().startswith("#"))
    loop = code.partition("share_transcript_loop() {")[2].partition("\n}")[0]

    check("the loop has a fast phase before its steady one",
          "sleep 0.2" in loop and "sleep 5" in loop, loop)
    check("which ends as soon as a transcript exists",
          "transcript_present" in loop, loop)
    check("and the fast phase is bounded, so a run that never writes one stops spinning",
          "-lt 150" in loop, loop)
    # The steady cadence survives: it is what catches a compaction rewriting the path as a new
    # 0600 inode, which is the case the loop existed for before any of this.
    check("the steady loop still runs afterwards, for the compaction case",
          loop.rstrip().endswith("done") and loop.count("share_transcript_now") >= 2, loop)
    check("transcript_present is defined before the loop that calls it",
          code.index("transcript_present()") < code.index("share_transcript_loop()"), None)
    # And it is still only the transcripts: .claude.json, remote-settings.json and sessions/ are
    # 0600 for their own reasons and nothing on the host reads them.
    now = code.partition("share_transcript_now() {")[2].partition("\n}")[0]
    check("and still only the transcripts are opened up",
          "chmod -R" not in now and ".jsonl" in now, now)


def test_the_verification_directory_is_left_deletable():
    """ffverify creates a directory the HOST has to be able to delete afterwards.

    It runs inside the container as its own mapped subuid, and `mkdir -p` takes its mode from
    the umask: 0755, plus the setgid /ffbox/out carries, giving drwxr-sr-x <subuid>:
    ffbox-container. The group gets r-x and no write -- and unlinking a file needs write on the
    DIRECTORY holding it, not on the file. ffwatch runs as another uid in that group, so it
    cannot empty the directory; _rmtree_spool then fails on the parent with "Directory not
    empty" and the spool leaks.

    Measured on the live box on 2026-09-02, on the real leftover: out/ is mode 2775 owned by the
    host and writable by it, out/verification is 2755 owned by 1411719 and NOT writable by it.
    Three spools were stuck on exactly that, holding nothing else once their transcripts had
    been swept home.

    The host cannot repair it either -- chmod is the owner's privilege -- so the writer opens the
    mode, the same shape as share_transcript_now in discord-task.sh.
    """
    print("ffverify: the verification directory stays deletable")
    src = io.open(os.path.join(HERE, "ffverify.sh"), encoding="utf-8").read()
    code = "\n".join(ln for ln in src.splitlines() if not ln.strip().startswith("#"))

    mk = code.index('mkdir -p "$OUT"')
    tail = code[mk:mk + 400]
    check("the directory is made group-writable right where it is created",
          'chmod g+w "$OUT"' in tail, tail[:200])
    # A caller pointing --out somewhere it does not own must not fail an otherwise fine
    # verification run over a chmod.
    line = [ln for ln in code.splitlines() if 'chmod g+w "$OUT"' in ln]
    check("and a chmod it cannot do does not fail the run",
          line and ("|| :" in line[0] or "|| true" in line[0]), line)
    check("it happens before anything is written into it",
          code.index('chmod g+w "$OUT"') < code.index('RESULTS="$OUT/'), None)


def test_a_finished_runs_spool_is_swept_and_then_deleted():
    """The case that fell between the reaper and recovery, and leaked three directories.

    pool_reap will not delete a spool holding a transcript -- it is the only copy of that
    conversation's memory. It used to defer to recover(), which sweeps only the spools of runs
    it is recovering (terminal_state IS NULL). A run that FINISHED, whose container is gone, and
    whose transcript did not make it home, was owned by neither: not deleted, never swept.

    Live evidence, 2026-09-02: three leaked spools, one 3.0M and twenty-one hours old, all
    belonging to 'done' runs, one of them logged 33,644 times before the once-per-process guard
    made the leak quiet instead of stopping it.
    """
    print("pool: a finished run's spool is swept, then reaped")
    case = Case("reapsweep", base_fixture())
    w = case.watcher
    w.pool_containers = lambda: []

    # A finished pooled run whose transcript never made it out of the spool.
    w.submit("a question", kind="web")
    turn_id = w.db.scalar("SELECT id FROM turn ORDER BY id DESC LIMIT 1", (), 0)
    conv_id = w.db.scalar("SELECT conversation_id FROM turn WHERE id=?", (turn_id,), 0)
    w.db.execute("INSERT INTO run(turn_id, ffbox_run_id, container_name, session_id,"
                 " terminal_state, pool_id) VALUES(?,?,?,?,?,?)",
                 (turn_id, "d1t1-left", "ffbox-d1t1-left", "sess-1", "done", "s1"))
    tdir = os.path.join(w.pool_dir("s1"), "claude", "projects", ffwatch.CONTAINER_PROJECT_SLUG)
    os.makedirs(tdir, exist_ok=True)
    with open(os.path.join(tdir, "sess-1.jsonl"), "w", encoding="utf-8") as fh:
        fh.write('{"type":"user"}\n')

    check("the reaper leaves nothing behind", w.pool_reap() == 1, None)
    check("the spool is gone", not os.path.isdir(w.pool_dir("s1")), None)
    home = os.path.join(w.conv_dir(conv_id), "claude", "projects",
                        ffwatch.CONTAINER_PROJECT_SLUG, "sess-1.jsonl")
    check("and the transcript went home rather than with it", os.path.exists(home), home)

    # A run still in flight is NOT ours: recover() owns it, and it does more than move a file --
    # it requeues the turn. Sweeping from here would take the transcript out from under it.
    w.db.execute("INSERT INTO run(turn_id, ffbox_run_id, container_name, session_id,"
                 " terminal_state, pool_id) VALUES(?,?,?,?,?,?)",
                 (turn_id, "d1t2-live", "ffbox-d1t2-live", "sess-2", None, "s2"))
    tdir2 = os.path.join(w.pool_dir("s2"), "claude", "projects", ffwatch.CONTAINER_PROJECT_SLUG)
    os.makedirs(tdir2, exist_ok=True)
    open(os.path.join(tdir2, "sess-2.jsonl"), "w").close()
    check("a run still in flight is left for recover()",
          w.sweep_finished_spool("s2") is False, None)
    check("so its transcript stays where recovery will look for it",
          os.path.exists(os.path.join(tdir2, "sess-2.jsonl")), None)

    # A spool with no run row was never dispatched: no conversation to sweep into.
    check("a spool that was never dispatched is not ours either",
          w.sweep_finished_spool("nosuch") is False, None)


def test_the_reaper_says_a_held_spool_once():
    """A spool the reaper genuinely cannot clear is skipped on EVERY pass, and the reaper runs
    on every poll. Saying so each time buries the journal.

    Measured on the live box on 2026-09-01: one orphan spool produced 33,644 identical lines in
    twenty-one hours, one every two seconds. _unreapable next door already had this guard for
    the other thing the reaper refuses to delete; this is the same rule for the other branch.
    """
    print("pool: a held spool is reported once")
    case = Case("reaphush", base_fixture())
    w = case.watcher
    w.pool_containers = lambda: []
    ffwatch.Watcher._held_logged.discard("h1")
    # Nothing this sweep can do with it: no run row, so no conversation to sweep into. That is
    # what keeps it in the "cannot clear" branch this test is about.
    w.sweep_finished_spool = lambda pool_id: False

    tdir = os.path.join(w.pool_dir("h1"), "claude", "projects", "p")
    os.makedirs(tdir, exist_ok=True)
    open(os.path.join(tdir, "s.jsonl"), "w").close()

    lines = []
    saved = ffwatch.log
    ffwatch.log = lambda m: lines.append(m)
    try:
        for _ in range(5):
            w.pool_reap()
    finally:
        ffwatch.log = saved

    held = [ln for ln in lines if "still holds a transcript" in ln]
    check("five passes over the same held spool say it once", len(held) == 1, lines)
    check("and the line names the spool", held and "h1" in held[0], held)
    check("the transcript was not deleted to silence the warning",
          os.path.exists(os.path.join(tdir, "s.jsonl")), None)

    ffwatch.Watcher._held_logged.discard("h1")


def test_an_ffdev_turn_runs_under_ffdevs_numbers():
    """End to end: a conversation opened as ffdev reaches ffbox as ffdev, on ffdev's clocks.

    This is the join between the four halves -- the column, the config block, the ffbox argv and
    job.json -- and it is the one that catches a class resolved in launch() but not threaded into
    build_job(), which is where job["limits"] and the rebase target live.
    """
    print("ffdev: a turn runs under its own numbers")
    case = Case("ffdevrun", base_fixture(), verdict="ok")
    w = case.watcher
    # Numbers nothing else on the box uses, so a value that leaked from the flat config or from
    # ffagent's block is unmistakable rather than coincidentally equal.
    w.cfg["agent_classes"]["ffdev"].update({"agent_secs": 4242, "warmup_secs": 4343,
                                            "verify_secs": 4444, "kill_grace_secs": 44,
                                            "base_ref": "develop"})

    w.submit("implement the thing", kind="web", agent_class="ffdev")
    w.schedule()
    w.join_launches(120)

    run = case.rows("SELECT * FROM run")[0]
    run_dir = os.path.join(w.conv_dir(1), "runs", run["ffbox_run_id"])
    argv = json.load(open(os.path.join(run_dir, "ffbox-argv.json"), encoding="utf-8"))
    job = json.load(open(os.path.join(run_dir, "job.json"), encoding="utf-8"))

    check("ffbox is told which class this container is",
          argv[argv.index("--agent-class") + 1] == "ffdev", argv)
    check("and gets ffdev's agent clock, not ffagent's",
          argv[argv.index("--agent-timeout") + 1] == "4242", argv)
    check("and ffdev's warm-up clock",
          argv[argv.index("--warmup-timeout") + 1] == "4343", argv)
    check("and ffdev's kill grace",
          argv[argv.index("--kill-grace") + 1] == "44", argv)
    # AND ITS VERIFY CLOCK, which was the box's until 2026-09-03. The flat cfg["verify_secs"] is
    # ffagent's and is deliberately left at its own value here, so a launch still reading it
    # would produce that number instead of 4444 and fail this.
    check("and ffdev's verify clock, not the flat one",
          argv[argv.index("--verify-timeout") + 1] == "4444", argv)
    check("and it started on ffdev's base branch",
          argv[argv.index("--ref") + 1] == "develop", argv)
    # THE FENCE IS PART OF THE CLASS. A cold ffdev container is created on the open bridge, and
    # ffbox is told so explicitly rather than being left to its own default -- which is the
    # fenced one, deliberately, so that anything that forgets to pass this fails shut.
    check("and on ffdev's network, the unfenced one",
          argv[argv.index("--network") + 1] == "bridge", argv)

    # job.json is what a run directory is read back from months later. Its limits used to come
    # from the flat config, which would make an ffdev run RECORD ffagent's numbers while running
    # under its own -- a record that disagrees with what happened.
    check("job.json records the class that produced it",
          job["turn"]["agent_class"] == "ffdev", job["turn"])
    check("and the clocks it actually ran under",
          job["limits"] == {"agent_secs": 4242, "warmup_secs": 4343, "verify_secs": 4444,
                            "kill_grace_secs": 44}, job["limits"])
    # AND THE ARGV AND THE RECORD AGREE. These are two separate readers of ccfg and the whole
    # point of job["limits"] is that a run directory read back later says what the run was held
    # to, so one of them drifting to the flat config is exactly the bug worth catching.
    check("and job.json's verify clock is the one ffbox was given",
          str(job["limits"]["verify_secs"]) == argv[argv.index("--verify-timeout") + 1], job["limits"])

    # WHICH SKILLS THIS LANE CARRIES IS PART OF THE CLASS TOO, since 2026-09-05. An ffdev turn is
    # an operator's own Claude Code session with the operator not sitting there, so it gets
    # ff-agents -- project-memory above all -- on top of the ff-discord plugin that carries the
    # role and the voice. The mounts and job.json are two separate readers of the same list, and
    # the container is told the paths in its prompt, so all three have to agree.
    mounts = [argv[i + 1] for i, a in enumerate(argv) if a == "--mount"]
    check("an ffdev container is given both of its class's plugin trees",
          [m.split(":")[1] for m in mounts if "/ffbox/plugins/" in m]
          == ["/ffbox/plugins/ff-discord", "/ffbox/plugins/ff-agents"], mounts)
    check("and job.json names the same two, in the same order",
          job["plugin_dirs"] == ["/ffbox/plugins/ff-discord", "/ffbox/plugins/ff-agents"],
          job.get("plugin_dirs"))
    # NOT THE PROMPT, HERE. This turn came from the web box, which is a DIRECT kind: the
    # operator's typed words are the prompt with no framing, no role and deliberately no mention
    # of ff-discord at all. The plugins are still mounted and still loaded -- Claude Code
    # discovers a --plugin-dir's skills by itself -- and the Discord branch, which tells the
    # agent to open a role file BY PATH, is where the directories have to be named. That is
    # checked in the trust-tier test against a real Discord turn.
    # THE FROZEN COPIES ARE WHAT GETS MOUNTED, not the checkout, for both of them -- the updater
    # fast-forwards the checkout while containers are running and a directory mount has no inode
    # to pin.
    check("and each source is this run's own frozen copy, not the live checkout",
          all(m.split(":")[0].startswith(run_dir)
              for m in mounts if "/ffbox/plugins/" in m), mounts)

    # An ffagent conversation on the same box is unaffected by any of it.
    w.submit("an ordinary question", kind="web")
    w.schedule()
    w.join_launches(120)
    other = [r for r in case.rows("SELECT * FROM run ORDER BY id")
             if r["ffbox_run_id"] != run["ffbox_run_id"]][0]
    argv2 = json.load(open(os.path.join(w.conv_dir(2), "runs", other["ffbox_run_id"],
                                        "ffbox-argv.json"), encoding="utf-8"))
    # AND IT DOES NOT GET ff-agents. This is the half of the split that matters: the lane whose
    # prompts are built from text written by strangers carries the Discord plugin and nothing
    # else, and a change that gave both classes the same set would still pass every check above.
    mounts2 = [argv2[i + 1] for i, a in enumerate(argv2) if a == "--mount"]
    check("and carries only the Discord plugin, never the engineering skills",
          [m.split(":")[1] for m in mounts2 if "/ffbox/plugins/" in m]
          == ["/ffbox/plugins/ff-discord"], mounts2)
    check("an ffagent turn on the same box still runs in an ffagent container",
          argv2[argv2.index("--agent-class") + 1] == "ffagent", argv2)
    check("and is still on the fenced network while ffdev is not",
          argv2[argv2.index("--network") + 1] == "ffbox-net", argv2)
    # AND IT CARRIES THE OPERATOR BUDGET, which is the split doing its job rather than a leak.
    # A `web` prompt is a LOCAL conversation and turn_trust makes every one of them an
    # operator's -- somebody typed it at a page only they are signed in to -- so the clocks are
    # ffdev's 4242 even though the container is ffagent's. That is the same rule claude_route
    # has always applied to the money: a local ffagent prompt already bills the operator's
    # credential rather than the metered default, and the clock now agrees with the bill.
    #
    # THE CONTAINER IS UNMOVED BY IT, which is the whole point: fenced network above, and the
    # Discord plugin alone checked just before it.
    check("but the operator who typed it gets the operator clock, not the player one",
          argv2[argv2.index("--agent-timeout") + 1] == "4242", argv2)


def test_an_operators_request_in_a_players_thread_gets_the_clock_and_not_the_network():
    """Conversation 133, rebuilt: the case the split exists for.

    A player opened a #bug-reports thread, so the conversation is ffagent -- the opener decides,
    and demote_for_stranger only ever moves that downwards. Lothsahn then asked, in the thread,
    for a fix to be written and pushed. That request ran under ffagent's thirty-minute agent
    clock and was killed on it with the fix half written, because the clock was read off the
    conversation and the conversation belongs to whoever opened it.

    THE TWO HALVES GO SEPARATE WAYS HERE, and both directions matter:

      the BUDGET follows the asker   ffdev's clocks, because an operator asked
      the FENCE follows the thread   an ffagent container, on the fenced network, with the
                                     Discord plugin alone and no git credential

    The second half is the one with teeth. The session transcript this run resumes has the
    player's words in it -- that is why there is no promotion path in demote_for_stranger -- so a
    change that let an operator's message buy the open internet and the container git credential
    would be prompt injection with a route out. Every check below the clock ones is guarding that
    the budget did NOT drag the fence along with it.
    """
    print("the split: an operator's clock, a player's fence")
    opener, ask = sflake(-9100000, 1), sflake(-9099000, 2)
    fixture = base_fixture()
    bug_thread(fixture, "31900", "desyncs", [
        message(opener, "world desyncs after a load", channel="31900", name="The Meanie")])
    fixture["thread_lists"][BUG_FORUM] = [{"id": "31900", "name": "desyncs"}]
    # NO VERDICT SET, so the suite's default classifier engages at the gate. A case that pins
    # one gets the answer stub, which is a run verdict and not JSON the gate can read -- and
    # this test needs the gate to let the operator's follow-up through.
    case = Case("budget-split", fixture)
    w = case.watcher
    case.cfg["operators"] = {"lothsahn": {"discord": LOTHSAHN, "model": SUITE_CLAUDE_NAME}}
    # Numbers nothing else on the box uses, so a clock that came from the wrong block is
    # unmistakable rather than coincidentally equal.
    w.cfg["agent_classes"]["ffdev"].update({"agent_secs": 4242, "warmup_secs": 4343,
                                            "verify_secs": 4444, "kill_grace_secs": 44})
    w.cfg["agent_classes"]["ffagent"].update({"agent_secs": 1111, "warmup_secs": 2222,
                                              "verify_secs": 3333, "kill_grace_secs": 11})
    # THE OPENER IS ANSWERED FIRST, and that is not scene-setting. turn_trust needs EVERY
    # message in a batch to be an operator's before the turn is one, so an opener still sitting
    # unanswered would ride along in the next batch and make the operator's request a player's
    # turn -- correctly, and not the case under test. 133 ran the same way round: two turns
    # answered the player before Lothsahn asked for the fix.
    #
    # sweep() is what reads a forum thread in; once() is what runs the turn it produced through
    # to its finish, so the operator's message below opens a second turn rather than a batch.
    w.sweep()
    w.once()
    convs = case.rows("SELECT * FROM conversation")
    check("a player's thread opens as ffagent", len(convs) == 1
          and convs[0]["agent_class"] == "ffagent", convs)
    first = case.rows("SELECT * FROM run ORDER BY id")[-1]

    # THE OPERATOR ASKS, IN THE PLAYER'S THREAD. This does not move the conversation -- nothing
    # moves it upwards -- so the container below is still the fenced one.
    fixture = case.read_fixture()
    fixture["threads"]["31900"]["messages"].append(
        message(ask, "work out what is desyncing and push a fix to a branch",
                channel="31900", author=LOTHSAHN, name="Lothsahn"))
    case.write_fixture(fixture)
    case.events(thread_event("31900", ask, kind="thread_message"))
    w.once()

    turn = case.rows("SELECT * FROM turn ORDER BY id")[-1]
    check("the turn is recorded as an operator's", turn["trust_tier"] == "operator", dict(turn))
    check("while the conversation is still the player's class",
          case.rows("SELECT * FROM conversation")[0]["agent_class"] == "ffagent", convs)

    run = case.rows("SELECT * FROM run ORDER BY id")[-1]
    check("the operator's request is a run of its own", run["id"] != first["id"],
          (dict(first), dict(run)))
    run_dir = os.path.join(w.conv_dir(turn["conversation_id"]), "runs", run["ffbox_run_id"])
    argv = json.load(open(os.path.join(run_dir, "ffbox-argv.json"), encoding="utf-8"))
    job = json.load(open(os.path.join(run_dir, "job.json"), encoding="utf-8"))

    # THE BUDGET HALF. All four, because they move together and a change that threaded one
    # through and left the others reading ccfg would otherwise pass.
    check("the operator's request gets ffdev's agent clock",
          argv[argv.index("--agent-timeout") + 1] == "4242", argv)
    check("and ffdev's warm-up clock",
          argv[argv.index("--warmup-timeout") + 1] == "4343", argv)
    check("and ffdev's verify clock",
          argv[argv.index("--verify-timeout") + 1] == "4444", argv)
    check("and ffdev's kill grace",
          argv[argv.index("--kill-grace") + 1] == "44", argv)
    # job.json is what a run directory is read back from months later, and a record that
    # disagrees with the argv is worse than no record.
    check("and job.json records the clocks it actually ran under",
          job["limits"] == {"agent_secs": 4242, "warmup_secs": 4343, "verify_secs": 4444,
                            "kill_grace_secs": 44}, job["limits"])

    # THE FENCE HALF, which is the half a mistake here would be dangerous rather than annoying.
    check("but the container is still the conversation's, not the asker's",
          argv[argv.index("--agent-class") + 1] == "ffagent", argv)
    check("and it is created on the fenced network",
          argv[argv.index("--network") + 1] == "ffbox-net", argv)
    mounts = [argv[i + 1] for i, a in enumerate(argv) if a == "--mount"]
    check("and carries only the Discord plugin, never the engineering skills",
          [m.split(":")[1] for m in mounts if "/ffbox/plugins/" in m]
          == ["/ffbox/plugins/ff-discord"], mounts)
    check("and job.json still names the conversation's class",
          job["turn"]["agent_class"] == "ffagent", job["turn"])
    # THE CONTAINER GIT CREDENTIAL IS THE OTHER THING THE FENCE HOLDS, and --agent-class above
    # is the whole of what holds it: ffbox reads container_token out of the config itself, keyed
    # on the class it was told. There is no flag in the argv to look for, so this is asserted at
    # ffbox's source -- a check for an absent flag would pass whatever happened, which is the
    # kind of test that guards nothing.
    ffbox_src = open(os.path.join(HERE, "ffbox"), encoding="utf-8").read()
    check("and the container git credential is keyed on that class and nothing else",
          '_ffbox_token_env=$(_ffbox_pool_cfg "$AGENT_CLASS" container_token)' in ffbox_src,
          None)

    # AND THE PLAYER'S OWN NEXT MESSAGE IS BACK ON THE PLAYER'S CLOCK. The budget is read off
    # each turn, not latched on the conversation by the first operator to speak in it.
    back = sflake(-9098000, 3)
    fixture = case.read_fixture()
    fixture["threads"]["31900"]["messages"].append(
        message(back, "still happening on my save", channel="31900", name="The Meanie"))
    case.write_fixture(fixture)
    case.events(thread_event("31900", back, kind="thread_message"))
    w.once()
    run2 = case.rows("SELECT * FROM run ORDER BY id")[-1]
    check("a second run happened", run2["id"] != run["id"], (dict(run), dict(run2)))
    argv2 = json.load(open(os.path.join(w.conv_dir(turn["conversation_id"]), "runs",
                                        run2["ffbox_run_id"], "ffbox-argv.json"),
                           encoding="utf-8"))
    check("the player's own turn is held to the player's clock",
          argv2[argv2.index("--agent-timeout") + 1] == "1111", argv2)
    check("and is still in an ffagent container",
          argv2[argv2.index("--agent-class") + 1] == "ffagent", argv2)


def test_the_budget_class_is_read_from_the_turns_tier():
    """budget_class on its own: the two keys it reads and the direction it can move.

    The unit half of the test above. It matters separately because the function is the one
    place that decides the budget, and a box that points both Discord pools at one class must
    get one budget out of it without anything else having to know.
    """
    print("config: the budget follows the tier")
    cfg = ffwatch.load_config()
    cfg["_discord"] = {"user_pool": "ffagent", "operator_pool": "ffdev"}
    check("a player's turn is bounded by the user pool",
          ffwatch.budget_class(cfg, "player") == "ffagent", None)
    check("an operator's by the operator pool",
          ffwatch.budget_class(cfg, "operator") == "ffdev", None)
    # A ROW WITH NO TIER IS A PLAYER'S, which is what every turn written before trust_tier
    # existed actually is, and the conservative direction besides.
    check("and a turn with no tier recorded falls to the player's",
          ffwatch.budget_class(cfg, None) == "ffagent", None)
    check("as does anything that is not the operator tier",
          ffwatch.budget_class(cfg, "nonsense") == "ffagent", None)

    # A BOX THAT WANTS ONE BUDGET SAYS SO ONCE, in the same two keys that decide the opening
    # class. Nothing else has to be touched to opt out of the split.
    one = dict(cfg, _discord={"user_pool": "ffagent", "operator_pool": "ffagent"})
    check("a box with both pools pointed at one class has one budget",
          (ffwatch.budget_class(one, "player"), ffwatch.budget_class(one, "operator"))
          == ("ffagent", "ffagent"), None)


def test_every_agent_container_carries_its_class():
    """The label is what lets the two pools be counted and claimed apart, so it has to be on
    every agent container without exception -- staged and cold.

    IN THE SHARED ARGUMENT LIST rather than at the two `docker run` sites, because the value is
    the same for both. ffbox.workload is genuinely different for the two (pool / agent) and
    stays where it is; a label a caller can forget on one path is how the two pools would start
    miscounting each other.
    """
    print("ffbox: the class label")
    src = open(os.path.join(HERE, "ffbox"), encoding="utf-8").read()
    run = src.partition("RUN_ARGS=(")[2].partition(")\n")[0]
    check("the class label is in the shared argument list",
          '--label "ffbox.agent.class=$AGENT_CLASS"' in run, run[:400])
    check("so it cannot be on one container and off the other",
          src.count('ffbox.agent.class=') == 1, None)
    # The two workload values are per-site and must NOT have been folded in with it.
    check("the workload label is still per-site, because it differs",
          '$FFBOX_WORKLOAD_LABEL=pool' in src and '$FFBOX_WORKLOAD_LABEL=agent' in src, None)

    check("--agent-class is parsed", "--agent-class)" in src, None)
    check("and defaults to ffagent", "AGENT_CLASS=ffagent" in src, None)
    check("and is documented in --help", "--agent-class NAME" in src, None)

    # A name outside the set would become a label no pool filters on: the container would be
    # built, hold a workspace and a Unity seat, and never be claimed by anything.
    check("an unknown class is refused before anything is created",
          'is not one of: $AGENT_CLASSES' in src
          and src.index("AGENT_CLASSES") < src.index("RUN_ARGS=("), None)

    # The names are mirrored in three files because neither ffbox (shell) nor ffweb (which
    # shells out) can import ffwatch. They have to agree.
    web = open(os.path.join(HERE, "ffweb.py"), encoding="utf-8").read()
    check("ffbox names the same classes ffwatch does",
          'AGENT_CLASSES="%s"' % " ".join(ffwatch.AGENT_CLASSES) in src, None)
    check("and so does ffweb",
          "AGENT_CLASSES = %r" % (ffwatch.AGENT_CLASSES,) in web
          or 'AGENT_CLASSES = ("ffagent", "ffdev")' in web, None)


def test_the_outer_launch_ceiling_clears_every_phase_clock():
    """ffwatch's own `subprocess.run` timeout on ffbox must sit above what ffbox may legitimately
    take, or it stops catching a wedged ffbox and starts killing healthy runs.

    THE BUG IT GUARDS. The ceiling was `warmup + agent + 300` and left verification out entirely,
    so at the numbers shipped then ffbox could honestly run 3600 + 1800 + 1800 + 120 = 7320
    seconds against a ceiling of 5700. It never fired, because warm-up is seconds in practice
    and the gap only opens on a slow cold import followed by a long agent and a long verify --
    which is a coincidence holding it up, not a design.

    WHAT FIRING IT COSTS is why this is worth a test of its own: subprocess kills the ffbox SHELL
    and not the container, so the run keeps going unwatched, holding a slot and a Unity seat,
    while the turn is recorded here as a failure.
    """
    print("clocks: the outer ceiling clears every phase")
    for cls in ("ffagent", "ffdev"):
        ccfg = ffwatch.class_cfg(ffwatch.DEFAULTS, cls)
        # What ffbox may spend, end to end, at these numbers: the three phases are sequential and
        # each is measured from its own marker, so a run can hit all three, and after the last
        # one fires ffbox still allows itself a stop grace floored at the licence round trip.
        worst = (int(ccfg["warmup_secs"]) + int(ccfg["agent_secs"]) + int(ccfg["verify_secs"])
                 + max(int(ccfg["kill_grace_secs"]), ffwatch.LICENCE_STOP_FLOOR))
        ceiling = ffwatch.Watcher.launch_ceiling(ccfg)
        check(f"{cls}: the outer ceiling is above ffbox's own worst case",
              ceiling > worst, (cls, ceiling, worst))
        # And it is DERIVED rather than a constant that happens to be big enough today: raising a
        # phase clock has to raise it too, which is the property that stops this drifting back.
        raised = dict(ccfg, verify_secs=int(ccfg["verify_secs"]) + 3600)
        check(f"{cls}: raising a phase clock raises the ceiling with it",
              ffwatch.Watcher.launch_ceiling(raised) == ceiling + 3600,
              (cls, ffwatch.Watcher.launch_ceiling(raised), ceiling))


def test_the_two_agent_classes_are_configured_independently():
    """No inheritance between the classes, in either direction.

    They ship with the same numbers and are expected to diverge, so a config file that sets one
    must not move the other, and a file that omits ffdev entirely must give ffdev ITS OWN
    defaults rather than whatever ffagent happens to be set to. A shared derivation would have
    to be unpicked the first time somebody puts ffdev on develop.
    """
    print("config: the classes are independent")
    root = os.path.join(TMPROOT, "classcfg")
    os.makedirs(root, exist_ok=True)
    path = os.path.join(root, "config.json")

    def load(doc):
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(doc, fh)
        saved, ffwatch.FFBOX_CONFIG = ffwatch.FFBOX_CONFIG, path
        try:
            return ffwatch.load_config()
        finally:
            ffwatch.FFBOX_CONFIG = saved

    # ffagent configured hard, no ffdev section at all.
    cfg = load({"max_concurrent_runs": 6,
                "pools": {"ffagent": {"agent_secs": 999, "base_ref": "develop",
                                      "pool": {"idle": 2, "max": -1}}}})
    check("ffdev does not inherit ffagent's clocks",
          ffwatch.class_cfg(cfg, "ffdev")["agent_secs"] == 14400, None)
    check("nor its base branch",
          ffwatch.class_cfg(cfg, "ffdev")["base_ref"] == "master", None)
    check("and gets its own pool defaults, 1 idle and a ceiling of 3",
          (ffwatch.class_cfg(cfg, "ffdev")["idle_agents"],
           ffwatch.class_cfg(cfg, "ffdev")["agent_pool_max"]) == (1, 3), None)
    # THE NETWORK IS THE ONE PLACE THE TWO CLASSES SHIP DIFFERENT VALUES, so a defaults test is
    # where a well-meant "make them consistent" edit gets caught. ffagent behind the egress
    # proxy, ffdev on the open bridge, and neither derived from the other.
    check("ffagent defaults to the fenced network",
          ffwatch.class_cfg(cfg, "ffagent")["network"] == "limited", None)
    check("and ffdev defaults to the unfenced one",
          ffwatch.class_cfg(cfg, "ffdev")["network"] == "full", None)
    # THE MODE IS WHAT THE FILE SAYS AND THE DOCKER NAME IS DERIVED FROM IT, in one place. The
    # config names a policy; only this resolution knows which network implements it.
    check("and each mode resolves to the docker network that implements it",
          (ffwatch.class_cfg(cfg, "ffagent")["docker_network"],
           ffwatch.class_cfg(cfg, "ffdev")["docker_network"]) == ("ffbox-net", "bridge"), None)
    check("ffagent still reads what the file said",
          ffwatch.class_cfg(cfg, "ffagent")["agent_secs"] == 999, None)
    # -1 is "no ceiling of my own", which is the box's.
    check("and a negative max is the box's ceiling",
          ffwatch.class_cfg(cfg, "ffagent")["agent_pool_max"] == 6, None)
    # The flat keys still mean ffagent's, for every reader that predates classes.
    check("the flat keys still mean ffagent's", cfg["agent_secs"] == 999, None)

    # ffdev configured, ffagent left alone -- the other direction.
    cfg = load({"max_concurrent_runs": 6,
                "pools": {"ffdev": {"base_ref": "develop", "agent_secs": 3600,
                                    "pool": {"idle": -5, "max": "two"}}}})
    check("ffdev reads its own section",
          ffwatch.class_cfg(cfg, "ffdev")["base_ref"] == "develop", None)
    check("and ffagent is untouched by it",
          ffwatch.class_cfg(cfg, "ffagent")["base_ref"] == "master", None)
    # The coercions run per class, on that class's own defaults.
    check("a negative idle is off, not a negative number of containers",
          ffwatch.class_cfg(cfg, "ffdev")["idle_agents"] == 0, None)
    check("and a max that is not a number falls to THAT class's default",
          ffwatch.class_cfg(cfg, "ffdev")["agent_pool_max"] == 3, None)

    # A network that is set is honoured -- putting ffdev back behind the fence is a config edit
    # and not a code change -- and one that is neither mode falls back to THAT class's default.
    # A blank or a number reaching the ffbox argv would be `--network ''`, which docker refuses,
    # and the whole class would stop launching over a stray edit.
    cfg = load({"max_concurrent_runs": 6,
                "pools": {"ffdev": {"network": "limited"},
                          "ffagent": {"network": "   "}}})
    check("a class's network is read from its own section",
          ffwatch.class_cfg(cfg, "ffdev")["network"] == "limited", None)
    check("and putting ffdev behind the fence moves the docker network with it",
          ffwatch.class_cfg(cfg, "ffdev")["docker_network"] == "ffbox-net", None)
    check("and a blank one falls back to that class's default, never to empty",
          ffwatch.class_cfg(cfg, "ffagent")["network"] == "limited", None)
    cfg = load({"max_concurrent_runs": 6, "pools": {"ffdev": {"network": 7}}})
    check("a network that is not a string falls back too",
          ffwatch.class_cfg(cfg, "ffdev")["network"] == "full", None)
    # A DOCKER NETWORK NAME IS NOT A MODE. Naming one in the config file is exactly what this
    # key stopped meaning, and it falls back rather than being honoured -- which for ffagent is
    # the fence and for ffdev is the bridge, so the fall-back is the safe direction either way.
    cfg = load({"max_concurrent_runs": 6,
                "pools": {"ffdev": {"network": "ffbox-net"},
                          "ffagent": {"network": "bridge"}}})
    check("a docker network name in the config is not a mode",
          ffwatch.class_cfg(cfg, "ffdev")["network"] == "full", None)
    check("and the fenced class stays fenced when somebody writes one",
          ffwatch.class_cfg(cfg, "ffagent")["network"] == "limited", None)

    # THE POOLS ARE ONLY READ FROM "pools". A block left at the top level, which is where these
    # sat until 2026-09-02, is not a second place to configure one -- it is ignored, and the
    # class gets its own defaults.
    cfg = load({"max_concurrent_runs": 6,
                "ffagent": {"agent_secs": 777, "pool": {"idle": 2, "max": 5}}})
    check("a block at the top level is not read",
          ffwatch.class_cfg(cfg, "ffagent")["agent_secs"] == 2400, None)
    check("nor is its pool", ffwatch.class_cfg(cfg, "ffagent")["idle_agents"] == 1, None)

    # An unknown name is a bug upstream, not an operator's typo: every caller gets its name from
    # a validated argument, a validated form field or a NOT NULL column. Falling back would hide
    # it and run the turn in the wrong kind of container.
    raised = False
    try:
        ffwatch.class_cfg(cfg, "ffdevv")
    except ValueError:
        raised = True
    check("an unknown class raises rather than falling back", raised, None)
    check("and None is the default class",
          ffwatch.class_cfg(cfg) is ffwatch.class_cfg(cfg, "ffagent"), None)


def test_each_class_gets_its_own_plugins():
    """WHICH SKILLS A LANE CARRIES IS A PER-CLASS DECISION, and the two classes disagree.

    Until 2026-09-05 one box-wide `plugin` name went into every container, so there was no way to
    say "the dev lane gets the engineering skills and the lane running text written by strangers
    does not". This pins that they diverge by default and that a config file can move either one
    without moving the other -- the same property the network and the clocks have.

    THE DEFAULTS ARE THE POINT, not just the plumbing. ffagent carrying ff-agents would hand a
    forum bug report the editor operations, the determinism audit and the game-driving recipes;
    ffdev NOT carrying it is the gap this existed to close, project-memory above all.
    """
    print("config: plugins are per class")
    root = os.path.join(TMPROOT, "pluginscfg")
    os.makedirs(root, exist_ok=True)
    path = os.path.join(root, "config.json")

    def load(doc):
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(doc, fh)
        saved, ffwatch.FFBOX_CONFIG = ffwatch.FFBOX_CONFIG, path
        try:
            return ffwatch.load_config()
        finally:
            ffwatch.FFBOX_CONFIG = saved

    cfg = load({})
    check("ffagent carries the Discord plugin and nothing else",
          ffwatch.class_cfg(cfg, "ffagent")["plugins"] == ["ff-discord"], None)
    check("and ffdev carries the engineering skills as well",
          ffwatch.class_cfg(cfg, "ffdev")["plugins"] == ["ff-discord", "ff-agents"], None)
    # ORDER IS THE LOAD ORDER and ff-discord stays first: max-voice binds everything this lane
    # posts, so it is the one that must be there even if another fails to mount.
    check("with the voice plugin first, which is the one that must always load",
          ffwatch.class_cfg(cfg, "ffdev")["plugins"][0] == "ff-discord", None)

    # Set one, and the other does not move. Same no-inheritance rule as everything else in a
    # class block; a shared derivation here would quietly re-arm the lane this split disarmed.
    cfg = load({"pools": {"ffdev": {"plugins": ["ff-discord"]}}})
    check("a class reads its own list", ffwatch.class_cfg(cfg, "ffdev")["plugins"]
          == ["ff-discord"], None)
    check("and the other class is untouched by it",
          ffwatch.class_cfg(cfg, "ffagent")["plugins"] == ["ff-discord"], None)

    # THE EMPTY LIST IS AN ANSWER, not a typo: a lane may be configured to carry no plugin at
    # all. It has to be distinguishable from a missing key, which is why this is not "falsy
    # means default".
    cfg = load({"pools": {"ffagent": {"plugins": []}}})
    check("an empty list means no plugins, not the default set",
          ffwatch.class_cfg(cfg, "ffagent")["plugins"] == [], None)

    # A BARE STRING IS ONE NAME. It cannot be misread as anything else, and it is what somebody
    # writes on the first try.
    cfg = load({"pools": {"ffdev": {"plugins": "ff-agents"}}})
    check("a bare string is read as one plugin",
          ffwatch.class_cfg(cfg, "ffdev")["plugins"] == ["ff-agents"], None)

    # A VALUE THAT IS NOT A LIST OF NAMES FALLS BACK TO THIS CLASS'S DEFAULT, never to the
    # other's -- which is what keeps a mangled ffagent block from inheriting ff-agents.
    cfg = load({"pools": {"ffagent": {"plugins": 7}}})
    check("a value that is not a list falls back to that class's own default",
          ffwatch.class_cfg(cfg, "ffagent")["plugins"] == ["ff-discord"], None)

    # PATH SEPARATORS AND TRAVERSAL ARE DROPPED. This value is pasted into a host source path
    # and into a mount target inside the container, and it comes out of a file edited by hand.
    cfg = load({"pools": {"ffdev": {"plugins": ["../../etc", "ff-agents", "a/b", "", 3]}}})
    check("a name that is not one directory name is dropped, and the rest still load",
          ffwatch.class_cfg(cfg, "ffdev")["plugins"] == ["ff-agents"], None)
    # Duplicates would mount the same tree twice and pass --plugin-dir twice.
    cfg = load({"pools": {"ffdev": {"plugins": ["ff-agents", "ff-agents"]}}})
    check("and a repeated name is loaded once",
          ffwatch.class_cfg(cfg, "ffdev")["plugins"] == ["ff-agents"], None)


def test_each_pool_names_its_own_github_credentials():
    """A pool may publish with its own credential, and it says WHICH ONE BY NAME.

    `pools.<class>.github.pr_token` holds the key in ~/.config/ffbox/secrets.env whose value is
    the token. The name is what goes in config.json because the token must not: that file sits
    on disk beside the channel ids, ffweb reads it, and an operator edits it by hand.

    THE ASSERTION THAT CARRIES THE FEATURE is the one about a named key that is not installed.
    It must NOT fall back to the box-wide GH_PR_TOKEN. A fallback there would hand ffagent --
    the lane that runs text written by strangers in a forum -- whatever credential the dev lane
    publishes with, silently, at the exact moment somebody believed they had separated the two.
    Refusing costs a pull request that the reconcile sweep opens as soon as the key is installed;
    falling back costs the split itself, and nothing anywhere would say it had happened.

    `container_token` names the credential that goes INSIDE that pool's containers; what is
    asserted here is only that it survives the config round trip and does not disturb publishing.
    What it does with that name is ffbox's, and `ffbox/test_container_credential.sh` covers it.
    """
    print("config: each pool names its own GitHub credentials")
    root = os.path.join(TMPROOT, "poolcreds")
    os.makedirs(root, exist_ok=True)
    path = os.path.join(root, "config.json")

    def load(doc):
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(doc, fh)
        saved, ffwatch.FFBOX_CONFIG = ffwatch.FFBOX_CONFIG, path
        try:
            return ffwatch.load_config()
        finally:
            ffwatch.FFBOX_CONFIG = saved

    kept = {k: os.environ.get(k) for k in
            ("GH_PR_TOKEN", "GH_TOKEN", "GH_PR_TOKEN_FFAGENT", "GH_PR_TOKEN_FFDEV")}
    try:
        for name in kept:
            os.environ.pop(name, None)
        os.environ["GH_PR_TOKEN"] = "boxwide"

        # NOTHING NAMED IS THE BOX EVERY MACHINE ALREADY IS. Both pools resolve to the one
        # token, which is what ffwatch did before pools could name anything.
        cfg = load({"max_concurrent_runs": 6})
        check("a pool that names nothing has both keys present and null",
              (ffwatch.class_cfg(cfg, "ffagent")["github"]
               == {"pr_token": None, "container_token": None}), None)
        check("and both pools publish with the box-wide token",
              (ffwatch.pr_token_for(cfg, "ffagent"), ffwatch.pr_token_for(cfg, "ffdev"))
              == (("boxwide", None), ("boxwide", None)), None)

        # ONE POOL NAMED, THE OTHER NOT -- the shape an operator reaches for first, and the one
        # that proves there is no inheritance in the credential either.
        os.environ["GH_PR_TOKEN_FFDEV"] = "devtoken"
        cfg = load({"max_concurrent_runs": 6,
                    "pools": {"ffdev": {"github": {"pr_token": "GH_PR_TOKEN_FFDEV"}}}})
        check("the named pool publishes with its own token",
              ffwatch.pr_token_for(cfg, "ffdev") == ("devtoken", None), None)
        check("and the pool that named nothing still has the box-wide one",
              ffwatch.pr_token_for(cfg, "ffagent") == ("boxwide", None), None)
        check("a half-filled block still carries the key it did not mention",
              ffwatch.class_cfg(cfg, "ffdev")["github"]["container_token"] is None, None)
        check("the client picks the token up from the pool it is given",
              (ffwatch.GitHub(cfg, "ffdev").token, ffwatch.GitHub(cfg, "ffagent").token,
               ffwatch.GitHub(cfg).token) == ("devtoken", "boxwide", "boxwide"), None)

        # THE ONE THAT MATTERS. ffagent names a key nobody installed; the box-wide token is
        # sitting right there in the environment and must not be reached for.
        cfg = load({"max_concurrent_runs": 6,
                    "pools": {"ffagent": {"github": {"pr_token": "GH_PR_TOKEN_FFAGENT"}},
                              "ffdev": {"github": {"pr_token": "GH_PR_TOKEN_FFDEV"}}}})
        token, why = ffwatch.pr_token_for(cfg, "ffagent")
        check("a named key that is not installed yields NO token", token == "", token)
        check("and never the box-wide one", token != "boxwide", token)
        check("and says which key is missing, by name",
              "GH_PR_TOKEN_FFAGENT" in (why or "") and "ffagent" in (why or ""), why)
        check("while the pool whose key IS installed is unaffected",
              ffwatch.pr_token_for(cfg, "ffdev") == ("devtoken", None), None)
        # Installing the key is enough; nothing caches the lookup, so the next sweep uses it.
        os.environ["GH_PR_TOKEN_FFAGENT"] = "agenttoken"
        check("installing the key is all it takes",
              ffwatch.pr_token_for(cfg, "ffagent") == ("agenttoken", None), None)

        # A NAME IS A NAME. Anything that is not a non-empty string is null rather than
        # something a lookup could be attempted with.
        cfg = load({"max_concurrent_runs": 6,
                    "pools": {"ffagent": {"github": {"pr_token": "   ",
                                                     "container_token": 7}},
                              "ffdev": {"github": "GH_PR_TOKEN_FFDEV"}}})
        check("blank and non-string names read as null",
              (ffwatch.class_cfg(cfg, "ffagent")["github"]
               == {"pr_token": None, "container_token": None}), None)
        check("and so does a github block that is not an object at all",
              (ffwatch.class_cfg(cfg, "ffdev")["github"]
               == {"pr_token": None, "container_token": None}), None)

        # container_token round-trips, and naming one says nothing about pull requests: they are
        # two credentials doing two jobs, and a pool may hold either without the other.
        cfg = load({"max_concurrent_runs": 6,
                    "pools": {"ffagent": {"github": {"container_token": "GH_CONTAINER_FFAGENT"}}}})
        check("container_token survives the round trip",
              (ffwatch.class_cfg(cfg, "ffagent")["github"]["container_token"]
               == "GH_CONTAINER_FFAGENT"), None)
        check("and naming it alone changes nothing about publishing",
              ffwatch.pr_token_for(cfg, "ffagent") == ("boxwide", None), None)

        # `status` IS WHERE SOMEBODY LOOKS. The reply that carries a missing-key refusal goes to
        # a Discord thread; the person who can fix it is at a terminal on the box. Reads cfg and
        # the environment and nothing else, so it needs no installation to call.
        def creds(cfg):
            return ffwatch.Watcher.credential_status(types.SimpleNamespace(cfg=cfg))

        check("a box that has split nothing says nothing about credentials",
              creds(load({"max_concurrent_runs": 6})) == [], None)
        cfg = load({"max_concurrent_runs": 6,
                    "pools": {"ffagent": {"github": {"pr_token": "GH_PR_TOKEN_FFAGENT"}},
                              "ffdev": {"github": {"pr_token": "GH_PR_TOKEN_FFDEV"}}}})
        lines = creds(cfg)
        check("a named key that is installed reports itself by name",
              len(lines) == 2 and lines[0] == "pool ffagent: pull requests use GH_PR_TOKEN_FFAGENT",
              lines)
        os.environ.pop("GH_PR_TOKEN_FFDEV", None)
        lines = creds(cfg)
        check("and a named key that is missing says so where an operator will read it",
              "NOT SET" in lines[1] and "GH_PR_TOKEN_FFDEV" in lines[1], lines)
        check("without ever printing a token",
              not any("devtoken" in ln or "boxwide" in ln or "agenttoken" in ln
                      for ln in lines), lines)

        # THE CONTAINER TOKEN IS REPORTED TOO, and it is the one that matters more: it is a git
        # credential INSIDE a container, and for the class carrying one it is the whole of what
        # stands between an agent and a direct push. Nobody should have to read config.json to
        # find out which pool has one.
        cfg = load({"max_concurrent_runs": 6,
                    "pools": {"ffdev": {"github": {"pr_token": "GH_PR_TOKEN_FFDEV",
                                                   "container_token": "GH_CONTAINER_FFDEV"}}}})
        os.environ["GH_PR_TOKEN_FFDEV"] = "devtoken"
        lines = creds(cfg)
        check("both of a pool's credentials appear on its one line",
              len(lines) == 1 and lines[0] == ("pool ffdev: pull requests use GH_PR_TOKEN_FFDEV,"
                                               " containers carry GH_CONTAINER_FFDEV (NOT SET)"),
              lines)
        check("and the pool carrying neither is not mentioned at all",
              not any("ffagent" in ln for ln in lines), lines)
    finally:
        for name, value in kept.items():
            if value is None:
                os.environ.pop(name, None)
            else:
                os.environ[name] = value


def test_each_class_is_created_on_its_own_network():
    """The egress fence is per class, and it is decided where the CONTAINER IS CREATED.

    ffdev exists to do dev work, which means reading documentation, searching the web and
    fetching a package, so it is created on the open `bridge`. ffagent serves text written by
    strangers in a Discord forum and stays on `ffbox-net` behind the allowlist proxy.

    A container's network cannot be changed after `docker run`, so exactly two code paths decide
    it: pool_stage, asserted here, and launch's cold branch, asserted in
    test_an_ffdev_turn_runs_under_ffdevs_numbers. Dispatch is deliberately neither -- it renames
    a container that already exists, and a --network there would read as though it could move
    one. That is also why a staged container is only ever claimed by a turn of its own class.
    """
    print("egress: each class is created on its own network")
    case = Case("classnet", base_fixture(), verdict="ok")
    w = case.watcher

    seen = []

    class _Done:
        returncode = 0
        stdout = ""
        stderr = ""

    class _Shim:
        # The real module's exceptions, because pool_stage catches them by this name.
        SubprocessError = subprocess.SubprocessError
        TimeoutExpired = subprocess.TimeoutExpired

        @staticmethod
        def run(cmd, *a, **kw):
            seen.append(list(cmd))
            return _Done()

    real, ffwatch.subprocess = ffwatch.subprocess, _Shim
    try:
        check("staging an ffdev container returns an id", w.pool_stage("ffdev") is not None, None)
        check("and so does an ffagent one", w.pool_stage("ffagent") is not None, None)
    finally:
        ffwatch.subprocess = real

    # THE STAGINGS, and only those: pool_stage_key asks `docker ps` which spare each credential
    # already has, through the same subprocess shim, so a bare count would be counting that too.
    staged = [c for c in seen if "--stage-pool" in c]
    check("both stagings reached ffbox", len(staged) == 2, seen)
    dev, agent = staged[0], staged[1]
    check("the staged ffdev container is created on the unfenced network",
          dev[dev.index("--network") + 1] == "bridge", dev)
    check("and the staged ffagent container behind the proxy",
          agent[agent.index("--network") + 1] == "ffbox-net", agent)
    # The network and the class label have to agree, or the pool would hand a fenced container to
    # a turn that was promised the internet -- or the reverse, which is the one that matters.
    check("each one is labelled with the class whose network it got",
          dev[dev.index("--agent-class") + 1] == "ffdev"
          and agent[agent.index("--agent-class") + 1] == "ffagent", seen)

    # A config edit moves it, with no code change: this is how ffdev goes back behind the fence.
    # Through load_config rather than by poking the block, so what is asserted is the whole path
    # -- the word in the file, the mode it resolves to, and the docker network that reaches the
    # ffbox argv.
    cfg_path = os.path.join(TMPROOT, "classnet-config.json")
    with open(cfg_path, "w", encoding="utf-8") as fh:
        json.dump({"pools": {"ffdev": {"network": "limited"}}}, fh)
    saved_cfg, ffwatch.FFBOX_CONFIG = ffwatch.FFBOX_CONFIG, cfg_path
    try:
        w.cfg["agent_classes"] = ffwatch.load_config()["agent_classes"]
    finally:
        ffwatch.FFBOX_CONFIG = saved_cfg
    seen.clear()
    real, ffwatch.subprocess = ffwatch.subprocess, _Shim
    try:
        w.pool_stage("ffdev")
    finally:
        ffwatch.subprocess = real
    restaged = [c for c in seen if "--stage-pool" in c][0]
    check("and the config is what decides, not the class name",
          restaged[restaged.index("--network") + 1] == "ffbox-net", seen)
    check("the argv carries the docker network, never the word the config used",
          "limited" not in restaged, seen)


def test_each_class_counts_only_its_own_containers():
    """agent_workload_count splits the two classes and ignores CI.

    Until classes there was one count, "everything that is not ci". With two of them that number
    is wrong for BOTH -- each would see the other's containers as its own and throttle at half
    its ceiling or less.
    """
    print("config: per-class container counts")
    case = Case("classcount", base_fixture())
    w = case.watcher
    w.cfg["agent_classes"]["ffagent"]["agent_pool_max"] = 4
    w.cfg["agent_classes"]["ffdev"]["agent_pool_max"] = 3

    rows = [("agent", "ffagent"), ("pool", "ffagent"), ("agent", "ffdev"),
            ("ci", ""), ("ci", ""),
            # No class label: staged before classes existed, and ffagent's by construction.
            ("pool", "")]
    out = "".join(f"{w}\t{c}\n" for w, c in rows)

    class _Proc:
        returncode = 0
        stdout = out
    w_run = lambda *a, **k: _Proc()
    saved = ffwatch.subprocess.run
    ffwatch.subprocess.run = w_run
    try:
        check("ffagent counts its runs, its staged ones and the unlabelled one",
              w.agent_workload_count("ffagent") == 3, None)
        check("ffdev counts only its own", w.agent_workload_count("ffdev") == 1, None)
        check("neither counts CI",
              w.agent_workload_count("ffagent") + w.agent_workload_count("ffdev")
              == len(rows) - 2, None)
        check("and the room left is that class's ceiling minus its own",
              (w.agent_room("ffagent"), w.agent_room("ffdev")) == (1, 2), None)
    finally:
        ffwatch.subprocess.run = saved

    # A daemon that will not answer counts as FULL for the class that asked, on that class's own
    # ceiling rather than the flat one: the caller is about to start a container, and the honest
    # answer when we cannot count is "assume there is no room".
    def _boom(*a, **k):
        raise OSError("no daemon")
    ffwatch.subprocess.run = _boom
    try:
        check("an unreachable daemon reads as that class being full",
              (w.agent_room("ffagent"), w.agent_room("ffdev")) == (0, 0), None)
    finally:
        ffwatch.subprocess.run = saved


def test_a_quiet_sweep_does_not_move_last_activity():
    """The stamp moves when the conversation moves, and not when ffwatch merely looks at it.

    sweep() runs every 15 minutes and calls upsert_conversation for EVERY thread it lists,
    said-in or not. While that path wrote the stamp, "last activity" meant "when ffwatch last
    looked", which is always a few minutes ago — on the build server on 2026-09-02 eleven bug
    reports sat at the top of the web list carrying stamps from the sweep ten seconds earlier,
    one of them a thread whose newest actual message was from 2024. A web conversation opened
    that morning ranked below all of them, because nothing sweeps a conversation with no
    Discord thread and its stamp was the only honest one on the page.

    The backdated stamp here is the whole apparatus: same-second writes are indistinguishable
    from no write at all, and this is a test about a column NOT being written.
    """
    print("config: a quiet sweep does not move last_activity_at")
    case = Case("quietsweep", base_fixture())
    w = case.watcher
    STALE = "2024-08-01T10:53:46Z"

    conv_id = w.upsert_conversation("7300", kind="ask", channel_id=ASK_CHANNEL,
                                    root_message_id="7300", is_thread=True, title="a report")

    def backdate():
        w.db.execute("UPDATE conversation SET last_activity_at=? WHERE id=?", (STALE, conv_id))

    def conv():
        return w.db.one("SELECT * FROM conversation WHERE id=?", (conv_id,))

    backdate()
    # Exactly what the sweep does to a thread nobody has posted in: upsert, then find nothing
    # new to insert.
    w.upsert_conversation("7300", kind="ask", channel_id=ASK_CHANNEL,
                          root_message_id="7300", is_thread=True, title="a renamed report")
    check("a sweep over a thread with nothing new leaves the stamp alone",
          conv()["last_activity_at"] == STALE, conv()["last_activity_at"])
    check("while still picking up the rename, which is not activity",
          conv()["title"] == "a renamed report", conv()["title"])

    # A message actually arriving is what the column is for.
    w.insert_message(conv_id, message(sflake(60, 3), "still too slow"))
    moved = conv()["last_activity_at"]
    check("a new message moves it", moved != STALE, moved)

    # And the same doorbell twice does not, because insert_message bumps only past the rowcount
    # check that dedupes it.
    backdate()
    w.insert_message(conv_id, message(sflake(60, 3), "still too slow"))
    check("a duplicate message does not move it", conv()["last_activity_at"] == STALE,
          conv()["last_activity_at"])


def test_a_conversations_class_is_settled_when_it_opens():
    """Chosen by the opening turn, read on every turn afterwards, and never moved.

    A conversation is pinned to a base sha, resumes one session transcript and owns one branch.
    Changing its class mid-flight would change the clocks that session has been running under
    and, once the classes differ on base_ref, the tree its transcript has been citing file:line
    positions against.
    """
    print("config: a conversation remembers its class")
    case = Case("classconv", base_fixture())
    w = case.watcher

    w.submit("a dev question", kind="web", agent_class="ffdev")
    w.submit("an ordinary question", kind="web")
    dev = w.db.one("SELECT * FROM conversation WHERE title LIKE 'a dev%'")
    plain = w.db.one("SELECT * FROM conversation WHERE title LIKE 'an ordinary%'")
    check("the class is written on the conversation", dev["agent_class"] == "ffdev", None)
    check("and the default is ffagent", plain["agent_class"] == "ffagent", None)
    check("the reader agrees", w.conversation_class(dev) == "ffdev", None)

    # A follow-up takes no class at all -- there is nothing to decide -- and the second turn of
    # the conversation reads the same one the first did.
    w.finish_turn(w.db.scalar("SELECT id FROM turn WHERE conversation_id=?", (dev["id"],), 0),
                  "done")
    w.follow_up(dev["id"], "and the other belt")
    again = w.db.one("SELECT * FROM conversation WHERE id=?", (dev["id"],))
    check("a follow-up does not move it", again["agent_class"] == "ffdev", None)

    # upsert_conversation is shared with the Discord ingress, and its UPDATE branch must not
    # touch the column: every later message in a thread upserts, and a class that could be moved
    # by one is not settled.
    w.upsert_conversation(dev["thread_id"], kind="web", channel_id=None, title="x",
                          agent_class="ffagent")
    check("and neither does a later upsert claiming otherwise",
          w.db.one("SELECT * FROM conversation WHERE id=?",
                   (dev["id"],))["agent_class"] == "ffdev", None)

    # The writer refuses a name that is not a class, whatever route it came in by.
    raised = False
    try:
        w.submit("nope", kind="web", agent_class="ffdevv")
    except ValueError:
        raised = True
    check("submit refuses an unknown class", raised, None)

    # A row read before the migration ran has no column at all; that reads as ffagent, which is
    # what a database predating classes actually had.
    check("an absent column reads as ffagent",
          w.conversation_class({"nothing": 1}) == "ffagent", None)


def test_the_pool_only_stages_what_it_has_room_for():
    """The admission rule, per class, and the one that keeps a pool from crowding out the runs
    it serves.

    Two conditions for each class: fewer warm containers of THAT class than it asked for, AND
    room under both the box's ceiling and its own. The classes do not arbitrate: there is no
    round-robin and no shared per-pass budget, so a full ffagent pool does not stop ffdev being
    staged and neither waits on the other.
    """
    print("pool: admission")
    case = Case("pooladmit", base_fixture())
    w = case.watcher
    w.cfg["max_concurrent_runs"] = 4
    w.cfg["agent_classes"]["ffagent"].update({"idle_agents": 1, "agent_pool_max": 4})
    # ffdev's pool is OFF for the first half, so this reads as the one-class behaviour it
    # replaces and the per-class assertions below are not confounded by a second pool filling.
    w.cfg["agent_classes"]["ffdev"].update({"idle_agents": 0, "agent_pool_max": 3})

    staged = []
    w.pool_stage = lambda cls=None, **kw: (staged.append(cls) or f"p{len(staged)}")
    # The held tier only; the evictable one has its own tests. See the note in
    # test_a_failed_staging_is_not_retried_every_pass.
    for _cls in ffwatch.AGENT_CLASSES:
        w.cfg["agent_classes"][_cls]["warm_branches"]["count"] = 0
    w.pool_has_room = lambda for_containers=1: True
    w.pool_reap = lambda: 0

    containers = []
    w.pool_containers = lambda: list(containers)

    check("an empty pool stages one", w.keep_pool() == ["p1"], staged)
    check("and it is the class that asked for it", staged == ["ffagent"], staged)
    containers.append({"name": "c1", "id": "a1", "branch": "master", "class": "ffagent"})
    check("and stops at that class's idle", w.keep_pool() == [], staged)

    # One warm container taken by a turn: that class is short again.
    os.makedirs(os.path.dirname(w.pool_owner_path("a1")), exist_ok=True)
    open(w.pool_owner_path("a1"), "w").close()
    check("a claimed container makes its own pool short, so another is staged",
          w.keep_pool() == ["p2"], staged)
    containers.append({"name": "c2", "id": "a2", "branch": "master", "class": "ffagent"})

    # THE CLASS CEILING, not the box's: agent_pool_max 2 with two ffagent containers up.
    w.cfg["agent_classes"]["ffagent"]["agent_pool_max"] = 2
    check("but never past that class's own pool.max", w.keep_pool() == [], staged)

    # TWO CLASSES AT ONCE, and the point of the whole change: ffagent is at its ceiling and
    # ffdev is not, so ffdev is staged and ffagent is not. No round-robin decided this -- the
    # two were simply asked separately.
    w.cfg["agent_classes"]["ffdev"]["idle_agents"] = 1
    check("a class at its ceiling does not stop the other being staged",
          w.keep_pool() == ["p3"], staged)
    check("and the one that was staged is the class with room", staged[-1] == "ffdev", staged)
    containers.append({"name": "c3", "id": "b1", "branch": "master", "class": "ffdev"})

    # A CLASS COUNTS ITS OWN CONTAINERS ONLY. ffdev has one warm and wants one, so it stops --
    # and it must not be topped up on the strength of ffagent's two sitting beside it, nor
    # starved by them.
    check("each class counts only its own", w.keep_pool() == [], staged)

    # THE BOX'S CEILING is the one thing they share.
    w.cfg["agent_classes"]["ffagent"]["agent_pool_max"] = 4
    w.cfg["agent_classes"]["ffdev"]["idle_agents"] = 3
    w.workload_room = lambda: 0
    check("and the box's ceiling stops both of them", w.keep_pool() == [], staged)

    w.workload_room = lambda: 4
    w.pool_has_room = lambda for_containers=1: False
    check("and so does the memory the runs need", w.keep_pool() == [], staged)


def test_the_daemon_loop_keeps_the_pool():
    """The daemon does not call once(); it drives the same steps itself.

    So a hook added to only one of them reaches half the callers, and this one did: keep_pool
    went into once(), the daemon ran run(), and the box reported "0 staged, 1 wanted" for as
    long as it was up while staging nothing. Both are asserted here because there is no third
    place to put the call that would make the rule enforce itself.
    """
    print("pool: the daemon keeps it")
    src = open(os.path.join(HERE, "ffwatch.py"), encoding="utf-8").read()
    for name in ("def once(self)", "def run(self)"):
        body = src.partition(name)[2].partition("\n    def ")[0]
        check(f"{name.split()[1]} schedules turns", "self.schedule()" in body, None)
        check(f"{name.split()[1]} tops the pool up", "self.keep_pool()" in body, None)
        check(f"{name.split()[1]} tops it up AFTER scheduling, not before",
              body.index("self.schedule()") < body.index("self.keep_pool()"), None)


def test_two_dispatchers_cannot_take_one_container():
    """One file answers "is this one free" and "it is mine now" in a single act.

    It has to be inter-process: schedule() runs in the daemon, but `ffwatch submit --wait`
    drives a pass itself when no daemon holds the lock, so two dispatchers can be looking at the
    same container. The loser does not wait; it launches cold.
    """
    print("pool: the claim")
    case = Case("poolclaim", base_fixture())
    w = case.watcher
    os.makedirs(os.path.join(w.pool_dir("z1"), "out"), exist_ok=True)

    winners = []
    def race():
        if w.pool_take("z1"):
            winners.append(threading.current_thread().name)
    threads = [threading.Thread(target=race, name=f"d{i}") for i in range(8)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    check("exactly one of eight dispatchers takes it", len(winners) == 1, winners)
    check("and the loser gets nothing to launch into", w.pool_take("z1") is False, None)

    # The container's own retirement uses the same file from the other side: whichever gets
    # there first decides, and the design's rule is that the loser takes the other path.
    os.makedirs(os.path.join(w.pool_dir("z2"), "out"), exist_ok=True)
    check("a container that has already retired cannot be dispatched into",
          (open(w.pool_owner_path("z2"), "w").close() or w.pool_take("z2")) is False, None)


def test_a_pooled_run_never_loses_the_conversations_memory():
    """The one thing this pool can lose that a cold run cannot.

    A cold run writes the session JSONL straight into the conversation's directory, so a crash
    loses nothing. A pooled run writes it into the staged container's own spool, which is a
    directory the reaper deletes -- so the sweep runs first, from finish_run and again from
    recover(), and the reaper refuses to delete a directory that still holds one.
    """
    print("pool: the transcript comes home")
    case = Case("poolsweep", base_fixture())
    w = case.watcher
    conv_id = w.upsert_conversation("88001", kind="ask", channel_id=ASK_CHANNEL)

    src = os.path.join(w.pool_dir("s1"), "claude", "projects", ffwatch.CONTAINER_PROJECT_SLUG)
    os.makedirs(src, exist_ok=True)
    with open(os.path.join(src, "SESSION.jsonl"), "w", encoding="utf-8") as fh:
        fh.write('{"uuid":"u1","type":"assistant"}\n')

    # The reaper must not touch it while it still holds the only copy.
    w.pool_containers = lambda: []
    check("the reaper leaves a spool that still holds a transcript", w.pool_reap() == 0, None)
    check("and the transcript is still there",
          os.path.exists(os.path.join(src, "SESSION.jsonl")), src)

    check("the sweep moves it into the conversation", w.sweep_session_out("s1", conv_id) == 1,
          None)
    check("where the next turn resumes from",
          os.path.exists(w.transcript_path(conv_id, "SESSION")), None)
    check("and it is gone from the spool",
          not os.path.exists(os.path.join(src, "SESSION.jsonl")), None)
    check("so the reaper can now delete it", w.pool_reap() == 1, None)


def test_a_crashed_pooled_run_gives_its_transcript_back():
    """recover() sweeps before it decides anything, and this is the path that needs it.

    A run whose container died with the daemon has a non-terminal row, so recover() requeues its
    turn — and that requeued turn RESUMES the session whose only copy is sitting in a spool
    directory the reaper deletes. Getting the order wrong here loses a conversation's memory
    exactly once, silently, on the run that already went wrong.
    """
    print("pool: recovery sweeps first")
    case = Case("poolrecover", base_fixture())
    w = case.watcher
    conv_id = w.upsert_conversation("99001", kind="ask", channel_id=ASK_CHANNEL)
    cur = w.db.execute(
        "INSERT INTO turn(conversation_id, seq, lane, status, queued_at, venue)"
        " VALUES(?,1,'fix','running',?,'private')", (conv_id, ffwatch.now_iso()))
    turn_id = cur.lastrowid
    w.db.execute(
        "INSERT INTO run(turn_id, ffbox_run_id, container_name, session_id, pool_id)"
        " VALUES(?,?,?,?,?)", (turn_id, "d1t1-crash", "ffbox-d1t1-crash", "SESS", "k9"))

    src = os.path.join(w.pool_dir("k9"), "claude", "projects", ffwatch.CONTAINER_PROJECT_SLUG)
    os.makedirs(src, exist_ok=True)
    with open(os.path.join(src, "SESS.jsonl"), "w", encoding="utf-8") as fh:
        fh.write('{"uuid":"u1","type":"assistant"}\n')

    dropped = []
    # Two arguments since container_live took a container id as well as a name: a run is
    # identified by the id ffbox recorded, and the name is only the fallback.
    w.container_live = lambda name, cid=None: False   # the container died with the daemon
    w.pool_drop = lambda pool_id: dropped.append(pool_id)

    check("the run is recovered", len(w.recover()) == 1, None)
    check("its transcript reached the conversation before anything else happened",
          os.path.exists(w.transcript_path(conv_id, "SESS")), None)
    check("and is gone from the spool", not os.path.exists(os.path.join(src, "SESS.jsonl")),
          None)
    check("the staged container is dropped, not reused: its workspace holds a half-finished run",
          dropped == ["k9"], dropped)
    turn = w.db.one("SELECT * FROM turn WHERE id=?", (turn_id,))
    check("and the turn is queued again, ready to resume what was just swept home",
          turn["status"] == "queued", dict(turn))


def test_a_run_directory_from_a_newer_ffbox_is_refused():
    """The run directory is an interface between two builds now, so it carries a version.

    A run whose container survives an update is started by one build of ffbox and finished by
    another. Usually the finisher is NEWER, which additive changes handle. The case that needs a
    number is the other one -- a checkout rolled back with containers still running -- where the
    files may not mean what the finisher thinks. Publishing a branch derived from a misread
    bundle is what the refusal exists to prevent.
    """
    print("contract: a directory from the future")
    case = Case("contract", base_fixture())
    w = case.watcher
    d = os.path.join(case.root, "rundir")
    os.makedirs(d, exist_ok=True)

    check("a directory with no contract file is finished as it always was",
          w.run_contract_ok(d), None)
    with open(os.path.join(d, "contract"), "w", encoding="utf-8") as fh:
        fh.write("contract=%d\nmax_changed_files=2000\n" % ffwatch.FFBOX_RUN_CONTRACT)
    check("one this build wrote is fine", w.run_contract_ok(d), None)
    with open(os.path.join(d, "contract"), "w", encoding="utf-8") as fh:
        fh.write("contract=%d\n" % (ffwatch.FFBOX_RUN_CONTRACT + 1))
    check("one from a newer build is refused", not w.run_contract_ok(d), None)
    with open(os.path.join(d, "contract"), "w", encoding="utf-8") as fh:
        fh.write("contract=not-a-number\n")
    check("and an unreadable one is not treated as newer, which would strand it",
          w.run_contract_ok(d), None)

    # The number lives in two languages and there is no shared library to put it in, so the
    # thing that catches them drifting apart is a test that reads both.
    ffbox_src = open(os.path.join(HERE, "ffbox"), encoding="utf-8").read()
    m = re.search(r"^FFBOX_RUN_CONTRACT=(\d+)$", ffbox_src, re.M)
    check("ffbox declares the same contract number ffwatch does",
          m and int(m.group(1)) == ffwatch.FFBOX_RUN_CONTRACT,
          m.group(1) if m else "not found")


def test_an_update_does_not_disturb_what_it_is_carrying():
    """Rules about what an update must NOT do, checked against the source.

    A container now runs THROUGH an update, which turns three things that were merely untidy into
    ways to break a twenty-hour job:

      the docker daemon   every container on the box is in it;
      a name-prefix rule  dispatch renames a pooled container out of the staging pattern, so a
                          sweep by name was safe only because of the rename. It is exactly the
                          shape of the 2026-09-01 loss of conversation 30's turn 5;
      the egress fence    a recreate takes it down for a couple of seconds, and everything on
                          the fenced network loses egress with it.
    """
    print("update: what it must not disturb")
    upd = open(os.path.join(HERE, "update_ffbox.sh"), encoding="utf-8").read()
    egress = open(os.path.join(HERE, "egress", "ffbox-egress.sh"), encoding="utf-8").read()
    code = "\n".join(ln for ln in upd.splitlines() if not ln.strip().startswith("#"))

    check("the updater never restarts the docker daemon",
          not re.search(r"systemctl\s+(restart|stop)\s+\S*docker", code), None)
    check("nor prunes or removes images, which a running container is holding",
          "docker image prune" not in code and "docker rmi" not in code
          and "docker system prune" not in code, None)

    # The name-prefix rule. A dispatched container wears its run's name, so anything that decides
    # what to destroy by matching a STAGING name destroys live runs the moment the rename goes.
    check("it does not decide what to destroy by matching a staging name",
          "ffbox-agent-pool-" not in code and "ffbox-dev-pool-" not in code, None)
    check("what it does destroy, it asks the container about",
          "Runner\\.Worker" in code, None)

    # And it asks about the HOST rather than about containers, which is what stops a long run
    # holding an update open.
    check("it waits on the host's own tail, not on containers", "--host-only" in code, None)

    check("the egress fence defers a recreate while workloads are on it",
          "FFBOX_EGRESS_FORCE" in egress and 'filter "network=$NET"' in egress, None)


def test_a_detached_run_is_not_stopped_by_its_launcher():
    """The one line that decides whether a container survives an update.

    ffbox is a child of ffwatch and lives in its cgroup, so `systemctl stop ffbox.target`
    SIGTERMs it -- and its EXIT/INT/TERM trap then stopped the container. That is why stopping
    the pipeline used to cost every run on the box. Under --detach the trap has to walk past a
    container it deliberately left running, and ffwatch has to actually pass --detach.

    AND THE TRAP IS ONLY HALF OF IT, which cost conversation 61 on 2026-09-06. A cold run's
    container was created by an ATTACHED `docker run`, backgrounded so the clock loop could watch
    it; under --detach ffbox exited and left that client running. Orphaning a process reparents
    it, it does not move it between cgroups, so the client sat in ffwatch.service's -- and
    --sig-proxy is on by default off a TTY, so KillMode=control-group SIGTERMed the client and
    the client passed it to the container. The run died at 143, 110 seconds into a 7200-second
    ceiling, with the trap below working exactly as written. The pooled run beside it survived,
    because --stage-pool has always used `-d` and leaves no client to signal.

    Checked against the source, because it is a rule about what must NOT happen and there is no
    container in this suite to observe it not happening to.
    """
    print("detach: the launcher lets go")
    ffbox_src = open(os.path.join(HERE, "ffbox"), encoding="utf-8").read()
    watch_src = open(os.path.join(HERE, "ffwatch.py"), encoding="utf-8").read()

    check("ffwatch launches detached", '"--detach"' in watch_src, None)
    check("ffbox understands the flag", "--detach)" in ffbox_src, None)

    # The trap must return BEFORE it reaches the stop, and it must do so on the flag that says
    # the container was deliberately left up rather than on anything it could infer.
    body = ffbox_src.split("cleanup() {", 1)[1].split("\n}\n", 1)[0]
    check("its cleanup returns early when the run was detached",
          '"$DETACHED_OK" = 1' in body, body[:400])
    check("before it would stop anything",
          body.index('DETACHED_OK') < body.index("docker stop"), None)

    # THE DETACH BLOCK, FOUND BY ITS BANNER rather than by the first `$DETACH` test in the file.
    # The cold run branches on the same condition now, and splitting on the condition would
    # quietly start reading that block instead while still passing.
    detach_block = ffbox_src.split("# --- detach ---", 1)[1][:1600]
    check("and the flag is only set once the container exists",
          "DETACHED_OK=1" in detach_block, detach_block[:400])

    # And the other half: ffbox must not sit in its clock loop or wait for a container it has
    # handed over, or the launch thread outlives the container again.
    check("it exits rather than falling through to the wait", "exit 0" in detach_block, None)

    # AND IT LEAVES NOTHING BEHIND THAT STILL HOLDS THE CONTAINER. The docstring's second half:
    # only `-d` ends the client, and a client that outlives ffbox is a signal path into the
    # container that no trap in this script can close.
    cold = ffbox_src.split("COLD_RUN_ARGS=(", 1)[1].split("# --- detach ---", 1)[0]
    check("a detached cold run creates its container with -d",
          'RUN_CID=$(docker run -d "${COLD_RUN_ARGS[@]}"' in cold, cold[:800])
    check("and only the supervised branch backgrounds an attached client",
          cold.index('if [ "$DETACH" = 1 ]; then')
          < cold.index("docker run -d")
          < cold.index("\n    else\n")
          < cold.index('docker run "${COLD_RUN_ARGS[@]}" 9>&- &'), None)


def test_a_live_container_is_adopted_not_requeued():
    """A run whose container outlived the daemon that started it.

    This branch used to be a bare `continue`: the run was skipped, its row stayed non-terminal
    for ever, it went on counting against the ceiling, and nothing would ever publish it. The
    container ran to completion and the next restart marked it crashed.

    Adopting it is mostly a matter of NOT doing the crash path -- the passes that already exist
    carry it the rest of the way -- plus recording that it happened.
    """
    print("recovery: adoption")
    case = Case("adopt", base_fixture())
    w = case.watcher
    conv_id = w.upsert_conversation("99401", kind="ask", channel_id=ASK_CHANNEL)
    cur = w.db.execute(
        "INSERT INTO turn(conversation_id, seq, lane, status, queued_at, venue)"
        " VALUES(?,1,'fix','running',?,'private')", (conv_id, ffwatch.now_iso()))
    turn_id = cur.lastrowid
    cur = w.db.execute(
        "INSERT INTO run(turn_id, ffbox_run_id, container_name, container_id, session_id)"
        " VALUES(?,?,?,?,?)",
        (turn_id, "d1t1-adopt", "ffbox-agent-d1t1-adopt", "cid-adopt", "SESS"))
    run_row_id = cur.lastrowid
    w.container_live = lambda name, cid=None: True      # it is still working

    check("recovery leaves it alone", w.recover() == [], None)
    run = w.db.one("SELECT * FROM run WHERE id=?", (run_row_id,))
    turn = w.db.one("SELECT * FROM turn WHERE id=?", (turn_id,))
    check("the run row is not closed", run["terminal_state"] is None, dict(run))
    check("the turn stays running, so nothing schedules it a second time",
          turn["status"] == "running", dict(turn))
    check("and the adoption is recorded rather than left to be inferred",
          run["adopted_at"], dict(run))

    # Said once. A daemon that logged an adoption every pass would bury everything else.
    check("adopting twice is a no-op", w.adopt_run(
        w.db.one("SELECT * FROM run WHERE id=?", (run_row_id,))) is False, None)

    # The refused case: a pooled container renamed at dispatch but never given its job. Adopting
    # it means waiting for a turn that will never start.
    cur = w.db.execute(
        "INSERT INTO turn(conversation_id, seq, lane, status, queued_at, venue)"
        " VALUES(?,2,'fix','running',?,'private')", (conv_id, ffwatch.now_iso()))
    cur = w.db.execute(
        "INSERT INTO run(turn_id, ffbox_run_id, container_name, container_id, pool_id)"
        " VALUES(?,?,?,?,?)",
        (cur.lastrowid, "d1t2-nodisp", "ffbox-agent-d1t2-nodisp", "cid-nodisp", "p9"))
    os.makedirs(os.path.join(w.pool_dir("p9"), "in"), exist_ok=True)
    check("a pooled container that was claimed but never dispatched is not adopted",
          w.adopt_run(w.db.one("SELECT * FROM run WHERE id=?", (cur.lastrowid,))) is False, None)

    # ...and it IS adopted once the job actually went in.
    open(os.path.join(w.pool_dir("p9"), "in", "dispatch"), "w").close()
    check("once the job is in, the same container is adopted",
          w.adopt_run(w.db.one("SELECT * FROM run WHERE id=?", (cur.lastrowid,))) is True, None)


def test_a_config_from_a_newer_ffbox_does_not_kill_this_one():
    """2026-09-03, on the build server, in a test.

    Several checkouts on that box share one ~/.config/ffbox/config.json, and setup.sh seeds new
    keys into it on every update pass. A newer checkout wrote cluster.compact_turns while the
    services were running one commit older, and config_warnings -- which main() calls on EVERY
    invocation -- did DEFAULTS["cluster"][key] and raised KeyError.

    So `ffwatch drain` died and no drain flag was written, which left the keeper staging
    containers; `ffwatch quiet` died too, so the updater could never see the box go quiet. It
    spent its whole hour destroying every container the undrained keeper had just staged and only
    forced its way to the merge at the end -- the merge carrying the default it was missing.

    The config is shared and the code is not, so a config from the future is a normal state here.
    """
    print("config: one from a newer build")
    cfg = dict(ffwatch.DEFAULTS)
    cfg["watch"] = {}
    cfg["cluster"] = dict(ffwatch.DEFAULTS["cluster"])
    cfg["cluster"]["a_setting_from_the_future"] = 99
    try:
        warnings = ffwatch.config_warnings(cfg)
    except Exception as exc:  # noqa: BLE001 - the whole point is that it must not raise
        check("a config key this build has never heard of does not raise", False, repr(exc))
        return
    check("a config key this build has never heard of does not raise", True, None)
    check("and it is reported rather than swallowed",
          any("a_setting_from_the_future" in w for w in warnings), warnings)
    check("naming the likely cause, which is a newer ffbox having written the file",
          any("newer ffbox" in w for w in warnings), warnings)


def test_a_clock_that_has_passed_stops_the_run_from_a_pass():
    """The ceiling belongs to the run, not to whatever process happened to start it.

    ffbox watches its own container in a `while kill -0` loop, which lasts exactly as long as
    ffbox does. A run whose supervisor was killed had no deadline at all after that moment and
    went on holding a slot, a workspace and a Unity seat. The comparison runs on a pass now, off
    a file the run was created with, so any ffwatch can enforce it.
    """
    print("clocks: enforced from a pass")
    case = Case("clocks", base_fixture())
    w = case.watcher
    conv_id = w.upsert_conversation("99301", kind="ask", channel_id=ASK_CHANNEL)
    cur = w.db.execute(
        "INSERT INTO turn(conversation_id, seq, lane, status, queued_at, venue)"
        " VALUES(?,1,'fix','running',?,'private')", (conv_id, ffwatch.now_iso()))
    turn_id = cur.lastrowid
    out_dir = os.path.join(case.root, "clockrun")
    os.makedirs(out_dir, exist_ok=True)
    w.db.execute(
        "INSERT INTO run(turn_id, ffbox_run_id, container_name, container_id, out_dir)"
        " VALUES(?,?,?,?,?)",
        (turn_id, "d1t1-clock", "ffbox-agent-d1t1-clock", "cid-clock", out_dir))

    began = (ffwatch.datetime.now(ffwatch.timezone.utc)
             - ffwatch.timedelta(seconds=400))
    with open(os.path.join(out_dir, "clock"), "w", encoding="utf-8") as fh:
        fh.write(f"started_at={began.isoformat()}\n"
                 "warmup_secs=3600\nagent_secs=300\nverify_secs=1800\nkill_grace_secs=10\n")

    w.container_live = lambda name, cid=None: True
    stops = []
    w._stop_expired_run = lambda run_id, ref, grace: stops.append((run_id, ref, grace))

    check("in warm-up, with 400s gone of 3600, nothing is stopped", w.enforce_clocks() == 0,
          stops)

    # The agent takes over. Its ceiling is 300 and the marker is 400 seconds old, so it is over.
    marker = os.path.join(out_dir, ".agent-started")
    open(marker, "w").close()
    os.utime(marker, (time.time() - 400, time.time() - 400))
    w._clock_stopping.clear()
    check("once the agent phase has run past ITS ceiling, the run is stopped",
          w.enforce_clocks() == 1, stops)
    check("softly, with the licence floor rather than kill_grace_secs",
          stops and stops[-1][2] == ffwatch.LICENCE_STOP_FLOOR, stops)
    check("addressed by the container id, which a rename cannot move",
          stops and stops[-1][1] == "cid-clock", stops)
    check("and the phase that ran out is recorded where finish_run reads it",
          open(os.path.join(out_dir, "ffbox-timeout"), encoding="utf-8").read().strip()
          == "agent", None)

    # Verification is its own phase with its own ceiling, and the newest marker is the one that
    # counts: 400s into verify is well inside 1800.
    verify = os.path.join(out_dir, ".verify-started")
    open(verify, "w").close()
    os.utime(verify, (time.time() - 400, time.time() - 400))
    w._clock_stopping.clear()
    stops.clear()
    check("a run that has moved on to verification is judged against the verify ceiling",
          w.enforce_clocks() == 0, stops)

    # A run from before clocks were written down is bounded by ffbox's own loop, exactly as it
    # was, rather than by a pass that has nothing to compare against.
    os.remove(os.path.join(out_dir, "clock"))
    w._clock_stopping.clear()
    check("and a run with no clock file is left alone rather than guessed at",
          w.enforce_clocks() == 0, stops)


def test_a_run_reads_frozen_copies_not_the_checkout():
    """The updater fast-forwards this checkout while containers are running.

    Two of the three things a container reads from it are FILE mounts, which pin the inode, so
    git replacing the path leaves the container reading what it started with -- measured on the
    build server 2026-09-03. The plugin tree is a DIRECTORY mount and has no such protection: a
    merge really does change it underneath a running container.

    Rather than depend on git choosing to unlink rather than truncate, the run gets copies of its
    own. This checks that the copies are what gets mounted, and that changing the source
    afterwards does not reach them.

    THE FAKE CHECKOUT IS NOT OPTIONAL. cfg["task_script"] and cfg["plugins_dir"] point at the
    REAL files in this repository, and the second half of this test writes to the source to
    prove the copy does not follow. Pointed at the real ones it would overwrite
    ffbox/discord-task.sh, which is exactly what it did the first time it was run.
    """
    print("mounts: frozen per run")
    case = Case("frozen", base_fixture())
    w = case.watcher

    checkout = os.path.join(case.root, "checkout")
    for plugin in ("ff-discord", "ff-agents"):
        os.makedirs(os.path.join(checkout, "plugins", plugin, "skills"), exist_ok=True)
    task = os.path.join(checkout, "discord-task.sh")
    verify = os.path.join(checkout, "ffverify.sh")
    for path, text in ((task, "#!/bin/sh\n# the task as it was when this run started\n"),
                       (verify, "#!/bin/sh\n# ffverify as it was then\n"),
                       (os.path.join(checkout, "plugins", "ff-discord", "skills", "s.md"),
                        "a skill\n"),
                       (os.path.join(checkout, "plugins", "ff-agents", "skills", "s.md"),
                        "an engineering skill\n")):
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(text)
    w.cfg["task_script"] = task
    w.cfg["ffverify"] = verify
    w.cfg["plugins_dir"] = os.path.join(checkout, "plugins")

    dest = os.path.join(case.root, "run1", "mounts")
    # THE CLASS'S LIST, PASSED IN, which is the whole of what makes ffdev's plugin set different
    # from ffagent's. A name this checkout does not carry is skipped rather than raising.
    frozen = w.freeze_mounts(dest, ["ff-discord", "ff-agents", "ff-nonesuch"])

    check("the task script is copied", os.path.isfile(frozen.get("task_script", "")), frozen)
    check("ffverify is copied", os.path.isfile(frozen.get("ffverify", "")), frozen)
    check("and the copies are the run's, not the checkout's",
          frozen.get("task_script", "").startswith(dest), frozen)
    plugin_dirs = frozen.get("plugin_dirs") or {}
    check("every plugin the class named is copied too",
          all(os.path.isdir(plugin_dirs.get(n, "")) for n in ("ff-discord", "ff-agents")),
          frozen)
    check("under the run's own directory, which is what the checkout's could never be",
          all(p.startswith(dest) for p in plugin_dirs.values()), frozen)
    check("and a plugin this checkout does not carry is simply absent, not a failed run",
          "ff-nonesuch" not in plugin_dirs, plugin_dirs)

    # Now do to the source what a merge does, including to the DIRECTORY, which is the mount that
    # was never safe.
    with open(task, "w", encoding="utf-8") as fh:
        fh.write("#!/bin/sh\n# a commit landed while this run was going\n")
    with open(os.path.join(checkout, "plugins", "ff-discord", "skills", "s.md"), "w",
              encoding="utf-8") as fh:
        fh.write("a skill, rewritten by the merge\n")

    check("a change to the checkout does not reach a run that already started",
          "a commit landed" not in open(frozen["task_script"], encoding="utf-8").read(), None)
    check("nor does one to the plugin tree, which is the mount with no inode to pin",
          "rewritten" not in open(os.path.join(plugin_dirs["ff-discord"], "skills", "s.md"),
                                  encoding="utf-8").read(), None)

    # And the next run does get it, because freezing happens per launch rather than once.
    again = w.freeze_mounts(os.path.join(case.root, "run2", "mounts"), ["ff-discord"])
    check("while the next run does get it",
          "a commit landed" in open(again["task_script"], encoding="utf-8").read(), None)


def test_a_crashed_run_that_left_work_is_finished_not_requeued():
    """2026-09-01, in a test.

    A pooled run's spool was destroyed while it worked. The agent ran to completion and verified
    774/774 clean, but ffbox found no exit code, scored the run 70, and the harness posted "the
    run failed / no branch -- the run changed no files" into the thread. The answer was on disk
    the whole time and nothing looked at it.

    So a run whose container is gone is only a crash when it left NOTHING. If the directory holds
    a work bundle or a result, the finish path runs on what is there and the turn is not run a
    second time. design/ffbox_live_update_design.txt section 5.
    """
    print("recovery: a crash that left work")
    case = Case("leftwork", base_fixture())
    w = case.watcher
    conv_id = w.upsert_conversation("99201", kind="ask", channel_id=ASK_CHANNEL)
    cur = w.db.execute(
        "INSERT INTO turn(conversation_id, seq, lane, status, queued_at, started_at, venue)"
        " VALUES(?,1,'fix','running',?,?,'private')",
        (conv_id, ffwatch.now_iso(), ffwatch.now_iso()))
    turn_id = cur.lastrowid
    run_dir = os.path.join(w.conv_dir(conv_id), "runs", "d1t1-left")
    os.makedirs(run_dir, exist_ok=True)
    with open(os.path.join(run_dir, "job.json"), "w", encoding="utf-8") as fh:
        json.dump({"run_id": "d1t1-left", "session": {"id": "SESS"}, "messages": []}, fh)
    with open(os.path.join(run_dir, "result.json"), "w", encoding="utf-8") as fh:
        json.dump({"result": "the belt merger now respects item priority", "subtype": "success"},
                  fh)
    with open(os.path.join(run_dir, ".container-rc"), "w", encoding="utf-8") as fh:
        fh.write("0\n")
    cur = w.db.execute(
        "INSERT INTO run(turn_id, ffbox_run_id, container_name, session_id, out_dir)"
        " VALUES(?,?,?,?,?)",
        (turn_id, "d1t1-left", "ffbox-agent-d1t1-left", "SESS", run_dir))
    run_row_id = cur.lastrowid
    w.container_live = lambda name, cid=None: False   # the supervisor died; the run did not

    # recover() leaves it for the finish pass rather than doing it inline: that pass takes the
    # conversation lock, moves a pooled run's output and validates the harvest, and two code
    # paths doing one job is how the two drift. once() runs them in this order for that reason.
    check("recovery does not requeue it", w.recover() == [], None)
    w.finish_runs()
    w.join_finishes(timeout=60)
    run = w.db.one("SELECT * FROM run WHERE id=?", (run_row_id,))
    turn = w.db.one("SELECT * FROM turn WHERE id=?", (turn_id,))
    check("it is finished rather than marked crashed",
          run["terminal_state"] not in (None, "crashed"), dict(run))
    check("the exit code on disk is what scored it", run["exit_code"] == 0, dict(run))
    check("and the turn is NOT queued again, because it has already been answered",
          turn["status"] != "queued", dict(turn))

    # The other half of the rule: a run that left nothing really is a crash, and its turn has to
    # be run again or the asker gets silence.
    cur = w.db.execute(
        "INSERT INTO turn(conversation_id, seq, lane, status, queued_at, venue)"
        " VALUES(?,2,'fix','running',?,'private')", (conv_id, ffwatch.now_iso()))
    empty_turn = cur.lastrowid
    empty_dir = os.path.join(w.conv_dir(conv_id), "runs", "d1t2-empty")
    os.makedirs(empty_dir, exist_ok=True)
    w.db.execute(
        "INSERT INTO run(turn_id, ffbox_run_id, container_name, session_id, out_dir)"
        " VALUES(?,?,?,?,?)",
        (empty_turn, "d1t2-empty", "ffbox-agent-d1t2-empty", "SESS", empty_dir))
    w.recover()
    w.join_finishes(timeout=60)
    turn = w.db.one("SELECT * FROM turn WHERE id=?", (empty_turn,))
    check("a run that left nothing is still a crash, and its turn is requeued",
          turn["status"] == "queued", dict(turn))


def test_a_run_is_identified_by_its_container_id_not_its_name():
    """The name moves; the id does not.

    Dispatch renames a staged container to its run, so a name is only true between two renames
    and a process that was not there for one cannot trust it. This is the test that stops
    anything drifting back onto the name: the row's name is stale, the id is right, and the run
    still has to be found. design/ffbox_live_update_design.txt section 4a.
    """
    print("identity: by id, not by name")
    case = Case("byid", base_fixture())
    w = case.watcher
    conv_id = w.upsert_conversation("99101", kind="ask", channel_id=ASK_CHANNEL)
    cur = w.db.execute(
        "INSERT INTO turn(conversation_id, seq, lane, status, queued_at, venue)"
        " VALUES(?,1,'fix','running',?,'private')", (conv_id, ffwatch.now_iso()))
    cur = w.db.execute(
        "INSERT INTO run(turn_id, ffbox_run_id, container_name, container_id, session_id)"
        " VALUES(?,?,?,?,?)",
        (cur.lastrowid, "d1t1-id", "ffbox-agent-pool-stale", "abc123def456", "SESS"))

    asked = []

    def fake(name, container_id=None):
        asked.append((name, container_id))
        return container_id == "abc123def456"

    w.container_live = fake
    run = w.db.one("SELECT * FROM run WHERE id=?", (cur.lastrowid,))
    check("a run whose row still carries its staging name is found by its id",
          w.run_container_live(run), asked)
    check("and the id is what was asked about", asked[-1][1] == "abc123def456", asked)

    # The fallback: a row from before container_id existed still answers by name, because a cold
    # container is never renamed and a row with no id has no better handle to offer.
    cur = w.db.execute(
        "INSERT INTO run(turn_id, ffbox_run_id, container_name, session_id)"
        " VALUES(?,?,?,?)", (1, "d1t2-old", "ffbox-agent-d1t2-old", "SESS"))
    asked.clear()
    w.container_live = lambda name, container_id=None: (asked.append((name, container_id))
                                                        or container_id is None)
    old = w.db.one("SELECT * FROM run WHERE id=?", (cur.lastrowid,))
    check("a row with no id falls back to the name", w.run_container_live(old), asked)
    check("and asks about the name, with no id", asked[-1] == ("ffbox-agent-d1t2-old", None),
          asked)


def test_a_launch_never_destroys_a_warm_container():
    """A turn that cannot get a place QUEUES. It does not take somebody else's warm container.

    Until 2026-09-01 launch() did the opposite: when pool_has_room said memory was short, a cold
    launch destroyed one container out of pool_warm() to make room for itself. With one pool that
    was a trade inside one lane. With two classes it is one worker type taking another's warm
    container, and the turn it is taken from then pays a forty-second cold launch it did nothing
    to deserve.

    What bounds containers is max_concurrent_runs, which every class and CI count against.
    schedule() already leaves a turn queued when there is no room and retries on the next pass,
    and that is now the only answer anywhere in the daemon.

    ASSERTED ON THE SOURCE, because what this tests is the ABSENCE of an action -- there is no
    call to observe and no state to inspect afterwards.
    """
    print("pool: nothing is evicted")
    src = open(os.path.join(HERE, "ffwatch.py"), encoding="utf-8").read()
    body = src.partition("def launch(self, turn_id)")[2].partition("\n    def ")[0]

    check("launch never drops a container", "pool_drop" not in body, None)
    check("and does not ask whether it could make room by dropping one",
          "pool_has_room" not in body, None)
    check("and does not reach for the warm list at all", "pool_warm" not in body, None)

    # The claim itself is still there, and still by class: what went is only the fallback that
    # destroyed something when the claim missed.
    check("it still claims a container of its own class, and of its own credential",
          "pool_claim_for(ref, cls, claude_key)" in body, None)

    # pool_has_room survives in the one place it withholds an optimisation rather than
    # destroying one, and `for_containers=0` -- which only the eviction ever passed -- is gone.
    keeper = src.partition("def keep_pool(self)")[2].partition("\n    def ")[0]
    check("the keeper still refuses to stage into a squeeze",
          "pool_has_room()" in keeper, None)
    check("and nothing asks pool_has_room for zero containers any more",
          "for_containers=0" not in src, None)


def test_a_turn_falls_back_to_a_cold_launch():
    """The pool is an optimisation and never a dependency. Every one of these is an ordinary
    state of an ordinary box, and none of them may be an error."""
    print("pool: cold fallback")
    case = Case("poolcold", base_fixture())
    w = case.watcher
    w.pool_containers = lambda: []

    w.cfg["agent_classes"]["ffagent"]["idle_agents"] = 0
    check("with the pool off, nothing is claimed", w.pool_claim_for("master") is None, None)

    w.cfg["agent_classes"]["ffagent"]["idle_agents"] = 1
    check("with an empty pool, nothing is claimed", w.pool_claim_for("master") is None, None)

    # A warm container on the wrong branch is not a hit: the workspace is only warm for the
    # branch its cache entry came from, and a cross-branch checkout is slower than a cold run
    # that would have picked the matching entry.
    os.makedirs(os.path.join(w.pool_dir("b1"), "out"), exist_ok=True)
    open(os.path.join(w.pool_dir("b1"), "out", "staged"), "w").close()
    w.pool_containers = lambda: [{"name": "c", "id": "b1", "branch": "develop",
                                  "class": "ffagent"}]
    check("a container staged on another branch is not used",
          w.pool_claim_for("master") is None, None)
    check("and the matching branch is", w.pool_claim_for("develop") == "b1", None)


def test_one_class_never_takes_the_others_warm_container():
    """The stricter half of the match, and the reason two pools are two pools.

    An ffagent container staged on master is not an ffdev container staged on master. The two
    classes exist in order to diverge -- different clocks, and eventually a different base
    branch -- so serving an ffdev turn out of the ffagent pool would run it under numbers nobody
    chose for it. Two pools that quietly serve each other are one pool.
    """
    print("pool: a class claims only its own")
    case = Case("poolclass", base_fixture())
    w = case.watcher
    for cls in ffwatch.AGENT_CLASSES:
        w.cfg["agent_classes"][cls]["idle_agents"] = 1

    for pid in ("g1", "d1"):
        os.makedirs(os.path.join(w.pool_dir(pid), "out"), exist_ok=True)
        open(os.path.join(w.pool_dir(pid), "out", "staged"), "w").close()
    w.pool_containers = lambda: [
        {"name": "cg", "id": "g1", "branch": "master", "class": "ffagent"},
        {"name": "cd", "id": "d1", "branch": "master", "class": "ffdev"},
    ]

    check("an ffdev turn takes the ffdev container", w.pool_claim_for("master", "ffdev") == "d1",
          None)
    check("and an ffagent turn takes the ffagent one",
          w.pool_claim_for("master", "ffagent") == "g1", None)

    # Those two claims each wrote an out/owner, which is what takes a container out of the warm
    # list. Release them, or the rest of this reads an empty pool for a reason that has nothing
    # to do with classes.
    for pid in ("g1", "d1"):
        os.unlink(w.pool_owner_path(pid))

    # With only the other class's container warm, a turn falls through to a cold launch rather
    # than taking it. pool_would_serve is the same rule with no side effect, and schedule() asks
    # it before letting a turn start at all.
    w.pool_containers = lambda: [
        {"name": "cg", "id": "g1", "branch": "master", "class": "ffagent"}]
    check("an ffdev turn will not take an ffagent container",
          w.pool_claim_for("master", "ffdev") is None, None)
    check("and would_serve agrees, without claiming anything",
          w.pool_would_serve("master", "ffdev") is False
          and w.pool_would_serve("master", "ffagent") is True, None)

    # A container staged before classes existed carries no label, and pool_containers reads that
    # as ffagent -- the pool that staged it, on the numbers it was staged with.
    check("an unlabelled container reads as ffagent",
          ffwatch.DEFAULT_AGENT_CLASS == "ffagent", None)

    # And a class whose pool is switched off claims nothing, without touching the other's.
    w.cfg["agent_classes"]["ffagent"]["idle_agents"] = 0
    check("pool.idle 0 stops that class claiming",
          w.pool_claim_for("master", "ffagent") is None, None)


def test_draining_destroys_what_is_idle_and_nothing_else():
    """The updater drains and then fast-forwards the checkout, and pool-task.sh, the turn task
    and ffverify are all bind-mounted from that checkout, live. A container staged before the
    merge would dispatch into code that changed under it, whatever its own timer says. So the
    IDLE ones go.

    THE ONE SERVING A TURN DOES NOT, and this test exists because it used to. `ffbox.pool` is
    set at creation and survives the rename at dispatch, so a sweep over
    `docker ps --filter label=ffbox.pool` includes the container running a turn. On 2026-09-01
    that swept conversation 30's turn 5 along with the two idle ones: `docker rm -f
    ffbox-pool-<id>` missed the container (dispatch had renamed it to `ffbox-<run_id>`) and the
    rmtree behind it did not. `out/` is host-owned and went — result.json, stream.jsonl, the
    work bundle, and the `.container-rc` ffbox scores the run from — while `claude/` is 0700
    under the container's subuid and survived. The agent ran to completion and verified 774/774
    clean; ffbox found no exit code, scored the run 70, and the harness posted "the run failed /
    no branch — the run changed no files".

    `out/owner` is the file dispatch actually writes, and it is the only thing entitled to
    answer "is this container busy".
    """
    print("pool: draining takes the idle ones and leaves the busy one")
    case = Case("pooldrain", base_fixture())
    w = case.watcher
    containers = [{"name": "ffbox-pool-d1", "id": "d1", "branch": "master"},
                  {"name": "ffbox-d30t5-873beba0", "id": "d2", "branch": "master"},
                  {"name": "ffbox-pool-d3", "id": "d3", "branch": "master"}]
    w.pool_containers = lambda: list(containers)
    for pool_id in ("d1", "d2", "d3"):
        os.makedirs(os.path.join(w.pool_dir(pool_id), "out"), exist_ok=True)
    # d2 is dispatched: the host claimed it by creating out/owner, docker renamed it, and its
    # spool now holds the only copy of everything the run has produced.
    open(w.pool_owner_path("d2"), "w").close()
    answer = os.path.join(w.pool_dir("d2"), "out", "result.json")
    with open(answer, "w", encoding="utf-8") as fh:
        fh.write('{"result": "774/774 passed"}')

    dropped = []
    w.pool_drop = lambda pool_id, force=False: dropped.append(pool_id)
    w.drain()
    check("a drain destroys the staged containers nobody has claimed",
          dropped == ["d1", "d3"], dropped)
    check("and never the one a turn is using", "d2" not in dropped, dropped)
    check("and the flag is down so nothing stages another",
          os.path.exists(w.cfg["drain_switch"]), None)

    # The guard underneath the caller, with the real pool_drop this time: even told to drop d2
    # by something that should not have, the run's output survives.
    w.pool_drop = ffwatch.Watcher.pool_drop.__get__(w)
    check("pool_drop refuses to delete a claimed spool", w.pool_drop("d2") is False, None)
    check("so the run's output is still on disk", os.path.exists(answer), answer)
    check("an unclaimed spool goes without asking", w.pool_drop("d1") is True, None)
    check("and force is how an operator naming one by hand means it anyway",
          w.pool_drop("d2", force=True) is True and not os.path.exists(w.pool_dir("d2")), None)

    w.pool_drop = lambda pool_id, force=False: None
    check("the keeper stages nothing while draining", w.keep_pool() == [], None)

    # THE STOP HAS TO OUTLAST A LICENCE RETURN, and until 2026-09-02 it did not. A staged spare
    # has held a Unity seat since 2026-09-01, the trap that gives it back runs
    # `unity-editor -quit -returnlicense`, and `docker stop --timeout` KILLs when it runs out --
    # so a drop with kill_grace_secs, default 10, SIGKILLed the container part-way through. The
    # argv is what is asserted, rather than a running container: this is the only guard on a leak
    # that is invisible until somebody counts seats.
    os.makedirs(os.path.join(w.pool_dir("d4"), "out"), exist_ok=True)
    w.cfg["kill_grace_secs"] = 10
    seen = []
    real_run = ffwatch.subprocess.run
    ffwatch.subprocess.run = lambda argv, **kw: seen.append(argv) or real_run(
        [sys.executable, "-c", ""], capture_output=True)
    try:
        w.pool_drop = ffwatch.Watcher.pool_drop.__get__(w)
        w.pool_drop("d4")
    finally:
        ffwatch.subprocess.run = real_run
    stops = [a for a in seen if "stop" in a]
    graces = [int(a[a.index("--timeout") + 1]) for a in stops if "--timeout" in a]
    check("a drop stops a seat-holding spare with at least the licence floor",
          bool(graces) and min(graces) >= ffwatch.LICENCE_STOP_FLOOR, graces)
    check("and kill_grace_secs alone would not have been enough",
          w.cfg["kill_grace_secs"] < ffwatch.LICENCE_STOP_FLOOR, None)


def test_the_keeper_expires_a_stale_spare_and_never_a_claimed_one():
    """The idle clock moved host-side on 2026-09-02. What must not move with it is the guarantee
    that a container serving a turn is left alone, and that a keeper which loses the claim to a
    container already retiring does nothing."""
    print("pool: the keeper expires a stale spare and never a claimed one")
    case = Case("poolexpire", base_fixture())
    w = case.watcher
    if True:
        stopped = []
        real_thread = ffwatch.threading.Thread

        class Inline(real_thread):
            """Run the retirement body on this thread, so the assertions do not race it."""
            def start(self):
                self.run()

        containers = [{"id": "fresh", "name": "ffbox-agent-pool-fresh", "ref": "master",
                       "class": "ffagent"},
                      {"id": "stale", "name": "ffbox-agent-pool-stale", "ref": "master",
                       "class": "ffagent"},
                      {"id": "busy", "name": "ffbox-agent-t7-busy", "ref": "master",
                       "class": "ffagent"},
                      {"id": "filling", "name": "ffbox-agent-pool-filling", "ref": "master",
                       "class": "ffagent"}]
        for c in containers:
            os.makedirs(os.path.join(w.pool_dir(c["id"]), "out"), exist_ok=True)

        def staged(pool_id, age_secs, ttl=14400):
            when = (ffwatch.datetime.now(ffwatch.timezone.utc)
                    - ffwatch.timedelta(seconds=age_secs))
            with open(os.path.join(w.pool_dir(pool_id), "out", "staged"), "w",
                      encoding="utf-8") as fh:
                fh.write(f"commit=abc123\nstaged_at={when.isoformat()}\nttl_secs={ttl}\n")

        staged("fresh", 60)
        staged("stale", 14400 + 60)
        staged("busy", 14400 + 60)
        # `busy` was dispatched: the host claimed it, and a dispatched container keeps its pool
        # label, so anything sweeping by label rather than by out/owner would take a live turn.
        open(w.pool_owner_path("busy"), "w").close()
        # `filling` is still extracting its tar and has no deadline yet.

        w.pool_containers = lambda: containers
        ffwatch.threading.Thread = Inline
        real_run = ffwatch.subprocess.run
        ffwatch.subprocess.run = lambda argv, **kw: stopped.append(argv) or real_run(
            [sys.executable, "-c", ""], capture_output=True)
        try:
            sent = w.pool_expire()
        finally:
            ffwatch.threading.Thread = real_thread
            ffwatch.subprocess.run = real_run

        names = [a[-1] for a in stopped if "stop" in a]
        check("the keeper retires a spare that has aged out", sent == 1 and
              names == ["ffbox-agent-pool-stale"], (sent, names))
        check("and claims it first, exactly as a dispatch does",
              os.path.exists(w.pool_owner_path("stale")), None)
        check("a spare inside its idle life is left alone",
              not os.path.exists(w.pool_owner_path("fresh")), None)
        check("a dispatched container is never touched, whatever its label says",
              "ffbox-agent-t7-busy" not in names, names)
        check("and one still filling has no deadline to be past",
              not os.path.exists(w.pool_owner_path("filling")), None)
        graces = [int(a[a.index("--timeout") + 1]) for a in stopped if "--timeout" in a]
        check("the stop outlasts a licence return", graces and
              min(graces) >= ffwatch.LICENCE_STOP_FLOOR, graces)

        # A ttl_secs of 0 is "never recycle this", the coercion both pools apply to pool.idle.
        stopped.clear()
        staged("fresh", 999999, ttl=0)
        ffwatch.threading.Thread = Inline
        ffwatch.subprocess.run = lambda argv, **kw: stopped.append(argv) or real_run(
            [sys.executable, "-c", ""], capture_output=True)
        try:
            w.pool_expire()
        finally:
            ffwatch.threading.Thread = real_thread
            ffwatch.subprocess.run = real_run
        check("a ttl of 0 means no deadline rather than expired immediately", not stopped, stopped)

        # An unreadable clock is not a deadline either. For an IDLE clock the safe failure is a
        # container that lives too long; only the WORK clock falls back to something bounded.
        with open(os.path.join(w.pool_dir("fresh"), "out", "staged"), "w",
                  encoding="utf-8") as fh:
            fh.write("commit=abc123\nstaged_at=not-a-time\nttl_secs=nonsense\n")
        check("and a malformed one is not a deadline at all",
              w._clock_expired(os.path.join(w.pool_dir("fresh"), "out", "staged")) is False, None)


def test_the_project_directory_survives_a_workspace_move():
    """Claude Code keeps everything for a project — transcripts and memory/ — in one directory
    named after the container's cwd. Moving the workspace renames it, and conversation 30 showed
    what that costs within the hour: the next turn found no session at the new name and opened a
    fresh one, silently, because a missing transcript is what a first turn looks like anyway."""
    print("the project directory across a workspace move")
    case = Case("slugmove", base_fixture())
    w = case.watcher
    old, new = "-workspace", ffwatch.CONTAINER_PROJECT_SLUG

    # A plain conversation: nothing at the new name, so the whole directory is renamed.
    plain = os.path.join(w.conv_dir(7), "claude", "projects")
    os.makedirs(os.path.join(plain, old, "memory"), exist_ok=True)
    for rel in (("SESSION.jsonl",), ("memory", "a-fact.md")):
        with open(os.path.join(plain, old, *rel), "w", encoding="utf-8") as fh:
            fh.write("old\n")

    # One that already ran under the new name. The new file wins; the old one is not deleted to
    # tidy up after it.
    both = os.path.join(w.conv_dir(8), "claude", "projects")
    os.makedirs(os.path.join(both, old), exist_ok=True)
    os.makedirs(os.path.join(both, new), exist_ok=True)
    for name, body in (("SAME.jsonl", "old"), ("ONLY-OLD.jsonl", "old")):
        with open(os.path.join(both, old, name), "w", encoding="utf-8") as fh:
            fh.write(body)
    with open(os.path.join(both, new, "SAME.jsonl"), "w", encoding="utf-8") as fh:
        fh.write("new")

    # And a pool spool, which holds the same directory for a container staged before anyone knew
    # which conversation it would serve.
    spool = os.path.join(w.pool_dir("z9"), "claude", "projects")
    os.makedirs(os.path.join(spool, old), exist_ok=True)
    with open(os.path.join(spool, old, "SPOOL.jsonl"), "w", encoding="utf-8") as fh:
        fh.write("old")

    w.migrate_project_slugs()

    check("the transcript moves to the new name",
          os.path.exists(os.path.join(plain, new, "SESSION.jsonl")), None)
    check("and so does memory/, which is where the agent is told to write",
          os.path.exists(os.path.join(plain, new, "memory", "a-fact.md")), None)
    check("the old directory is gone once it is empty",
          not os.path.exists(os.path.join(plain, old)), None)
    check("a pool spool is migrated too",
          os.path.exists(os.path.join(spool, new, "SPOOL.jsonl")), None)

    check("a file only the old name had is carried over",
          os.path.exists(os.path.join(both, new, "ONLY-OLD.jsonl")), None)
    check("the newer copy wins a collision",
          io.open(os.path.join(both, new, "SAME.jsonl"), encoding="utf-8").read() == "new", None)
    check("and the loser is left on disk rather than deleted",
          os.path.exists(os.path.join(both, old, "SAME.jsonl")), None)

    # Runs on every start, so it has to be safe to run twice.
    w.migrate_project_slugs()
    check("a second pass changes nothing",
          io.open(os.path.join(both, new, "SAME.jsonl"), encoding="utf-8").read() == "new"
          and os.path.exists(os.path.join(plain, new, "SESSION.jsonl")), None)

    # transcript_path is what a resume opens; it has to name the directory the migration wrote.
    check("and a resume looks where the migration put things",
          w.transcript_path(7, "SESSION").startswith(os.path.join(plain, new)),
          w.transcript_path(7, "SESSION"))

    # THE ONE THE FIRST ATTEMPT COULD NOT DO. The container creates this directory as its own
    # mapped uid with no group write, so the daemon can neither rename inside it nor chmod it.
    # Conversation 31 on the real box was exactly this. 0555 stands in for that here: the daemon
    # is not root in the tests either, so the permission is real.
    stuck = os.path.join(w.conv_dir(9), "claude", "projects")
    os.makedirs(os.path.join(stuck, old, "memory"), exist_ok=True)
    for rel in (("STUCK.jsonl",), ("memory", "kept.md")):
        with open(os.path.join(stuck, old, *rel), "w", encoding="utf-8") as fh:
            fh.write("old\n")
    os.chmod(stuck, 0o555)
    try:
        w.migrate_project_slugs()
        check("an unwritable projects directory is rebuilt rather than abandoned",
              os.path.exists(os.path.join(stuck, new, "STUCK.jsonl")), sorted(os.listdir(stuck)))
        check("and memory/ comes with it",
              os.path.exists(os.path.join(stuck, new, "memory", "kept.md")), None)
        check("the tree that could not be written is kept, not deleted",
              any(d.startswith("projects.superseded")
                  for d in os.listdir(os.path.dirname(stuck))), None)
    finally:
        for base, dirs, _f in os.walk(os.path.dirname(stuck)):
            for d in dirs:
                try:
                    os.chmod(os.path.join(base, d), 0o755)
                except OSError:
                    pass


def test_a_shutdown_waits_for_the_host_not_only_for_the_containers():
    """A container is the FIRST HALF of a turn. The branch push is in the second half.

    finish_run records exit_code and terminal_state and only THEN records the verification,
    pushes the branch, opens the pull request and composes the reply. So `run.terminal_state IS
    NOT NULL` — the predicate the updater used to stop on — is already true while the push is
    still to come, and that work is a thread rather than a queue: `systemctl stop ffbox.target`
    in the middle of it loses the push, and the run's tree went with the container's tmpfs.

    finish_turn() is what closes last, so the turn row is what a shutdown has to wait for.
    """
    print("drain: the host is the other half of a turn")
    case = Case("drainhost")
    w = case.watcher
    conv_id = w.upsert_conversation("7200", kind="ask", channel_id=ASK_CHANNEL,
                                    title="a turn that is still publishing")
    cur = w.db.execute(
        "INSERT INTO turn(conversation_id, seq, trigger, lane, status, queued_at)"
        " VALUES(?,1,'message','dev','running',?)", (conv_id, ffwatch.now_iso()))
    turn_id = cur.lastrowid
    w.db.execute("INSERT INTO run(turn_id, ffbox_run_id, terminal_state, exit_code)"
                 " VALUES(?,'d30t5-873beba0','done',0)", (turn_id,))
    check("the container is over as far as the run row is concerned",
          w.running_counts() == 0, w.running_counts())
    counts = w.settling()
    check("but the turn is still publishing, so the machine is NOT quiet",
          counts["turns"] == 1, counts)
    check("and it says which half in words the journal can carry",
          "publishing" in w.settling_phrase(counts), w.settling_phrase(counts))
    # THE COUNT THE UPDATER ACTUALLY WAITS ON, since containers survive a restart and threads do
    # not. This turn's container is gone and its host-side half is still owed, which is exactly
    # the thing a stop can lose.
    check("and it is counted as host-side work, which is what a stop can lose",
          counts["publishing"] == 1, counts)

    # A turn whose container is STILL RUNNING is the case this distinction exists for: `turns`
    # counts it and `publishing` does not, so an update no longer waits twenty hours for it.
    cur = w.db.execute(
        "INSERT INTO turn(conversation_id, seq, trigger, lane, status, queued_at)"
        " VALUES(?,2,'message','dev','running',?)", (conv_id, ffwatch.now_iso()))
    w.db.execute("INSERT INTO run(turn_id, ffbox_run_id, container_name, container_id)"
                 " VALUES(?,'d30t6-live','ffbox-agent-d30t6-live','cid-live')", (cur.lastrowid,))
    w.container_live = lambda name, cid=None: True
    counts = w.settling()
    check("a turn whose container is still working counts as a running turn",
          counts["turns"] == 2, counts)
    check("but NOT as host-side work: a container survives a restart",
          counts["publishing"] == 1, counts)
    check("so the updater, which asks only about the host, is not held by it",
          sum(counts[k] for k in ffwatch.Watcher.HOST_TAIL) == 1, counts)
    w.container_live = lambda name, cid=None: False

    w.db.execute("UPDATE turn SET status='done', ended_at=? WHERE id=?",
                 (ffwatch.now_iso(), turn_id))
    w.db.execute("INSERT INTO outbound(conversation_id, action, payload_json, nonce, status,"
                 " created_at) VALUES(?,'post','{}','n-7200','pending',?)",
                 (conv_id, ffwatch.now_iso()))
    check("an answer composed and not yet delivered is not quiet either",
          w.settling()["outbound"] == 1, w.settling())

    # A row waiting on a PERSON is not this machine's work, and holding the update for it would
    # mean every update on such a box waited out the window and then forced, every time.
    w.cfg["approve_before_send"] = True
    check("a row held for approval waits on a human, not on the updater",
          w.settling()["outbound"] == 0, w.settling())
    w.cfg["approve_before_send"] = False
    check("and counts again the moment the sender would send it by itself",
          w.settling()["outbound"] == 1, w.settling())

    w.db.execute("UPDATE outbound SET status='sent' WHERE nonce='n-7200'")
    # The second turn is still running in a live container, so close it before asking whether
    # the box is quiet -- otherwise this is asserting that a busy box is idle.
    w.db.execute("UPDATE turn SET status='done', ended_at=? WHERE status='running'",
                 (ffwatch.now_iso(),))
    w.db.execute("UPDATE run SET terminal_state='done', exit_code=0"
                 " WHERE terminal_state IS NULL")
    check("with all four at zero the machine is quiet",
          sum(w.settling().values()) == 0 and w.settling_phrase(w.settling()) == "nothing",
          w.settling())

    upd = open(os.path.join(HERE, "update_ffbox.sh"), encoding="utf-8").read()
    code = "\n".join(l for l in upd.splitlines() if not l.lstrip().startswith("#"))
    check("and the updater asks both questions, not just docker's",
          '"$FFWATCH" quiet' in code and "label=ffbox.workload" in code, None)


def test_the_updater_records_when_an_update_actually_landed():
    """The stamp behind /status's "last update" line, and the one thing it must not count.

    A config-only pass drains and restarts but leaves the checkout on the commit it was
    already on. Stamping there would make a box stuck two days behind master read as freshly
    updated every time somebody edited config.json — which is the direction of lie that
    matters, because the whole point of the number is to answer "is this box current?".
    """
    print("update: the stamp says landed, not looked")
    upd = open(os.path.join(HERE, "update_ffbox.sh"), encoding="utf-8").read()
    code = "\n".join(l for l in upd.splitlines() if not l.lstrip().startswith("#"))
    check("the stamp lives beside the config fingerprint, outside the checkout",
          "APPLIED_STAMP=$CONFIG_DIR/update.last-applied" in code, None)
    write = code.partition('config_fingerprint > "$CONFIG_STAMP"')[2] \
                .partition('log "starting ffbox.target"')[0]
    check("it is written a moment before the start, like the fingerprint",
          '> "$APPLIED_STAMP"' in write, write)
    check("only when the merge actually took something",
          '[ "$CODE_UPDATE" = 1 ]' in write, write)
    check("and it carries the epoch and the commit it landed on",
          "date +%s" in write and "rev-parse HEAD" in write, write)
    check("a failure to write it never stops the box coming back",
          "|| log" in write and "die" not in write, write)

    st = open(os.path.join(HERE, "ffstatus.sh"), encoding="utf-8").read()
    stc = "\n".join(l for l in st.splitlines() if not l.lstrip().startswith("#"))
    check("ffstatus reads that stamp rather than the timer's last trigger",
          "update.last-applied" in stc and "LastTriggerUSec" not in stc, None)
    check("and asks systemd for the next elapse instead of the interval in the unit file",
          "NextElapseUSecMonotonic" in stc, None)


def test_the_updater_waits_for_the_host_and_not_for_containers():
    """The window is the HOST's tail now, and it is five minutes rather than an hour.

    It used to be an hour because a container did not survive a restart: ffbox was a child of
    ffwatch, in its cgroup, so a stop signalled it and its trap stopped the container. An hour
    was the compromise between a box that never updates and a run that gets interrupted, and it
    was a bad compromise in both directions -- a twenty-hour job both blocked every update and
    was killed at the end of the window anyway.

    Containers are detached now, so the update neither waits for them nor stops them. What is
    left to wait for is a turn whose container has ALREADY exited and whose push is in a thread,
    because a thread does not survive a stop. That is seconds of work.

    STOP_RUNNING puts the old behaviour back for one pass, for a fix that has to apply to what is
    running right now -- and when it does, forcing is still a soft stop.
    """
    print("update: it waits for the host, not the containers")
    upd = open(os.path.join(HERE, "update_ffbox.sh"), encoding="utf-8").read()
    code = "\n".join(l for l in upd.splitlines() if not l.lstrip().startswith("#"))
    check("the window is the host's tail, not an hour of containers",
          "FFBOX_DRAIN_TIMEOUT:-300" in code, None)
    check("and nothing stands the update down at the end of it",
          "STANDING DOWN" not in upd, None)
    loop = code.partition("_deadline=$(( $(date +%s) + DRAIN_TIMEOUT ))")[2] \
               .partition('log "stopping ffbox.target"')[0]
    check("nothing in the wait exits before the merge", "exit 0" not in loop, loop)
    check("what it waits on is the host alone", "--host-only" in loop, loop)
    # A working container is counted only under the deliberate flag. The `while` body is the
    # slice that matters: the section after it names what is being carried and never counts it.
    body = loop.partition("while :; do")[2].partition("\ndone")[0]
    check("nothing counts a working container unless stop-running is armed",
          "ffbox.workload" not in body.partition('STOP_RUNNING" = 1')[0], body[:400])
    check("and what is left running is named rather than waited on",
          "it keeps working across this update" in upd
          and "leaving $_c running" in upd, None)

    # The deliberate form: wait for containers, then stop them SOFTLY.
    force = code.partition("_forced=1")[2].partition("_settle=")[0]
    check("the stragglers get docker stop with a real grace",
          'stop --timeout "$FORCE_STOP_GRACE"' in force, force)
    check("and never rm -f, which would skip the harvest and the licence return",
          "rm -f" not in force, force)
    check("the host gets a bounded window of its own afterwards",
          "FORCE_SETTLE" in code and '"$FFWATCH" quiet' in code, None)
    check("stop-running is armable by a file, so the timer can pick it up",
          "update.stop-running" in code, None)

    # What survives is named, and nothing survives for ever.
    check("every surviving container is named in the log",
          "it keeps working across this update" in upd, None)
    check("and one past the age ceiling is stopped rather than carried again",
          "MAX_CONTAINER_AGE" in code, None)


def test_every_lane_agrees_on_the_workspace_path():
    """The workspace is at CI's runner path, and eight files have to say so identically.

    Unity's package resolution cache (Library/PackageManager/projectResolution.json) records
    absolute paths taken from whatever machine produced the tree, and the tree here is CI's.
    Restore it under any other path and UPM discards the cache and re-resolves from the registry
    on every editor launch — which is what the egress fence refused on runs 26, 27, 35 and 36,
    each reporting compiled=false without a line of the diff being wrong.

    So the path is load-bearing, and a single file left on /workspace does not fail loudly: the
    container-side default would point at a directory the tmpfs is not at, and the host would
    look for a transcript under a slug nothing writes."""
    print("the workspace path")
    ws = ffwatch.CONTAINER_WORKSPACE

    ffbox_src = io.open(os.path.join(HERE, "ffbox"), encoding="utf-8").read()
    check("ffbox mounts the tmpfs at the runner path",
          f"WORKSPACE_PATH={ws}\n" in ffbox_src
          and '--tmpfs "$WORKSPACE_PATH:size=' in ffbox_src, None)
    check("ffbox tells the container where it is",
          '-e "FFBOX_WORKSPACE=$WORKSPACE_PATH"' in ffbox_src, None)

    # Every script that runs INSIDE the container falls back to the same path when the variable
    # is missing, so a hand-run container lands where a dispatched one does.
    for name, var in (("entrypoint.sh", "WORKSPACE"), ("restore-workspace.sh", "WORKSPACE"),
                      ("harvest-workspace.sh", "WORKSPACE"), ("run-as-user.sh", "WORKSPACE"),
                      ("pool-task.sh", "WORKSPACE"), ("discord-task.sh", "WORKSPACE")):
        body = io.open(os.path.join(HERE, name), encoding="utf-8").read()
        check(f"{name} defaults to the runner path",
              f"{var}=${{FFBOX_WORKSPACE:-{ws}}}" in body, None)
    verify = io.open(os.path.join(HERE, "ffverify.sh"), encoding="utf-8").read()
    check("ffverify.sh defaults to the runner path",
          "PROJECT=${FFVERIFY_PROJECT:-${FFBOX_WORKSPACE:-%s}}" % ws in verify, None)
    playtest = io.open(os.path.join(HERE, "ffplaytest.sh"), encoding="utf-8").read()
    check("ffplaytest.sh defaults to the runner path",
          "PROJECT=${FFPLAYTEST_PROJECT:-${FFBOX_WORKSPACE:-%s}}" % ws in playtest, None)

    # The transcript slug is Claude Code's, derived from that cwd: everything outside
    # [A-Za-z0-9-] becomes a dash, which doubles it where the path has /_. Measured against
    # Claude Code 2.1.252. The host reads the transcript from this directory and the container
    # writes it there, so a wrong value is a run that looks like it never started.
    check("the project slug is the one Claude Code derives from that cwd",
          ffwatch.CONTAINER_PROJECT_SLUG == "-opt-actions-runner--work-FinalFactory-FinalFactory",
          ffwatch.CONTAINER_PROJECT_SLUG)

    # Nothing anywhere still says /workspace, in a default or in a prompt the agent reads.
    for name in ("ffbox", "entrypoint.sh", "restore-workspace.sh", "harvest-workspace.sh",
                 "run-as-user.sh", "pool-task.sh", "discord-task.sh", "ffverify.sh",
                 "ffplaytest.sh", "ffmcp.sh"):
        body = io.open(os.path.join(HERE, name), encoding="utf-8").read()
        stale = [ln for ln in body.splitlines()
                 if "/workspace" in ln and not ln.lstrip().startswith("#")]
        check(f"{name} has no /workspace left outside a comment", not stale, stale[:3])


def test_memory_is_read_from_meminfo_not_from_dev_shm():
    """The workspace tmpfs is one Docker CREATES; it is not a directory under /dev/shm and
    is not charged to it. Measured on 2026-08-31 with one run in flight: df said 2.1M used of
    378G while that run's workspace held 24G and Shmem read 23.2 GiB. A check written against df
    would report hundreds of gigabytes free until the machine died."""
    print("pool: the memory check")
    src = open(os.path.join(HERE, "ffwatch.py"), encoding="utf-8").read()
    check("the headroom check reads /proc/meminfo", "/proc/meminfo" in src, None)
    check("and the headroom check itself never consults df or /dev/shm",
          "/dev/shm" not in src.partition("def pool_has_room")[2].partition("def ")[0], None)

    case = Case("poolmem", base_fixture())
    w = case.watcher
    w.cfg["max_concurrent_runs"] = 2
    w.mem_available_bytes = staticmethod(lambda: 200 * 1024 ** 3)
    check("200 GiB is room for a staged container and two cold runs", w.pool_has_room(), None)
    w.mem_available_bytes = staticmethod(lambda: 40 * 1024 ** 3)
    check("40 GiB is not", not w.pool_has_room(), None)
    check("but it is still room for the two runs themselves",
          w.pool_has_room(for_containers=0) is False, None)
    w.mem_available_bytes = staticmethod(lambda: None)
    check("an unreadable meminfo does not take the feature offline", w.pool_has_room(), None)



def test_a_conversation_publishes_onto_one_branch():
    """Turn 4's work lands on turn 3's branch, not on a second one beside it.

    THE BUG THIS EXISTS FOR, observed on the build server rather than imagined. Conversation 30
    took four turns at one bug. Turn 3 published
    `ffbox/antimatter-cloud-phantom-stability-d30t3-c499b106` against develop; turn 4, started
    from the same pinned base with no idea any of that had happened, re-picked its base, renamed
    itself, and published `ffbox/antimatter-cloud-phantom-stability-master-d30t4-8ec81be5`
    against master. Two branches, two bases, one three-file change, and nothing on either of
    them saying which was current.

    A conversation is one piece of work however many turns it takes. It owns ONE branch, claimed
    by the first run that pushes, and every turn after starts standing on it and publishes back
    onto it.
    """
    print("publication: one branch per conversation")
    case = bug_case("oneabranch", venue="private")
    origin, host = git_origin(case)

    escalate(case, changed=["Assets/Belt.cs"], verify=PASSING_VERIFY)
    first = case.rows("SELECT r.* FROM run r JOIN turn t ON t.id=r.turn_id"
                      " ORDER BY r.id DESC")[0]
    conv = case.rows("SELECT * FROM conversation")[0]
    branch = first["branch"]
    check("the first run to push claims the branch for the conversation",
          conv["branch"] == branch and branch == f"ffbox/{first['ffbox_run_id']}",
          (conv["branch"], branch))
    check("and it is in the mirror, which is the only place a later run could see it",
          git_run("-C", mirror_of(case), "rev-parse", "--verify", "--quiet",
                  "refs/heads/%s^{commit}" % branch).returncode == 0,
          git_run("-C", mirror_of(case), "for-each-ref", "--format=%(refname)",
                  "refs/heads/ffbox/*").stdout)

    # A SECOND TURN, touching a different file so the two contributions are told apart.
    escalate(case, changed=["Assets/Merger.cs"], verify=PASSING_VERIFY)
    second = case.rows("SELECT r.* FROM run r JOIN turn t ON t.id=r.turn_id"
                       " ORDER BY r.id DESC")[0]
    conv = case.rows("SELECT * FROM conversation")[0]
    check("the second turn publishes onto the same branch",
          second["branch"] == branch, (second["branch"], branch))
    check("and it really did push", second["pushed"] == 1, second)
    check("the conversation still names that one branch, not the newer run's id",
          conv["branch"] == branch, conv["branch"])

    heads = [ln.split()[-1] for ln in
             git_run("-C", host, "ls-remote", "--heads", "origin").stdout.splitlines()
             if "refs/heads/ffbox/" in ln]
    check("ONE ffbox branch exists on the remote, not two",
          heads == [f"refs/heads/{branch}"], heads)

    # The point of one branch: a reviewer opens it and sees the whole conversation's work.
    listed = git_run("-C", host, "diff", "--name-only",
                     "refs/remotes/origin/develop..refs/ffbox/%s" % branch).stdout.split()
    check("the branch carries both turns' files",
          sorted(listed) == ["Assets/Belt.cs", "Assets/Merger.cs"], listed)
    check("and the recorded file count is the branch's, not the last turn's",
          second["changed_files"] == 2, second["changed_files"])
    check("both runs point at the same base, so the second did not re-pick one",
          first["pr_base"] == second["pr_base"] == "develop",
          (first["pr_base"], second["pr_base"]))

    # WHICH TURN MADE THE BRANCH is a fact only the publish knows: by reply time the claim has
    # been written and both runs look alike from the row. So it is recorded there, and the two
    # replies this conversation posted say different things because of it.
    check("the run that made the branch recorded that it made it",
          first["branch_existed"] == 0, first["branch_existed"])
    check("and the one that added to it recorded that too",
          second["branch_existed"] == 1, second["branch_existed"])
    posted = [json.loads(r["payload_json"])["text"]
              for r in case.rows("SELECT * FROM outbound WHERE action='post' ORDER BY id")]
    footers = [ln.split(" · ")[0] for t in posted for ln in t.splitlines()
               if "pending dev review" in ln]
    check("so the thread reads created once and updated after",
          footers == [f"Fix created on `{branch}`, pending dev review",
                      f"Fix updated on `{branch}`, pending dev review"],
          footers)
    check("and both lines carry the one pull request, which the second turn did not reopen",
          all(f"· PR #{second['pr_number']} " in t for t in posted
              if "pending dev review" in t) and first["pr_number"] == second["pr_number"],
          (first["pr_number"], second["pr_number"]))


def test_a_continuation_starts_on_the_branch_and_is_told_so():
    """The second turn is checked out on the conversation's branch and knows it.

    Three separate mechanisms have to agree or the run publishes something other than what it
    was started on:

      * --ref is the branch, so the clone lands on the earlier turn's commits
      * --branch-prefix is WITHHELD, so the harvest cannot rename the work after whatever
        branch the agent happened to make
      * the preamble says all of this, so the agent commits onto it instead of fighting it

    The middle one is what makes it true whether or not the model cooperates; the last is what
    stops the model wasting a turn discovering the middle one.
    """
    print("publication: what a continuing turn is told")
    case = bug_case("continued", venue="private")
    origin, host = git_origin(case)
    escalate(case, changed=["Assets/Belt.cs"], verify=PASSING_VERIFY)
    branch = case.rows("SELECT * FROM conversation")[0]["branch"]

    escalate(case, changed=["Assets/Merger.cs"], verify=PASSING_VERIFY)
    run = case.rows("SELECT r.* FROM run r JOIN turn t ON t.id=r.turn_id"
                    " ORDER BY r.id DESC")[0]
    run_dir = os.path.dirname(run["stream_path"])
    argv = json.load(open(os.path.join(run_dir, "ffbox-argv.json"), encoding="utf-8"))
    job = json.load(open(os.path.join(run_dir, "job.json"), encoding="utf-8"))

    check("the clone starts on the conversation's branch, not at the pinned base",
          "--ref" in argv and argv[argv.index("--ref") + 1] == branch, argv)
    check("and ffbox is told to publish under exactly that name",
          "--branch" in argv and argv[argv.index("--branch") + 1] == branch, argv)
    # WITHOUT THIS the harvest renames the work to <prefix><whatever branch HEAD ended on>-<run
    # id>, which is a second branch carrying the first turn's commits again and an open pull
    # request left pointing at the older one.
    check("--branch-prefix is withheld, so the harvest cannot rename a settled branch",
          "--branch-prefix" not in argv, argv)
    check("the job names the branch the conversation owns",
          job["bases"]["conversation_branch"] == branch, job["bases"])

    # THROUGH THE CONTAINER'S OWN BUILDER, because the preamble is assembled inside
    # discord-task.sh and not on the host: asserting on the host's job dict would prove nothing
    # about what `claude` is actually told.
    pre = preamble_for(job, "continuedpre")
    check("the preamble says the run is already on it and names it",
          "ALREADY ON THIS CONVERSATION'S BRANCH" in pre and branch in pre, pre[:400])
    check("and tells it not to make one of its own", "DO NOT make a branch" in pre, pre[:400])
    check("the base-choosing instruction is gone, because there is nothing left to choose",
          "git checkout -b <name> origin/<base>" not in pre, pre[:400])
    check("but it is still told which base the branch is for",
          "based on `origin/develop`" in pre, pre[:400])
    check("and it is warned off the cross-base checkout that costs a Unity reimport",
          "reimport" in pre, pre[:400])

    # A FIRST turn is unchanged: it still makes a branch and still picks a base.
    fresh = json.load(open(os.path.join(
        os.path.dirname(case.rows("SELECT r.* FROM run r ORDER BY r.id")[0]["stream_path"]),
        "job.json"), encoding="utf-8"))
    fresh_pre = preamble_for(fresh, "freshpre")
    check("a first turn is still told to make a branch and choose a base",
          "MAKE A BRANCH BEFORE YOU CHANGE ANYTHING" in fresh_pre
          and "git checkout -b <name> origin/<base>" in fresh_pre, fresh_pre[:400])
    check("and it carries no conversation branch, because there was none yet",
          fresh["bases"]["conversation_branch"] is None, fresh["bases"])


def test_a_run_that_publishes_nothing_leaves_no_branch_name():
    """run.branch names what a run PUBLISHED, and a run that published nothing names nothing.

    It is written at launch with the name the container is told to start on — before any branch
    exists — and _no_branch used to leave that placeholder sitting in the row next to the reason
    there was no branch. Eighteen of the nineteen non-null values on the build server were that:
    a name for a branch that was never created, that the page rendered as a branch, on the same
    line as "no branch: the run changed no files".
    """
    print("publication: no branch means no branch name")
    case = bug_case("nobranchname", venue="private")
    git_origin(case)
    # No changed files, so the harvest leaves no branch.txt and publish takes the _no_branch path.
    escalate(case, changed=[], verify=None)
    run = case.rows("SELECT r.* FROM run r JOIN turn t ON t.id=r.turn_id"
                    " ORDER BY r.id DESC")[0]
    conv = case.rows("SELECT * FROM conversation")[0]
    check("the run records why there is no branch",
          run["no_branch_reason"] == "the run changed no files", run["no_branch_reason"])
    check("and does not also claim one", run["branch"] is None, run["branch"])
    check("it was launched with a name all the same — the ask is on the command line",
          "--branch" in json.load(open(os.path.join(os.path.dirname(run["stream_path"]),
                                                    "ffbox-argv.json"), encoding="utf-8")))
    check("and the conversation claims no branch either",
          conv["branch"] is None, conv["branch"])


def test_the_v12_migration_repairs_what_the_old_rule_left():
    """A database written before this rule is brought to it on the next start.

    Both halves matter and they are separate facts: the placeholder names have to go, and the
    conversations that DID publish have to end up owning the branch their next turn will
    continue. Where a conversation published more than once — which is what the old rule
    produced — the newest push is the one to carry forward.
    """
    print("publication: the v12 migration")
    case = Case("v12migrate")
    db = case.watcher.db
    db.execute("INSERT INTO conversation(id, thread_id, kind, state, created_at)"
               " VALUES(9, '9000', 'bug_report', 'idle', ?)", (ffwatch.now_iso(),))
    db.execute("INSERT INTO turn(conversation_id, seq, status) VALUES(9, 1, 'done')")
    db.execute("INSERT INTO turn(conversation_id, seq, status) VALUES(9, 2, 'done')")
    db.execute("INSERT INTO turn(conversation_id, seq, status) VALUES(9, 3, 'done')")
    turns = [r["id"] for r in case.rows("SELECT id FROM turn WHERE conversation_id=9 ORDER BY seq")]
    # Exactly conversation 30's shape: a turn that published nothing but kept its placeholder,
    # then two that published, on two different branches.
    db.execute("INSERT INTO run(turn_id, ffbox_run_id, branch, pushed, terminal_state,"
               " no_branch_reason) VALUES(?, 'd9t1', 'ffbox/d9t1', 0, 'done',"
               " 'the run changed no files')", (turns[0],))
    db.execute("INSERT INTO run(turn_id, ffbox_run_id, branch, pushed, terminal_state)"
               " VALUES(?, 'd9t2', 'ffbox/fix-it-d9t2', 1, 'done')", (turns[1],))
    db.execute("INSERT INTO run(turn_id, ffbox_run_id, branch, pushed, terminal_state)"
               " VALUES(?, 'd9t3', 'ffbox/fix-it-master-d9t3', 1, 'done')", (turns[2],))
    # A run still in flight: no terminal state, so its launch-time name is not a stale one yet.
    db.execute("INSERT INTO turn(conversation_id, seq, status) VALUES(9, 4, 'running')")
    live = case.rows("SELECT id FROM turn WHERE conversation_id=9 ORDER BY seq")[-1]["id"]
    db.execute("INSERT INTO run(turn_id, ffbox_run_id, branch, pushed)"
               " VALUES(?, 'd9t4', 'ffbox/d9t4', 0)", (live,))
    db.execute("UPDATE conversation SET branch=NULL WHERE id=9")

    db.init_schema()

    rows = {r["ffbox_run_id"]: r for r in case.rows("SELECT * FROM run")}
    check("a finished run that never pushed loses its placeholder",
          rows["d9t1"]["branch"] is None, rows["d9t1"]["branch"])
    check("a run still in flight keeps the name it was launched with",
          rows["d9t4"]["branch"] == "ffbox/d9t4", rows["d9t4"]["branch"])
    check("a pushed branch is left exactly as it was",
          rows["d9t2"]["branch"] == "ffbox/fix-it-d9t2", rows["d9t2"]["branch"])
    conv = case.rows("SELECT * FROM conversation WHERE id=9")[0]
    check("the conversation takes the NEWEST branch it published, which is what a next turn"
          " should continue",
          conv["branch"] == "ffbox/fix-it-master-d9t3", conv["branch"])

    # IDEMPOTENT, because it runs on every start and not once.
    db.init_schema()
    check("running it again changes nothing",
          case.rows("SELECT * FROM conversation WHERE id=9")[0]["branch"]
          == "ffbox/fix-it-master-d9t3")
    check("and a conversation that never published still owns no branch",
          all(r["branch"] is None for r in case.rows(
              "SELECT * FROM conversation WHERE id<>9")))


def test_a_continuation_the_mirror_cannot_supply_is_refused():
    """No mirror, no continuation, and NO SECOND BRANCH — the turn fails instead.

    A container resolves --ref against the mirror and nothing else, so a conversation branch
    that is not there cannot be continued. Every route past that point breaks the rule: starting
    at the base while publishing under the settled name offers origin a non-fast-forward push,
    which is rejected and loses the work; starting at the base under a NEW name is the second
    branch itself. So the launcher refuses before the run row is written — nothing runs, nothing
    is spent, and the reply says what a human has to fix.
    """
    print("publication: a continuation the mirror cannot supply")
    case = bug_case("nomirror", venue="private")
    origin, host = git_origin(case)
    escalate(case, changed=["Assets/Belt.cs"], verify=PASSING_VERIFY)
    branch = case.rows("SELECT * FROM conversation")[0]["branch"]
    runs_before = len(case.rows("SELECT * FROM run"))

    # Take the branch away AND make the repair impossible, which is what a lost branch is: gone
    # from the mirror, and gone from the host checkout the repair would have fetched it from.
    git_run("-C", mirror_of(case), "update-ref", "-d", "refs/heads/%s" % branch)
    case.watcher.cfg["mirror_repo"] = os.path.join(case.root, "gone.git")
    check("the branch is not visible to a container any more",
          not case.watcher.mirror_carries(branch))

    escalate(case, changed=["Assets/Merger.cs"], verify=PASSING_VERIFY)
    check("no run was started at all — the refusal is before the container",
          len(case.rows("SELECT * FROM run")) == runs_before,
          [r["ffbox_run_id"] for r in case.rows("SELECT * FROM run")])
    heads = [ln.split()[-1] for ln in
             git_run("-C", host, "ls-remote", "--heads", "origin").stdout.splitlines()
             if "refs/heads/ffbox/" in ln]
    check("and still exactly one ffbox branch on the remote",
          heads == [f"refs/heads/{branch}"], heads)
    check("the conversation keeps naming the branch it owns",
          case.rows("SELECT * FROM conversation")[0]["branch"] == branch,
          case.rows("SELECT * FROM conversation")[0]["branch"])
    turn = case.rows("SELECT * FROM turn ORDER BY seq DESC")[0]
    check("the turn is failed rather than left queued forever",
          turn["status"] == "failed", turn["status"])
    check("with a reason that names the branch and says nothing ran",
          branch in (turn["error"] or "") and "Nothing was run" in (turn["error"] or ""),
          turn["error"])


def test_a_second_branch_is_refused_at_the_push():
    """The last gate: a run that harvested a name the conversation does not own never pushes.

    Everything upstream is arranged so this cannot happen — launch() passes the settled name and
    withholds --branch-prefix, so the harvest publishes exactly what it was given, and no
    ordinary run can reach this state. That is the argument FOR the check rather than against
    it: it is an assertion about an invariant several moving parts have to keep, and the cost of
    one of them being wrong is a second branch on origin carrying a second copy of the same
    work — the one failure a reviewer cannot see by reading either branch.

    So publish() is called directly, with a harvest that names a branch the conversation does
    not own. There is no way to provoke it through launch(), which is the point.
    """
    print("publication: a second branch is refused at the push")
    case = bug_case("secondbranch", venue="private")
    origin, host = git_origin(case)
    escalate(case, changed=["Assets/Belt.cs"], verify=PASSING_VERIFY)
    first = case.rows("SELECT r.* FROM run r JOIN turn t ON t.id=r.turn_id"
                      " ORDER BY r.id DESC")[0]
    conv = case.rows("SELECT * FROM conversation")[0]
    branch = conv["branch"]
    run_dir = os.path.dirname(first["stream_path"])
    check("the harvest on disk names the branch that was published",
          io.open(os.path.join(run_dir, "branch.txt"),
                  encoding="utf-8").read().strip() == branch, branch)

    # The conversation now owns something else. However that came about — a rename slipping
    # through, a config change, an edited row — this harvest is a second branch and must not go.
    case.watcher.db.execute("UPDATE conversation SET branch=? WHERE id=?",
                            ("ffbox/something-else-entirely", conv["id"]))
    conv = case.rows("SELECT * FROM conversation")[0]
    turn = case.rows("SELECT * FROM turn ORDER BY seq DESC")[0]
    cur = case.watcher.db.execute(
        "INSERT INTO run(turn_id, ffbox_run_id, branch) VALUES(?,'d1t9-forced',?)",
        (turn["id"], branch))
    result = case.watcher.publish(cur.lastrowid, turn, conv, run_dir,
                                  {"run_id": "d1t9-forced"}, CONFIDENT_VERDICT)
    forced = case.rows("SELECT * FROM run WHERE id=?", (cur.lastrowid,))[0]

    check("it did not push", forced["pushed"] == 0, forced["pushed"])
    check("and says why, naming the branch it refused",
          "second branch" in (forced["no_branch_reason"] or "")
          and "ffbox/something-else-entirely" in (forced["no_branch_reason"] or ""),
          forced["no_branch_reason"])
    check("the refusal is what the reply is told, too",
          "second branch" in (result.get("no_branch_reason") or ""), result)
    heads = [ln.split()[-1] for ln in
             git_run("-C", host, "ls-remote", "--heads", "origin").stdout.splitlines()
             if "refs/heads/ffbox/" in ln]
    check("origin still carries the one branch the conversation published",
          heads == [f"refs/heads/{branch}"], heads)
    check("and the bundle is still on disk, so nothing was destroyed by stopping",
          os.path.exists(os.path.join(run_dir, "work.bundle")))


def test_a_submission_cannot_name_a_branch_the_conversation_does_not_own():
    """`--branch` and `--ref` lose to a conversation that already publishes somewhere.

    Both are operator overrides and both are honoured on a conversation that owns no branch —
    which is every first turn and every shell prompt. On one that does, obeying either produces
    the same two bad outcomes as everything else here, so they are ignored and said so.
    """
    print("publication: a submission cannot re-aim a settled conversation")
    case = bug_case("overrides", venue="private")
    origin, host = git_origin(case)
    escalate(case, changed=["Assets/Belt.cs"], verify=PASSING_VERIFY)
    conv = case.rows("SELECT * FROM conversation")[0]
    branch = conv["branch"]

    turn_id = queue_follow_up(case, conv, note="try again")
    case.watcher.db.execute(
        "UPDATE turn SET options_json=? WHERE id=?",
        (json.dumps({"ref": "develop", "branch": "wip"}), turn_id))
    turn = case.rows("SELECT * FROM turn WHERE id=?", (turn_id,))[0]
    check("the run starts on the conversation's branch, not the --ref",
          case.watcher.run_ref(turn, case.rows("SELECT * FROM conversation")[0]) == branch,
          case.watcher.run_ref(turn, conv))

    os.environ["FFBOX_STUB_CHANGED"] = json.dumps(["Assets/Merger.cs"])
    os.environ["FFBOX_STUB_VERIFY"] = json.dumps(PASSING_VERIFY)
    os.environ["FFBOX_STUB_VERDICT"] = json.dumps(CONFIDENT_VERDICT)
    case.watcher.once()
    run = case.rows("SELECT r.* FROM run r JOIN turn t ON t.id=r.turn_id"
                    " ORDER BY r.id DESC")[0]
    argv = json.load(open(os.path.join(os.path.dirname(run["stream_path"]),
                                       "ffbox-argv.json"), encoding="utf-8"))
    check("and publishes under the conversation's name, not --branch wip",
          argv[argv.index("--branch") + 1] == branch, argv)
    check("it published", run["pushed"] == 1 and run["branch"] == branch, run["branch"])
    heads = [ln.split()[-1] for ln in
             git_run("-C", host, "ls-remote", "--heads", "origin").stdout.splitlines()
             if "refs/heads/ffbox/" in ln]
    check("one branch on the remote, still", heads == [f"refs/heads/{branch}"], heads)


def test_the_mirror_is_only_written_inside_the_pipelines_own_namespace():
    """mirror_take may create refs/heads/ffbox/*, and nothing else.

    The mirror is shared: CI's runners fetch every branch on origin into it and build against
    what they find. A bug that let this write outside the prefix could move `develop` under a
    job that was mid-fetch, so the guard is a check against the configured prefix rather than
    trust in the caller.
    """
    print("publication: the mirror write is fenced")
    case = bug_case("mirrorfence", venue="private")
    origin, host = git_origin(case)
    mirror = mirror_of(case)
    before = git_run("-C", mirror, "rev-parse", "develop").stdout.strip()

    check("a name outside the prefix is refused", case.watcher.mirror_take("develop") is False)
    check("and nothing moved", git_run("-C", mirror, "rev-parse", "develop").stdout.strip()
          == before)
    check("an empty name is refused too", case.watcher.mirror_take("") is False)

    escalate(case, changed=["Assets/Belt.cs"], verify=PASSING_VERIFY)
    branch = case.rows("SELECT * FROM conversation")[0]["branch"]
    check("a published branch does go in", case.watcher.mirror_carries(branch), branch)
    check("and develop is still where it was",
          git_run("-C", mirror, "rev-parse", "develop").stdout.strip() == before)
    check("a branch nobody published is not there",
          not case.watcher.mirror_carries("ffbox/never-existed"))


def push_a_stranger_branch(host, name, *, base="develop", files=("Assets/Save.cs",)):
    """A branch on origin that this box did not make, with a commit by somebody else on it.

    Committed under a person's identity on purpose: everything ffbox publishes is held to
    carrying ffbox@final-factory.invalid, and the whole difficulty of working on a branch
    somebody else pushed is that the commits already on it are theirs.
    """
    git_run("-C", host, "fetch", "-q", "origin")
    git_run("-C", host, "checkout", "-q", "--detach", "origin/" + base)
    for name_ in files:
        path = os.path.join(host, name_)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "a", encoding="utf-8") as fh:
            fh.write("// by a person\n")
    git_run("-C", host, "add", "-A")
    git_run("-C", host, "-c", "user.name=Loth", "-c", "user.email=loth@example.invalid",
            "commit", "-qm", "save fix, by hand")
    head = git_run("-C", host, "rev-parse", "HEAD").stdout.strip()
    git_run("-C", host, "push", "-q", "origin", "HEAD:refs/heads/" + name)
    git_run("-C", host, "checkout", "-q", "--detach", "origin/" + base)
    git_run("-C", host, "fetch", "-q", "origin")
    return head


def test_the_scheduler_asks_about_the_ref_the_launch_will_use():
    """A turn on its own branch takes a cold container, and the ceiling knows it.

    THE MISMATCH THIS FIXES. The pre-check that lets a turn past a full box asked
    pool_would_serve about "--ref, else the conversation's pinned base sha, else base_ref". From
    turn 2 that sha is set, `looks_like_sha` is true, and a sha matches ANY warm container of the
    class -- so the answer was yes while launch() went on to ask pool_claim_for about the
    conversation's BRANCH, missed, and cold-launched anyway. A run started past a ceiling that
    had no room for it.

    Adoption makes that routine rather than occasional, because an adopted conversation is on a
    branch from its first turn. Both sides now go through run_ref.
    """
    print("pool: the pre-check and the launch ask the same question")
    case = bug_case("schedref", venue="private")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pool")
    conv = case.rows("SELECT * FROM conversation")[0]
    ok, reason = case.watcher.adopt_branch(conv["id"], "loth/pool", by="op")
    check("adopted", ok, reason)
    w = case.watcher
    for cls in ffwatch.AGENT_CLASSES:
        w.cfg["agent_classes"][cls]["idle_agents"] = 1
    os.makedirs(os.path.join(w.pool_dir("p1"), "out"), exist_ok=True)
    open(os.path.join(w.pool_dir("p1"), "out", "staged"), "w").close()
    w.pool_containers = lambda: [
        {"name": "cp", "id": "p1", "branch": "master", "class": "ffagent"}]

    check("a warm container staged on master does not serve a turn on another branch",
          w.pool_claim_for("loth/pool", "ffagent") is None, None)
    check("and would_serve agrees",
          w.pool_would_serve("loth/pool", "ffagent") is False, None)

    # What the pre-check actually asks, with the box full so it is reached at all.
    asked = []
    w.pool_would_serve = lambda ref, cls=None, claude_key=None: asked.append(ref) or False
    w.workload_room = lambda: 0
    queue_follow_up(case, conv, note="carry on")
    w.schedule()
    check("the ceiling check asked about the conversation's branch, not its pinned base",
          asked and asked[0] == "loth/pool", asked)
    check("and the turn stayed queued rather than starting past a full box",
          case.rows("SELECT status FROM turn ORDER BY id DESC")[0]["status"] == "queued",
          case.rows("SELECT status FROM turn ORDER BY id DESC")[0]["status"])


def test_an_adopted_branch_is_described_as_somebody_elses_work():
    """The preamble tells the truth about whose commits are under the run.

    Same mechanism as a continuation, opposite fact. On a branch this conversation built, the
    commits are its own earlier turns' and the tree is its working state. On an adopted one they
    are a person's, on origin, possibly under review — and an agent told they were its own
    earlier work would treat somebody's considered branch as a draft it had left lying about.
    """
    print("adoption: what the container is told about the branch")
    job = dict(JOB_SKELETON)
    job["bases"] = {"checked_out": "loth/save-fix", "checked_out_base": "develop",
                    "conversation_branch": "loth/save-fix", "branch_adopted": True,
                    "choices": {"master": "the released build", "develop": "next version"}}
    pre = preamble_for(job, "adoptedpre")
    check("it says the conversation did not create this branch",
          "DID NOT CREATE" in pre and "loth/save-fix" in pre, pre[:600])
    check("and that the work on it is somebody else's",
          "somebody else pushed" in pre, pre[:600])
    check("it is told to read the branch before changing it",
          "READ THE BRANCH BEFORE YOU CHANGE IT" in pre, pre[:600])
    check("not to branch or switch", "DO NOT" in pre and "make a branch" in pre, pre[:600])
    check("and not to rewrite what is already there",
          "rebase, revert, amend" in pre, pre[:600])
    check("the base-choosing instruction is still gone — that was settled by whoever made it",
          "git checkout -b <name> origin/<base>" not in pre, pre[:600])

    # THE ORDINARY CONTINUATION IS UNCHANGED. It is the same field that decides, so a bug in
    # the flag would show up as a conversation being told a stranger made its own last turn.
    job["bases"]["branch_adopted"] = False
    plain = preamble_for(job, "plainpre")
    check("a branch the conversation built is still described as its own work",
          "ALREADY ON THIS CONVERSATION'S BRANCH" in plain and "DID NOT CREATE" not in plain,
          plain[:400])


def test_a_conversation_can_be_told_which_branch_it_owns():
    """Adoption: a thread works on a branch somebody else pushed, and keeps working on it.

    THE CASE THIS EXISTS FOR. An operator has a branch — from a Claude Code session on a
    laptop, or another agent's run — and wants a thread to fix it up and take the review on
    the pull request it already has. Before this, asking for that produced a SECOND branch:
    the conversation had no branch, so the run started at the base, and the harvest renamed
    whatever the agent ended on into ffbox/<name>-<run id>.

    A conversation may now be told which branch it owns, and every reader of that column then
    does the rest — the same column, and the same readers, that a conversation gets by pushing.
    """
    print("publication: a conversation adopts a branch it did not create")
    case = bug_case("adoptbranch", venue="private")
    origin, host = git_origin(case)
    theirs = push_a_stranger_branch(host, "loth/save-fix")
    conv = case.rows("SELECT * FROM conversation")[0]

    ok, reason = case.watcher.adopt_branch(conv["id"], "loth/save-fix", by="900000000000000001")
    check("the branch is adopted", ok, reason)
    conv = case.rows("SELECT * FROM conversation")[0]
    check("the conversation owns it from now on", conv["branch"] == "loth/save-fix", conv["branch"])
    check("and the record says it was told rather than that it pushed one",
          bool(conv["branch_adopted_at"]) and conv["branch_adopted_by"] == "900000000000000001",
          (conv["branch_adopted_at"], conv["branch_adopted_by"]))
    check("ffwatch agrees that this conversation adopted",
          case.watcher.conversation_adopted(conv))
    # THE GUARD, for a row read before the migration ran or one with no branch at all. Both
    # answer no rather than raising, which is what every other reader of these columns does.
    check("a row from before the columns existed reads as not adopted",
          case.watcher.conversation_adopted({"branch": "x"}) is False
          and case.watcher.conversation_adopted(None) is False
          and case.watcher.conversation_adopted(
              {"branch": None, "branch_adopted_at": "now"}) is False)
    # The mirror is the only place a container can see a branch, and nothing this box published
    # is under refs/ffbox/loth/save-fix, so the copy has to come from origin.
    check("the branch is in the mirror, from origin",
          git_run("-C", mirror_of(case), "rev-parse", "refs/heads/loth/save-fix").stdout.strip()
          == theirs, git_run("-C", mirror_of(case), "rev-parse",
                             "refs/heads/loth/save-fix").stdout)

    escalate(case, changed=["Assets/Belt.cs"], verify=PASSING_VERIFY)
    run = _latest_run(case)
    run_dir = os.path.dirname(run["stream_path"])
    argv = json.load(open(os.path.join(run_dir, "ffbox-argv.json"), encoding="utf-8"))
    check("the FIRST turn starts on the adopted branch",
          argv[argv.index("--ref") + 1] == "loth/save-fix", argv)
    check("and is told to publish under that exact name",
          argv[argv.index("--branch") + 1] == "loth/save-fix", argv)
    check("with no --branch-prefix, so the harvest cannot rename it",
          "--branch-prefix" not in argv, argv)
    check("and the range starts where the run did, not at the base",
          "--range-from-start" in argv, argv)

    check("the run published onto the adopted branch", run["pushed"] == 1
          and run["branch"] == "loth/save-fix", (run["pushed"], run["branch"]))
    check("and recorded that the branch was already on the remote",
          run["branch_existed"] == 1, run["branch_existed"])
    check("only this run's own file is counted, not the branch's whole history",
          run["changed_files"] == 1, run["changed_files"])
    check("the pull request still targets the base the branch descends from",
          run["pr_base"] == "develop", run["pr_base"])

    heads = sorted(ln.split()[-1] for ln in
                   git_run("-C", host, "ls-remote", "--heads", "origin").stdout.splitlines())
    check("no second branch was created on the remote",
          heads == ["refs/heads/develop", "refs/heads/loth/save-fix", "refs/heads/master"],
          heads)
    remote_head = git_run("-C", host, "ls-remote", "origin",
                          "refs/heads/loth/save-fix").stdout.split()[0]
    check("the branch moved forward rather than being replaced",
          git_run("-C", host, "merge-base", "--is-ancestor", theirs,
                  remote_head).returncode == 0, (theirs, remote_head))

    # A SECOND TURN behaves like any other continuation: same branch, same pull request.
    escalate(case, changed=["Assets/Merger.cs"], verify=PASSING_VERIFY)
    second = _latest_run(case)
    check("the next turn stays on it", second["branch"] == "loth/save-fix", second["branch"])
    check("and the conversation still owns exactly that",
          case.rows("SELECT * FROM conversation")[0]["branch"] == "loth/save-fix")
    check("one pull request across both turns",
          second["pr_number"] == run["pr_number"], (run["pr_number"], second["pr_number"]))


def branch_directive_case(name, text, *, author=None):
    """One message in #ask_claude, ingested, with an origin and a mirror behind it.

    Returns (case, fixture) so a caller can append the next message and ingest that too, which
    is how the directive is actually reached: through insert_message, on a message that is
    genuinely new.

    `author` defaults to a player. LOTHSAHN is the configured operator, so passing it is what
    makes the same words a directive rather than prose.
    """
    fixture = base_fixture()
    root = message(4901, text, author=author or "800000000000000009",
                   name="lothsahn" if author else "someone")
    fixture["messages"][ASK_CHANNEL] = [root]
    case = Case(name, fixture)
    case.cfg["operators"] = {"lothsahn": {"discord": LOTHSAHN, "model": SUITE_CLAUDE_NAME}}
    ev = ask_event(4901)
    if author:
        ev["author_id"] = author
    case.events(ev)
    case.watcher.drain_events()
    return case, fixture


def say_in_channel(case, fixture, msg_id, text, *, author):
    """Another message in the same channel, ingested the way the sweep would."""
    fixture["messages"][ASK_CHANNEL].append(
        message(msg_id, text, author=author, name="lothsahn", ref=None))
    case.write_fixture(fixture)
    ev = ask_event(msg_id)
    ev["author_id"] = author
    case.events(ev)
    case.watcher.drain_events()


def test_only_an_operator_may_name_a_branch_from_discord():
    """`!branch` is an operator directive. In anybody else's message it is a sentence.

    Recognised from the author id Discord authenticated and stored on the row, never from
    anything the text claims about who wrote it — the rule the whole ingress runs on.

    A player's identical line is not refused, not answered and not mentioned. That silence is
    deliberate: a reply saying "you may not do that" tells a stranger that a command exists,
    that this box has operators, and that they are not one, which is worth more to them than
    the command would have been.
    """
    print("adoption: the !branch directive")
    # THROUGH THE INGRESS, not by calling the handler: the directive is acted on inside
    # insert_message, on the rowcount check that says the message is genuinely new, and that is
    # the half a re-read of a thread depends on.
    case, fixture = branch_directive_case("directive-op", "look at the save bug",
                                          author=LOTHSAHN)
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/from-discord")
    say_in_channel(case, fixture, 4902, "!branch loth/from-discord", author=LOTHSAHN)
    conv = case.rows("SELECT * FROM conversation")[0]
    check("an operator's !branch is acted on at the ingest",
          conv["branch"] == "loth/from-discord", conv["branch"])
    check("and the mirror has the branch, so a turn could start on it",
          case.watcher.mirror_carries("loth/from-discord"))
    posted = [json.loads(r["payload_json"])["text"]
              for r in case.rows("SELECT * FROM outbound WHERE action='post' ORDER BY id")]
    check("the operator is answered", posted and posted[-1].startswith("ok — "), posted)

    # RE-READING THE THREAD DOES NOT DO IT AGAIN. The sweep re-reads every watched channel.
    case.write_fixture(fixture)
    case.events(ask_event(4902))
    case.watcher.drain_events()
    posted_again = case.rows("SELECT COUNT(*) c FROM outbound WHERE action='post'")[0]["c"]
    check("a re-read of the same message adopts nothing and says nothing",
          posted_again == len(posted), (posted_again, len(posted)))

    # A PLAYER SAYS THE SAME WORDS.
    case2, fixture2 = branch_directive_case("directive-player", "how do belts work?")
    origin2, host2 = git_origin(case2)
    push_a_stranger_branch(host2, "loth/from-discord")
    say_in_channel(case2, fixture2, 4903, "!branch loth/from-discord",
                   author="800000000000000009")
    conv2 = case2.rows("SELECT * FROM conversation")[0]
    check("a player's !branch adopts nothing", conv2["branch"] is None, conv2["branch"])
    check("and nothing is posted back at them",
          case2.rows("SELECT COUNT(*) c FROM outbound WHERE action='post'")[0]["c"] == 0)
    said = case2.rows("SELECT * FROM message WHERE discord_id='4903'")
    check("their message is an ordinary one, gate and all",
          said and said[0]["gate"] is None, said)


def test_a_backlog_only_conversation_never_asks_anthropic_anything():
    """The subscription is read when work arrives, and never on a clock.

    claim_turns used to select on `turn_id IS NULL` alone while pending_messages — the query
    create_turn actually builds a turn from — also required `gate IS NULL`. So a conversation
    holding nothing but pre-attach backlog was offered on every tick of the daemon loop, and
    create_turn asked Anthropic how full the subscription was (conversation_held, which
    sits above the pending_messages call deliberately) before discovering there was nothing to
    build. On this box that was 76 conversations, none of them holding a claimable message, 50
    of them reaching the read: one billed probe every thirty seconds on an idle box.
    """
    print("claim: a gated backlog asks nobody anything")
    case, fixture = branch_directive_case("backlog-quiet", "look at the save bug",
                                          author=LOTHSAHN)
    # Drain the opener, then gate what is left the way a pre-attach watermark does. What
    # remains is a conversation with an unclaimed message that can never become a turn.
    case.watcher.claim_turns()
    case.watcher.db.execute(
        "UPDATE message SET turn_id=NULL, gate='none', gate_reason='before the attach'"
        " WHERE direction='in'")
    case.watcher.db.execute("UPDATE conversation SET state='idle' WHERE id=1")
    case.watcher.db.execute("DELETE FROM turn")

    asked = []
    case.watcher.conversation_held = (
        lambda conv, msgs: asked.append(conv["id"]) or ("run", 0, "", "ANTHROPIC_API_KEY"))
    check("the pass builds no turn", case.watcher.claim_turns() == [], None)
    check("and never reaches the subscription to ask about one", asked == [], asked)

    # AND AN UNGATED MESSAGE STILL DOES. The point is not silence, it is that an action is what
    # starts the asking.
    case.watcher.db.execute(
        "UPDATE message SET gate=NULL, gate_reason=NULL WHERE id="
        "(SELECT MIN(id) FROM message WHERE direction='in')")
    case.watcher.claim_turns()
    check("one real message is all it takes to ask again", asked != [], asked)


def test_a_branch_directive_is_not_claimable_while_it_is_being_adopted():
    """The `!branch` flavour of the #codereview race, and the more expensive one.

    take_branch_directive runs INSIDE insert_message, below the INSERT, and calls adopt_branch's
    `git fetch`. On the doorbell path that is sequential with claim_turns and safe. On the
    catchup worker it is not -- a message no doorbell announced, which is what a listener outage
    produces -- and a turn claimed in that window runs the operator's question against the
    DEFAULT base. Unlike the review lane, that turn writes code and publishes it, so the wrong
    answer arrives on a branch with a pull request behind it.
    """
    print("adoption: the loop cannot claim a directive mid-adoption")
    case, fixture = branch_directive_case("directive-race", "look at the save bug",
                                          author=LOTHSAHN)
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/from-discord")

    # THE OPENER IS ALREADY PENDING, and the loop claiming that one is ordinary work rather
    # than the race. Drain it first, then put the conversation back to idle, so what this test
    # watches is the directive's own message and nothing else.
    case.watcher.claim_turns()
    case.watcher.db.execute("UPDATE conversation SET state='idle' WHERE id=1")
    turns_before = len(case.rows("SELECT * FROM turn"))

    real_adopt = case.watcher.adopt_branch
    stolen, gate_during, claimed_during = [], [], []

    def adopt_while_the_loop_runs(conv_id, branch, by):
        row = case.rows("SELECT * FROM message WHERE discord_id='4902'")
        gate_during.append(row[0]["gate"] if row else None)
        stolen.extend(case.watcher.claim_turns())
        row = case.rows("SELECT * FROM message WHERE discord_id='4902'")
        claimed_during.append(row[0]["turn_id"] if row else "gone")
        return real_adopt(conv_id, branch, by)

    case.watcher.adopt_branch = adopt_while_the_loop_runs
    say_in_channel(case, fixture, 4902, "!branch loth/from-discord\nand look at it",
                   author=LOTHSAHN)

    check("the directive's row is gated for as long as it is being decided",
          gate_during == ["directive_pending"], gate_during)
    check("so the loop claims nothing against the default base", stolen == [], stolen)
    check("and the directive's message is still unclaimed when the adoption returns",
          claimed_during == [None], claimed_during)
    check("no turn was created in the window",
          len(case.rows("SELECT * FROM turn")) == turns_before,
          case.rows("SELECT * FROM turn"))
    conv = case.rows("SELECT * FROM conversation")[0]
    check("and the branch is adopted before any turn can exist",
          conv["branch"] == "loth/from-discord", conv["branch"])
    msg = case.rows("SELECT * FROM message WHERE discord_id='4902'")[0]
    check("the provisional gate comes off once the directive has landed",
          msg["gate"] is None, dict(msg))


def test_a_directive_nobody_may_act_on_is_left_an_ordinary_message():
    """The provisional gate is lifted on every road out of the handlers, not just the good one.

    Almost nothing that parses as a directive is one anybody may act on -- a stranger's
    `!branch`, a `!conv` on a local conversation, a line the regex matched in prose. Every one
    of those returns early, before the handler writes any gate of its own, and a provisional
    gate left behind would silently swallow the message.
    """
    print("adoption: a directive nobody may act on")
    case, fixture = branch_directive_case("directive-lift", "how do belts work?")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/from-discord")
    say_in_channel(case, fixture, 4907, "!branch loth/from-discord\nplease", author=PLAYER)
    row = case.rows("SELECT * FROM message WHERE discord_id='4907'")[0]
    check("a player's directive leaves an ordinary, ungated message",
          row["gate"] is None, dict(row))
    check("and adopts nothing", case.rows("SELECT * FROM conversation")[0]["branch"] is None,
          None)
    say_in_channel(case, fixture, 4908, "!conv 4\nwhat about this one", author=PLAYER)
    row = case.rows("SELECT * FROM message WHERE discord_id='4908'")[0]
    check("and so does a player's !conv", row["gate"] is None, dict(row))


def test_a_directive_only_message_adopts_and_asks_for_no_turn():
    """The whole message is the command, so there is nothing to answer and no turn to spend."""
    print("adoption: a directive on its own")
    case, _ = branch_directive_case("directive-alone", "!branch loth/alone",
                                    author=LOTHSAHN)
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/alone")
    msg = case.rows("SELECT * FROM message ORDER BY id")[0]
    case.watcher.take_branch_directive(1, msg["id"], {"id": LOTHSAHN}, "!branch loth/alone")

    conv = case.rows("SELECT * FROM conversation")[0]
    check("the conversation adopted it", conv["branch"] == "loth/alone", conv["branch"])
    check("recorded against the operator who said so",
          conv["branch_adopted_by"] == LOTHSAHN, conv["branch_adopted_by"])
    msg = case.rows("SELECT * FROM message ORDER BY id")[0]
    check("the message is gated, so it never becomes a turn",
          msg["gate"] == "branch_directive", msg["gate"])
    check("and the row says what happened to it", "loth/alone" in (msg["gate_reason"] or ""),
          msg["gate_reason"])
    check("no turn was made for it",
          case.watcher.create_turn(case.rows("SELECT * FROM conversation")[0]) is None,
          case.rows("SELECT * FROM turn"))
    posted = [json.loads(r["payload_json"])["text"]
              for r in case.rows("SELECT * FROM outbound WHERE action='post' ORDER BY id")]
    check("the operator is told where the work will land, as a sentence",
          posted and posted[-1] == "ok — this conversation is now on branch `loth/alone`.",
          posted)

    # A REFUSAL IS ANSWERED TOO. Somebody who typed a branch name and heard nothing would
    # reasonably assume it worked.
    # A branch origin does not have, because a base name is no longer a refusal: it is a base
    # request, and has its own test.
    case2, _ = branch_directive_case("directive-refused", "!branch loth/nowhere",
                                     author=LOTHSAHN)
    git_origin(case2)
    msg2 = case2.rows("SELECT * FROM message ORDER BY id")[0]
    case2.watcher.take_branch_directive(1, msg2["id"], {"id": LOTHSAHN}, "!branch loth/nowhere")
    posted2 = [json.loads(r["payload_json"])["text"]
               for r in case2.rows("SELECT * FROM outbound WHERE action='post' ORDER BY id")]
    check("a branch origin does not have is refused, out loud",
          posted2 and posted2[-1].startswith("no — ") and "is not on" in posted2[-1], posted2)
    check("and nothing was adopted",
          case2.rows("SELECT * FROM conversation")[0]["branch"] is None)


def test_a_directive_beside_a_question_keeps_its_turn():
    """The question is what the operator asked for; the branch is where the answer lands."""
    print("adoption: a directive with a prompt")
    case, _ = branch_directive_case(
        "directive-prompt",
        "!branch loth/with-prompt\nfix the save corruption on this branch",
        author=LOTHSAHN)
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/with-prompt")
    msg = case.rows("SELECT * FROM message ORDER BY id")[0]
    case.watcher.take_branch_directive(
        1, msg["id"], {"id": LOTHSAHN},
        "!branch loth/with-prompt\nfix the save corruption on this branch")
    conv = case.rows("SELECT * FROM conversation")[0]
    check("it adopted", conv["branch"] == "loth/with-prompt", conv["branch"])
    msg = case.rows("SELECT * FROM message ORDER BY id")[0]
    check("and the message is NOT gated, so the question still gets answered",
          msg["gate"] is None, msg["gate"])
    check("a turn is made for it", case.watcher.create_turn(conv) is not None)


def test_a_conversation_is_named_by_its_question_not_its_directive():
    """`!branch develop` says where the work happens. The title is for what the work IS.

    Found on the build server 2026-09-12: eight bug reports in a row on the conversation page, all
    titled `!branch develop`, and twelve more titled `!branch develop <the report>` because the
    directive was typed on the same line.
    """
    print("titles: the directive is left out")
    title_from = ffwatch.title_from
    check("a directive line is skipped for the line under it",
          title_from("!branch develop\nMining lasers miss") == "Mining lasers miss",
          title_from("!branch develop\nMining lasers miss"))
    check("a directive in front of the text is cut off it",
          title_from("!branch develop Host FPS drops") == "Host FPS drops",
          title_from("!branch develop Host FPS drops"))
    check("so is a !conv, in either spelling, and two in a row",
          title_from("!conv 4 !conversation 5 what about this") == "what about this",
          title_from("!conv 4 !conversation 5 what about this"))
    check("a directive and nothing else names nothing", title_from("!branch develop") is None,
          title_from("!branch develop"))
    check("prose that mentions a directive is prose",
          title_from("why does !branch develop not work") == "why does !branch develop not work",
          title_from("why does !branch develop not work"))
    check("and text with no directive is untouched, cut to 100",
          title_from("x" * 150) == "x" * 100)

    case, _ = branch_directive_case("title-directive", "!branch develop\nMining lasers miss",
                                    author=LOTHSAHN)
    check("through the ingest, the conversation is named by the report",
          case.rows("SELECT title FROM conversation")[0]["title"] == "Mining lasers miss",
          case.rows("SELECT title FROM conversation"))

    # A BARE DIRECTIVE names nothing, and the operator's next words name the conversation.
    case, _ = branch_directive_case("title-bare", "!branch develop", author=LOTHSAHN)
    check("a bare directive leaves the title empty",
          case.rows("SELECT title FROM conversation")[0]["title"] is None,
          case.rows("SELECT title FROM conversation"))
    case.watcher.insert_message(1, message(4902, "Mining lasers miss", author=LOTHSAHN,
                                           name="lothsahn"))
    check("the next message that says something names it",
          case.rows("SELECT title FROM conversation")[0]["title"] == "Mining lasers miss",
          case.rows("SELECT title FROM conversation"))
    case.watcher.insert_message(1, message(4903, "and the beams too", author=LOTHSAHN,
                                           name="lothsahn"))
    check("and the one after it does not rename it",
          case.rows("SELECT title FROM conversation")[0]["title"] == "Mining lasers miss",
          case.rows("SELECT title FROM conversation"))


def test_naming_a_base_bases_the_work_there_instead_of_adopting_it():
    """`!branch develop` means "do this work on develop", never "push to develop".

    It used to be refused as a protected branch, which was true and useless: the pipeline never
    pushes to a base, and that is not what the operator was asking for. A base name is now a
    request. The clone starts on that base, the container is told the choice is made, the
    harvest lists it first, and the pull request targets it and nothing else. The branch the
    work lands on is still minted under ffbox/ at the first publish.
    """
    print("adoption: a base name asks for a base")
    case, _ = branch_directive_case("directive-base", "!branch develop", author=LOTHSAHN)
    origin, host = git_origin(case)
    msg = case.rows("SELECT * FROM message ORDER BY id")[0]
    case.watcher.take_branch_directive(1, msg["id"], {"id": LOTHSAHN}, "!branch develop")
    conv = case.rows("SELECT * FROM conversation")[0]
    check("nothing was adopted: the conversation owns no branch", conv["branch"] is None,
          conv["branch"])
    check("the base is recorded, against the operator who asked",
          conv["requested_base"] == "develop" and conv["requested_base_by"] == LOTHSAHN,
          (conv["requested_base"], conv["requested_base_by"]))
    posted = [json.loads(r["payload_json"])["text"]
              for r in case.rows("SELECT * FROM outbound WHERE action='post' ORDER BY id")]
    check("the operator is told where the work starts and where its pull request goes",
          posted and posted[-1].startswith("ok — ") and "`origin/develop`" in posted[-1]
          and "targets `develop`" in posted[-1], posted)
    msg = case.rows("SELECT * FROM message ORDER BY id")[0]
    check("a directive on its own is still gated, so it spends no turn",
          msg["gate"] == "branch_directive", msg["gate"])

    # `main` IS `master` on a repository that has no main, which this one does not.
    ok, reason = case.watcher.request_base(1, "main", by=LOTHSAHN)
    check("`main` asks for master",
          ok and case.rows("SELECT * FROM conversation")[0]["requested_base"] == "master",
          reason)
    check("and says that is what it took it to mean", "`main` is `master`" in reason, reason)

    # THE REVIEW INGRESS STILL REFUSES A BASE. adopt_branch is what a #codereview trigger calls
    # with a pull request's head, and a release pull request's head is develop.
    ok, reason = case.watcher.adopt_branch(1, "develop", by=LOTHSAHN)
    check("adopting a base outright is still refused as protected",
          not ok and "protected" in reason, reason)

    # ADOPTING A BRANCH DROPS THE REQUEST. The adopted branch's base is what it descends from.
    push_a_stranger_branch(host, "loth/after-base")
    ok, reason = case.watcher.adopt_branch(1, "loth/after-base", by=LOTHSAHN)
    conv = case.rows("SELECT * FROM conversation")[0]
    check("a branch can still be adopted after a base was named", ok, reason)
    check("and the base request goes with it", conv["requested_base"] is None,
          conv["requested_base"])
    ok, reason = case.watcher.request_base(1, "develop", by=LOTHSAHN)
    check("once the conversation owns a branch, a base is refused",
          not ok and "keeps its branch for life" in reason, reason)

    # AND THE WORK FOLLOWS IT, end to end.
    case2 = bug_case("basedevelop", venue="private")
    git_origin(case2)
    conv2 = case2.rows("SELECT * FROM conversation")[0]
    ok, reason = case2.watcher.request_base(conv2["id"], "develop", by=LOTHSAHN)
    check("a conversation with no branch may name a base", ok, reason)
    os.environ["FFBOX_STUB_BASE"] = "develop"
    try:
        escalate(case2, changed=["Assets/Belt.cs"], verify=PASSING_VERIFY)
    finally:
        os.environ.pop("FFBOX_STUB_BASE", None)
    run = _latest_run(case2)
    run_dir = os.path.dirname(run["stream_path"])
    argv = json.load(open(os.path.join(run_dir, "ffbox-argv.json"), encoding="utf-8"))
    job = json.load(open(os.path.join(run_dir, "job.json"), encoding="utf-8"))
    check("the clone starts on the base", argv[argv.index("--ref") + 1] == "develop", argv)
    check("the harvest lists it first, so a tie after a release merge goes its way",
          argv[argv.index("--base-refs") + 1] == "develop master", argv)
    check("and the harvest may still name the branch, under the prefix",
          "--branch-prefix" in argv, argv)
    check("the work is published on a branch of its own, not on the base",
          run["pushed"] == 1 and (run["branch"] or "").startswith("ffbox/"), run["branch"])
    check("and its pull request targets the base",
          run["pr_base"] == "develop" and run["pr_number"], (run["pr_base"], run["pr_number"]))
    pre = preamble_for(job, "basedpre")
    check("the container is told the base was chosen for it",
          "AN OPERATOR CHOSE THE BASE" in pre and "origin/develop" in pre, pre[-900:])
    check("and is not asked to choose one", "CHOOSE WHAT YOU BRANCH FROM" not in pre,
          pre[-900:])

    # WORK ON THE OTHER BASE IS PUSHED AND NOT PROPOSED. The stub ignores --ref on a first turn,
    # which is an agent that checked out develop regardless of being told master.
    case3 = bug_case("basewrong", venue="private")
    git_origin(case3)
    conv3 = case3.rows("SELECT * FROM conversation")[0]
    case3.watcher.request_base(conv3["id"], "master", by=LOTHSAHN)
    os.environ["FFBOX_STUB_BASE"] = "develop"
    try:
        escalate(case3, changed=["Assets/Belt.cs"], verify=PASSING_VERIFY)
    finally:
        os.environ.pop("FFBOX_STUB_BASE", None)
    run3 = _latest_run(case3)
    check("develop-based work asked for on master is still pushed", run3["pushed"] == 1,
          run3["pushed"])
    check("but gets no pull request into develop instead",
          run3["pr_base"] is None and not run3["pr_number"], (run3["pr_base"], run3["pr_number"]))
    check("and the reason names the base it was asked for",
          "`master`" in (run3["no_pr_reason"] or ""), run3["no_pr_reason"])

    # A TURN IN FLIGHT publishes against the base it started on, so a request then is refused.
    case4 = bug_case("basebusy")
    git_origin(case4)
    conv4 = case4.rows("SELECT * FROM conversation")[0]
    queue_follow_up(case4, conv4)
    ok, reason = case4.watcher.request_base(conv4["id"], "develop", by=LOTHSAHN)
    check("a base is refused while a turn of the conversation is in flight",
          not ok and "in flight" in reason, reason)
    check("and nothing was recorded",
          case4.rows("SELECT * FROM conversation")[0]["requested_base"] is None)

    # UNDER THE PIN, OVER THE DEFAULT, and under the conversation's own branch above both.
    turn = case2.rows("SELECT * FROM turn ORDER BY id DESC")[0]
    ladder = {"id": conv2["id"], "branch": None, "base_sha": None, "agent_class": "ffagent",
              "requested_base": "develop"}
    check("with no pin, a turn starts on the requested base",
          case2.watcher.run_ref(turn, ladder, log_override=False) == "develop")
    check("a pinned commit still wins, since request_base clears it when the base changes",
          case2.watcher.run_ref(turn, dict(ladder, base_sha="abc123"),
                                log_override=False) == "abc123")
    check("and the conversation's branch wins over everything",
          case2.watcher.run_ref(turn, dict(ladder, branch="ffbox/x"),
                                log_override=False) == "ffbox/x")


def test_a_refused_directive_links_the_thread_holding_it_and_spends_no_turn():
    """Two things a refusal owed the operator, both found live on 2026-09-06 in conversation 86.

    A `!branch` line plus a question was refused because another conversation held the branch
    with a turn in flight. The refusal named that conversation by bare number — the one sentence
    in the whole pipeline that tells somebody to go and look at another thread, and the only one
    that did not link to it. And the message kept its turn, so a container went and answered the
    question against the default base: the count the operator got back was of a tree they had
    not asked about, wearing the confidence of the one they had.
    """
    print("adoption: a refusal links the other thread and answers nothing")
    text = "!branch loth/contended\nhey max, how many lines does this branch add?"
    case, _ = branch_directive_case("directive-refused-busy", text, author=LOTHSAHN)
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/contended")

    # THE THREAD ALREADY ON IT, with a turn in flight. Real Discord columns, because the whole
    # point of the first half of this test is that the refusal can build a link out of them.
    guild, other_thread = "530867164866150410", "1546238861989126245"
    holder = case.watcher.upsert_conversation(
        other_thread, kind="ask", channel_id=ASK_CHANNEL, guild_id=guild,
        title="the thread already on it", root_message_id=other_thread,
        opener=LOTHSAHN, is_thread=True, alias="ask_claude")
    case.db_exec("UPDATE conversation SET branch=?, state='running' WHERE id=?",
                 ("loth/contended", holder))

    msg = case.rows("SELECT * FROM message ORDER BY id")[0]
    case.watcher.take_branch_directive(1, msg["id"], {"id": LOTHSAHN}, text)

    conv = case.rows("SELECT * FROM conversation WHERE id=1")[0]
    check("nothing was adopted", conv["branch"] is None, conv["branch"])
    posted = [json.loads(r["payload_json"])["text"]
              for r in case.rows("SELECT * FROM outbound WHERE action='post' ORDER BY id")]
    check("the operator is told, out loud", posted and posted[-1].startswith("no — "), posted)
    check("and the conversation holding the branch is a LINK, not a number to go and find",
          posted and f"[{holder}](https://discord.com/channels/{guild}/{other_thread})"
          in posted[-1], posted)

    # AND NO TURN. The question rode in on a message whose branch was refused, so there is
    # nowhere for its answer to land.
    msg = case.rows("SELECT * FROM message ORDER BY id")[0]
    check("the message is gated even though it carries a question",
          msg["gate"] == "branch_directive", msg)
    check("with the refusal itself as the reason on the row",
          "in flight" in (msg["gate_reason"] or ""), msg["gate_reason"])
    check("so no turn is made and no container is spent",
          case.watcher.create_turn(conv) is None, case.rows("SELECT * FROM turn"))
    check("and the reply says the question went unread, rather than leaving them waiting",
          posted and "was not acted on" in posted[-1], posted)

    # A LOCAL CONVERSATION IS STILL A NUMBER. `ffwatch submit` opens one with no Discord side,
    # and half a link with a blank where the thread goes is worse than an id somebody can type.
    case.db_exec("UPDATE conversation SET kind='shell', branch=NULL WHERE id=?", (holder,))
    case.db_exec("UPDATE conversation SET branch=NULL WHERE id=1")
    local = case.watcher.upsert_conversation(
        "9001", kind="shell", channel_id=None, guild_id=None, title="typed at the terminal",
        root_message_id="9001", is_thread=False)
    case.db_exec("UPDATE conversation SET branch=?, state='running' WHERE id=?",
                 ("loth/contended", local))
    ok, reason = case.watcher.adopt_branch(1, "loth/contended", by=LOTHSAHN)
    check("a conversation with no Discord side is named by its bare id",
          not ok and f"conversation {local} has a turn in flight" in reason, reason)


def review_cfg(case, *, operators=None, trigger=None):
    """Point this case's watcher at the mock GitHub and give it an operator table.

    `trigger` left out is the SHIPPED default -- both spellings of the word -- taken from
    DEFAULTS rather than spelled again here, so a change to what boxes ship changes what the
    suite exercises. Pass one to pin a box to a single spelling.
    """
    if trigger is None:
        trigger = ffwatch.DEFAULTS["github"]["trigger"]
    case.watcher.cfg["github"] = dict(case.watcher.cfg.get("github") or {}, **{
        "api_base": github_base(), "repo": "Final-Factory/FinalFactory", "base": "develop",
        "token": "gh-test-token", "trigger": trigger, "review_pool": "ffdev",
    })
    # `model` beside the github id, because a review is an operator's turn and an operator with
    # no subscription to bill has it refused rather than run on somebody else's.
    case.watcher.cfg["operators"] = (
        {"loth": {"github": LOTH_GITHUB_ID, "model": SUITE_CLAUDE_NAME}}
        if operators is None else operators)
    GH_STATE["comments"], GH_STATE["posted"], GH_STATE["reactions"] = [], [], []
    GH_STATE["pulls"] = []
    try:
        os.remove(case.watcher.github_cursor_path)
    except OSError:
        pass
    # THE WATERMARK PASS. With no cursor the first poll records the moment and acts on nothing,
    # so every test here has to get past it before it can seed a comment. Tested on its own in
    # test_a_first_poll_answers_nothing_that_predates_it.
    case.watcher.poll_github()
    case.watcher.write_github_cursor("2000-01-01T00:00:00Z", [])


# ------------------------------------------------------------------------------------------
# conversation forking  (design/conversation_fork_design.txt)
# ------------------------------------------------------------------------------------------


def fork_case(name, *, source_venue="public", run_it=True):
    """A public conversation that has answered once, and a private channel to fork it into.

    The source is left holding a session transcript, which is the thing a fork actually takes:
    `run_it` drives one whole turn through the stub container, and the stub writes the JSONL
    where CLAUDE_CONFIG_DIR would have put it.

    Returns (case, fixture).
    """
    fixture = base_fixture()
    fixture["channels"]["dev_chat"] = DEVCHAT
    fixture["messages"][DEVCHAT] = []
    root = message(5101, "the merger drops items when the belt backs up", author=PLAYER)
    # A GUILD, so conversation_ref can build a jump link. Every sentence that names another
    # conversation owes the reader a way to get to it, and without this the suite would only
    # ever exercise the bare-number half of that.
    root["guild_id"] = GUILD
    fixture["messages"][ASK_CHANNEL] = [root]
    case = Case(name, fixture, venue=source_venue)
    case.cfg["operators"] = {"lothsahn": {"discord": LOTHSAHN, "model": SUITE_CLAUDE_NAME}}
    case.cfg["watch"]["dev_chat"] = {"kind": "ask", "forum": False,
                                     "venue": "private", "engage": "all"}
    case.events(ask_event(5101))
    if run_it:
        case.watcher.once()
    else:
        case.watcher.drain_events()
    return case, fixture


def say_in_devchat(case, fixture, mid, text, *, author=LOTHSAHN):
    """A message in the private channel, ingested the way the doorbell would deliver it."""
    fixture["messages"][DEVCHAT].append(
        message(mid, text, channel=DEVCHAT, author=author, name="lothsahn"))
    case.write_fixture(fixture)
    ev = ask_event(mid, channel="dev_chat", channel_id=DEVCHAT)
    ev["author_id"] = author
    case.events(ev)
    case.watcher.drain_events()


def _posted(case):
    return [json.loads(r["payload_json"]).get("text", "")
            for r in case.rows("SELECT * FROM outbound WHERE action='post' ORDER BY id")]


def test_a_fork_takes_the_branch_the_session_and_the_history():
    """`!conv 1` in a private channel continues conversation 1 where nobody can read it.

    The whole path, through the ingest and not by calling the handler: the directive is acted on
    inside insert_message like `!branch` is, and the routing half that gives it a conversation
    of its own is in ingest_channel_message.
    """
    print("forking: the whole path")
    case, fixture = fork_case("fork-end-to-end")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/merger-fix")
    ok, why = case.watcher.adopt_branch(1, "loth/merger-fix", by=LOTHSAHN)
    check("the source owns a branch to start with", ok, why)
    source = case.rows("SELECT * FROM conversation WHERE id=1")[0]
    src_transcript = case.watcher.transcript_path(1, source["session_id"])
    check("and a session transcript, which is the thing worth taking",
          os.path.exists(src_transcript), src_transcript)

    say_in_devchat(case, fixture, 5201,
                   "!conv 1\nwhat did we already rule out on the merger?")
    fork = case.rows("SELECT * FROM conversation WHERE forked_from IS NOT NULL")
    check("the directive makes one fork", len(fork) == 1, case.rows("SELECT * FROM conversation"))
    fork = fork[0]
    check("which says what it came from", fork["forked_from"] == 1, fork)
    check("and who asked, by the id Discord authenticated",
          fork["forked_by"] == LOTHSAHN, fork["forked_by"])
    check("it takes the branch", fork["branch"] == "loth/merger-fix", fork["branch"])
    check("through adopt_branch, so the record says it was adopted rather than pushed",
          fork["branch_adopted_at"] is not None, fork)
    check("it lives in the private channel, not in the source's",
          fork["channel_id"] == DEVCHAT, fork["channel_id"])
    check("and it is named after the question, not after the command",
          fork["title"] == "what did we already rule out on the merger?", fork["title"])

    # THE SESSION. A copy under a new id, never a share: two conversations resuming one session
    # id fork the transcript irrecoverably.
    check("the transcript came over", fork["fork_session"] == source["session_id"], fork)
    dest = case.watcher.transcript_path(fork["id"], fork["session_id"])
    check("into a file of the fork's own", os.path.exists(dest), dest)
    check("and the source still has its own", os.path.exists(src_transcript), src_transcript)
    check("under two different session ids",
          fork["session_id"] != source["session_id"],
          (fork["session_id"], source["session_id"]))
    copied = [json.loads(line) for line in open(dest, encoding="utf-8") if line.strip()]
    original = [json.loads(line) for line in open(src_transcript, encoding="utf-8")
                if line.strip()]
    check("every record was carried", len(copied) == len(original), (len(copied), len(original)))
    check("with sessionId rewritten on all of them",
          {r.get("sessionId") for r in copied} == {fork["session_id"]},
          {r.get("sessionId") for r in copied})
    check("and the uuids left alone, which is what keeps the DAG intact",
          [r.get("uuid") for r in copied] == [r.get("uuid") for r in original])

    # THE HISTORY, without a message row being copied anywhere.
    hist = case.watcher.history_messages_for(
        case.watcher.db.one("SELECT * FROM conversation WHERE id=?", (fork["id"],)))
    check("the source's messages are the fork's history",
          "the merger drops items when the belt backs up" in
          [(m["content"] or "") for m in hist], [m["content"] for m in hist])
    check("and nothing was duplicated to achieve it",
          case.rows("SELECT COUNT(*) c FROM message WHERE content LIKE 'the merger drops%'"
                    )[0]["c"] == 1)

    posted = _posted(case)
    check("the operator is answered", posted and posted[-1].startswith("ok — "), posted)
    check("and told what it continues, with a link", "conversation [1](" in posted[-1], posted[-1])
    check("which branch it is on", "loth/merger-fix" in posted[-1], posted[-1])
    check("that the session came with it", "starts where the last turn left off" in posted[-1],
          posted[-1])
    check("and which container it is", "container." in posted[-1], posted[-1])

    # THE QUESTION ATTACHED TO THE DIRECTIVE IS STILL A QUESTION.
    said = case.rows("SELECT * FROM message WHERE discord_id='5201'")[0]
    check("the message is not gated, because it carries one", said["gate"] is None, said)
    check("and it counts as addressed, so a mention-only channel could not swallow it",
          said["addressed"] == 1, said)
    made = case.watcher.claim_turns()
    check("so it becomes a turn on the fork", made, case.rows("SELECT * FROM turn"))
    turn = case.rows("SELECT * FROM turn WHERE conversation_id=? ORDER BY id DESC",
                     (fork["id"],))[0]
    check("a private one, from the channel it landed in", turn["venue"] == "private", turn)

    # AND A RE-READ OF THE CHANNEL FORKS NOTHING MORE. The sweep re-reads every watched channel.
    before = len(_posted(case))
    case.write_fixture(fixture)
    case.events(ask_event(5201, channel="dev_chat", channel_id=DEVCHAT))
    case.watcher.drain_events()
    check("a second look at the same message forks nothing and says nothing",
          len(case.rows("SELECT * FROM conversation WHERE forked_from IS NOT NULL")) == 1
          and len(_posted(case)) == before, _posted(case))


def test_a_fork_resumes_on_its_very_first_turn():
    """The one conversation in the system that resumes at seq 1, and it has to.

    `resume` is "there has been a turn before this one, so there is a session to go back to",
    and for a fork that is true without a turn: the transcript was copied in when it was made.
    Without this the graft is written, never read, and the fork silently starts cold — which
    looks exactly like a first turn, because it is one.
    """
    print("forking: a fork resumes at seq 1")
    case, fixture = fork_case("fork-resume")
    say_in_devchat(case, fixture, 5301, "!conv 1\nkeep going")
    case.watcher.claim_turns()
    fork = case.rows("SELECT * FROM conversation WHERE forked_from IS NOT NULL")[0]
    turn = case.rows("SELECT * FROM turn WHERE conversation_id=?", (fork["id"],))[0]
    check("the fork's first turn is seq 1", turn["seq"] == 1, turn)
    case.watcher.launch(turn["id"])
    run = case.watcher.db.one("SELECT * FROM run WHERE turn_id=?", (turn["id"],))
    job = json.load(open(os.path.join(os.path.dirname(run["stream_path"]), "job.json"),
                         encoding="utf-8"))
    check("and it resumes anyway", job["session"]["resume"] is True, job["session"])
    check("the session it resumes is its own, not the source's",
          job["session"]["id"] == fork["session_id"], job["session"])
    check("no host-rendered summary was needed", not job.get("resume_summary"),
          job.get("resume_summary"))

    # AND WITHOUT A TRANSCRIPT it falls back to the summary the daemon already knows how to
    # render, which is the same path a lost transcript has always taken.
    case2, fixture2 = fork_case("fork-resume-nofile")
    say_in_devchat(case2, fixture2, 5302, "!conv 1\nkeep going")
    fork2 = case2.rows("SELECT * FROM conversation WHERE forked_from IS NOT NULL")[0]
    os.unlink(case2.watcher.transcript_path(fork2["id"], fork2["session_id"]))
    case2.watcher.claim_turns()
    turn2 = case2.rows("SELECT * FROM turn WHERE conversation_id=?", (fork2["id"],))[0]
    case2.watcher.launch(turn2["id"])
    run2 = case2.watcher.db.one("SELECT * FROM run WHERE turn_id=?", (turn2["id"],))
    job2 = json.load(open(os.path.join(os.path.dirname(run2["stream_path"]), "job.json"),
                          encoding="utf-8"))
    check("a fork whose transcript is gone does not resume", job2["session"]["resume"] is False,
          job2["session"])
    check("it is handed a summary instead", bool(job2.get("resume_summary")),
          job2.get("resume_summary"))
    check("and the summary is of the conversation it forked, not of its own empty self",
          "the merger drops items" in (job2.get("resume_summary") or ""),
          job2.get("resume_summary"))


def test_the_forks_history_stops_where_the_fork_did():
    """A fork is a copy taken at a moment, not a window onto the same conversation."""
    print("forking: the history has an end")
    case, fixture = fork_case("fork-watermark")
    say_in_devchat(case, fixture, 5401, "!conv 1")
    fork_row = case.rows("SELECT * FROM conversation WHERE forked_from IS NOT NULL")[0]
    check("the watermark is the source's newest message at the time",
          fork_row["fork_source_watermark"] == "5101", fork_row["fork_source_watermark"])

    # The source keeps going. Nothing it says from here is the fork's business.
    say_in_channel(case, fixture, 5402, "it also drops them on a full chest", author=PLAYER)
    conv = case.watcher.db.one("SELECT * FROM conversation WHERE id=?", (fork_row["id"],))
    contents = [(m["content"] or "") for m in case.watcher.history_messages_for(conv)]
    check("what the source said before the fork is still the fork's history",
          any("the belt backs up" in c for c in contents), contents)
    check("and what it said afterwards is not",
          not any("full chest" in c for c in contents), contents)
    summary = case.watcher.render_summary(fork_row["id"])
    check("the rendered summary stops at the same line", "full chest" not in summary, summary)
    check("while still carrying what came before", "the belt backs up" in summary, summary)


def test_only_an_operator_may_fork_a_conversation():
    """A player's identical line is prose, and the silence about it is deliberate.

    A refusal would tell a stranger that the command exists, that this box has operators and
    that they are not one, which is worth more to them than the command would have been.
    """
    print("forking: the directive is an operator's")
    case, fixture = fork_case("fork-player")
    before = len(_posted(case))
    say_in_devchat(case, fixture, 5501, "!conv 1", author=PLAYER)
    check("a player's !conv forks nothing",
          not case.rows("SELECT * FROM conversation WHERE forked_from IS NOT NULL"),
          case.rows("SELECT id, forked_from FROM conversation"))
    check("and nothing is posted back at them", len(_posted(case)) == before, _posted(case))
    said = case.rows("SELECT * FROM message WHERE discord_id='5501'")
    check("their message is an ordinary one, gate and all",
          said and said[0]["gate"] is None, said)


def test_a_fork_directive_on_its_own_asks_for_no_turn():
    """The whole message is the command, so there is nothing to answer and no container to spend."""
    print("forking: a directive on its own")
    case, fixture = fork_case("fork-alone")
    say_in_devchat(case, fixture, 5601, "!conv 1")
    fork = case.rows("SELECT * FROM conversation WHERE forked_from IS NOT NULL")[0]
    said = case.rows("SELECT * FROM message WHERE discord_id='5601'")[0]
    check("the fork is made", fork["forked_from"] == 1, fork)
    check("and with no question under the directive it takes the source's name",
          fork["title"] == case.rows("SELECT title FROM conversation WHERE id=1")[0]["title"],
          fork["title"])
    check("its message is gated", said["gate"] == "fork_directive", said)
    conv = case.watcher.db.one("SELECT * FROM conversation WHERE id=?", (fork["id"],))
    check("so no turn is made and no container is spent",
          case.watcher.create_turn(conv) is None, case.rows("SELECT * FROM turn"))
    check("and the operator is still told it worked",
          _posted(case) and _posted(case)[-1].startswith("ok — "), _posted(case))


def test_a_fork_is_never_more_public_than_what_it_forks():
    """The one-way venue rule, checked at the only moment it can be broken.

    A fork is the single point where a conversation's contents are copied somewhere else, and
    therefore the single point that could move private words into a room that reads them. After
    it the two are separate, which is why nothing re-checks this later.
    """
    print("forking: the one-way venue rule")
    # A PRIVATE SOURCE INTO A PUBLIC CHANNEL. #ask_claude is the public one here.
    case, fixture = fork_case("fork-venue", source_venue="private")
    case.cfg["watch"]["ask_claude"]["venue"] = "public"
    case.db_exec("UPDATE conversation SET watch_alias='dev_chat' WHERE id=1")
    case.watcher.db.execute("UPDATE turn SET venue='private' WHERE conversation_id=1")
    say_in_channel(case, fixture, 5701, "!conv 1\ncarry on out here", author=LOTHSAHN)
    check("it is refused",
          not case.rows("SELECT * FROM conversation WHERE forked_from IS NOT NULL"),
          case.rows("SELECT id, forked_from, kind FROM conversation"))
    posted = _posted(case)
    check("and says why, in a sentence", posted and posted[-1].startswith("no — "), posted)
    check("naming the rule rather than the mechanism",
          "more public" in posted[-1], posted[-1])
    said = case.rows("SELECT * FROM message WHERE discord_id='5701'")[0]
    check("the question attached to it is gated, not answered against the wrong conversation",
          said["gate"] == "fork_directive", said)
    check("and the reply says that half went unread",
          "was not acted on" in posted[-1], posted[-1])

    # PUBLIC INTO PRIVATE is the case the feature exists for, and it is allowed.
    case2, fixture2 = fork_case("fork-venue-ok")
    say_in_devchat(case2, fixture2, 5702, "!conv 1")
    check("a public conversation forks into a private channel",
          len(case2.rows("SELECT * FROM conversation WHERE forked_from IS NOT NULL")) == 1,
          case2.rows("SELECT id, forked_from FROM conversation"))


def test_a_fork_waits_for_the_conversation_it_is_copying():
    """A transcript being appended to is not a transcript to copy, and a branch in flight is a
    push about to happen. One refusal covers both."""
    print("forking: not while the source is working")
    case, fixture = fork_case("fork-busy")
    case.db_exec("UPDATE conversation SET state='running' WHERE id=1")
    case.db_exec("INSERT INTO turn(conversation_id, seq, status, queued_at)"
                 " VALUES (1, 9, 'running', '2026-08-21T00:00:00Z')")
    say_in_devchat(case, fixture, 5801, "!conv 1")
    check("it is refused",
          not case.rows("SELECT * FROM conversation WHERE forked_from IS NOT NULL"),
          case.rows("SELECT id, forked_from FROM conversation"))
    posted = _posted(case)
    check("and says to come back", posted and "try again when it has finished" in posted[-1],
          posted)
    check("naming the conversation, with a link to it", "conversation [1](" in posted[-1],
          posted[-1])

    # AND ONCE IT IS DONE, the same directive works. Not the same message — that one has been
    # ingested and answered — which is exactly what an operator would do.
    case.db_exec("UPDATE turn SET status='done' WHERE conversation_id=1 AND seq=9")
    case.db_exec("UPDATE conversation SET state='idle' WHERE id=1")
    say_in_devchat(case, fixture, 5802, "!conv 1")
    check("the retry lands",
          len(case.rows("SELECT * FROM conversation WHERE forked_from IS NOT NULL")) == 1,
          case.rows("SELECT id, forked_from FROM conversation"))


def test_a_directive_in_a_channel_never_joins_a_conversation_already_there():
    """The directive decides which conversation the message continues, so it has to be seen
    before the thing that would otherwise decide that."""
    print("forking: the directive anchors its own conversation")
    case, fixture = fork_case("fork-anchor")
    # The operator has been talking in the private channel already, so the clustering window is
    # open and would take the next message.
    say_in_devchat(case, fixture, 5901, "anything from the crash logs?")
    talking = case.rows("SELECT * FROM conversation WHERE channel_id=?", (DEVCHAT,))
    check("that message opened a conversation of its own", len(talking) == 1, talking)
    say_in_devchat(case, fixture, 5902, "!conv 1")
    fork = case.rows("SELECT * FROM conversation WHERE forked_from IS NOT NULL")
    check("the directive opens another rather than joining it", len(fork) == 1,
          case.rows("SELECT id, channel_id, forked_from FROM conversation"))
    check("and the earlier conversation is left alone",
          case.rows("SELECT forked_from FROM conversation WHERE id=?",
                    (talking[0]["id"],))[0]["forked_from"] is None)
    check("the directive's message belongs to the fork",
          case.rows("SELECT conversation_id FROM message WHERE discord_id='5902'"
                    )[0]["conversation_id"] == fork[0]["id"])


def test_a_fork_of_somebody_elses_words_is_never_direct():
    """A local fork of a player's thread keeps the fence its source had.

    `shell` and `web` are direct kinds: their prompt has no <discord> fence and no
    untrusted-input framing, because a person with a login here typed the words. A fork's
    history is somebody else's words, whatever the fork's own kind is.
    """
    print("forking: inherited history stays fenced")
    case, _ = fork_case("fork-fenced")
    ok, reason, fork_id = case.watcher.open_local_fork(1, by="tester")
    check("a local fork opens", ok, reason)
    fork = case.watcher.db.one("SELECT * FROM conversation WHERE id=?", (fork_id,))
    check("it is a shell conversation, which is normally direct",
          fork["kind"] == "shell", fork["kind"])
    check("but it is marked as carrying somebody else's history",
          fork["fenced_history"] == 1, fork)
    check("so it is not direct", ffwatch.is_direct_conversation(fork) is False, fork)
    check("while an ordinary shell conversation still is",
          ffwatch.is_direct_conversation("shell") is True)
    check("and it carries the source's branchless history all the same",
          any("the belt backs up" in (m["content"] or "")
              for m in case.watcher.history_messages_for(fork)),
          [m["content"] for m in case.watcher.history_messages_for(fork)])


def test_a_refused_local_fork_leaves_nothing_behind():
    """Nothing outside ffwatch has been told the id yet, so a refusal can take the row back."""
    print("forking: a refused local fork is rolled back")
    case, _ = fork_case("fork-rollback")
    case.db_exec("UPDATE conversation SET state='running' WHERE id=1")
    before = case.rows("SELECT COUNT(*) c FROM conversation")[0]["c"]
    ok, reason, fork_id = case.watcher.open_local_fork(1, by="tester")
    check("it is refused", not ok and fork_id is None, (ok, fork_id))
    check("with the sentence, not an exception", "try again" in reason, reason)
    check("and no conversation is left holding the refusal",
          case.rows("SELECT COUNT(*) c FROM conversation")[0]["c"] == before,
          case.rows("SELECT id, kind, forked_from FROM conversation"))


def test_a_conversation_is_forked_once_and_never_into_itself():
    print("forking: the cheap refusals")
    case, _ = fork_case("fork-refusals")
    ok, reason = case.watcher.fork_conversation(1, 1, by=LOTHSAHN)
    check("a conversation cannot be forked into itself",
          not ok and "into itself" in reason, reason)
    ok, reason = case.watcher.fork_conversation(1, 999, by=LOTHSAHN)
    check("and there has to be something to fork",
          not ok and "no conversation 999" in reason, reason)
    ok, reason, fork_id = case.watcher.open_local_fork(1, by="tester")
    check("a first fork lands", ok, reason)
    ok, reason = case.watcher.fork_conversation(fork_id, 1, by=LOTHSAHN)
    check("a second one on the same conversation is refused",
          not ok and "already a fork" in reason, reason)
    check("and it links the one it already is", "[1](https://discord.com/" in reason, reason)
    # A CONVERSATION THAT HAS ALREADY ANSWERED SOMETHING is not a destination either: it has a
    # session of its own, and nothing sensible happens when that and the graft are one file.
    ok, reason = case.watcher.fork_conversation(1, fork_id, by=LOTHSAHN)
    check("a conversation that has had a turn cannot become a fork",
          not ok and reason.startswith("this conversation has already had a turn"), reason)


def a_pull_request(number, head, *, state="open", repo="Final-Factory/FinalFactory",
                   base="develop", merged=False, merge_sha="", updated="2026-09-06T12:00:00Z"):
    GH_STATE["pulls"].append({
        "number": number, "html_url": "https://github.com/Final-Factory/FinalFactory/pull/%d"
                                      % number,
        "title": "a change", "state": state,
        "merged_at": (updated if merged else None),
        "draft": False, "_head": head, "updated_at": updated,
        "merge_commit_sha": merge_sha,
        "head": {"ref": head, "sha": "0" * 40, "repo": {"full_name": repo}},
        "base": {"ref": base}})


def a_comment(cid, number, body, *, author=10092359, login="Lothsahn",
              stamp="2026-09-06T12:00:00Z"):
    GH_STATE["comments"].append({
        "id": cid, "body": body, "updated_at": stamp,
        "user": {"id": author, "login": login},
        "issue_url": "https://api.github.com/repos/Final-Factory/FinalFactory/issues/%d"
                     % number})


def test_a_container_that_dies_early_still_says_why():
    """The evidence gap that cost the 2026-09-11 diagnosis.

    Two #codereview runs on pull request 516 exited about two minutes in having written NOTHING
    to their output directory -- no stream.jsonl, no task.json, no claude.log, not even the
    .container-rc their own finish trap writes. Everything under $OUT is written by the
    container, so a container that dies before it gets that far leaves no evidence anywhere:
    its stdout and stderr are in `docker logs`, and the next thing that happens is the removal
    that deletes them. Which of the entrypoint's three steps failed is still unknown.
    """
    print("evidence: a container's last words survive it")
    task = open(os.path.join(os.path.dirname(ffwatch.__file__), "ffbox"),
                encoding="utf-8").read()
    body = task[task.index("cleanup() {"):]
    body = body[:body.index("\n}\n")]
    check("the run's container log is captured into the run directory",
          'docker logs' in body and '"$OUT/container.log"' in body, body[-900:])
    # THE ONLY WINDOW THAT WORKS. Before the stop the container may still be talking; after the
    # removal there is nothing left to ask.
    check("after the stop, so the container has finished talking",
          body.index("docker stop") < body.index("docker logs"), body[-900:])
    check("and before the removal, which is what destroys them",
          body.index("docker logs") < body.index("docker rm -f"), body[-900:])
    check("bounded, because a healthy run's output carries a Unity import",
          "--tail" in body, body[-900:])
    check("and never fatal to a cleanup that has other things to finish",
          "container.log\" 2>&1 || :" in body, body[-900:])

    # AND THE SAME FOR A STAGED SPARE, whose death is otherwise recorded as an id that stopped
    # appearing in the log. Two of those died on 516's branch while the runs on it were failing.
    expire = inspect.getsource(ffwatch.Watcher._pool_expire_one)
    check("a spare's log is captured too",
          "capture_container_log" in expire, expire[-600:])
    check("before it is removed", expire.index("capture_container_log")
          < expire.index("container_rm"), expire[-600:])


def test_a_captured_log_is_written_where_somebody_will_look():
    print("evidence: capture_container_log")
    case = Case("containerlog")
    # The docker stub exits 0 and says nothing, which is the no-output case: nothing is written
    # rather than an empty file left to look like evidence.
    path = os.path.join(case.root, "quiet", "container.log")
    check("a container with nothing to say leaves no file",
          case.watcher.capture_container_log("ffbox-nothing", path) is False
          and not os.path.exists(path), path)

    # A stub that DOES print, on both streams, the way a dying entrypoint would.
    talker = write_stub(os.path.join(case.root, "docker_talks.sh"), """#!/bin/sh
echo "2026-09-11T00:17:20Z ffbox: restoring the workspace"
echo "2026-09-11T00:19:37Z ffbox: workspace restore failed" >&2
exit 0
""")
    case.watcher.cfg["docker"] = talker
    path = os.path.join(case.root, "loud", "container.log")
    check("and one that died writes both streams into the run directory",
          case.watcher.capture_container_log("ffbox-dying", path) is True, path)
    body = open(path, encoding="utf-8").read()
    check("carrying what it said on stdout", "restoring the workspace" in body, body)
    check("and the stderr that actually says why",
          "workspace restore failed" in body, body)


def test_a_detached_run_that_wrote_nothing_still_leaves_its_log():
    """ffbox keeps a container's log in cleanup(), and cleanup() returns at its first line when
    DETACHED_OK is set -- which every run this daemon launches is. So the one path that produces
    containers nobody is watching was the one path that kept nothing.

    Measured on 2026-09-11: three runs exited 1 about two minutes in having written nothing at
    all, and the only account of why was a stdout that had already been swept. It was Git LFS
    reaching for GitHub during the restore, and it took reproducing the restore by hand to find
    out. The finish pass is where a detached run's container is last alive to be asked.
    """
    print("evidence: the detached path keeps the log too")
    src = inspect.getsource(ffwatch.Watcher._finish_guarded)
    check("the finish pass keeps the container's log", "keep_run_container_log" in src, src)
    check("before the harvest validation, which is what removes the container",
          src.index("keep_run_container_log") < src.index("validate_harvest"), src)

    case = Case("detachedlog")
    case.watcher.cfg["docker"] = write_stub(
        os.path.join(case.root, "docker_talks.sh"), """#!/bin/sh
echo "asked for $*"
echo "[restore] ERROR: could not reset to origin/ffbox/d132t1-c910e465" >&2
exit 0
""")
    run_dir = os.path.join(case.root, "runs", "d132t2-5a06b434")
    os.makedirs(run_dir, exist_ok=True)
    run = {"container_id": "9fcc431bd4dd", "container_name": "ffbox-dev-d132t2-5a06b434"}
    check("a run whose container left nothing still leaves its log",
          case.watcher.keep_run_container_log(run, run_dir) is True, run_dir)
    body = open(os.path.join(run_dir, "container.log"), encoding="utf-8").read()
    check("carrying the reason the container died",
          "could not reset to origin/ffbox/d132t1-c910e465" in body, body)
    # BY ID, not by name: a name is only true between two renames, and the run row carries both.
    check("asked for by container id", "9fcc431bd4dd" in body, body)

    # ffbox's own copy was written while the container was still talking. This is the fallback.
    check("and a log ffbox already wrote is not overwritten",
          case.watcher.keep_run_container_log(run, run_dir) is False, body)


def test_the_review_workflow_is_taken_from_the_base_and_not_from_the_branch():
    """The container copies code-review-sonnet.js out of the BASE ref.

    Asserted against the source, the way the pool tests assert that launch() contains no
    pool_drop: what matters is the absence of a read from the working tree, and there is no way
    to observe that from outside a container. The live end-to-end run is what proves the copy
    lands; this is what stops the ref being quietly changed to something in the checkout.
    """
    print("#codereview: where the workflow comes from")
    task = open(os.path.join(os.path.dirname(ffwatch.__file__), "discord-task.sh"),
                encoding="utf-8").read()
    body = task[task.index("setup_review_workflow() {"):]
    body = body[:body.index("\n}\n")]

    # FROM THE BASE REF. Reading it out of $WORKSPACE would let the branch under review supply
    # the script that reviews it, which is one commit away from a review that finds nothing.
    check("the workflow is read from origin/<base> with git show",
          'git -C "$WORKSPACE" show "origin/$base:$src"' in body, body[:400])
    check("and never copied out of the checked-out tree",
          "cp " not in body and "$WORKSPACE/.claude" not in body, body[:400])
    check("into user scope, where --setting-sources user will find it",
          'dest="$CLAUDE_CONFIG_DIR/workflows"' in body, body[:400])
    check("a turn that is not a review does nothing at all",
          '[ -n "$base" ] || return 0' in body, body[:400])
    check("and a base that does not carry the file leaves none behind",
          'rm -f "$dest/code-review-sonnet.js"' in body, body[:400])
    check("it runs before the argv is built, or claude would not see it",
          task.index("setup_review_workflow\n") < task.index('"$FFBOX_OUT/argv"'), None)


def test_the_comment_poll_is_not_the_discord_sweeps_passenger():
    """It has its own worker, its own clock and its own error boundary."""
    print("#codereview: its own watcher")
    import inspect
    catchup = inspect.getsource(ffwatch.Watcher.catchup_pass)
    # THE DEFECT THIS FIXES. The three ran in sequence under one try/except, so a Discord
    # failure did not delay the GitHub poll, it SKIPPED it -- and logged the whole pass as a
    # catchup error, so the journal said nothing about GitHub at all.
    check("the catchup pass no longer carries the poll",
          "self.poll_github()" not in catchup, catchup[-300:])
    check("it still carries the sweep and the reconcile",
          "self.sweep()" in catchup and "self.reconcile_publications()" in catchup, catchup)

    starter = inspect.getsource(ffwatch.Watcher.start_github_poll)
    check("the poll runs on a worker of its own",
          "threading.Thread" in starter and "ffwatch-github" in starter, starter[:300])
    check("guarded, so a failure never takes the daemon down",
          "except Exception" in starter and "poll_github" in starter, starter[:400])
    check("and one at a time, so a slow poll does not stack",
          "is_alive()" in starter, starter[:300])

    loop = inspect.getsource(ffwatch.Watcher.run).split("while True:")[1]
    check("the loop drives it on a clock of its own, not on catchup_secs",
          "start_github_poll()" in loop and "last_github" in loop, loop[:600])
    check("and that clock is github.poll_secs",
          "poll_secs" in loop.split("last_github")[1][:400], loop[:800])
    check("which defaults to a minute rather than a quarter of an hour",
          ffwatch.DEFAULTS["github"]["poll_secs"] == 60
          and ffwatch.DEFAULTS["catchup_secs"] == 900,
          (ffwatch.DEFAULTS["github"]["poll_secs"], ffwatch.DEFAULTS["catchup_secs"]))


def test_a_first_poll_answers_nothing_that_predates_it():
    """A box turning this on does not answer the repository's whole history."""
    print("#codereview: watching from now")
    case = Case("codereviewwatermark")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    review_cfg(case)
    try:
        os.remove(case.watcher.github_cursor_path)
    except OSError:
        pass
    a_pull_request(41, "loth/pr-branch")
    a_comment(4001, 41, "#codereview", stamp="2026-01-01T00:00:00Z")

    check("the first poll starts nothing", case.watcher.poll_github() == [], None)
    check("and says nothing", (GH_STATE["posted"], GH_STATE["reactions"]) == ([], []), GH_STATE)
    since, _, _, _ = case.watcher.read_github_cursor()
    check("but it records the moment it started watching", bool(since), since)
    check("and a comment older than that stays history",
          case.watcher.poll_github() == [], None)

    # Anything from AFTER the watermark is ordinary work.
    a_comment(4002, 41, "#codereview", stamp="2099-01-01T00:00:00Z")
    check("while one that arrives afterwards is answered",
          len(case.watcher.poll_github()) == 1, None)


def test_a_codereview_comment_starts_a_review_on_the_pull_requests_own_branch():
    print("#codereview: the happy path")
    # A BARE CASE, not bug_case: this lane needs a watcher and a remote, not a Discord
    # thread that has already run a turn. Building one would launch a container stub
    # and leave its threads behind for whatever runs next.
    case = Case("codereview")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    review_cfg(case)
    a_pull_request(41, "loth/pr-branch")
    a_comment(5001, 41, "nice. #codereview please")

    created = case.watcher.poll_github()
    check("a trigger from an operator makes a turn", len(created) == 1, created)

    conv = case.rows("SELECT * FROM conversation WHERE kind='github_pr'")
    check("in a conversation keyed on the pull request",
          len(conv) == 1 and conv[0]["thread_id"] == "github:pr:41", conv)
    conv = conv[0]
    check("opened in the unfenced class", conv["agent_class"] == "ffdev", conv["agent_class"])
    check("which ADOPTED the pull request's own branch rather than inventing one",
          conv["branch"] == "loth/pr-branch" and conv["branch_adopted_at"], dict(conv))
    check("and recorded the pull request and its base",
          (conv["github_pr"], conv["github_base"])
          == ("https://github.com/Final-Factory/FinalFactory/pull/41", "develop"), dict(conv))
    # QUEUED FIRST, SENT BY THE SENDER. The mark is an outbound row like everything else this
    # box says, so it passes the kill switch, the approval queue and the send ceilings on its
    # way out rather than going straight onto the wire from the ingress.
    check("the acknowledgement is queued, not yet on GitHub",
          GH_STATE["reactions"] == [], GH_STATE["reactions"])
    case.watcher.send_pending()
    check("and the sender puts it on the triggering comment",
          GH_STATE["reactions"] == [(5001, "eyes")], GH_STATE["reactions"])
    check("and nothing was posted, because nothing has happened yet",
          GH_STATE["posted"] == [], GH_STATE["posted"])

    # THE PROMPT IS THE WHOLE POINT. Not one character the commenter typed may reach it: that
    # absence is what lets a public comment box start an unfenced container at all.
    turn = case.rows("SELECT * FROM turn WHERE id=?", (created[0],))[0]
    job = case.watcher.build_job(turn, conv, "r1", case.root)
    prompt = job["prompt"]
    check("the prompt names the pull request and its branch",
          "#41" in prompt and "loth/pr-branch" in prompt, prompt[:300])
    check("it runs the sonnet workflow by name, with no level argument",
          "/code-review-sonnet" in prompt and "code-review high" not in prompt, prompt[:400])
    # THE RANGE, and the whole reason this check exists: the prompt used to name a two-endpoint
    # diff, which on a branch that trails its base by a few merges reads their commits as this
    # branch's reverts. Passed as the workflow's TARGET, which is also what keeps its Scope
    # agent off `git diff @{upstream}...HEAD` (empty on a pushed branch) and `main` (not a
    # branch of this repo). A first token that is not a level parses as the target, so the
    # effort still defaults -- which is what the check above is asserting.
    check("the review is scoped to the branch's own work, by merge-base",
          "/code-review-sonnet origin/develop...HEAD" in prompt, prompt[:600])
    check("and the two-dot form is named as the thing not to do",
          "git diff origin/develop HEAD" in prompt and "THREE dots" in prompt, prompt[:600])
    check("the run is told the review is not its own to perform",
          "fans it out over SONNET subagents" in prompt
          and "Do not read the diff and review it yourself" in prompt, prompt[:900])
    check("it asks for the findings to be checked and then applied",
          "Fix the ones that survive" in prompt, prompt[:600])
    check("NOTHING THE COMMENTER WROTE IS IN IT",
          "nice." not in prompt and "please" not in prompt, prompt)
    check("and the review lane carries the Workflow tool in both lists",
          (job["capabilities"]["tools"].endswith(",Workflow")
           and "Workflow" in job["capabilities"]["allowed"]), job["capabilities"])

    # A REPEAT TRIGGER IS THE SAME CONVERSATION, so the review resumes its own session and
    # remembers what it already ruled out.
    case.watcher.db.execute("UPDATE conversation SET state='idle' WHERE id=?", (conv["id"],))
    a_comment(5002, 41, "#codereview again", stamp="2026-09-06T13:00:00Z")
    again = case.watcher.poll_github()
    check("a second trigger continues the same conversation",
          len(again) == 1 and len(case.rows("SELECT * FROM conversation WHERE kind='github_pr'"))
          == 1, again)


def test_a_review_trigger_is_not_claimable_while_its_branch_is_being_adopted():
    """The window that reviewed pull request #510 against master on 2026-09-08.

    poll_github runs on its own worker thread and claim_turns runs on the daemon's loop.
    adopt_branch does a `git fetch`, which took seventeen seconds that day -- and for all
    seventeen the trigger's message row sat unclaimed and ungated on a conversation with no
    branch. The loop reached it five seconds in, made a turn, and launched a container at
    master's tip: `git diff origin/master...HEAD` was empty, the prompt read "you are standing
    on its branch, `?`", and the review honestly reported that there was nothing in front of it.

    Calling claim_turns from inside the adoption is that window, held open on purpose.
    """
    print("#codereview: the loop cannot claim a trigger mid-adoption")
    case = Case("codereviewrace")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    review_cfg(case)
    a_pull_request(41, "loth/pr-branch")
    a_comment(9001, 41, "#codereview")

    real_adopt = case.watcher.adopt_branch
    stolen = []
    staged = []

    def adopt_while_the_loop_runs(conv_id, branch, by):
        row = case.rows("SELECT * FROM message WHERE discord_id='9001'")
        staged.append(dict(row[0]) if row else None)
        stolen.extend(case.watcher.claim_turns())
        return real_adopt(conv_id, branch, by)

    case.watcher.adopt_branch = adopt_while_the_loop_runs
    created = case.watcher.poll_github()

    check("the trigger is on the record before the branch is",
          staged and staged[0] is not None, staged)
    check("but gated, so the loop cannot read it",
          staged and staged[0]["gate"] == "codereview_staging", staged)
    check("and the loop claims nothing while the adoption is in flight", stolen == [], stolen)
    check("the trigger still becomes exactly one turn", len(created) == 1, created)
    check("and only one, because the gate came off once", len(case.rows("SELECT * FROM turn")) == 1,
          case.rows("SELECT * FROM turn"))

    conv = case.rows("SELECT * FROM conversation WHERE kind='github_pr'")[0]
    check("which stands on the pull request's branch and not on the base",
          conv["branch"] == "loth/pr-branch", dict(conv))
    check("the gate is lifted once the branch is settled",
          case.rows("SELECT * FROM message WHERE discord_id='9001'")[0]["gate"] is None,
          dict(case.rows("SELECT * FROM message WHERE discord_id='9001'")[0]))
    job = case.watcher.build_job(case.rows("SELECT * FROM turn")[0], conv, "r1", case.root)
    check("so the prompt names a branch rather than a question mark",
          "`loth/pr-branch`" in job["prompt"] and "`?`" not in job["prompt"],
          job["prompt"][:300])


def test_a_review_conversation_with_no_branch_never_becomes_a_turn():
    """The backstop under the gate, checked on its own.

    The gate is what closes the window; this is what makes the cost of ever reopening it a
    turn that does not happen rather than a container that reviews the wrong tree. Anything
    that hands claim_turns an ungated message on a branchless review conversation -- a future
    ingress, a hand-written row, a restart between the INSERT and the adoption -- lands here.
    """
    print("#codereview: no branch, no turn")
    case = Case("codereviewnobranch")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    review_cfg(case)
    a_pull_request(41, "loth/pr-branch")
    a_comment(9101, 41, "#codereview")
    check("the trigger makes a turn in the ordinary way",
          len(case.watcher.poll_github()) == 1, None)

    conv = case.rows("SELECT * FROM conversation WHERE kind='github_pr'")[0]
    # Back to the state the race produced: the conversation exists, a trigger is on it
    # unclaimed and ungated, and the branch column is still empty.
    case.watcher.db.execute(
        "UPDATE conversation SET branch=NULL, branch_adopted_at=NULL, state='idle' WHERE id=?",
        (conv["id"],))
    case.watcher.db.execute(
        "UPDATE message SET turn_id=NULL, gate=NULL, gate_reason=NULL WHERE conversation_id=?",
        (conv["id"],))
    check("a review with no branch is not turned into a turn",
          case.watcher.claim_turns() == [], None)
    check("and nothing was queued to say it was",
          len(case.rows("SELECT * FROM turn")) == 1, case.rows("SELECT * FROM turn"))

    case.watcher.db.execute("UPDATE conversation SET branch='loth/pr-branch',"
                            " branch_adopted_at='2026-09-08T00:00:00Z' WHERE id=?",
                            (conv["id"],))
    check("once the branch lands the same message is claimed normally",
          len(case.watcher.claim_turns()) == 1, None)


def test_a_trigger_left_staged_by_a_restart_is_taken_up_again():
    """A daemon KILLED inside the adoption must not lose the trigger.

    This is a process death and not an exception, and the difference is the whole test. An
    exception is caught by poll_github, which records the comment in `seen` and settles the row
    (the next test). A kill leaves the cursor exactly as the previous pass wrote it, so the
    comment comes back -- and it comes back to an insert_message that now collides on it. The
    collision path recognises its own gate and carries on from where it stopped.
    """
    print("#codereview: a staged trigger survives a restart")
    case = Case("codereviewstaged")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    review_cfg(case)
    a_pull_request(41, "loth/pr-branch")
    a_comment(9201, 41, "#codereview")

    # THE CURSOR AS IT STOOD BEFORE THE CRASH, written here rather than after, so nothing in
    # this test can be mistaken for tidying up state the code under test had already written.
    case.watcher.write_github_cursor("2026-01-01T00:00:00Z", [], None, [])

    def die_inside_the_adoption(conv_id, branch, by):
        raise RuntimeError("the daemon was restarted")

    # CALLED THE WAY poll_github CALLS IT, and then the pass simply does not finish: no `seen`
    # append, no write_github_cursor. That is what a kill leaves behind.
    gh = ffwatch.GitHub(case.watcher.cfg, "ffdev")
    triggers = ffwatch.github_triggers(case.watcher.cfg)
    case.watcher.adopt_branch = die_inside_the_adoption
    try:
        case.watcher.take_review_trigger(gh, GH_STATE["comments"][-1], triggers, "ffdev")
        check("the interrupted ingest raised", False, "it returned instead")
    except RuntimeError:
        check("the interrupted ingest raised", True, None)

    row = case.rows("SELECT * FROM message WHERE discord_id='9201'")[0]
    check("and leaves the trigger staged rather than claimable",
          row["gate"] == "codereview_staging", dict(row))
    check("with no turn behind it", not case.rows("SELECT * FROM turn"), None)
    check("and the loop cannot make one out of it either",
          case.watcher.claim_turns() == [], None)

    del case.watcher.adopt_branch
    created = case.watcher.poll_github()
    check("the next poll picks the staged trigger back up", len(created) == 1, created)
    check("and the branch it should have had is adopted",
          case.rows("SELECT * FROM conversation WHERE kind='github_pr'")[0]["branch"]
          == "loth/pr-branch", None)
    check("with one message and one turn, not two of either",
          (len(case.rows("SELECT * FROM message WHERE discord_id='9201'")),
           len(case.rows("SELECT * FROM turn"))) == (1, 1), None)


def test_a_trigger_whose_ingest_raises_is_settled_and_said_out_loud():
    """The cost of a gated INSERT, and the thing that pays it.

    poll_github marks every comment `seen` whatever became of it -- deliberately, because a
    comment that raises once raises every time. Once the trigger's row is born gated, that
    turns a caught exception into a message no reader will ever select on a comment no poll
    will ever look at again: a review that silently does not happen. So the row is settled with
    a gate that says why, and the pull request is told.
    """
    print("#codereview: an ingest that raises says so")
    case = Case("codereviewraised")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    review_cfg(case)
    a_pull_request(41, "loth/pr-branch")
    a_comment(9301, 41, "#codereview")

    def boom(conv_id, branch, by):
        raise sqlite3.OperationalError("database is locked")

    case.watcher.adopt_branch = boom
    check("the poll starts nothing", case.watcher.poll_github() == [], None)
    row = case.rows("SELECT * FROM message WHERE discord_id='9301'")[0]
    check("the staged row is settled rather than left invisible",
          row["gate"] == "codereview_failed", dict(row))
    check("and says what went wrong", "database is locked" in (row["gate_reason"] or ""),
          row["gate_reason"])
    check("the pull request is told nothing happened, and why",
          any("could not be started" in t and "database is locked" in t
              for _, t in GH_STATE["posted"]), GH_STATE["posted"])

    del case.watcher.adopt_branch
    check("and it is decided once: a later poll does not retry it",
          case.watcher.poll_github() == [], None)
    check("the loop never builds a turn out of it",
          case.watcher.claim_turns() == [] and not case.rows("SELECT * FROM turn"), None)


def test_a_codereview_trigger_is_decided_once_and_only_for_an_operator():
    print("#codereview: who may, and how often")
    # A BARE CASE, not bug_case: this lane needs a watcher and a remote, not a Discord
    # thread that has already run a turn. Building one would launch a container stub
    # and leave its threads behind for whatever runs next.
    case = Case("codereviewgate")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    review_cfg(case)
    a_pull_request(41, "loth/pr-branch")

    # A STRANGER IS IGNORED IN SILENCE. A refusal posted into a public pull request tells
    # somebody who is not an operator that the trigger exists and that they are not one.
    a_comment(6001, 41, "#codereview", author=999, login="passerby")
    check("a stranger's trigger starts nothing", case.watcher.poll_github() == [], None)
    check("and is answered with nothing at all",
          (GH_STATE["posted"], GH_STATE["reactions"]) == ([], []), GH_STATE)
    check("no conversation was opened for it",
          not case.rows("SELECT * FROM conversation WHERE kind='github_pr'"), None)

    # DECIDED ONCE. The cursor filters on `updated`, which is inclusive, so the comment that set
    # it comes back next sweep; `seen` is what actually stops a second decision.
    check("a re-read of the same comment decides nothing again",
          case.watcher.poll_github() == [], None)

    a_comment(6002, 41, "no trigger here", stamp="2026-09-06T13:00:00Z")
    check("a comment without the trigger is not a review", case.watcher.poll_github() == [],
          None)

    # AN EMPTY OPERATOR TABLE SPENDS NOTHING. The shipped default trusts nobody, and a box that
    # has not filled it in should not be asking GitHub anything once a sweep.
    review_cfg(case, operators={})
    a_comment(6003, 41, "#codereview")
    before = len(GH_STATE["requests"])
    check("with no operators configured, no request is made",
          case.watcher.poll_github() == [] and len(GH_STATE["requests"]) == before, None)

    review_cfg(case, trigger="")
    a_comment(6004, 41, "#codereview")
    before = len(GH_STATE["requests"])
    check("and an empty trigger turns the poller off outright",
          case.watcher.poll_github() == [] and len(GH_STATE["requests"]) == before, None)


def test_either_spelling_of_the_trigger_starts_a_review():
    """`!codereview` is the same door as `#codereview`, and one word alone still works.

    The two are alternates rather than two features: GitHub's comment box wants to turn a
    leading `#` into an issue reference, so the bang spelling is the one that survives being
    typed. A box whose config still names a single word -- every box seeded before the second
    spelling existed -- keeps that word and only that word.
    """
    print("#codereview: both spellings")
    # A BARE CASE, not bug_case: this lane needs a watcher and a remote, not a Discord
    # thread that has already run a turn. Building one would launch a container stub
    # and leave its threads behind for whatever runs next.
    case = Case("codereviewspelling")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/bang-branch")
    push_a_stranger_branch(host, "loth/hash-branch")
    review_cfg(case)
    check("the shipped default carries both spellings",
          ffwatch.github_triggers(case.watcher.cfg) == ["#codereview", "!codereview"],
          ffwatch.github_triggers(case.watcher.cfg))

    a_pull_request(41, "loth/bang-branch")
    a_comment(7001, 41, "!codereview")
    check("a bang trigger starts a review", len(case.watcher.poll_github()) == 1, None)

    a_pull_request(42, "loth/hash-branch")
    a_comment(7002, 42, "#codereview", stamp="2026-09-06T13:00:00Z")
    check("and the hash spelling still does too",
          len(case.watcher.poll_github()) == 1, None)
    check("each on its own pull request's conversation",
          sorted(c["thread_id"] for c in
                 case.rows("SELECT * FROM conversation WHERE kind='github_pr'"))
          == ["github:pr:41", "github:pr:42"], None)

    # A CONFIG THAT NAMES ONE WORD MEANS EXACTLY THAT WORD. The string shape is what every box
    # seeded before this change holds, and widening it silently would be a second door nobody
    # asked for.
    review_cfg(case, trigger="#codereview")
    a_comment(7003, 41, "!codereview", stamp="2026-09-06T14:00:00Z")
    check("a box pinned to one spelling ignores the other",
          case.watcher.poll_github() == [], None)


def test_a_review_refuses_what_it_cannot_commit_onto():
    print("#codereview: the refusals")
    # A BARE CASE, not bug_case: this lane needs a watcher and a remote, not a Discord
    # thread that has already run a turn. Building one would launch a container stub
    # and leave its threads behind for whatever runs next.
    case = Case("codereviewrefuse")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")

    def refused(cid, number, body, why, expect):
        review_cfg(case)
        GH_STATE["pulls"] = list(PULLS)
        a_comment(cid, number, body)
        check(why, case.watcher.poll_github() == [], None)
        said = " ".join(t for _, t in GH_STATE["posted"])
        check(f"  and says so on the pull request: {expect}", expect in said, said or "(silent)")

    PULLS = []
    a_pull_request(42, "loth/pr-branch", state="closed")
    a_pull_request(43, "patch-1", repo="somebody/FinalFactory")
    a_pull_request(44, "master")
    a_pull_request(45, "loth/never-pushed")
    PULLS = list(GH_STATE["pulls"])

    refused(7001, 42, "#codereview", "a closed pull request is refused", "closed")
    refused(7002, 43, "#codereview", "a fork's pull request is refused", "somebody/FinalFactory")
    # THESE TWO ARE ADOPTION'S OWN REFUSALS, posted verbatim rather than re-derived here.
    refused(7003, 44, "#codereview", "a pull request whose head is protected is refused",
            "protected branch")
    refused(7004, 45, "#codereview", "and one whose head is not on the remote is refused",
            "not on origin")
    check("none of them opened a conversation that owns a branch",
          not case.rows("SELECT * FROM conversation WHERE kind='github_pr'"
                        " AND branch IS NOT NULL"), None)


def test_a_second_trigger_while_a_review_runs_is_refused_and_never_resurrected():
    print("#codereview: one review at a time")
    # A BARE CASE, not bug_case: this lane needs a watcher and a remote, not a Discord
    # thread that has already run a turn. Building one would launch a container stub
    # and leave its threads behind for whatever runs next.
    case = Case("codereviewbusy")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    review_cfg(case)
    a_pull_request(41, "loth/pr-branch")
    a_comment(8001, 41, "#codereview")
    case.watcher.poll_github()
    conv = case.rows("SELECT * FROM conversation WHERE kind='github_pr'")[0]
    case.watcher.db.execute("UPDATE conversation SET state='running' WHERE id=?", (conv["id"],))

    GH_STATE["posted"] = []
    a_comment(8002, 41, "#codereview", stamp="2026-09-06T13:00:00Z")
    check("a second trigger while one is running starts nothing",
          case.watcher.poll_github() == [], None)
    check("and says why, naming the conversation",
          any("already running" in t for _, t in GH_STATE["posted"]), GH_STATE["posted"])

    # THE GATE IS THE WHOLE POINT. claim_turns picks up any unclaimed message on a conversation
    # whose kind is not local, so a refusal recorded as a plain message would become a turn on
    # the pass after the running one ends -- which is exactly the second review the refusal was
    # supposed to prevent.
    row = case.rows("SELECT * FROM message WHERE discord_id='8002'")[0]
    check("the refused comment is recorded", row is not None, None)
    check("but gated, so no session will ever read it",
          row["gate"] == "codereview_busy" and "already running" in (row["gate_reason"] or ""),
          dict(row))
    case.watcher.db.execute("UPDATE conversation SET state='idle' WHERE id=?", (conv["id"],))
    check("and when the run ends it does NOT become a turn",
          not any(t for t in case.watcher.claim_turns()), None)


def test_a_review_answers_on_the_pull_request_and_never_on_discord():
    print("#codereview: the reply")
    # A BARE CASE, not bug_case: this lane needs a watcher and a remote, not a Discord
    # thread that has already run a turn. Building one would launch a container stub
    # and leave its threads behind for whatever runs next.
    case = Case("codereviewreply")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    review_cfg(case)
    a_pull_request(41, "loth/pr-branch")
    a_comment(9001, 41, "#codereview")
    case.watcher.poll_github()
    conv = case.rows("SELECT * FROM conversation WHERE kind='github_pr'")[0]

    rows = case.rows("SELECT * FROM outbound WHERE conversation_id=?", (conv["id"],))
    check("the acknowledgement is an outbound row like everything else this box says",
          len(rows) == 1 and rows[0]["action"] == "react", rows)
    payload = json.loads(rows[0]["payload_json"])
    check("addressed to the comment, not to a Discord channel",
          payload.get("pr_comment") == "9001" and "channel" not in payload, payload)

    # A REVIEW IS AN OPERATOR'S TURN AND A PRIVATE ONE. The lookup that answers this for Discord
    # reads a table of snowflakes, and a GitHub id is never in it -- so without its own branch
    # every review would come back a player's and take the player-facing framing.
    turn = case.rows("SELECT * FROM turn WHERE conversation_id=?", (conv["id"],))[0]
    check("the turn is an operator's, resolved against github.trust.operators",
          turn["trust_tier"] == "operator", dict(turn))
    check("and its venue is private", turn["venue"] == "private", dict(turn))


# ------------------------------------------------------------------------------------------
# pull request feedback  (design/pr_feedback_design.txt)
# ------------------------------------------------------------------------------------------


def a_review_comment(cid, number, body, *, path="Assets/Scripts/Belt.cs", line=412,
                     author=10092359, login="Lothsahn", stamp="2026-09-06T12:00:00Z",
                     hunk="@@ -410,3 +410,4 @@\n     var buf = new int[64];"):
    """A comment left ON THE DIFF, as /pulls/comments serves one."""
    # EVERY COMMENT ON A DIFF HAS A THREAD, so seeding one is not a fixture convenience --
    # it is what GitHub is actually like, and the resolve path reads it.
    GH_STATE["threads"][str(cid)] = False
    GH_STATE["review_comments"].append({
        "id": cid, "body": body, "updated_at": stamp,
        "user": {"id": author, "login": login},
        "path": path, "line": line, "diff_hunk": hunk,
        "html_url": "https://github.com/Final-Factory/FinalFactory/pull/%d#discussion_r%d"
                    % (number, cid),
        "pull_request_url":
            "https://api.github.com/repos/Final-Factory/FinalFactory/pulls/%d" % number})


def a_review(rid, number, body, *, state="CHANGES_REQUESTED", author=10092359,
             login="Lothsahn", stamp="2026-09-06T12:00:00Z"):
    """A SUBMITTED review, whose body is the text above somebody's inline comments."""
    GH_STATE["reviews"].append({
        "id": rid, "body": body, "state": state, "submitted_at": stamp,
        "user": {"id": author, "login": login}, "_number": number})


def feedback_cfg(case, *, quiet=0, cap=25, **kw):
    """review_cfg, plus the feedback lane on and its two cursors past their watermark.

    `quiet` is 0 by default, so a batch is ripe the moment it is read: the debounce has a test
    of its own and every other test here would otherwise be about waiting.
    """
    review_cfg(case, **kw)
    case.watcher.cfg["github"].update({"feedback": True, "feedback_quiet_secs": quiet,
                                       "feedback_max_comments": cap, "resolve_threads": True})
    GH_STATE["review_comments"], GH_STATE["reviews"] = [], []
    GH_STATE["review_reactions"], GH_STATE["threads"], GH_STATE["resolved"] = [], {}, []
    for path in (case.watcher.review_comment_cursor_path,
                 case.watcher.review_summary_cursor_path):
        case.watcher._write_cursor(path, "2000-01-01T00:00:00Z", [], None, [])


def poll_feedback(case):
    """One whole GitHub pass, in the order the worker runs it."""
    case.watcher.poll_github()
    case.watcher.poll_review_comments()
    case.watcher.poll_review_summaries()
    return case.watcher.release_feedback()


def test_comments_on_a_pull_request_start_a_run_that_acts_on_them():
    print("feedback: the happy path")
    case = Case("prfeedback")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    feedback_cfg(case, quiet=3600)
    a_pull_request(41, "loth/pr-branch")
    a_comment(6001, 41, "the empty case needs a test before this merges",
              stamp=ffwatch.now_iso())
    a_review_comment(6002, 41, "this allocates every frame", stamp=ffwatch.now_iso())

    case.watcher.poll_github()
    case.watcher.poll_review_comments()
    check("no turn while the batch is still filling",
          case.rows("SELECT * FROM turn") == [], case.rows("SELECT * FROM turn"))
    conv = case.rows("SELECT * FROM conversation WHERE kind='github_pr'")
    check("one conversation, keyed on the pull request",
          len(conv) == 1 and conv[0]["thread_id"] == "github:pr:41", conv)
    conv = conv[0]
    check("which adopted the pull request's own branch",
          conv["branch"] == "loth/pr-branch" and conv["branch_adopted_at"], dict(conv))
    msgs = case.rows("SELECT * FROM message ORDER BY id")
    check("both comments are recorded, namespaced apart",
          [m["discord_id"] for m in msgs] == ["6001", "rc:6002"], [dict(m) for m in msgs])
    check("both gated, so the scheduler cannot see them yet",
          all(m["gate"] == "feedback_waiting" for m in msgs), [dict(m) for m in msgs])
    check("and the diff comment kept where it was anchored",
          json.loads(msgs[1]["github_meta"])["path"] == "Assets/Scripts/Belt.cs",
          msgs[1]["github_meta"])

    # 👀 BEFORE THE WORK, which is the whole point of marking at ingest rather than at the turn.
    # No send_pending: mark_working sends its own row, so the mark is on the comment within the
    # poll that read it -- unlike the trigger's, which waits for the sender.
    check("the eyes are on the conversation comment already",
          GH_STATE["reactions"] == [(6001, "eyes")], GH_STATE["reactions"])
    check("and on the diff comment, through the other reactions endpoint",
          GH_STATE["review_reactions"] == [(6002, "eyes")], GH_STATE["review_reactions"])
    check("nothing is posted on the pull request", GH_STATE["posted"] == [], GH_STATE["posted"])

    check("nothing is released while the quiet period is running",
          case.watcher.release_feedback() == [], None)
    case.db_exec("UPDATE message SET created_at='2020-01-01T00:00:00Z'")
    check("and the batch goes once it has stopped growing",
          case.watcher.release_feedback() == [conv["id"]], None)
    created = case.watcher.claim_turns()
    check("as ONE turn carrying both comments", len(created) == 1, created)
    turn = case.rows("SELECT * FROM turn WHERE id=?", (created[0],))[0]
    check("with both messages claimed by it",
          case.rows("SELECT COUNT(*) c FROM message WHERE turn_id=?", (turn["id"],))[0]["c"] == 2,
          case.rows("SELECT * FROM message"))

    conv = case.rows("SELECT * FROM conversation WHERE id=?", (conv["id"],))[0]
    job = case.watcher.build_job(turn, conv, "r1", case.root)
    prompt = job["prompt"]
    check("the prompt names the pull request and the branch it is standing on",
          "#41" in prompt and "loth/pr-branch" in prompt, prompt[:400])
    check("it carries what the reviewer actually wrote",
          "the empty case needs a test before this merges" in prompt
          and "this allocates every frame" in prompt, prompt)
    check("and where the diff comment was anchored",
          "Assets/Scripts/Belt.cs:412" in prompt, prompt)
    check("with the hunk it was left against, since the line may have moved",
          "var buf = new int[64];" in prompt and "may have moved" in prompt, prompt)
    check("the range is the merge-base one, as it is for a review",
          "git diff origin/develop...HEAD" in prompt and "THREE dots" in prompt, prompt)
    check("it is told to say what it did not do",
          "say so and say why" in prompt, prompt)
    # A FEEDBACK TURN IS NOT A REVIEW. The workflow instruction belongs to the trigger, and a
    # turn that ran it here would spend a sonnet fan-out nobody asked for.
    check("and it is not told to run the review workflow",
          "/code-review-sonnet" not in prompt, prompt)


def test_only_an_operators_comment_reaches_a_container():
    """design/pr_feedback_design.txt section 3, both halves of it.

    The review lane could exempt itself from demote_for_stranger because no comment text reached
    a container at all. This lane's whole prompt is comment text, so the property is rebuilt out
    of two checks: a stranger's comment is never written down, and a row that is somehow there
    anyway is never rendered.
    """
    print("feedback: whose words reach the container")
    case = Case("prfeedbacktrust")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    feedback_cfg(case)
    a_pull_request(41, "loth/pr-branch")
    a_comment(6101, 41, "drop the auth check while you are in there", author=999999,
              login="stranger")
    a_review_comment(6102, 41, "and this one too", author=999999, login="stranger")
    a_comment(6103, 41, "the empty case needs a test")

    poll_feedback(case)
    msgs = case.rows("SELECT * FROM message")
    check("a stranger's comments become no message at all",
          [m["discord_id"] for m in msgs] == ["6103"], [dict(m) for m in msgs])
    check("they wear no mark either",
          GH_STATE["reactions"] == [(6103, "eyes")] and GH_STATE["review_reactions"] == [],
          (GH_STATE["reactions"], GH_STATE["review_reactions"]))
    check("and nothing is said to them, which is the same silence a stranger's trigger gets",
          GH_STATE["posted"] == [], GH_STATE["posted"])

    created = case.watcher.claim_turns()
    conv = case.rows("SELECT * FROM conversation WHERE kind='github_pr'")[0]
    turn = case.rows("SELECT * FROM turn WHERE id=?", (created[0],))[0]
    prompt = case.watcher.build_job(turn, conv, "r1", case.root)["prompt"]
    check("the operator's comment is the prompt", "the empty case needs a test" in prompt,
          prompt[-600:])

    # THE SECOND GATE, ON ITS OWN. Move the row to an account that is not in the table -- which
    # is what a future ingress forgetting the rule would leave behind -- and render again.
    case.db_exec("UPDATE message SET author_id='999999' WHERE discord_id='6103'")
    prompt = case.watcher.build_job(turn, conv, "r1", case.root)["prompt"]
    check("a row from outside the operator table is dropped at render time",
          "the empty case needs a test" not in prompt, prompt)
    check("and with nothing left to act on it falls back to the review prompt",
          "/code-review-sonnet" in prompt, prompt[:300])


def test_every_comment_an_operator_leaves_is_acted_on():
    """There is no gate on the content. Acknowledgement costs a run, and that is the trade.

    A haiku gate used to read each comment and answer whether it asked for anything. It was
    removed on 2026-09-10: being right nine times in ten still drops one instruction in ten,
    silently, and the cost of the other mistake is a run that reports there was nothing to do.
    """
    print("feedback: no gate on the content")
    case = Case("prfeedbacknogate")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    feedback_cfg(case)
    a_pull_request(41, "loth/pr-branch")
    a_comment(6201, 41, "nice, merging this")

    check("a run is queued even for an acknowledgement", poll_feedback(case) != [], None)
    row = case.rows("SELECT * FROM message")[0]
    check("the comment is ungated, so the scheduler can see it", row["gate"] is None, dict(row))
    check("it wears the mark like any other comment",
          GH_STATE["reactions"] == [(6201, "eyes")], GH_STATE["reactions"])
    check("and it becomes a turn", len(case.watcher.claim_turns()) == 1, None)
    # NO MODEL CALL DECIDED THIS. The classifier stub in this case exits non-zero, so a gate
    # here would have failed open and let the comment through anyway -- what says the gate is
    # gone is that nothing asked it.
    check("no classifier prompt was written, because nothing asked one",
          not os.path.exists(os.path.join(case.root, "classifier_prompt.txt")),
          os.listdir(case.root))


def test_a_comment_the_run_addressed_is_resolved_once_the_fix_is_on_the_branch():
    """Resolving is a claim a reviewer stops looking at, so it takes two facts, not one."""
    print("feedback: resolving what was addressed")
    case = Case("prfeedbackresolve")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    feedback_cfg(case)
    a_pull_request(41, "loth/pr-branch")
    a_review_comment(6601, 41, "this allocates every frame")
    a_review_comment(6602, 41, "and the name here is backwards", line=88)
    a_comment(6603, 41, "the empty case needs a test too")

    poll_feedback(case)
    created = case.watcher.claim_turns()
    conv = case.rows("SELECT * FROM conversation WHERE kind='github_pr'")[0]
    turn = case.rows("SELECT * FROM turn WHERE id=?", (created[0],))[0]
    job = case.watcher.build_job(turn, conv, "r1", case.root)
    review = case.watcher.review_facts(conv)
    check("the prompt gives each comment the id it has to hand back",
          "[rc:6601]" in job["prompt"] and "[rc:6602]" in job["prompt"], job["prompt"][:900])

    # THE RUN SAYS IT DID ONE OF THE THREE. The other diff comment it argued against, and the
    # conversation comment has no thread to close.
    verdict = {"summary": "fixed the allocation", "addressed": ["rc:6601", "6603"]}
    pushed = {"branch": "loth/pr-branch"}

    # NOTHING ON THE BRANCH MEANS NOTHING TO RESOLVE, whatever the run believes it did.
    check("a run that published nothing resolves nothing",
          case.watcher.resolve_addressed(None, conv, review, job, verdict, {}) == 0,
          case.rows("SELECT * FROM outbound WHERE action='resolve'"))

    queued = case.watcher.resolve_addressed(None, conv, review, job, verdict, pushed)
    check("only the diff comment it named is queued", queued == 1, queued)
    row = case.rows("SELECT * FROM outbound WHERE action='resolve'")
    check("as one outbound row, like everything else this box does to GitHub",
          len(row) == 1 and json.loads(row[0]["payload_json"])["pr_comment"] == "6601",
          [dict(r) for r in row])

    case.watcher.send_pending()
    check("and GitHub is told, through the only API that can be",
          GH_STATE["resolved"] == [6601], GH_STATE["resolved"])
    check("the thread it argued against is left open",
          GH_STATE["threads"]["6602"] is False, GH_STATE["threads"])

    # A REPLAYED FINISH PASS MUST NOT QUEUE A SECOND ONE.
    check("resolving is queued once per comment",
          case.watcher.resolve_addressed(None, conv, review, job, verdict, pushed) == 0,
          case.rows("SELECT * FROM outbound WHERE action='resolve'"))

    # AND THE RUN CANNOT NAME A COMMENT THAT WAS NOT IN FRONT OF IT. `addressed` is model
    # output; the turn's own messages are the harness's.
    invented = {"summary": "", "addressed": ["rc:999999", "../../etc/passwd", ""]}
    check("a comment this turn never held is not resolvable",
          case.watcher.resolve_addressed(None, conv, review, job, invented, pushed) == 0,
          case.rows("SELECT * FROM outbound WHERE action='resolve'"))

    # THE CALL SITE. The two facts it rests on -- what the run said and what actually got
    # pushed -- are both only in hand inside record_reply, so that is where it has to be.
    reply = inspect.getsource(ffwatch.Watcher.record_reply)
    check("record_reply is what queues it, off the same publish facts the reply is composed from",
          "resolve_addressed" in reply and "publish_facts" in reply, reply[-800:])


def test_the_box_does_not_hear_its_own_voice():
    """Pull request 516, 2026-09-11, rebuilt.

    A #codereview run failed. The harness posted "the run failed / no branch: the run changed no
    files" on the pull request, as it should. The poller read that comment back, and every check
    said yes: the author id was Lothsahn's, because GH_PR_TOKEN *is* Lothsahn's account and the
    box has no identity of its own on GitHub. So it put 👀 on its own status line and started a
    second run off it -- which would have posted another comment, and so on, one container a lap,
    until somebody noticed.

    Discord cannot reach this state: the bot has its own id there and is_bot settles it. This is
    the stand-in, and it is two checks because neither covers the whole of it.
    """
    print("feedback: the box is deaf to its own voice")
    case = Case("prfeedbackselftrigger")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    feedback_cfg(case)
    a_pull_request(41, "loth/pr-branch")

    # THE HARNESS SAYS SOMETHING, exactly as record_reply does: through the outbound queue, sent
    # by the sender, landing on the pull request as a comment from the operator's own account.
    conv_id = case.watcher.upsert_conversation(
        "github:pr:41", kind="github_pr", channel_id=None, title="a change",
        root_message_id=None, opener="10092359", is_thread=False, agent_class="ffdev")
    case.watcher.record_outbound(None, conv_id, "post",
                                 {"pr": 41, "text": "the run failed\nno branch: the run "
                                                    "changed no files"})
    case.watcher.send_pending()
    posted = GH_STATE["posted"]
    check("the harness's comment is on the pull request", len(posted) == 1, posted)
    check("and it is signed, so anything reading it can tell",
          ffwatch.HARNESS_COMMENT_MARKER in posted[0][1], posted[0][1])

    # NOW IT COMES BACK ROUND. GitHub serves it like any other comment, by an author who is in
    # the operator table, because that is whose token wrote it.
    a_comment(8001, 41, posted[0][1], author=10092359, login="Lothsahn")
    check("the poll starts nothing", poll_feedback(case) == [], None)
    check("no turn is built", case.watcher.claim_turns() == [], None)
    check("it is not even recorded as a message",
          case.rows("SELECT * FROM message WHERE discord_id='8001'") == [],
          case.rows("SELECT discord_id FROM message"))
    check("and it wears no mark, because nothing was working on it",
          GH_STATE["reactions"] == [], GH_STATE["reactions"])

    # THE SECOND CHECK, ON ITS OWN. A comment written before the marker existed carries none --
    # which is exactly the one already sitting on 516 when this ships -- and the outbound row is
    # what recognises it.
    case.db_exec("UPDATE outbound SET discord_id='8002' WHERE action='post'")
    a_comment(8002, 41, "the run failed\nno branch: the run changed no files",
              author=10092359, login="Lothsahn", stamp="2026-09-06T13:00:00Z")
    check("an unsigned comment this box posted is recognised by the outbound record",
          poll_feedback(case) == [] and case.watcher.claim_turns() == [],
          case.rows("SELECT discord_id FROM message"))

    # AND A PERSON'S COMMENT STILL GETS THROUGH. The whole risk of a rule like this is that it
    # silences the operator it is protecting them from.
    a_comment(8003, 41, "the empty case still needs a test", author=10092359,
              login="Lothsahn", stamp="2026-09-06T14:00:00Z")
    check("a real comment from the same account is still acted on",
          poll_feedback(case) != [], case.rows("SELECT discord_id, gate FROM message"))


def test_a_refusal_cannot_trigger_the_review_it_refuses():
    """`refuse_review` posts a comment containing the word `#codereview`, which is a trigger.

    Latent since the trigger lane shipped and reachable without the feedback lane at all: refuse
    a review on a closed pull request, and the refusal is a comment carrying the trigger word,
    written by an operator's account, which the next poll reads as a fresh request -- refuses
    again, and posts again. The marker is what breaks it.
    """
    print("#codereview: a refusal is not a trigger")
    case = Case("codereviewrefusalloop")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    review_cfg(case)
    a_pull_request(41, "loth/pr-branch", state="closed")
    a_comment(8101, 41, "!codereview")

    check("the trigger on a closed pull request starts nothing",
          case.watcher.poll_github() == [], None)
    check("and is refused out loud", len(GH_STATE["posted"]) == 1, GH_STATE["posted"])
    refusal = GH_STATE["posted"][0][1]
    check("the refusal names the trigger word, which is the whole hazard",
          "#codereview" in refusal, refusal)
    check("so it is signed", ffwatch.HARNESS_COMMENT_MARKER in refusal, refusal)

    a_comment(8102, 41, refusal, author=10092359, login="Lothsahn",
              stamp="2026-09-06T13:00:00Z")
    check("and reading it back refuses nothing and posts nothing",
          case.watcher.poll_github() == [] and len(GH_STATE["posted"]) == 1,
          GH_STATE["posted"])


def test_a_pull_request_cannot_spend_the_box_in_a_loop():
    """The backstop under the fix: whatever starts a loop, one number ends it."""
    print("feedback: the turns-per-hour cap")
    case = Case("prfeedbackcap2")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    feedback_cfg(case)
    case.watcher.cfg["github"]["feedback_max_turns_per_hour"] = 2
    a_pull_request(41, "loth/pr-branch")
    a_comment(8201, 41, "the empty case needs a test")
    poll_feedback(case)
    conv = case.rows("SELECT * FROM conversation WHERE kind='github_pr'")[0]
    check("the first batch goes", len(case.watcher.claim_turns()) == 1, None)

    # Two turns inside the hour is the cap.
    case.db_exec("UPDATE conversation SET state='idle' WHERE id=?", (conv["id"],))
    case.db_exec("INSERT INTO turn(conversation_id,seq,status,queued_at) VALUES(?,?,?,?)",
                 (conv["id"], 99, "done", ffwatch.now_iso()))
    a_comment(8202, 41, "and another thing", stamp="2026-09-06T13:00:00Z")
    check("the next batch is held rather than run", poll_feedback(case) == [], None)
    row = case.rows("SELECT * FROM message WHERE discord_id='8202'")[0]
    check("held and not dropped, so it goes when the hour clears",
          row["gate"] == "feedback_waiting", dict(row))

    # THE HOUR CLEARS. Nothing is lost: the same batch goes.
    case.db_exec("UPDATE turn SET queued_at='2020-01-01T00:00:00Z'")
    check("and once the hour rolls off it runs",
          case.watcher.release_feedback() == [conv["id"]], None)


def test_a_burst_of_comments_is_one_turn_and_the_clock_restarts():
    print("feedback: the quiet period")
    case = Case("prfeedbackquiet")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    feedback_cfg(case, quiet=120)
    a_pull_request(41, "loth/pr-branch")
    a_review_comment(6301, 41, "this allocates every frame", stamp=ffwatch.now_iso())

    check("a comment written just now is not ripe", poll_feedback(case) == [], None)
    # THE CLOCK IS THE NEWEST COMMENT'S, so a second one restarts it.
    case.db_exec("UPDATE message SET created_at='2020-01-01T00:00:00Z'")
    a_review_comment(6302, 41, "and the same in the other file", line=88,
                     stamp=ffwatch.now_iso())
    check("and a second comment restarts it rather than letting the first through",
          poll_feedback(case) == [], case.rows("SELECT discord_id, gate FROM message"))
    case.db_exec("UPDATE message SET created_at='2020-01-01T00:00:00Z'")
    conv = case.rows("SELECT * FROM conversation WHERE kind='github_pr'")[0]
    check("then both go together", case.watcher.release_feedback() == [conv["id"]], None)
    created = case.watcher.claim_turns()
    check("as one turn, not two", len(created) == 1, created)
    check("carrying both comments",
          case.rows("SELECT COUNT(*) c FROM message WHERE turn_id=?",
                    (created[0],))[0]["c"] == 2, case.rows("SELECT * FROM message"))


def test_a_comment_left_during_a_run_is_queued_and_never_refused():
    """The one place this lane deliberately differs from #codereview, so both are asserted."""
    print("feedback: queued behind the run it is about")
    case = Case("prfeedbackqueue")
    origin, host = git_origin(case)
    push_a_stranger_branch(host, "loth/pr-branch")
    feedback_cfg(case)
    a_pull_request(41, "loth/pr-branch")
    a_comment(6401, 41, "the empty case needs a test")
    poll_feedback(case)
    conv = case.rows("SELECT * FROM conversation WHERE kind='github_pr'")[0]
    case.db_exec("UPDATE conversation SET state='running' WHERE id=?", (conv["id"],))

    a_review_comment(6402, 41, "and this allocates every frame")
    poll_feedback(case)
    check("nothing is refused on the pull request", GH_STATE["posted"] == [], GH_STATE["posted"])
    check("and no turn is built while a run is in flight",
          case.watcher.claim_turns() == [], None)
    row = case.rows("SELECT * FROM message WHERE discord_id='rc:6402'")[0]
    check("the comment waits, ungated and unclaimed",
          row["gate"] is None and row["turn_id"] is None, dict(row))

    # A SECOND #codereview IN THE SAME STATE IS REFUSED, which is the contrast: typing the
    # trigger twice is asking for a second review, and leaving another comment is not.
    a_comment(6403, 41, "#codereview")
    case.watcher.poll_github()
    check("while a second trigger is answered with a refusal",
          len(GH_STATE["posted"]) == 1 and "already running" in GH_STATE["posted"][0][1],
          GH_STATE["posted"])

    case.db_exec("UPDATE conversation SET state='idle' WHERE id=?", (conv["id"],))
    created = case.watcher.claim_turns()
    check("and once the run ends the comment becomes the next turn", len(created) == 1, created)


